CREATE OR REPLACE FUNCTION "public"."academic_core_can_read_class"("p_school_id" "uuid", "p_class_id" "uuid") RETURNS boolean
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT public.secretaria_can_manage_school(p_school_id)
    OR public.academic_core_teacher_can_read_class(p_school_id, p_class_id)
    OR EXISTS (
      SELECT 1 FROM public.students s
      JOIN public.enrollments e ON e.student_id = s.id
      WHERE s.user_id = auth.uid()
        AND e.school_id = p_school_id
        AND e.class_id = p_class_id
        AND e.status = 'active'
        AND e.ended_at IS NULL
    )
    OR EXISTS (
      SELECT 1 FROM public.guardians g
      JOIN public.student_guardian_links sgl ON sgl.guardian_id = g.id AND sgl.status = 'active'
      JOIN public.enrollments e ON e.student_id = sgl.student_id
      WHERE g.profile_id = auth.uid()
        AND e.school_id = p_school_id
        AND e.class_id = p_class_id
        AND e.status = 'active'
        AND e.ended_at IS NULL
    );
$$;


ALTER FUNCTION "public"."academic_core_can_read_class"("p_school_id" "uuid", "p_class_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."academic_core_teacher_can_read_class"("p_school_id" "uuid", "p_class_id" "uuid") RETURNS boolean
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.teachers t
    JOIN public.class_teacher_memberships ctm ON ctm.teacher_id = t.id
    WHERE t.profile_id = auth.uid()
      AND t.school_id = p_school_id
      AND ctm.class_id = p_class_id
      AND ctm.status = 'active'
      AND ctm.started_at <= now()
      AND (ctm.ended_at IS NULL OR ctm.ended_at > now())
  );
$$;


ALTER FUNCTION "public"."academic_core_teacher_can_read_class"("p_school_id" "uuid", "p_class_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_change_institutional_role"("p_profile_id" "uuid", "p_new_role" "text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_profile public.profiles%rowtype;
  v_old_role text;
  v_new_role text;
  v_admin_roles text[] := array['admin', 'admin_ti', 'administrador', 'administrador_nacional', 'ti'];
  v_active_admins integer;
begin
  if not public.is_platform_admin() then
    raise exception 'ADMIN_REQUIRED';
  end if;

  v_new_role := lower(btrim(coalesce(p_new_role, '')));
  v_new_role := case v_new_role
    when 'responsavel' then 'educacao_infantil'
    when 'familia' then 'educacao_infantil'
    when 'rede' then 'secretaria_municipal'
    when 'rede_municipal' then 'secretaria_municipal'
    else v_new_role
  end;

  if v_new_role not in ('admin', 'secretaria', 'gestor', 'secretaria_municipal', 'professor', 'aluno', 'educacao_infantil') then
    raise exception 'INVALID_ROLE';
  end if;

  select * into v_profile
  from public.profiles
  where id = p_profile_id
  for update;

  if v_profile.id is null then
    raise exception 'PROFILE_NOT_FOUND';
  end if;

  v_old_role := lower(coalesce(v_profile.platform_role, ''));

  if v_old_role = any(v_admin_roles) and not (v_new_role = any(v_admin_roles)) then
    select count(*) into v_active_admins
    from public.profiles p
    where p.status = 'active'
      and p.id <> p_profile_id
      and lower(coalesce(p.platform_role, '')) = any(v_admin_roles);

    if v_active_admins < 1 then
      raise exception 'LAST_ADMIN_PROTECTED';
    end if;
  end if;

  update public.profiles
  set platform_role = v_new_role,
      updated_at = now()
  where id = p_profile_id;

  update auth.users
  set raw_app_meta_data = jsonb_set(
        coalesce(raw_app_meta_data, '{}'::jsonb),
        '{platform_role}',
        to_jsonb(v_new_role),
        true
      ),
      updated_at = now()
  where id = p_profile_id;

  update public.users
  set perfil = v_new_role
  where id = p_profile_id;

  insert into public.admin_operational_audit_events (
    actor_profile_id,
    actor_role,
    target_profile_id,
    module,
    action,
    result,
    details
  ) values (
    auth.uid(),
    public.current_platform_role(),
    p_profile_id,
    'usuarios',
    'role_changed',
    'success',
    jsonb_build_object(
      'old_role', v_old_role,
      'new_role', v_new_role,
      'reason', nullif(left(coalesce(p_reason, ''), 240), '')
    )
  );

  return jsonb_build_object(
    'ok', true,
    'profile_id', p_profile_id,
    'old_role', v_old_role,
    'new_role', v_new_role
  );
end;
$$;


ALTER FUNCTION "public"."admin_change_institutional_role"("p_profile_id" "uuid", "p_new_role" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_confirm_network_bulk_import"("p_batch_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_batch public.admin_network_bulk_import_batches%rowtype;
  v_row jsonb;
  v_school_code text;
  v_school_name text;
  v_school_year text;
  v_type text;
  v_school_id uuid;
  v_packages jsonb := '{}'::jsonb;
  v_package jsonb;
  v_report jsonb;
  v_reports jsonb := '[]'::jsonb;
  v_school_created integer := 0;
  v_school_existing integer := 0;
  v_key text;
  v_raw_relationship text;
  v_relationship text;
  v_student_reference text;
begin
  if not public.is_platform_admin() then
    raise exception 'Perfil Admin/TI obrigatorio para confirmar importacao de rede.' using errcode = '42501';
  end if;

  select * into v_batch
  from public.admin_network_bulk_import_batches
  where id = p_batch_id;

  if v_batch.id is null then
    raise exception 'Lote de implantacao nao encontrado.' using errcode = '22023';
  end if;

  if v_batch.status = 'confirmed' then
    return jsonb_build_object(
      'batch_id', v_batch.id,
      'status', 'confirmed',
      'idempotent_replay', true,
      'report', v_batch.preview_report
    );
  end if;

  if v_batch.status <> 'validated' then
    raise exception 'Somente lotes validados podem ser confirmados.' using errcode = '22023';
  end if;

  v_school_year := coalesce(nullif(v_batch.school_year, ''), '2026');

  for v_row in select * from jsonb_array_elements(v_batch.payload) loop
    v_type := lower(btrim(coalesce(v_row ->> 'tipo', v_row ->> 'entity_type', v_row ->> 'entidade', v_batch.import_type, 'auto')));
    v_type := translate(v_type, 'áàãâéêíóôõúç', 'aaaaeeiooouc');
    v_school_code := nullif(btrim(coalesce(v_row ->> 'codigo_escola', v_row ->> 'school_code', v_row ->> 'codigo_inep', v_row ->> 'inep')), '');
    v_school_name := nullif(btrim(coalesce(v_row ->> 'nome_escola', v_row ->> 'school_name', v_row ->> 'escola')), '');

    if v_type in ('school', 'schools', 'escola', 'escolas') then
      select id into v_school_id
      from public.schools
      where lower(btrim(coalesce(codigo_inep, ''))) = lower(v_school_code)
         or lower(btrim(nome)) = lower(v_school_name)
      order by created_at
      limit 1;

      if v_school_id is null then
        insert into public.schools (nome, codigo_inep, municipio, estado, diretor, status)
        values (
          v_school_name,
          v_school_code,
          nullif(btrim(coalesce(v_row ->> 'municipio', v_row ->> 'city')), ''),
          nullif(btrim(coalesce(v_row ->> 'estado', v_row ->> 'uf')), ''),
          nullif(btrim(coalesce(v_row ->> 'diretor', v_row ->> 'principal')), ''),
          'inactive'
        )
        returning id into v_school_id;

        insert into public.rs_school_installations (
          school_id,
          school_code,
          deployment_mode,
          schema_version,
          package_version,
          school_year,
          current_stage,
          validation_status,
          created_by
        ) values (
          v_school_id,
          v_school_code,
          'production',
          'RS-SCHOOL-TEMPLATE V1',
          'RS-SCHOOL-V1-DEPLOYMENT-2026-09-01',
          v_school_year,
          'em_configuracao',
          'pending',
          auth.uid()
        )
        on conflict (school_id) do nothing;

        v_school_created := v_school_created + 1;
      else
        v_school_existing := v_school_existing + 1;
      end if;
    end if;
  end loop;

  for v_row in select * from jsonb_array_elements(v_batch.payload) loop
    v_type := lower(btrim(coalesce(v_row ->> 'tipo', v_row ->> 'entity_type', v_row ->> 'entidade', v_batch.import_type, 'auto')));
    v_type := translate(v_type, 'áàãâéêíóôõúç', 'aaaaeeiooouc');
    v_type := case
      when v_type in ('school', 'schools', 'escola', 'escolas') then 'school'
      when v_type in ('class', 'classes', 'turma', 'turmas') then 'class'
      when v_type in ('teacher', 'teachers', 'professor', 'professores') then 'teacher'
      when v_type in ('student', 'students', 'aluno', 'alunos') then 'student'
      when v_type in ('guardian', 'guardians', 'responsavel', 'responsaveis') then 'guardian'
      when v_type in ('enrollment', 'enrollments', 'matricula', 'matriculas') then 'enrollment'
      when v_type in ('teacher_class', 'teacher_class_link', 'vinculo_professor_turma', 'professor_turma') then 'teacher_class_link'
      when v_type in ('guardian_student', 'guardian_student_link', 'vinculo_responsavel_aluno', 'responsavel_aluno') then 'guardian_student_link'
      else v_type
    end;

    if v_type = 'school' then
      continue;
    end if;

    v_school_code := nullif(btrim(coalesce(v_row ->> 'codigo_escola', v_row ->> 'school_code', v_row ->> 'codigo_inep', v_row ->> 'inep')), '');
    if v_school_code is null then
      continue;
    end if;

    if not (v_packages ? v_school_code) then
      v_packages := jsonb_set(v_packages, array[v_school_code], jsonb_build_object(
        'package_version', 'RS-SCHOOL-V1-DEPLOYMENT-2026-09-01',
        'schema_version', 'RS-SCHOOL-TEMPLATE V1',
        'school_year', v_school_year,
        'classes', '[]'::jsonb,
        'teachers', '[]'::jsonb,
        'teacher_classes', '[]'::jsonb,
        'students', '[]'::jsonb,
        'guardians', '[]'::jsonb
      ), true);
    end if;

    if v_type = 'class' and nullif(btrim(coalesce(v_row ->> 'nome_turma', v_row ->> 'class_name', v_row ->> 'turma')), '') is not null then
      v_packages := jsonb_set(v_packages, array[v_school_code, 'classes'],
        coalesce(v_packages #> array[v_school_code, 'classes'], '[]'::jsonb) || jsonb_build_array(jsonb_build_object(
          'class_name', btrim(coalesce(v_row ->> 'nome_turma', v_row ->> 'class_name', v_row ->> 'turma')),
          'school_year', coalesce(nullif(btrim(coalesce(v_row ->> 'ano_letivo', v_row ->> 'school_year')), ''), v_school_year),
          'status', 'active',
          'age_group', nullif(btrim(coalesce(v_row ->> 'faixa_etaria', v_row ->> 'age_group')), ''),
          'shift', nullif(btrim(coalesce(v_row ->> 'turno', v_row ->> 'shift')), ''),
          'grade', nullif(btrim(coalesce(v_row ->> 'ano_serie', v_row ->> 'grade')), '')
        )), true);
    end if;

    if v_type = 'teacher' and coalesce(nullif(btrim(coalesce(v_row ->> 'nome_professor', v_row ->> 'teacher_name', v_row ->> 'professor')), ''), nullif(btrim(coalesce(v_row ->> 'email_professor', v_row ->> 'teacher_email')), '')) is not null then
      v_packages := jsonb_set(v_packages, array[v_school_code, 'teachers'],
        coalesce(v_packages #> array[v_school_code, 'teachers'], '[]'::jsonb) || jsonb_build_array(jsonb_build_object(
          'full_name', coalesce(nullif(btrim(coalesce(v_row ->> 'nome_professor', v_row ->> 'teacher_name', v_row ->> 'professor')), ''), nullif(btrim(coalesce(v_row ->> 'email_professor', v_row ->> 'teacher_email')), '')),
          'email', nullif(btrim(coalesce(v_row ->> 'email_professor', v_row ->> 'teacher_email')), ''),
          'disciplina', nullif(btrim(coalesce(v_row ->> 'componente', v_row ->> 'disciplina')), ''),
          'status', 'active'
        )), true);
    end if;

    if v_type = 'teacher_class_link' then
      v_packages := jsonb_set(v_packages, array[v_school_code, 'teacher_classes'],
        coalesce(v_packages #> array[v_school_code, 'teacher_classes'], '[]'::jsonb) || jsonb_build_array(jsonb_build_object(
          'teacher_email', coalesce(nullif(btrim(coalesce(v_row ->> 'email_professor', v_row ->> 'teacher_email')), ''), nullif(btrim(coalesce(v_row ->> 'nome_professor', v_row ->> 'teacher_name', v_row ->> 'professor')), '')),
          'class_name', btrim(coalesce(v_row ->> 'nome_turma', v_row ->> 'class_name', v_row ->> 'turma')),
          'school_year', coalesce(nullif(btrim(coalesce(v_row ->> 'ano_letivo', v_row ->> 'school_year')), ''), v_school_year),
          'role', coalesce(nullif(btrim(coalesce(v_row ->> 'funcao', v_row ->> 'role')), ''), 'principal')
        )), true);
    end if;

    if v_type = 'student' and nullif(btrim(coalesce(v_row ->> 'nome_aluno', v_row ->> 'student_name', v_row ->> 'aluno')), '') is not null then
      v_packages := jsonb_set(v_packages, array[v_school_code, 'students'],
        coalesce(v_packages #> array[v_school_code, 'students'], '[]'::jsonb) || jsonb_build_array(jsonb_build_object(
          'full_name', btrim(coalesce(v_row ->> 'nome_aluno', v_row ->> 'student_name', v_row ->> 'aluno')),
          'birth_date', nullif(btrim(coalesce(v_row ->> 'data_nascimento', v_row ->> 'birth_date')), ''),
          'class_name', nullif(btrim(coalesce(v_row ->> 'nome_turma', v_row ->> 'class_name', v_row ->> 'turma')), ''),
          'school_year', coalesce(nullif(btrim(coalesce(v_row ->> 'ano_letivo', v_row ->> 'school_year')), ''), v_school_year),
          'status', 'active'
        )), true);
    end if;

    if v_type in ('guardian', 'guardian_student_link') and coalesce(nullif(btrim(coalesce(v_row ->> 'nome_responsavel', v_row ->> 'guardian_name', v_row ->> 'responsavel')), ''), nullif(btrim(coalesce(v_row ->> 'email_responsavel', v_row ->> 'guardian_email')), '')) is not null then
      v_student_reference := nullif(btrim(coalesce(v_row ->> 'nome_aluno', v_row ->> 'student_name', v_row ->> 'aluno')), '');

      if v_type <> 'guardian_student_link' then
        continue;
      end if;

      v_raw_relationship := nullif(btrim(coalesce(v_row ->> 'parentesco', v_row ->> 'relationship')), '');
      v_relationship := coalesce(public.admin_normalize_guardian_relationship(v_raw_relationship), case when v_raw_relationship is null then 'responsavel' else null end);
      if v_relationship is null then
        raise exception 'Vinculo de responsavel invalido para %. Use Mae, Pai, Responsavel, Avo, Tutor ou Outro.', coalesce(nullif(btrim(coalesce(v_row ->> 'nome_responsavel', v_row ->> 'guardian_name', v_row ->> 'responsavel')), ''), nullif(btrim(coalesce(v_row ->> 'email_responsavel', v_row ->> 'guardian_email')), ''))
          using errcode = '22023';
      end if;

      v_packages := jsonb_set(v_packages, array[v_school_code, 'guardians'],
        coalesce(v_packages #> array[v_school_code, 'guardians'], '[]'::jsonb) || jsonb_build_array(jsonb_build_object(
          'guardian_name', coalesce(nullif(btrim(coalesce(v_row ->> 'nome_responsavel', v_row ->> 'guardian_name', v_row ->> 'responsavel')), ''), nullif(btrim(coalesce(v_row ->> 'email_responsavel', v_row ->> 'guardian_email')), '')),
          'email', nullif(btrim(coalesce(v_row ->> 'email_responsavel', v_row ->> 'guardian_email')), ''),
          'phone', nullif(btrim(coalesce(v_row ->> 'telefone_responsavel', v_row ->> 'phone')), ''),
          'relationship', v_relationship,
          'student_reference', v_student_reference,
          'status', 'active',
          'is_primary', case lower(btrim(coalesce(v_row ->> 'principal', v_row ->> 'is_primary', 'true')))
            when 'false' then false
            when 'falso' then false
            when 'nao' then false
            when 'não' then false
            when '0' then false
            else true
          end
        )), true);
    end if;
  end loop;

  for v_key, v_package in select key, value from jsonb_each(v_packages) loop
    select s.id into v_school_id
    from public.schools s
    where lower(btrim(coalesce(s.codigo_inep, ''))) = lower(v_key)
    order by s.created_at
    limit 1;

    if v_school_id is null then
      raise exception 'Escola do pacote nao encontrada: %', v_key using errcode = '22023';
    end if;

    v_report := public.admin_confirm_rs_school_import(v_school_id, v_package, false);
    v_reports := v_reports || jsonb_build_array(jsonb_build_object(
      'school_code', v_key,
      'school_id', v_school_id,
      'report', v_report
    ));
  end loop;

  update public.admin_network_bulk_import_batches
     set status = 'confirmed',
         confirmed_by = auth.uid(),
         confirmed_at = now(),
         preview_report = preview_report || jsonb_build_object(
           'confirmed', true,
           'schools_created', v_school_created,
           'schools_existing', v_school_existing,
           'school_reports', v_reports
         )
   where id = v_batch.id
   returning * into v_batch;

  return jsonb_build_object(
    'batch_id', v_batch.id,
    'status', 'confirmed',
    'report', v_batch.preview_report,
    'errors', v_batch.errors
  );
end;
$$;


ALTER FUNCTION "public"."admin_confirm_network_bulk_import"("p_batch_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_confirm_network_bulk_import"("p_batch_id" "uuid") IS 'Admin hotfix: confirms network bulk implantation with strict entity routing between unified import sheets.';



CREATE OR REPLACE FUNCTION "public"."admin_confirm_rs_school_import"("p_school_id" "uuid", "p_package" "jsonb", "p_dry_run" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_admin_user_id uuid := auth.uid();
  v_admin_role text;
  v_school_code text;
  v_school_year text := coalesce(nullif(btrim(p_package ->> 'school_year'), ''), '2026');
  v_package_version text := coalesce(nullif(btrim(p_package ->> 'package_version'), ''), 'RS-SCHOOL-V1-DEPLOYMENT-2026-09-01');
  v_schema_version text := coalesce(nullif(btrim(p_package ->> 'schema_version'), ''), 'RS-SCHOOL-TEMPLATE V1');
  v_counts jsonb := jsonb_build_object(
    'valid_rows', 0,
    'classes_created', 0,
    'teachers_created', 0,
    'teacher_links_created', 0,
    'students_created', 0,
    'enrollments_created', 0,
    'guardians_created', 0,
    'family_links_created', 0,
    'existing', 0,
    'invalid', 0
  );
  v_class_ids jsonb := '{}'::jsonb;
  v_teacher_ids jsonb := '{}'::jsonb;
  v_student_ids jsonb := '{}'::jsonb;
  v_guardian_ids jsonb := '{}'::jsonb;
  v_item jsonb;
  v_key text;
  v_class_id uuid;
  v_teacher_id uuid;
  v_student_id uuid;
  v_guardian_id uuid;
  v_enrollment_id uuid;
  v_link_id uuid;
begin
  if v_admin_user_id is null then
    raise exception 'Sessao autenticada obrigatoria.' using errcode = '42501';
  end if;

  select lower(platform_role)
    into v_admin_role
  from public.profiles
  where id = v_admin_user_id
    and status = 'active';

  if v_admin_role not in ('admin', 'admin_ti', 'administrador', 'administrador_nacional') then
    raise exception 'Perfil Admin/TI obrigatorio para importar escola.' using errcode = '42501';
  end if;

  select coalesce(i.school_code, s.codigo_inep, s.nome)
    into v_school_code
  from public.schools s
  left join public.rs_school_installations i on i.school_id = s.id
  where s.id = p_school_id
    and s.status <> 'archived';

  if v_school_code is null then
    raise exception 'Escola alvo nao encontrada.' using errcode = '22023';
  end if;

  if v_package_version <> 'RS-SCHOOL-V1-DEPLOYMENT-2026-09-01' or v_schema_version <> 'RS-SCHOOL-TEMPLATE V1' then
    raise exception 'Pacote de importacao incompativel.' using errcode = '22023';
  end if;

  if jsonb_typeof(coalesce(p_package -> 'classes', '[]'::jsonb)) <> 'array'
    or jsonb_typeof(coalesce(p_package -> 'teachers', '[]'::jsonb)) <> 'array'
    or jsonb_typeof(coalesce(p_package -> 'teacher_classes', '[]'::jsonb)) <> 'array'
    or jsonb_typeof(coalesce(p_package -> 'students', '[]'::jsonb)) <> 'array'
    or jsonb_typeof(coalesce(p_package -> 'guardians', '[]'::jsonb)) <> 'array' then
    raise exception 'Formato do pacote de importacao invalido.' using errcode = '22023';
  end if;

  v_counts := jsonb_set(
    v_counts,
    '{valid_rows}',
    to_jsonb(
      jsonb_array_length(coalesce(p_package -> 'classes', '[]'::jsonb))
      + jsonb_array_length(coalesce(p_package -> 'teachers', '[]'::jsonb))
      + jsonb_array_length(coalesce(p_package -> 'teacher_classes', '[]'::jsonb))
      + jsonb_array_length(coalesce(p_package -> 'students', '[]'::jsonb))
      + jsonb_array_length(coalesce(p_package -> 'guardians', '[]'::jsonb))
    )
  );

  for v_item in select * from jsonb_array_elements(coalesce(p_package -> 'classes', '[]'::jsonb)) loop
    v_key := lower(btrim(v_item ->> 'class_name')) || '|' || coalesce(nullif(btrim(v_item ->> 'school_year'), ''), v_school_year);
    if nullif(btrim(v_item ->> 'class_name'), '') is null then
      v_counts := jsonb_set(v_counts, '{invalid}', to_jsonb((v_counts ->> 'invalid')::int + 1));
      continue;
    end if;

    select id into v_class_id
    from public.classes
    where school_id = p_school_id
      and lower(btrim(nome)) = lower(btrim(v_item ->> 'class_name'))
      and coalesce(school_year, '') = coalesce(nullif(btrim(v_item ->> 'school_year'), ''), v_school_year)
      and status <> 'archived'
    order by created_at
    limit 1;

    if v_class_id is null and p_dry_run then
      v_class_ids := jsonb_set(v_class_ids, array[v_key], to_jsonb(v_key), true);
    elsif v_class_id is null then
      insert into public.classes (school_id, nome, age_group, school_year, status, turno, ano_escolar)
      values (
        p_school_id,
        btrim(v_item ->> 'class_name'),
        nullif(btrim(v_item ->> 'age_group'), ''),
        coalesce(nullif(btrim(v_item ->> 'school_year'), ''), v_school_year),
        coalesce(nullif(btrim(v_item ->> 'status'), ''), 'active'),
        nullif(btrim(v_item ->> 'shift'), ''),
        nullif(btrim(v_item ->> 'grade'), '')
      )
      returning id into v_class_id;
      v_counts := jsonb_set(v_counts, '{classes_created}', to_jsonb((v_counts ->> 'classes_created')::int + 1));
    elsif v_class_id is not null then
      v_counts := jsonb_set(v_counts, '{existing}', to_jsonb((v_counts ->> 'existing')::int + 1));
    end if;

    if v_class_id is not null then
      v_class_ids := jsonb_set(v_class_ids, array[v_key], to_jsonb(v_class_id::text), true);
    end if;
  end loop;

  for v_item in select * from jsonb_array_elements(coalesce(p_package -> 'teachers', '[]'::jsonb)) loop
    v_key := lower(coalesce(nullif(btrim(v_item ->> 'email'), ''), btrim(v_item ->> 'full_name')));
    if nullif(btrim(v_item ->> 'full_name'), '') is null then
      v_counts := jsonb_set(v_counts, '{invalid}', to_jsonb((v_counts ->> 'invalid')::int + 1));
      continue;
    end if;

    select id into v_teacher_id
    from public.teachers
    where school_id = p_school_id
      and lower(coalesce(nullif(btrim(full_name), ''), '')) = lower(btrim(v_item ->> 'full_name'))
      and status <> 'archived'
    order by created_at
    limit 1;

    if v_teacher_id is null and p_dry_run then
      v_teacher_ids := jsonb_set(v_teacher_ids, array[v_key], to_jsonb(v_key), true);
    elsif v_teacher_id is null then
      insert into public.teachers (school_id, profile_id, full_name, email, disciplina, status)
      values (
        p_school_id,
        null,
        btrim(v_item ->> 'full_name'),
        nullif(btrim(v_item ->> 'email'), ''),
        nullif(btrim(v_item ->> 'disciplina'), ''),
        coalesce(nullif(btrim(v_item ->> 'status'), ''), 'active')
      )
      returning id into v_teacher_id;
      v_counts := jsonb_set(v_counts, '{teachers_created}', to_jsonb((v_counts ->> 'teachers_created')::int + 1));
    elsif v_teacher_id is not null then
      v_counts := jsonb_set(v_counts, '{existing}', to_jsonb((v_counts ->> 'existing')::int + 1));
    end if;

    if v_teacher_id is not null then
      v_teacher_ids := jsonb_set(v_teacher_ids, array[v_key], to_jsonb(v_teacher_id::text), true);
    end if;
  end loop;

  for v_item in select * from jsonb_array_elements(coalesce(p_package -> 'students', '[]'::jsonb)) loop
    v_key := lower(btrim(v_item ->> 'full_name'));
    if nullif(btrim(v_item ->> 'full_name'), '') is null or nullif(btrim(v_item ->> 'class_name'), '') is null then
      v_counts := jsonb_set(v_counts, '{invalid}', to_jsonb((v_counts ->> 'invalid')::int + 1));
      continue;
    end if;

    select id into v_student_id
    from public.students
    where school_id = p_school_id
      and lower(btrim(nome)) = lower(btrim(v_item ->> 'full_name'))
      and status <> 'archived'
    order by created_at
    limit 1;

    if v_student_id is null and p_dry_run then
      v_student_ids := jsonb_set(v_student_ids, array[v_key], to_jsonb(v_key), true);
    elsif v_student_id is null then
      if (v_class_ids ->> (lower(btrim(v_item ->> 'class_name')) || '|' || coalesce(nullif(btrim(v_item ->> 'school_year'), ''), v_school_year))) is null then
        v_counts := jsonb_set(v_counts, '{invalid}', to_jsonb((v_counts ->> 'invalid')::int + 1));
        continue;
      end if;

      insert into public.students (school_id, class_id, nome, data_nascimento, status, turma)
      values (
        p_school_id,
        (v_class_ids ->> (lower(btrim(v_item ->> 'class_name')) || '|' || coalesce(nullif(btrim(v_item ->> 'school_year'), ''), v_school_year)))::uuid,
        btrim(v_item ->> 'full_name'),
        nullif(btrim(v_item ->> 'birth_date'), '')::date,
        coalesce(nullif(btrim(v_item ->> 'status'), ''), 'active'),
        btrim(v_item ->> 'class_name')
      )
      returning id into v_student_id;
      v_counts := jsonb_set(v_counts, '{students_created}', to_jsonb((v_counts ->> 'students_created')::int + 1));
    elsif v_student_id is not null then
      v_counts := jsonb_set(v_counts, '{existing}', to_jsonb((v_counts ->> 'existing')::int + 1));
    end if;

    if v_student_id is not null then
      v_student_ids := jsonb_set(v_student_ids, array[v_key], to_jsonb(v_student_id::text), true);
    end if;

    if v_student_id is not null then
      select id into v_enrollment_id
      from public.enrollments
      where school_id = p_school_id
        and student_id = v_student_id
        and class_id = (v_class_ids ->> (lower(btrim(v_item ->> 'class_name')) || '|' || coalesce(nullif(btrim(v_item ->> 'school_year'), ''), v_school_year)))::uuid
        and school_year = coalesce(nullif(btrim(v_item ->> 'school_year'), ''), v_school_year)
        and status = 'active'
      order by created_at
      limit 1;

      if v_enrollment_id is null and not p_dry_run then
        insert into public.enrollments (student_id, class_id, school_id, school_year, status)
        values (
          v_student_id,
          (v_class_ids ->> (lower(btrim(v_item ->> 'class_name')) || '|' || coalesce(nullif(btrim(v_item ->> 'school_year'), ''), v_school_year)))::uuid,
          p_school_id,
          coalesce(nullif(btrim(v_item ->> 'school_year'), ''), v_school_year),
          'active'
        )
        returning id into v_enrollment_id;
        v_counts := jsonb_set(v_counts, '{enrollments_created}', to_jsonb((v_counts ->> 'enrollments_created')::int + 1));
      elsif v_enrollment_id is not null then
        v_counts := jsonb_set(v_counts, '{existing}', to_jsonb((v_counts ->> 'existing')::int + 1));
      end if;
    end if;
  end loop;

  for v_item in select * from jsonb_array_elements(coalesce(p_package -> 'teacher_classes', '[]'::jsonb)) loop
    if p_dry_run and (v_teacher_ids ? lower(btrim(v_item ->> 'teacher_email')))
      and (v_class_ids ? (lower(btrim(v_item ->> 'class_name')) || '|' || coalesce(nullif(btrim(v_item ->> 'school_year'), ''), v_school_year))) then
      continue;
    end if;

    v_teacher_id := (v_teacher_ids ->> lower(btrim(v_item ->> 'teacher_email')))::uuid;
    v_class_id := (v_class_ids ->> (lower(btrim(v_item ->> 'class_name')) || '|' || coalesce(nullif(btrim(v_item ->> 'school_year'), ''), v_school_year)))::uuid;
    if not p_dry_run and (v_teacher_id is null or v_class_id is null) then
      v_counts := jsonb_set(v_counts, '{invalid}', to_jsonb((v_counts ->> 'invalid')::int + 1));
      continue;
    end if;

    select id into v_link_id
    from public.class_teacher_memberships
    where teacher_id = v_teacher_id
      and class_id = v_class_id
      and status = 'active'
    order by created_at
    limit 1;

    if v_link_id is null and not p_dry_run then
      insert into public.class_teacher_memberships (teacher_id, class_id, role, status)
      values (
        v_teacher_id,
        v_class_id,
        coalesce(nullif(btrim(v_item ->> 'role'), ''), 'principal'),
        'active'
      )
      returning id into v_link_id;
      v_counts := jsonb_set(v_counts, '{teacher_links_created}', to_jsonb((v_counts ->> 'teacher_links_created')::int + 1));
    elsif v_link_id is not null then
      v_counts := jsonb_set(v_counts, '{existing}', to_jsonb((v_counts ->> 'existing')::int + 1));
    end if;
  end loop;

  for v_item in select * from jsonb_array_elements(coalesce(p_package -> 'guardians', '[]'::jsonb)) loop
    v_key := lower(coalesce(nullif(btrim(v_item ->> 'email'), ''), btrim(v_item ->> 'guardian_name')));
    if p_dry_run and (v_student_ids ? lower(btrim(v_item ->> 'student_reference'))) then
      continue;
    end if;

    v_student_id := (v_student_ids ->> lower(btrim(v_item ->> 'student_reference')))::uuid;
    if nullif(btrim(v_item ->> 'guardian_name'), '') is null or (not p_dry_run and v_student_id is null) then
      v_counts := jsonb_set(v_counts, '{invalid}', to_jsonb((v_counts ->> 'invalid')::int + 1));
      continue;
    end if;

    select id into v_guardian_id
    from public.guardians
    where school_id = p_school_id
      and lower(coalesce(nullif(btrim(email), ''), btrim(full_name))) = v_key
      and status <> 'archived'
    order by created_at
    limit 1;

    if v_guardian_id is null and not p_dry_run then
      insert into public.guardians (school_id, profile_id, full_name, email, phone, status, access_status)
      values (
        p_school_id,
        null,
        btrim(v_item ->> 'guardian_name'),
        nullif(btrim(v_item ->> 'email'), ''),
        nullif(btrim(v_item ->> 'phone'), ''),
        coalesce(nullif(btrim(v_item ->> 'status'), ''), 'active'),
        'not_configured'
      )
      returning id into v_guardian_id;
      v_counts := jsonb_set(v_counts, '{guardians_created}', to_jsonb((v_counts ->> 'guardians_created')::int + 1));
    elsif v_guardian_id is not null then
      v_counts := jsonb_set(v_counts, '{existing}', to_jsonb((v_counts ->> 'existing')::int + 1));
    end if;

    if v_guardian_id is not null then
      v_guardian_ids := jsonb_set(v_guardian_ids, array[v_key], to_jsonb(v_guardian_id::text), true);

      select id into v_link_id
      from public.student_guardian_links
      where student_id = v_student_id
        and guardian_id = v_guardian_id
        and relationship = coalesce(nullif(btrim(v_item ->> 'relationship'), ''), 'responsavel')
        and status = 'active'
      order by created_at
      limit 1;

      if v_link_id is null and not p_dry_run then
        insert into public.student_guardian_links (student_id, guardian_id, relationship, is_primary, status)
        values (
          v_student_id,
          v_guardian_id,
          coalesce(nullif(btrim(v_item ->> 'relationship'), ''), 'responsavel'),
          coalesce((v_item ->> 'is_primary')::boolean, false),
          'active'
        )
        returning id into v_link_id;
        v_counts := jsonb_set(v_counts, '{family_links_created}', to_jsonb((v_counts ->> 'family_links_created')::int + 1));
      elsif v_link_id is not null then
        v_counts := jsonb_set(v_counts, '{existing}', to_jsonb((v_counts ->> 'existing')::int + 1));
      end if;
    end if;
  end loop;

  if (v_counts ->> 'invalid')::int > 0 then
    if not p_dry_run then
      raise exception 'Pacote contem registros invalidos.' using errcode = '22023';
    end if;
  end if;

  if not p_dry_run then
    update public.rs_school_installations
       set current_stage = case
             when (v_counts ->> 'classes_created')::int > 0
              and (v_counts ->> 'teachers_created')::int > 0
              and (v_counts ->> 'students_created')::int > 0
              and (v_counts ->> 'enrollments_created')::int > 0
              and (v_counts ->> 'guardians_created')::int > 0
              and (v_counts ->> 'family_links_created')::int > 0
             then 'pronta_para_validacao'
             else 'dados_parciais'
           end,
           validation_status = 'pending',
           updated_at = now()
     where school_id = p_school_id;

    insert into public.admin_school_deployment_events (
      admin_user_id,
      school_id,
      school_code,
      action,
      stage,
      result,
      reason
    ) values (
      v_admin_user_id,
      p_school_id,
      v_school_code,
      'school_import_confirmed',
      'dados_parciais',
      'created',
      jsonb_build_object(
        'package', v_package_version,
        'processed', jsonb_array_length(coalesce(p_package -> 'classes', '[]'::jsonb))
          + jsonb_array_length(coalesce(p_package -> 'teachers', '[]'::jsonb))
          + jsonb_array_length(coalesce(p_package -> 'teacher_classes', '[]'::jsonb))
          + jsonb_array_length(coalesce(p_package -> 'students', '[]'::jsonb))
          + jsonb_array_length(coalesce(p_package -> 'guardians', '[]'::jsonb)),
        'created', v_counts,
        'failures', 0
      )::text
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'dry_run', p_dry_run,
    'school_id', p_school_id,
    'school_code', v_school_code,
    'school_year', v_school_year,
    'package_version', v_package_version,
    'counts', v_counts
  );
end;
$$;


ALTER FUNCTION "public"."admin_confirm_rs_school_import"("p_school_id" "uuid", "p_package" "jsonb", "p_dry_run" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_confirm_rs_school_import"("p_school_id" "uuid", "p_package" "jsonb", "p_dry_run" boolean) IS 'Admin/TI assisted RS-SCHOOL V1 import. Validates a controlled package, imports institutional records idempotently, and does not create Auth users or secrets.';



CREATE OR REPLACE FUNCTION "public"."admin_create_school"("p_nome" "text", "p_school_code" "text", "p_school_year" "text", "p_municipio" "text" DEFAULT NULL::"text", "p_estado" "text" DEFAULT NULL::"text", "p_diretor" "text" DEFAULT NULL::"text", "p_deployment_mode" "text" DEFAULT 'test'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_admin_user_id uuid := auth.uid();
  v_admin_role text;
  v_nome text := nullif(btrim(p_nome), '');
  v_school_code text := nullif(btrim(p_school_code), '');
  v_school_year text := nullif(btrim(p_school_year), '');
  v_deployment_mode text := coalesce(nullif(btrim(p_deployment_mode), ''), 'test');
  v_municipio text := nullif(btrim(p_municipio), '');
  v_estado text := nullif(btrim(p_estado), '');
  v_diretor text := nullif(btrim(p_diretor), '');
  v_school_id uuid;
  v_installation_id uuid;
BEGIN
  IF v_admin_user_id IS NULL THEN
    RAISE EXCEPTION 'Sessao autenticada obrigatoria.' USING ERRCODE = '42501';
  END IF;

  SELECT lower(platform_role)
    INTO v_admin_role
  FROM public.profiles
  WHERE id = v_admin_user_id
    AND status = 'active';

  IF v_admin_role NOT IN ('admin', 'admin_ti', 'administrador', 'administrador_nacional') THEN
    RAISE EXCEPTION 'Perfil Admin/TI obrigatorio para criar escola.' USING ERRCODE = '42501';
  END IF;

  IF v_nome IS NULL OR v_school_code IS NULL OR v_school_year IS NULL THEN
    RAISE EXCEPTION 'Nome, codigo institucional e ano letivo inicial sao obrigatorios.' USING ERRCODE = '22023';
  END IF;

  IF v_deployment_mode NOT IN ('production', 'pilot', 'demo', 'test') THEN
    RAISE EXCEPTION 'Modo de implantacao invalido.' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.schools s
    WHERE lower(btrim(s.nome)) = lower(v_nome)
       OR lower(btrim(coalesce(s.codigo_inep, ''))) = lower(v_school_code)
  ) OR EXISTS (
    SELECT 1
    FROM public.rs_school_installations i
    WHERE lower(btrim(i.school_code)) = lower(v_school_code)
  ) THEN
    INSERT INTO public.admin_school_deployment_events (
      admin_user_id,
      school_code,
      action,
      stage,
      result,
      reason
    ) VALUES (
      v_admin_user_id,
      v_school_code,
      'duplicate_blocked',
      'em_configuracao',
      'blocked',
      'duplicate_school_or_code'
    );

    RAISE EXCEPTION 'Escola ou codigo institucional ja existe.' USING ERRCODE = '23505';
  END IF;

  INSERT INTO public.schools (
    nome,
    codigo_inep,
    municipio,
    estado,
    diretor,
    status
  ) VALUES (
    v_nome,
    v_school_code,
    v_municipio,
    v_estado,
    v_diretor,
    'inactive'
  )
  RETURNING id INTO v_school_id;

  INSERT INTO public.rs_school_installations (
    school_id,
    school_code,
    deployment_mode,
    schema_version,
    package_version,
    school_year,
    current_stage,
    validation_status,
    created_by
  ) VALUES (
    v_school_id,
    v_school_code,
    v_deployment_mode,
    'RS-SCHOOL-TEMPLATE V1',
    'RS-SCHOOL-V1-DEPLOYMENT-2026-09-01',
    v_school_year,
    'em_configuracao',
    'pending',
    v_admin_user_id
  )
  RETURNING id INTO v_installation_id;

  INSERT INTO public.admin_school_deployment_events (
    admin_user_id,
    school_id,
    school_code,
    action,
    stage,
    result
  ) VALUES (
    v_admin_user_id,
    v_school_id,
    v_school_code,
    'school_created',
    'em_configuracao',
    'created'
  );

  RETURN jsonb_build_object(
    'ok', true,
    'school_id', v_school_id,
    'installation_id', v_installation_id,
    'school_code', v_school_code,
    'school_year', v_school_year,
    'status', 'inactive',
    'stage', 'em_configuracao'
  );
END;
$$;


ALTER FUNCTION "public"."admin_create_school"("p_nome" "text", "p_school_code" "text", "p_school_year" "text", "p_municipio" "text", "p_estado" "text", "p_diretor" "text", "p_deployment_mode" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_create_school"("p_nome" "text", "p_school_code" "text", "p_school_year" "text", "p_municipio" "text", "p_estado" "text", "p_diretor" "text", "p_deployment_mode" "text") IS 'Admin/TI controlled school creation. Requires active admin profile and creates inactive school plus deployment state and audit event. No secrets.';



CREATE OR REPLACE FUNCTION "public"."admin_finalize_student_credential_provisioning"("p_credential_id" "uuid", "p_auth_user_id" "uuid", "p_technical_email" "text", "p_plain_password" "text", "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_credential public.student_institutional_credentials%rowtype;
  v_student public.students%rowtype;
  v_display_name text;
  v_technical_email text;
begin
  if not (
    length(coalesce(p_plain_password, '')) >= 10
    or coalesce(p_plain_password, '') ~ '^[A-Z]{3,12}-[0-9]{4}$'
  ) then
    raise exception 'WEAK_INITIAL_PASSWORD';
  end if;

  select * into v_credential
  from public.student_institutional_credentials
  where id = p_credential_id
  for update;

  if v_credential.id is null then
    raise exception 'CREDENTIAL_NOT_FOUND';
  end if;

  if public.current_platform_role() <> 'service_role' and not public.secretaria_can_manage_school(v_credential.school_id) then
    raise exception 'UNAUTHORIZED_PROVISIONING' using errcode = '42501';
  end if;

  select * into v_student
  from public.students
  where id = v_credential.student_id
  for update;

  if v_student.id is null then
    raise exception 'STUDENT_NOT_FOUND';
  end if;

  v_display_name := coalesce(nullif(btrim(v_student.nome), ''), v_credential.login);
  v_technical_email := lower(nullif(btrim(p_technical_email), ''));

  insert into public.users (id, nome, email, perfil, school_id, class_id, ativo)
  values (
    p_auth_user_id,
    v_display_name,
    v_technical_email,
    'aluno',
    v_student.school_id,
    v_student.class_id,
    true
  )
  on conflict (id) do update
  set nome = excluded.nome,
      email = excluded.email,
      perfil = 'aluno',
      school_id = excluded.school_id,
      class_id = excluded.class_id,
      ativo = true;

  insert into public.profiles (id, display_name, platform_role, status)
  values (p_auth_user_id, v_display_name, 'aluno', 'active')
  on conflict (id) do update
  set display_name = excluded.display_name,
      platform_role = 'aluno',
      status = 'active',
      updated_at = now();

  update public.students
  set user_id = p_auth_user_id,
      updated_at = now()
  where id = v_credential.student_id;

  update public.student_institutional_credentials
  set auth_user_id = p_auth_user_id,
      technical_email = v_technical_email,
      password_hash = extensions.crypt(p_plain_password, extensions.gen_salt('bf', 10)),
      password_hash_algorithm = 'pgcrypto_bf',
      password_version = password_version + 1,
      status = 'active',
      technical_auth_created_at = coalesce(technical_auth_created_at, now()),
      password_changed_at = now(),
      last_reset_at = coalesce(last_reset_at, now()),
      blocked_at = null,
      unblocked_at = null,
      updated_at = now()
  where id = v_credential.id
  returning * into v_credential;

  insert into public.student_credential_events (
    credential_id,
    student_id,
    school_id,
    actor_profile_id,
    action,
    result,
    metadata
  ) values (
    v_credential.id,
    v_credential.student_id,
    v_credential.school_id,
    coalesce(p_actor_id, auth.uid()),
    'CREDENTIAL_CREATED',
    'success',
    jsonb_build_object('login', v_credential.login)
  );

  return jsonb_build_object(
    'ok', true,
    'credential_id', v_credential.id,
    'student_id', v_credential.student_id,
    'school_id', v_credential.school_id,
    'login', v_credential.login,
    'status', v_credential.status,
    'auth_user_id', v_credential.auth_user_id
  );
end;
$_$;


ALTER FUNCTION "public"."admin_finalize_student_credential_provisioning"("p_credential_id" "uuid", "p_auth_user_id" "uuid", "p_technical_email" "text", "p_plain_password" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_get_habite_se_settings"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_ai jsonb := '[]'::jsonb;
  v_live jsonb := '[]'::jsonb;
  v_sso jsonb := '[]'::jsonb;
begin
  if not public.is_platform_admin() then
    raise exception 'ADMIN_REQUIRED';
  end if;

  if to_regclass('public.ai_provider_configs') is not null then
    select coalesce(jsonb_agg(jsonb_build_object(
      'label', provider_label,
      'status', case when status = 'configured' then 'CONFIGURADO' else 'AGUARDANDO CONFIGURACAO' end
    ) order by provider_label), '[]'::jsonb)
    into v_ai
    from public.ai_provider_configs;
  end if;

  if to_regclass('public.live_provider_settings') is not null then
    select coalesce(jsonb_agg(jsonb_build_object(
      'label', coalesce(provider, 'Aulas ao vivo'),
      'status', case when provider_status = 'PASS' and secret_configured then 'CONFIGURADO' else 'AGUARDANDO CONFIGURACAO' end
    ) order by provider), '[]'::jsonb)
    into v_live
    from public.live_provider_settings;
  end if;

  if to_regclass('public.integration_sso_providers') is not null then
    select coalesce(jsonb_agg(jsonb_build_object(
      'label', provider,
      'status', case when status = 'configured' then 'CONFIGURADO' else 'AGUARDANDO CONFIGURACAO' end
    ) order by provider), '[]'::jsonb)
    into v_sso
    from public.integration_sso_providers;
  end if;

  return jsonb_build_object(
    'institutional', (
      select jsonb_build_object(
        'schools_total', count(*),
        'schools_active', count(*) filter (where status = 'active'),
        'states', coalesce(jsonb_agg(distinct estado) filter (where estado is not null), '[]'::jsonb)
      )
      from public.schools
    ),
    'communication_permissions', (
      select jsonb_build_object(
        'configured_schools', count(*),
        'student_to_student_default', 'BLOQUEADO',
        'student_to_student_enabled_schools', count(*) filter (where student_student_enabled)
      )
      from public.communication_permission_settings
    ),
    'gamification', (
      select jsonb_build_object(
        'settings_rows', count(*),
        'ranking_enabled_schools', count(*) filter (where rankings_enabled),
        'store_enabled_schools', count(*) filter (where store_enabled)
      )
      from public.gamification_settings
    ),
    'sla', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'priority', priority,
        'first_response_minutes', first_response_minutes,
        'resolution_minutes', resolution_minutes,
        'status', status
      ) order by case priority when 'urgente' then 1 when 'alta' then 2 when 'normal' then 3 else 4 end), '[]'::jsonb)
      from public.support_sla_policies
    ),
    'avalia_plus', jsonb_build_object(
      'item_bank', case when to_regclass('public.assessment_item_bank') is not null or to_regclass('public.question_items') is not null then 'CONFIGURADO' else 'AGUARDANDO CONFIGURACAO' end,
      'printed_offline', case when to_regclass('public.assessment_print_batches') is not null or to_regclass('public.assessment_offline_import_batches') is not null then 'CONFIGURADO' else 'AGUARDANDO CONFIGURACAO' end,
      'tri', case when to_regclass('public.assessment_irt_calibrations') is not null then 'CONFIGURADO' else 'AGUARDANDO CONFIGURACAO' end
    ),
    'external_services', jsonb_build_array(
      jsonb_build_object('label', 'IA Pedagógica', 'status', case when jsonb_array_length(v_ai) > 0 then 'CONFIGURADO' else 'AGUARDANDO CONFIGURACAO' end, 'items', v_ai),
      jsonb_build_object('label', 'OCR', 'status', 'AGUARDANDO CONFIGURACAO'),
      jsonb_build_object('label', 'Aulas ao vivo', 'status', case when jsonb_array_length(v_live) > 0 then 'CONFIGURADO' else 'AGUARDANDO CONFIGURACAO' end, 'items', v_live),
      jsonb_build_object('label', 'SSO', 'status', case when jsonb_array_length(v_sso) > 0 then 'CONFIGURADO' else 'AGUARDANDO CONFIGURACAO' end, 'items', v_sso),
      jsonb_build_object('label', 'HLS/CDN', 'status', 'AGUARDANDO CONFIGURACAO')
    )
  );
end;
$$;


ALTER FUNCTION "public"."admin_get_habite_se_settings"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_list_audit_events"("p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_user_id" "uuid" DEFAULT NULL::"uuid", "p_role" "text" DEFAULT NULL::"text", "p_school_id" "uuid" DEFAULT NULL::"uuid", "p_module" "text" DEFAULT NULL::"text", "p_action" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_limit integer := least(greatest(coalesce(p_limit, 100), 1), 300);
begin
  if not public.is_platform_admin() then
    raise exception 'ADMIN_REQUIRED';
  end if;

  return (
    with events as (
      select
        e.created_at,
        e.actor_profile_id as actor_id,
        coalesce(p.display_name, e.actor_profile_id::text, 'Sistema') as actor_name,
        coalesce(e.actor_role, p.platform_role, 'sistema') as actor_role,
        e.school_id,
        s.nome as school_name,
        e.module,
        e.action,
        e.result,
        e.details
      from public.admin_operational_audit_events e
      left join public.profiles p on p.id = e.actor_profile_id
      left join public.schools s on s.id = e.school_id

      union all

      select
        ce.created_at,
        ce.performed_by,
        coalesce(p.display_name, ce.performed_by::text, 'Sistema'),
        coalesce(p.platform_role, 'sistema'),
        c.school_id,
        s.nome,
        'comunicacoes',
        ce.event_type,
        coalesce(ce.to_status, ce.from_status, 'success'),
        jsonb_build_object('communication_id', ce.communication_id)
      from public.communication_events ce
      join public.communications c on c.id = ce.communication_id
      left join public.profiles p on p.id = ce.performed_by
      left join public.schools s on s.id = c.school_id

      union all

      select
        em.created_at,
        em.performed_by,
        coalesce(p.display_name, em.performed_by::text, 'Sistema'),
        coalesce(p.platform_role, 'sistema'),
        em.school_id,
        s.nome,
        'matriculas',
        em.movement_type,
        coalesce(em.to_status, 'success'),
        jsonb_build_object('student_id', em.student_id, 'enrollment_id', em.enrollment_id, 'reason', em.reason)
      from public.enrollment_movements em
      left join public.profiles p on p.id = em.performed_by
      left join public.schools s on s.id = em.school_id

      union all

      select
        de.created_at,
        de.admin_user_id,
        coalesce(p.display_name, de.admin_user_id::text, 'Sistema'),
        coalesce(p.platform_role, 'admin'),
        de.school_id,
        s.nome,
        'implantacao',
        de.action,
        de.result,
        jsonb_build_object('stage', de.stage, 'school_code', de.school_code, 'reason', de.reason)
      from public.admin_school_deployment_events de
      left join public.profiles p on p.id = de.admin_user_id
      left join public.schools s on s.id = de.school_id

      union all

      select
        se.created_at,
        se.actor_profile_id,
        coalesce(p.display_name, se.actor_profile_id::text, 'Sistema'),
        coalesce(p.platform_role, 'suporte'),
        st.school_id,
        s.nome,
        'suporte',
        se.event_type,
        coalesce(se.to_status, se.from_status, 'success'),
        se.details || jsonb_build_object('ticket_id', se.ticket_id, 'protocol', st.protocol)
      from public.support_ticket_events se
      join public.support_tickets st on st.id = se.ticket_id
      left join public.profiles p on p.id = se.actor_profile_id
      left join public.schools s on s.id = st.school_id

      union all

      select
        il.created_at,
        null::uuid,
        'API Institucional',
        'integracao',
        il.school_id,
        s.nome,
        'integracoes',
        il.method || ' ' || il.endpoint,
        case when il.status_code between 200 and 299 then 'success' else 'failed' end,
        jsonb_build_object('status_code', il.status_code, 'client_id', il.client_id)
      from public.integration_api_audit_logs il
      left join public.schools s on s.id = il.school_id
    ),
    filtered as (
      select *
      from events
      where (p_from is null or created_at >= p_from)
        and (p_to is null or created_at <= p_to)
        and (p_user_id is null or actor_id = p_user_id)
        and (p_role is null or p_role = '' or lower(actor_role) = lower(p_role))
        and (p_school_id is null or school_id = p_school_id)
        and (p_module is null or p_module = '' or lower(module) = lower(p_module))
        and (p_action is null or p_action = '' or action ilike '%' || p_action || '%')
      order by created_at desc
      limit v_limit
    )
    select coalesce(jsonb_agg(jsonb_build_object(
      'created_at', created_at,
      'actor_id', actor_id,
      'actor_name', actor_name,
      'actor_role', actor_role,
      'school_id', school_id,
      'school_name', school_name,
      'module', module,
      'action', action,
      'result', result,
      'details', details
    ) order by created_at desc), '[]'::jsonb)
    from filtered
  );
end;
$$;


ALTER FUNCTION "public"."admin_list_audit_events"("p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_user_id" "uuid", "p_role" "text", "p_school_id" "uuid", "p_module" "text", "p_action" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_list_auth_users"() RETURNS TABLE("auth_user_id" "uuid", "email" "text", "email_confirmed" boolean, "last_sign_in_at" timestamp with time zone, "created_at" timestamp with time zone, "banned_until" timestamp with time zone, "deleted_at" timestamp with time zone, "auth_status" "text", "auth_platform_role" "text", "profile_id" "uuid", "display_name" "text", "platform_role" "text", "profile_status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Usuario autenticado obrigatorio para listar acessos Auth.'
      USING ERRCODE = '42501';
  END IF;

  IF NOT (
    public.is_platform_admin()
    OR EXISTS (
      SELECT 1
      FROM public.profiles caller_profile
      WHERE caller_profile.id = auth.uid()
        AND caller_profile.status = 'active'
        AND caller_profile.platform_role = ANY (ARRAY[
          'admin',
          'admin_ti',
          'administrador',
          'administrador_nacional',
          'ti'
        ])
    )
  ) THEN
    RAISE EXCEPTION 'Acesso restrito ao Admin/TI.'
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    au.id AS auth_user_id,
    au.email::text AS email,
    (COALESCE(au.email_confirmed_at, au.confirmed_at) IS NOT NULL) AS email_confirmed,
    au.last_sign_in_at,
    au.created_at,
    au.banned_until,
    au.deleted_at,
    CASE
      WHEN au.deleted_at IS NOT NULL THEN 'deleted'
      WHEN au.banned_until IS NOT NULL AND au.banned_until > now() THEN 'banned'
      WHEN COALESCE(au.email_confirmed_at, au.confirmed_at) IS NULL THEN 'pending_confirmation'
      ELSE 'active'
    END::text AS auth_status,
    NULLIF(au.raw_app_meta_data ->> 'platform_role', '')::text AS auth_platform_role,
    p.id AS profile_id,
    p.display_name,
    p.platform_role,
    p.status AS profile_status
  FROM auth.users au
  LEFT JOIN public.profiles p ON p.id = au.id
  ORDER BY lower(au.email::text) ASC NULLS LAST, au.created_at DESC;
END;
$$;


ALTER FUNCTION "public"."admin_list_auth_users"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_list_auth_users"() IS 'Admin-only read RPC exposing minimal Auth user status for the Admin/TI console.';


