    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "feature_key" "text" NOT NULL,
    "role_key" "text" NOT NULL,
    "permission_scope" "text" NOT NULL,
    "enabled" boolean DEFAULT false NOT NULL,
    "locked" boolean DEFAULT false NOT NULL,
    "description" "text",
    "updated_by" "uuid" DEFAULT "auth"."uid"(),
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "admin_feature_permission_flags_role_check" CHECK (("role_key" = ANY (ARRAY['admin'::"text", 'secretaria'::"text", 'gestor'::"text", 'rede_municipal'::"text", 'professor'::"text", 'aluno'::"text", 'familia'::"text"]))),
    CONSTRAINT "admin_feature_permission_flags_scope_check" CHECK (("permission_scope" = ANY (ARRAY['administrar'::"text", 'utilizar'::"text"])))
);


