CREATE OR REPLACE FUNCTION "public"."admin_list_students_without_credentials"("p_school_id" "uuid" DEFAULT NULL::"uuid", "p_class_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 1000) RETURNS TABLE("student_id" "uuid", "school_id" "uuid", "class_id" "uuid", "student_name" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if p_school_id is null and p_class_id is null then
    raise exception 'SCHOOL_OR_CLASS_REQUIRED';
  end if;

  if p_school_id is not null and public.current_platform_role() <> 'service_role' and not public.secretaria_can_manage_school(p_school_id) then
    raise exception 'UNAUTHORIZED_PROVISIONING' using errcode = '42501';
  end if;

  if p_class_id is not null and public.current_platform_role() <> 'service_role' and not exists (
    select 1
    from public.classes c
    where c.id = p_class_id
      and public.secretaria_can_manage_school(c.school_id)
  ) then
    raise exception 'UNAUTHORIZED_PROVISIONING' using errcode = '42501';
  end if;

  return query
  select s.id, s.school_id, s.class_id, s.nome::text
  from public.students s
  left join public.student_institutional_credentials sic
    on sic.student_id = s.id
  where (p_school_id is null or s.school_id = p_school_id)
    and (p_class_id is null or s.class_id = p_class_id)
    and coalesce(lower(s.status), 'ativo') in ('ativo', 'active')
    and (
      sic.id is null
      or lower(coalesce(sic.status, '')) = 'pending_auth'
    )
  order by s.nome nulls last, s.created_at
  limit greatest(1, least(coalesce(p_limit, 1000), 5000));
end;
$$;


ALTER FUNCTION "public"."admin_list_students_without_credentials"("p_school_id" "uuid", "p_class_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_log_access_recovery_event"("p_target_auth_user_id" "uuid", "p_target_email" "text", "p_result" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_admin_user_id uuid := auth.uid();
  v_event_id uuid;
BEGIN
  IF v_admin_user_id IS NULL THEN
    RAISE EXCEPTION 'Usuario autenticado obrigatorio para registrar recuperacao de acesso.'
      USING ERRCODE = '42501';
  END IF;

  IF NOT (
    public.is_platform_admin()
    OR EXISTS (
      SELECT 1
      FROM public.profiles caller_profile
      WHERE caller_profile.id = v_admin_user_id
        AND caller_profile.status = 'active'
        AND caller_profile.platform_role = ANY (ARRAY[
          'admin',
          'admin_ti',
          'administrador',
          'administrador_nacional',
          'ti'
        ])
    )
  ) THEN
    RAISE EXCEPTION 'Acesso restrito ao Admin/TI.'
      USING ERRCODE = '42501';
  END IF;

  IF p_target_auth_user_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM auth.users au WHERE au.id = p_target_auth_user_id
  ) THEN
    RAISE EXCEPTION 'Usuario Auth alvo inexistente.'
      USING ERRCODE = '23503';
  END IF;

  INSERT INTO public.admin_access_recovery_events (
    admin_user_id,
    target_auth_user_id,
    target_email,
    result
  )
  VALUES (
    v_admin_user_id,
    p_target_auth_user_id,
    lower(btrim(p_target_email)),
    CASE WHEN p_result = 'sent' THEN 'sent' ELSE 'failed' END
  )
  RETURNING id INTO v_event_id;

  RETURN v_event_id;
END;
$$;


ALTER FUNCTION "public"."admin_log_access_recovery_event"("p_target_auth_user_id" "uuid", "p_target_email" "text", "p_result" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_log_access_recovery_event"("p_target_auth_user_id" "uuid", "p_target_email" "text", "p_result" "text") IS 'Admin-only audit RPC for password recovery requests; does not expose password or token data.';



CREATE OR REPLACE FUNCTION "public"."admin_manage_school_lifecycle"("p_school_id" "uuid", "p_action" "text", "p_confirmation_code" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_admin_user_id uuid := auth.uid();
  v_admin_role text;
  v_school public.schools%rowtype;
  v_installation public.rs_school_installations%rowtype;
  v_action text := lower(btrim(coalesce(p_action, '')));
  v_school_code text;
  v_dependencies jsonb := '{}'::jsonb;
  v_dependency_total integer := 0;
  v_count integer := 0;
  v_result jsonb;
begin
  if v_admin_user_id is null then
    raise exception 'Usuario autenticado obrigatorio.' using errcode = '42501';
  end if;

  select p.platform_role
    into v_admin_role
    from public.profiles p
   where p.id = v_admin_user_id
     and p.status = 'active';

  if coalesce(v_admin_role, '') not in ('admin', 'admin_ti', 'administrador', 'administrador_nacional') then
    raise exception 'Perfil sem permissao administrativa para ciclo de vida da escola.' using errcode = '42501';
  end if;

  select *
    into v_school
    from public.schools s
   where s.id = p_school_id
   for update;

  if v_school.id is null then
    raise exception 'Escola nao encontrada.' using errcode = '22023';
  end if;

  select *
    into v_installation
    from public.rs_school_installations i
   where i.school_id = p_school_id
   for update;

  v_school_code := coalesce(v_installation.school_code, v_school.codigo_inep, v_school.nome);

  if v_action in ('deactivate', 'desativar') then
    update public.schools
       set status = 'inactive',
           updated_at = now()
     where id = p_school_id;

    update public.rs_school_installations
       set current_stage = 'arquivada',
           updated_at = now()
     where school_id = p_school_id;

    insert into public.admin_school_deployment_events (
      admin_user_id, school_id, school_code, action, stage, result, reason
    ) values (
      v_admin_user_id,
      p_school_id,
      v_school_code,
      'school_deactivated',
      'arquivada',
      'created',
      jsonb_build_object('previous_status', v_school.status, 'preserve_history', true)::text
    );

    return jsonb_build_object(
      'ok', true,
      'action', 'deactivate',
      'school_id', p_school_id,
      'status', 'inactive',
      'stage', 'arquivada'
    );
  end if;

  if v_action in ('reactivate', 'reativar') then
    update public.schools
       set status = 'active',
           updated_at = now()
     where id = p_school_id;

    update public.rs_school_installations
       set current_stage = case
             when validation_status = 'passed' then 'ativa'
             else coalesce(nullif(current_stage, 'arquivada'), 'em_configuracao')
           end,
           updated_at = now()
     where school_id = p_school_id;

    insert into public.admin_school_deployment_events (
      admin_user_id, school_id, school_code, action, stage, result, reason
    ) values (
      v_admin_user_id,
      p_school_id,
      v_school_code,
      'school_reactivated',
      case when coalesce(v_installation.validation_status, '') = 'passed' then 'ativa' else 'em_configuracao' end,
      'created',
      jsonb_build_object('previous_status', v_school.status)::text
    );

    return jsonb_build_object(
      'ok', true,
      'action', 'reactivate',
      'school_id', p_school_id,
      'status', 'active'
    );
  end if;

  if v_action not in ('delete', 'excluir') then
    raise exception 'Ação de ciclo de vida não reconhecida.' using errcode = '22023';
  end if;

  select count(*) into v_count from public.classes where school_id = p_school_id and coalesce(status, 'active') <> 'archived';
  v_dependencies := v_dependencies || jsonb_build_object('classes', v_count);
  v_dependency_total := v_dependency_total + v_count;

  select count(*) into v_count from public.enrollments where school_id = p_school_id and coalesce(status, 'active') <> 'archived';
  v_dependencies := v_dependencies || jsonb_build_object('enrollments', v_count);
  v_dependency_total := v_dependency_total + v_count;

  select count(*) into v_count from public.students where school_id = p_school_id and coalesce(status, 'active') <> 'archived';
  v_dependencies := v_dependencies || jsonb_build_object('students', v_count);
  v_dependency_total := v_dependency_total + v_count;

  select count(*) into v_count from public.teachers where school_id = p_school_id and coalesce(status, 'active') <> 'archived';
  v_dependencies := v_dependencies || jsonb_build_object('teachers', v_count);
  v_dependency_total := v_dependency_total + v_count;

  select count(*) into v_count from public.guardians where school_id = p_school_id and coalesce(status, 'active') <> 'archived';
  v_dependencies := v_dependencies || jsonb_build_object('guardians', v_count);
  v_dependency_total := v_dependency_total + v_count;

  select count(*) into v_count
    from public.student_guardian_links sgl
    join public.students s on s.id = sgl.student_id
   where s.school_id = p_school_id
     and coalesce(sgl.status, 'active') <> 'archived';
  v_dependencies := v_dependencies || jsonb_build_object('guardian_student_links', v_count);
  v_dependency_total := v_dependency_total + v_count;

  select count(*) into v_count from public.school_memberships where school_id = p_school_id and coalesce(status, 'active') <> 'archived';
  v_dependencies := v_dependencies || jsonb_build_object('school_memberships', v_count);
  v_dependency_total := v_dependency_total + v_count;

  select count(*) into v_count from public.admin_school_deployment_events where school_id = p_school_id;
  v_dependencies := v_dependencies || jsonb_build_object('audit_events', v_count);
  v_dependency_total := v_dependency_total + v_count;

  if to_regclass('public.communications') is not null then
    execute 'select count(*) from public.communications where school_id = $1 and coalesce(status, ''active'') <> ''deleted'''
      into v_count using p_school_id;
    v_dependencies := v_dependencies || jsonb_build_object('communications', v_count);
    v_dependency_total := v_dependency_total + v_count;
  end if;

  if to_regclass('public.assessment_assignments') is not null then
    execute 'select count(*) from public.assessment_assignments where school_id = $1'
      into v_count using p_school_id;
    v_dependencies := v_dependencies || jsonb_build_object('assessments', v_count);
    v_dependency_total := v_dependency_total + v_count;
  end if;

  if to_regclass('public.school_content_availability') is not null then
    execute 'select count(*) from public.school_content_availability where school_id = $1 and deleted_at is null'
      into v_count using p_school_id;
    v_dependencies := v_dependencies || jsonb_build_object('content_links', v_count);
    v_dependency_total := v_dependency_total + v_count;
  end if;

  insert into public.admin_school_deployment_events (
    admin_user_id, school_id, school_code, action, stage, result, reason
  ) values (
    v_admin_user_id,
    case when v_dependency_total > 0 then p_school_id else null end,
    v_school_code,
    'school_delete_attempt',
    coalesce(v_installation.current_stage, 'em_configuracao'),
    case when v_dependency_total > 0 then 'blocked' else 'created' end,
    jsonb_build_object('dependencies', v_dependencies, 'dependency_total', v_dependency_total)::text
  );

  if v_dependency_total > 0 then
    insert into public.admin_school_deployment_events (
      admin_user_id, school_id, school_code, action, stage, result, reason
    ) values (
      v_admin_user_id,
      p_school_id,
      v_school_code,
      'school_delete_blocked',
      coalesce(v_installation.current_stage, 'em_configuracao'),
      'blocked',
      jsonb_build_object('delete_blocked', true, 'dependencies', v_dependencies, 'dependency_total', v_dependency_total)::text
    );

    return jsonb_build_object(
      'ok', false,
      'action', 'delete',
      'status', 'DELETE_BLOCKED',
      'school_id', p_school_id,
      'dependencies', v_dependencies,
      'dependency_total', v_dependency_total,
      'message', 'Exclusão bloqueada: a escola possui dependências institucionais.'
    );
  end if;

  if nullif(btrim(coalesce(p_confirmation_code, '')), '') is null
    or btrim(p_confirmation_code) <> coalesce(v_school.codigo_inep, v_school.nome) then
    return jsonb_build_object(
      'ok', false,
      'action', 'delete',
      'status', 'CONFIRMATION_REQUIRED',
      'school_id', p_school_id,
      'required_confirmation', coalesce(v_school.codigo_inep, v_school.nome),
      'message', 'Digite exatamente o código institucional da escola para confirmar a exclusão.'
    );
  end if;

  v_result := jsonb_build_object(
    'ok', true,
    'action', 'delete',
    'status', 'deleted',
    'school_id', p_school_id,
    'school_code', v_school_code
  );

  insert into public.admin_school_deployment_events (
    admin_user_id, school_id, school_code, action, stage, result, reason
  ) values (
    v_admin_user_id,
    null,
    v_school_code,
    'school_deleted',
    'arquivada',
    'created',
    jsonb_build_object('deleted_school_id', p_school_id, 'school_name', v_school.nome)::text
  );

  delete from public.rs_school_installations where school_id = p_school_id;
  delete from public.schools where id = p_school_id;

  return v_result;
end;
$_$;


ALTER FUNCTION "public"."admin_manage_school_lifecycle"("p_school_id" "uuid", "p_action" "text", "p_confirmation_code" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_manage_school_lifecycle"("p_school_id" "uuid", "p_action" "text", "p_confirmation_code" "text") IS 'Admin-only lifecycle controls for schools: deactivate/reactivate/delete with dependency checks, strong confirmation and audit trail.';



CREATE OR REPLACE FUNCTION "public"."admin_normalize_guardian_relationship"("p_relationship" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  with normalized as (
    select lower(
      btrim(
        translate(
          coalesce(p_relationship, ''),
          'áàãâäéèêëíìîïóòõôöúùûüçÁÀÃÂÄÉÈÊËÍÌÎÏÓÒÕÔÖÚÙÛÜÇ',
          'aaaaaeeeeiiiiooooouuuucAAAAAEEEEIIIIOOOOOUUUUC'
        )
      )
    ) as value
  )
  select case
    when value = '' then null
    when value in ('responsavel', 'responsaveis', 'responsavel_legal', 'guardiao', 'guardia', 'responsavel_financeiro') then 'responsavel'
    when value in ('mae', 'mamae', 'genitora') then 'mae'
    when value in ('pai', 'papai', 'genitor') then 'pai'
    when value in ('avo', 'avoo') then 'avo'
    when value in ('tutor', 'tutora', 'curador', 'curadora') then 'tutor'
    when value in ('outro', 'outra') then 'outro'
    else null
  end
  from normalized;
$$;


ALTER FUNCTION "public"."admin_normalize_guardian_relationship"("p_relationship" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_normalize_guardian_relationship"("p_relationship" "text") IS 'Normaliza parentesco amigavel de planilhas para o contrato canonico student_guardian_links.relationship.';



CREATE OR REPLACE FUNCTION "public"."admin_prepare_student_credential_provisioning"("p_student_id" "uuid", "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_student public.students%rowtype;
  v_namespace public.school_auth_namespaces%rowtype;
  v_credential public.student_institutional_credentials%rowtype;
  v_sequence bigint;
  v_login text;
  v_reusable_auth_user_id uuid;
begin
  select * into v_student
  from public.students
  where id = p_student_id
  for update;

  if v_student.id is null then
    raise exception 'STUDENT_NOT_FOUND';
  end if;

  if public.current_platform_role() <> 'service_role' and not public.secretaria_can_manage_school(v_student.school_id) then
    raise exception 'UNAUTHORIZED_PROVISIONING' using errcode = '42501';
  end if;

  select * into v_credential
  from public.student_institutional_credentials
  where student_id = p_student_id
  for update;

  if v_credential.id is not null then
    if v_credential.auth_user_id is null and nullif(btrim(v_credential.technical_email), '') is not null then
      select au.id into v_reusable_auth_user_id
      from auth.users au
      where lower(au.email) = lower(v_credential.technical_email)
      order by au.created_at
      limit 1;
    end if;

    insert into public.student_credential_events (
      credential_id,
      student_id,
      school_id,
      actor_profile_id,
      action,
      result,
      metadata
    ) values (
      v_credential.id,
      v_credential.student_id,
      v_credential.school_id,
      coalesce(p_actor_id, auth.uid()),
      'IDEMPOTENT_REPLAY',
      'success',
      jsonb_build_object(
        'login', v_credential.login,
        'status', v_credential.status,
        'auth_reconciled', v_reusable_auth_user_id is not null
      )
    );

    return jsonb_build_object(
      'ok', true,
      'existing', true,
      'credential_id', v_credential.id,
      'student_id', v_credential.student_id,
      'school_id', v_credential.school_id,
      'login', v_credential.login,
      'status', v_credential.status,
      'auth_user_id', coalesce(v_credential.auth_user_id, v_reusable_auth_user_id),
      'technical_email', v_credential.technical_email
    );
  end if;

  perform public.ensure_school_auth_namespace(v_student.school_id, null, coalesce(p_actor_id, auth.uid()));

  select * into v_namespace
  from public.school_auth_namespaces
  where school_id = v_student.school_id
  for update;

  v_sequence := v_namespace.next_sequence;
  v_login := v_namespace.namespace || '-' || lpad(v_sequence::text, 6, '0');

  update public.school_auth_namespaces
  set next_sequence = next_sequence + 1
  where id = v_namespace.id;

  insert into public.student_institutional_credentials (
    student_id,
    school_id,
    namespace_id,
    login,
    sequence_no,
    technical_email,
    status,
    created_by
  ) values (
    v_student.id,
    v_student.school_id,
    v_namespace.id,
    v_login,
    v_sequence,
    lower(v_login) || '@students.raizes.invalid',
    'pending_auth',
    coalesce(p_actor_id, auth.uid())
  )
  returning * into v_credential;

  return jsonb_build_object(
    'ok', true,
    'existing', false,
    'credential_id', v_credential.id,
    'student_id', v_credential.student_id,
    'school_id', v_credential.school_id,
    'login', v_credential.login,
    'status', v_credential.status,
    'technical_email', lower(v_credential.login) || '@students.raizes.invalid'
  );
end;
$$;


ALTER FUNCTION "public"."admin_prepare_student_credential_provisioning"("p_student_id" "uuid", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_preview_network_bulk_import"("p_rows" "jsonb", "p_source_format" "text" DEFAULT 'CSV'::"text", "p_import_type" "text" DEFAULT 'auto'::"text", "p_school_year" "text" DEFAULT '2026'::"text", "p_column_mapping" "jsonb" DEFAULT '{}'::"jsonb", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_batch public.admin_network_bulk_import_batches%rowtype;
  v_row jsonb;
  v_lookup_row jsonb;
  v_row_errors jsonb;
  v_row_number integer := 0;
  v_total integer := 0;
  v_invalid integer := 0;
  v_duplicate integer := 0;
  v_new integer := 0;
  v_updates integer := 0;
  v_unchanged integer := 0;
  v_seen text[] := array[]::text[];
  v_errors jsonb := '[]'::jsonb;
  v_type text;
  v_school_code text;
  v_school_name text;
  v_class_name text;
  v_student_name text;
  v_student_birth text;
  v_teacher_name text;
  v_teacher_email text;
  v_guardian_name text;
  v_guardian_email text;
  v_municipio text;
  v_estado text;
  v_diretor text;
  v_key text;
  v_school_id uuid;
  v_sheet_name text;
  v_batch_school_codes text[] := array[]::text[];
  v_exists boolean;
  v_existing_school_name text;
  v_existing_school_code text;
  v_existing_municipio text;
  v_existing_estado text;
  v_existing_diretor text;
  v_contract_version text := 'network_unified_v1';
  v_effective_idempotency_key text;
  v_counts jsonb := jsonb_build_object(
    'schools', 0,
    'classes', 0,
    'teachers', 0,
    'students', 0,
    'guardians', 0,
    'enrollments', 0,
    'teacher_class_links', 0,
    'guardian_student_links', 0
  );
begin
  if not public.is_platform_admin() then
    raise exception 'Perfil Admin/TI obrigatorio para importar rede.' using errcode = '42501';
  end if;

  if jsonb_typeof(coalesce(p_rows, '[]'::jsonb)) <> 'array' then
    raise exception 'Linhas CSV/XLSX devem chegar como array JSON ja parseado pela interface.' using errcode = '22023';
  end if;

  v_effective_idempotency_key := p_idempotency_key;

  if p_idempotency_key is not null then
    select * into v_batch
    from public.admin_network_bulk_import_batches
    where idempotency_key = p_idempotency_key;

    if v_batch.id is not null and coalesce(v_batch.preview_report ->> 'import_contract_version', '') = v_contract_version then
      return jsonb_build_object(
        'batch_id', v_batch.id,
        'status', v_batch.status,
        'idempotent_replay', true,
        'report', v_batch.preview_report,
        'errors', v_batch.errors
      );
    elsif v_batch.id is not null then
      v_effective_idempotency_key := p_idempotency_key || ':' || v_contract_version;
      select * into v_batch
      from public.admin_network_bulk_import_batches
      where idempotency_key = v_effective_idempotency_key;

      if v_batch.id is not null then
        return jsonb_build_object(
          'batch_id', v_batch.id,
          'status', v_batch.status,
          'idempotent_replay', true,
          'report', v_batch.preview_report,
          'errors', v_batch.errors
        );
      end if;
    end if;
  end if;

  for v_lookup_row in select * from jsonb_array_elements(p_rows) loop
    if nullif(btrim(coalesce(
      v_lookup_row ->> 'nome_escola',
      v_lookup_row ->> 'nome_da_escola',
      v_lookup_row ->> 'school_name',
      v_lookup_row ->> 'Nome da Escola',
      v_lookup_row ->> 'escola'
    )), '') is not null then
      v_school_code := lower(nullif(btrim(coalesce(
        v_lookup_row ->> 'codigo_escola',
        v_lookup_row ->> 'codigo_da_escola',
        v_lookup_row ->> 'school_code',
        v_lookup_row ->> 'codigo_inep',
        v_lookup_row ->> 'codigo',
        v_lookup_row ->> 'Código',
        v_lookup_row ->> 'Codigo'
      )), ''));
      if v_school_code is not null and v_school_code <> all(v_batch_school_codes) then
        v_batch_school_codes := array_append(v_batch_school_codes, v_school_code);
      end if;
    end if;
  end loop;

  for v_row in select * from jsonb_array_elements(p_rows) loop
    v_row_number := v_row_number + 1;
    v_total := v_total + 1;
    v_row_errors := '[]'::jsonb;
    v_sheet_name := nullif(btrim(coalesce(v_row ->> '_aba', v_row ->> 'aba', v_row ->> 'sheet')), '');
    v_type := lower(btrim(coalesce(
      nullif(v_row ->> 'tipo', ''),
      nullif(v_row ->> 'entity_type', ''),
      nullif(v_row ->> 'entidade', ''),
      nullif(v_row ->> 'tipo_de_importacao', ''),
      nullif(p_import_type, ''),
      'auto'
    )));
    v_type := translate(v_type, 'áàãâéêíóôõúç', 'aaaaeeiooouc');
    v_school_code := nullif(btrim(coalesce(
      v_row ->> 'codigo_escola',
      v_row ->> 'codigo_da_escola',
      v_row ->> 'cod_escola',
      v_row ->> 'codigo_unidade',
      v_row ->> 'school_code',
      v_row ->> 'codigo_inep',
      v_row ->> 'cod_inep',
      v_row ->> 'codigo',
      v_row ->> 'Código',
      v_row ->> 'Codigo',
      v_row ->> 'Código da Escola',
      v_row ->> 'Codigo da Escola',
      v_row ->> 'inep'
    )), '');
    v_school_name := nullif(btrim(coalesce(
      v_row ->> 'nome_escola',
      v_row ->> 'nome_da_escola',
      v_row ->> 'nome_unidade',
      v_row ->> 'nome_da_unidade',
      v_row ->> 'unidade_escolar',
      v_row ->> 'school_name',
      v_row ->> 'Nome da Escola',
      v_row ->> 'Nome Escola',
      v_row ->> 'Nome da Unidade',
      v_row ->> 'escola'
    )), '');
    v_class_name := nullif(btrim(coalesce(v_row ->> 'nome_turma', v_row ->> 'nome_da_turma', v_row ->> 'class_name', v_row ->> 'Nome da Turma', v_row ->> 'turma')), '');
    v_student_name := nullif(btrim(coalesce(v_row ->> 'nome_aluno', v_row ->> 'nome_do_aluno', v_row ->> 'student_name', v_row ->> 'Nome do Aluno', v_row ->> 'aluno')), '');
    v_student_birth := nullif(btrim(coalesce(v_row ->> 'data_nascimento', v_row ->> 'data_de_nascimento', v_row ->> 'birth_date', v_row ->> 'Data de Nascimento')), '');
    v_teacher_name := nullif(btrim(coalesce(v_row ->> 'nome_professor', v_row ->> 'nome_do_professor', v_row ->> 'teacher_name', v_row ->> 'Nome do Professor', v_row ->> 'professor')), '');
    v_teacher_email := nullif(btrim(coalesce(v_row ->> 'email_professor', v_row ->> 'email_do_professor', v_row ->> 'e_mail_professor', v_row ->> 'teacher_email', v_row ->> 'E-mail do Professor', v_row ->> 'Email do Professor')), '');
    v_guardian_name := nullif(btrim(coalesce(v_row ->> 'nome_responsavel', v_row ->> 'nome_do_responsavel', v_row ->> 'guardian_name', v_row ->> 'Nome do Responsável', v_row ->> 'Nome do Responsavel', v_row ->> 'responsavel')), '');
    v_guardian_email := nullif(btrim(coalesce(v_row ->> 'email_responsavel', v_row ->> 'email_do_responsavel', v_row ->> 'e_mail_responsavel', v_row ->> 'guardian_email', v_row ->> 'E-mail do Responsável', v_row ->> 'Email do Responsavel')), '');
    v_municipio := nullif(btrim(coalesce(v_row ->> 'municipio', v_row ->> 'Município', v_row ->> 'Municipio', v_row ->> 'cidade', v_row ->> 'city')), '');
    v_estado := nullif(upper(btrim(coalesce(v_row ->> 'estado', v_row ->> 'Estado', v_row ->> 'uf', v_row ->> 'UF'))), '');
    v_diretor := nullif(btrim(coalesce(v_row ->> 'diretor', v_row ->> 'Diretor', v_row ->> 'diretora', v_row ->> 'Diretora', v_row ->> 'principal')), '');

    if v_type = 'auto' then
      v_type := case
        when v_school_name is not null and v_class_name is null and v_student_name is null and v_teacher_name is null and v_guardian_name is null then 'school'
        when v_class_name is not null and v_student_name is null and v_teacher_name is null and v_guardian_name is null then 'class'
        when v_teacher_name is not null and v_class_name is null then 'teacher'
        when v_student_name is not null and v_guardian_name is null then 'student'
        when v_guardian_name is not null and v_student_name is null then 'guardian'
        when v_teacher_name is not null and v_class_name is not null then 'teacher_class_link'
        when v_guardian_name is not null and v_student_name is not null then 'guardian_student_link'
        else 'unknown'
      end;
    end if;

    v_type := case
      when v_type in ('school', 'schools', 'escola', 'escolas') then 'school'
      when v_type in ('class', 'classes', 'turma', 'turmas') then 'class'
      when v_type in ('teacher', 'teachers', 'professor', 'professores') then 'teacher'
      when v_type in ('student', 'students', 'aluno', 'alunos') then 'student'
      when v_type in ('guardian', 'guardians', 'responsavel', 'responsaveis') then 'guardian'
      when v_type in ('enrollment', 'enrollments', 'matricula', 'matriculas') then 'enrollment'
      when v_type in ('teacher_class', 'teacher_class_link', 'vinculo_professor_turma', 'professor_turma') then 'teacher_class_link'
      when v_type in ('guardian_student', 'guardian_student_link', 'vinculo_responsavel_aluno', 'responsavel_aluno') then 'guardian_student_link'
      else v_type
    end;

    if v_type not in ('school', 'class', 'teacher', 'student', 'guardian', 'enrollment', 'teacher_class_link', 'guardian_student_link') then
      v_invalid := v_invalid + 1;
      v_errors := v_errors || jsonb_build_array(jsonb_build_object(
        'sheet', v_sheet_name,
        'row', v_row_number,
        'field', 'Tipo',
        'error', 'UNSUPPORTED_ENTITY',
        'message', 'Tipo de importação não reconhecido. Selecione Escolas, Turmas, Professores, Alunos, Responsáveis, Matrículas ou Vínculos.'
      ));
      continue;
    end if;

    if v_type <> 'school' and v_school_code is null then
      v_row_errors := v_row_errors || jsonb_build_array(jsonb_build_object(
        'sheet', v_sheet_name,
        'row', v_row_number,
        'field', 'Código da Escola',
        'error', 'REQUIRED',
        'message', 'Informe o código da escola para vincular esta linha à unidade correta.'
      ));
    end if;

    if v_type = 'school' then
      if v_school_name is null then
        v_row_errors := v_row_errors || jsonb_build_array(jsonb_build_object('sheet', v_sheet_name, 'row', v_row_number, 'field', 'Nome da Escola', 'error', 'REQUIRED', 'message', 'Informe o nome oficial da escola.'));
      end if;
      if v_school_code is null then
        v_row_errors := v_row_errors || jsonb_build_array(jsonb_build_object('sheet', v_sheet_name, 'row', v_row_number, 'field', 'Código', 'error', 'REQUIRED', 'message', 'Informe um código único para a escola.'));
      end if;
    elsif v_type = 'class' and v_class_name is null then
      v_row_errors := v_row_errors || jsonb_build_array(jsonb_build_object('sheet', v_sheet_name, 'row', v_row_number, 'field', 'Nome da Turma', 'error', 'REQUIRED', 'message', 'Informe o nome da turma.'));
    elsif v_type = 'teacher' and coalesce(v_teacher_name, v_teacher_email) is null then
      v_row_errors := v_row_errors || jsonb_build_array(jsonb_build_object('sheet', v_sheet_name, 'row', v_row_number, 'field', 'Nome/E-mail do Professor', 'error', 'REQUIRED', 'message', 'Informe o nome ou o e-mail do professor.'));
    elsif v_type = 'student' and v_student_name is null then
      v_row_errors := v_row_errors || jsonb_build_array(jsonb_build_object('sheet', v_sheet_name, 'row', v_row_number, 'field', 'Nome do Aluno', 'error', 'REQUIRED', 'message', 'Informe o nome do aluno.'));
    elsif v_type = 'guardian' and coalesce(v_guardian_name, v_guardian_email) is null then
      v_row_errors := v_row_errors || jsonb_build_array(jsonb_build_object('sheet', v_sheet_name, 'row', v_row_number, 'field', 'Nome/E-mail do Responsável', 'error', 'REQUIRED', 'message', 'Informe o nome ou o e-mail do responsável.'));
    elsif v_type = 'enrollment' then
      if v_student_name is null then
        v_row_errors := v_row_errors || jsonb_build_array(jsonb_build_object('sheet', v_sheet_name, 'row', v_row_number, 'field', 'Nome do Aluno', 'error', 'REQUIRED', 'message', 'Informe o aluno da matrícula.'));
      end if;
      if v_class_name is null then
        v_row_errors := v_row_errors || jsonb_build_array(jsonb_build_object('sheet', v_sheet_name, 'row', v_row_number, 'field', 'Nome da Turma', 'error', 'REQUIRED', 'message', 'Informe a turma da matrícula.'));
      end if;
    elsif v_type = 'teacher_class_link' then
      if coalesce(v_teacher_name, v_teacher_email) is null then
        v_row_errors := v_row_errors || jsonb_build_array(jsonb_build_object('sheet', v_sheet_name, 'row', v_row_number, 'field', 'Nome/E-mail do Professor', 'error', 'REQUIRED', 'message', 'Informe o professor do vínculo.'));
      end if;
      if v_class_name is null then
        v_row_errors := v_row_errors || jsonb_build_array(jsonb_build_object('sheet', v_sheet_name, 'row', v_row_number, 'field', 'Nome da Turma', 'error', 'REQUIRED', 'message', 'Informe a turma do vínculo.'));
      end if;
    elsif v_type = 'guardian_student_link' then
      if coalesce(v_guardian_name, v_guardian_email) is null then
        v_row_errors := v_row_errors || jsonb_build_array(jsonb_build_object('sheet', v_sheet_name, 'row', v_row_number, 'field', 'Nome/E-mail do Responsável', 'error', 'REQUIRED', 'message', 'Informe o responsável do vínculo.'));
      end if;
      if v_student_name is null then
        v_row_errors := v_row_errors || jsonb_build_array(jsonb_build_object('sheet', v_sheet_name, 'row', v_row_number, 'field', 'Nome do Aluno', 'error', 'REQUIRED', 'message', 'Informe o aluno do vínculo.'));
      end if;
    end if;

    if jsonb_array_length(v_row_errors) > 0 then
      v_invalid := v_invalid + 1;
      v_errors := v_errors || v_row_errors;
      continue;
    end if;

    v_key := case
      when v_type = 'student' then
        v_type || '|' || coalesce(lower(v_school_code), '') || '|' || lower(coalesce(v_student_name, '')) || '|' || coalesce(v_student_birth, '')
      when v_type = 'enrollment' then
        v_type || '|' || coalesce(lower(v_school_code), '') || '|' || lower(coalesce(v_student_name, '')) || '|' || coalesce(v_student_birth, '') || '|' || lower(coalesce(v_class_name, '')) || '|' || coalesce(v_row ->> 'ano_letivo', v_row ->> 'school_year', p_school_year, '')
      else
        v_type || '|' || coalesce(lower(v_school_code), '') || '|' || lower(coalesce(v_school_name, v_class_name, v_student_name, v_teacher_email, v_teacher_name, v_guardian_email, v_guardian_name, ''))
    end;
    if v_key = any(v_seen) then
      v_duplicate := v_duplicate + 1;
      v_errors := v_errors || jsonb_build_array(jsonb_build_object('sheet', v_sheet_name, 'row', v_row_number, 'field', 'Linha', 'error', 'DUPLICATE_IN_FILE', 'message', 'Esta linha repete outro registro do mesmo arquivo.'));
      continue;
    end if;
    v_seen := array_append(v_seen, v_key);

    v_school_id := null;
    v_existing_school_name := null;
    v_existing_school_code := null;
    v_existing_municipio := null;
    v_existing_estado := null;
    v_existing_diretor := null;

    select s.id, s.nome, s.codigo_inep, s.municipio, s.estado, s.diretor
      into v_school_id, v_existing_school_name, v_existing_school_code, v_existing_municipio, v_existing_estado, v_existing_diretor
    from public.schools s
    where lower(btrim(coalesce(s.codigo_inep, ''))) = lower(coalesce(v_school_code, ''))
       or (v_type = 'school' and lower(btrim(s.nome)) = lower(coalesce(v_school_name, '')))
    order by s.created_at
    limit 1;

    if v_type <> 'school'
      and v_school_id is null
      and lower(coalesce(v_school_code, '')) <> all(v_batch_school_codes) then
      v_invalid := v_invalid + 1;
      v_errors := v_errors || jsonb_build_array(jsonb_build_object(
        'sheet', v_sheet_name,
        'row', v_row_number,
        'field', 'Código da Escola',
        'error', 'UNKNOWN_SCHOOL_REFERENCE',
        'message', 'Código da escola não encontrado no banco nem na aba ESCOLAS deste arquivo.'
      ));
      continue;
    end if;

    v_counts := jsonb_set(v_counts, array[
      case v_type
        when 'school' then 'schools'
        when 'class' then 'classes'
        when 'teacher' then 'teachers'
        when 'student' then 'students'
        when 'guardian' then 'guardians'
        when 'enrollment' then 'enrollments'
        when 'teacher_class_link' then 'teacher_class_links'
        else 'guardian_student_links'
      end
    ], to_jsonb(coalesce((v_counts ->> case v_type
        when 'school' then 'schools'
        when 'class' then 'classes'
        when 'teacher' then 'teachers'
        when 'student' then 'students'
        when 'guardian' then 'guardians'
        when 'enrollment' then 'enrollments'
        when 'teacher_class_link' then 'teacher_class_links'
        else 'guardian_student_links'
      end)::integer, 0) + 1), true);

    if v_type = 'school' then
      v_exists := v_school_id is not null;
    elsif v_type = 'class' then
      select exists(select 1 from public.classes c where c.school_id = v_school_id and lower(btrim(c.nome)) = lower(v_class_name) and c.status <> 'archived') into v_exists;
    elsif v_type = 'teacher' then
      select exists(select 1 from public.teachers t where t.school_id = v_school_id and lower(coalesce(nullif(btrim(t.email), ''), nullif(btrim(t.full_name), ''))) = lower(coalesce(v_teacher_email, v_teacher_name)) and t.status <> 'archived') into v_exists;
    elsif v_type = 'student' then
      select exists(
        select 1
        from public.students s
        where s.school_id = v_school_id
          and lower(btrim(s.nome)) = lower(v_student_name)
          and (v_student_birth is null or coalesce(s.data_nascimento::text, '') = v_student_birth)
          and coalesce(s.status, 'active') <> 'archived'
      ) into v_exists;
    elsif v_type = 'guardian' then
      select exists(select 1 from public.guardians g where g.school_id = v_school_id and lower(coalesce(nullif(btrim(g.email), ''), btrim(g.full_name))) = lower(coalesce(v_guardian_email, v_guardian_name)) and g.status <> 'archived') into v_exists;
    else
      v_exists := false;
    end if;

    if v_exists and v_type = 'school' then
      if lower(btrim(coalesce(v_existing_school_name, ''))) = lower(btrim(coalesce(v_school_name, '')))
        and lower(btrim(coalesce(v_existing_school_code, ''))) = lower(btrim(coalesce(v_school_code, '')))
        and (v_municipio is null or lower(btrim(coalesce(v_existing_municipio, ''))) = lower(btrim(v_municipio)))
        and (v_estado is null or upper(btrim(coalesce(v_existing_estado, ''))) = upper(btrim(v_estado)))
        and (v_diretor is null or lower(btrim(coalesce(v_existing_diretor, ''))) = lower(btrim(v_diretor))) then
        v_unchanged := v_unchanged + 1;
      else
        v_updates := v_updates + 1;
      end if;
    elsif v_exists then
      v_updates := v_updates + 1;
    else
      v_new := v_new + 1;
    end if;
  end loop;

  insert into public.admin_network_bulk_import_batches (
    source_format,
    import_type,
    school_year,
    status,
    payload,
    column_mapping,
    preview_report,
    errors,
    idempotency_key,
    created_by
  ) values (
    upper(coalesce(nullif(p_source_format, ''), 'CSV')),
    lower(coalesce(nullif(p_import_type, ''), 'auto')),
    coalesce(nullif(p_school_year, ''), '2026'),
    case when v_invalid = 0 and v_duplicate = 0 then 'validated' else 'draft' end,
    p_rows,
    coalesce(p_column_mapping, '{}'::jsonb),
    jsonb_build_object(
      'total_rows', v_total,
      'valid_rows', greatest(v_total - v_invalid - v_duplicate, 0),
      'invalid_rows', v_invalid,
      'duplicate_rows', v_duplicate,
      'new_rows', v_new,
      'update_rows', v_updates,
      'unchanged_existing', v_unchanged,
      'counts', v_counts,
      'requires_confirmation', true,
      'import_type', lower(coalesce(nullif(p_import_type, ''), 'auto')),
      'import_contract_version', v_contract_version,
      'canonical_engine', 'admin_confirm_rs_school_import'
    ),
    v_errors,
    v_effective_idempotency_key,
    auth.uid()
  )
  returning * into v_batch;

  return jsonb_build_object(
    'batch_id', v_batch.id,
    'status', v_batch.status,
    'report', v_batch.preview_report,
    'errors', v_batch.errors
  );
end;
$$;


ALTER FUNCTION "public"."admin_preview_network_bulk_import"("p_rows" "jsonb", "p_source_format" "text", "p_import_type" "text", "p_school_year" "text", "p_column_mapping" "jsonb", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_preview_network_bulk_import"("p_rows" "jsonb", "p_source_format" "text", "p_import_type" "text", "p_school_year" "text", "p_column_mapping" "jsonb", "p_idempotency_key" "text") IS 'Admin hotfix: supports unified multi-sheet network import previews with sheet-aware errors and school reference validation.';



CREATE OR REPLACE FUNCTION "public"."admin_refresh_rs_school_import_stage"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_has_classes boolean := false;
  v_has_teachers boolean := false;
  v_has_teacher_links boolean := false;
  v_has_students boolean := false;
  v_has_enrollments boolean := false;
  v_has_guardians boolean := false;
  v_has_family_links boolean := false;
  v_next_stage text := 'dados_parciais';
BEGIN
  IF NEW.action <> 'school_import_confirmed' OR NEW.school_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT EXISTS (
    SELECT 1
      FROM public.classes c
     WHERE c.school_id = NEW.school_id
       AND lower(coalesce(c.status, 'active')) = 'active'
  ) INTO v_has_classes;

  SELECT EXISTS (
    SELECT 1
      FROM public.teachers t
     WHERE t.school_id = NEW.school_id
       AND lower(coalesce(t.status, 'active')) = 'active'
  ) INTO v_has_teachers;

  SELECT EXISTS (
    SELECT 1
      FROM public.class_teacher_memberships ctm
      JOIN public.classes c ON c.id = ctm.class_id
      JOIN public.teachers t ON t.id = ctm.teacher_id
     WHERE c.school_id = NEW.school_id
       AND t.school_id = NEW.school_id
       AND lower(coalesce(ctm.status, 'active')) = 'active'
  ) INTO v_has_teacher_links;

  SELECT EXISTS (
    SELECT 1
      FROM public.students s
     WHERE s.school_id = NEW.school_id
       AND lower(coalesce(s.status, 'active')) = 'active'
  ) INTO v_has_students;

  SELECT EXISTS (
    SELECT 1
      FROM public.enrollments e
      JOIN public.students s ON s.id = e.student_id
      JOIN public.classes c ON c.id = e.class_id
     WHERE s.school_id = NEW.school_id
       AND c.school_id = NEW.school_id
       AND lower(coalesce(e.status, 'active')) = 'active'
  ) INTO v_has_enrollments;

  SELECT EXISTS (
    SELECT 1
      FROM public.guardians g
     WHERE g.school_id = NEW.school_id
       AND lower(coalesce(g.status, 'active')) = 'active'
  ) INTO v_has_guardians;

  SELECT EXISTS (
    SELECT 1
      FROM public.student_guardian_links sgl
      JOIN public.students s ON s.id = sgl.student_id
      JOIN public.guardians g ON g.id = sgl.guardian_id
     WHERE s.school_id = NEW.school_id
       AND g.school_id = NEW.school_id
       AND lower(coalesce(sgl.status, 'active')) = 'active'
  ) INTO v_has_family_links;

  IF v_has_classes
     AND v_has_teachers
     AND v_has_teacher_links
     AND v_has_students
     AND v_has_enrollments
     AND v_has_guardians
     AND v_has_family_links THEN
    v_next_stage := 'pronta_para_validacao';
  END IF;

  UPDATE public.rs_school_installations
     SET current_stage = v_next_stage,
         validation_status = 'pending',
         updated_at = now()
   WHERE school_id = NEW.school_id
     AND current_stage <> 'ativa';

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."admin_refresh_rs_school_import_stage"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_refresh_rs_school_import_stage"() IS 'Internal trigger helper that recomputes RS School import stage from persisted data. Does not handle Auth, passwords, tokens, or public execution.';



CREATE OR REPLACE FUNCTION "public"."admin_reset_student_credential_password"("p_student_id" "uuid", "p_plain_password" "text", "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_credential public.student_institutional_credentials%rowtype;
begin
  if length(coalesce(p_plain_password, '')) < 10 then
    raise exception 'WEAK_RESET_PASSWORD';
  end if;

  select * into v_credential
  from public.student_institutional_credentials
  where student_id = p_student_id
  for update;

  if v_credential.id is null then
    raise exception 'CREDENTIAL_NOT_FOUND';
  end if;

  if public.current_platform_role() <> 'service_role' and not public.secretaria_can_manage_school(v_credential.school_id) then
    raise exception 'UNAUTHORIZED_RESET' using errcode = '42501';
  end if;

  update public.student_institutional_credentials
  set password_hash = extensions.crypt(p_plain_password, extensions.gen_salt('bf', 10)),
      password_hash_algorithm = 'pgcrypto_bf',
      password_version = password_version + 1,
      status = case when status = 'pending_auth' then 'active' else status end,
      password_changed_at = now(),
      last_reset_at = now(),
      updated_at = now()
  where id = v_credential.id
  returning * into v_credential;

  insert into public.student_credential_events (
    credential_id,
    student_id,
    school_id,
    actor_profile_id,
    action,
    result,
    metadata
  ) values (
    v_credential.id,
    v_credential.student_id,
    v_credential.school_id,
    coalesce(p_actor_id, auth.uid()),
    'PASSWORD_RESET',
    'success',
    jsonb_build_object('login', v_credential.login, 'credential_version', v_credential.password_version)
  );

  return jsonb_build_object(
    'ok', true,
    'credential_id', v_credential.id,
    'student_id', v_credential.student_id,
    'school_id', v_credential.school_id,
    'login', v_credential.login,
    'status', v_credential.status,
    'auth_user_id', v_credential.auth_user_id,
    'technical_email', v_credential.technical_email,
    'password_version', v_credential.password_version
  );
end;
$$;


ALTER FUNCTION "public"."admin_reset_student_credential_password"("p_student_id" "uuid", "p_plain_password" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_permission_flag"("p_feature_key" "text", "p_role_key" "text", "p_permission_scope" "text", "p_enabled" boolean, "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_flag public.admin_feature_permission_flags%rowtype;
begin
  if not public.is_platform_admin() then
    raise exception 'ADMIN_REQUIRED';
  end if;

  select * into v_flag
  from public.admin_feature_permission_flags
  where feature_key = p_feature_key
    and role_key = p_role_key
    and permission_scope = p_permission_scope
  for update;

  if v_flag.id is null then
    raise exception 'PERMISSION_FLAG_NOT_FOUND';
  end if;

  if v_flag.locked then
    raise exception 'PERMISSION_FLAG_LOCKED';
  end if;

  update public.admin_feature_permission_flags
  set enabled = p_enabled,
      updated_by = auth.uid(),
      updated_at = now()
  where id = v_flag.id
  returning * into v_flag;

  insert into public.admin_operational_audit_events (
    actor_profile_id,
    actor_role,
    module,
    action,
    result,
    details
  ) values (
    auth.uid(),
    public.current_platform_role(),
    'permissoes',
    'permission_flag_updated',
    'success',
    jsonb_build_object(
      'feature_key', p_feature_key,
      'role_key', p_role_key,
      'permission_scope', p_permission_scope,
      'enabled', p_enabled,
      'reason', nullif(left(coalesce(p_reason, ''), 240), '')
    )
  );

  return jsonb_build_object(
    'ok', true,
    'feature_key', v_flag.feature_key,
    'role_key', v_flag.role_key,
    'permission_scope', v_flag.permission_scope,
    'enabled', v_flag.enabled
  );
end;
$$;


ALTER FUNCTION "public"."admin_set_permission_flag"("p_feature_key" "text", "p_role_key" "text", "p_permission_scope" "text", "p_enabled" boolean, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_school_content_availability"("p_school_id" "uuid", "p_content_type" "text", "p_content_id" "text", "p_status" "text" DEFAULT 'available'::"text", "p_available_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_available_until" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_admin uuid := auth.uid();
  v_type text;
  v_status text := lower(btrim(coalesce(p_status, 'available')));
  v_content_id text := btrim(coalesce(p_content_id, ''));
  v_existing public.school_content_availability;
  v_availability_id uuid;
  v_result text;
  v_action text;
BEGIN
  IF v_admin IS NULL OR NOT public.is_platform_admin() THEN
    RAISE EXCEPTION 'Apenas Admin/TI pode alterar disponibilidade de conteudo.'
      USING errcode = '42501';
  END IF;

  v_type := public.normalize_school_content_type(p_content_type);

  IF v_content_id = '' THEN
    RAISE EXCEPTION 'content_id obrigatorio.' USING errcode = '22023';
  END IF;

  IF v_content_id ~* '(password|senha|token|secret|service_role|access_token|refresh_token)' THEN
    RAISE EXCEPTION 'content_id contem termo sensivel.' USING errcode = '22023';
  END IF;

  IF v_status NOT IN ('available', 'unavailable') THEN
    RAISE EXCEPTION 'Status de disponibilidade invalido.' USING errcode = '22023';
  END IF;

  IF p_available_from IS NOT NULL AND p_available_until IS NOT NULL AND p_available_until < p_available_from THEN
    RAISE EXCEPTION 'Janela de disponibilidade invalida.' USING errcode = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.schools s
    WHERE s.id = p_school_id
      AND coalesce(s.status, 'active') <> 'archived'
  ) THEN
    RAISE EXCEPTION 'Escola nao encontrada ou arquivada.' USING errcode = '22023';
  END IF;

  SELECT * INTO v_existing
  FROM public.school_content_availability sca
  WHERE sca.school_id = p_school_id
    AND sca.content_type = v_type
    AND lower(btrim(sca.content_id)) = lower(v_content_id)
    AND sca.deleted_at IS NULL
  LIMIT 1;

  IF v_status = 'unavailable' THEN
    IF v_existing.id IS NULL THEN
      v_result := 'noop';
      v_action := 'noop';
    ELSE
      UPDATE public.school_content_availability
      SET
        status = 'unavailable',
        available_from = p_available_from,
        available_until = p_available_until,
        updated_by = v_admin,
        deleted_by = v_admin,
        deleted_at = now()
      WHERE id = v_existing.id
      RETURNING id INTO v_availability_id;
      v_result := 'removed';
      v_action := 'set_unavailable';
    END IF;
  ELSIF v_existing.id IS NULL THEN
    INSERT INTO public.school_content_availability (
      school_id,
      content_type,
      content_id,
      status,
      available_from,
      available_until,
      created_by,
      updated_by
    )
    VALUES (
      p_school_id,
      v_type,
      v_content_id,
      'available',
      p_available_from,
      p_available_until,
      v_admin,
      v_admin
    )
    RETURNING id INTO v_availability_id;
    v_result := 'created';
    v_action := 'set_available';
  ELSE
    UPDATE public.school_content_availability
    SET
      status = 'available',
      available_from = p_available_from,
      available_until = p_available_until,
      updated_by = v_admin
    WHERE id = v_existing.id
    RETURNING id INTO v_availability_id;
    v_result := 'updated';
    v_action := CASE
      WHEN v_existing.available_from IS DISTINCT FROM p_available_from
        OR v_existing.available_until IS DISTINCT FROM p_available_until
        THEN 'period_updated'
      ELSE 'set_available'
    END;
  END IF;

  INSERT INTO public.admin_content_availability_events (
    admin_user_id,
    school_id,
    availability_id,
    content_type,
    content_id,
    action,
    from_status,
    to_status,
    available_from,
    available_until,
    result
  )
  VALUES (
    v_admin,
    p_school_id,
    v_availability_id,
    v_type,
    v_content_id,
    v_action,
    v_existing.status,
    v_status,
    p_available_from,
    p_available_until,
    v_result
  );

  RETURN jsonb_build_object(
    'ok', true,
    'availability_id', v_availability_id,
    'school_id', p_school_id,
    'content_type', v_type,
    'content_id', v_content_id,
    'status', v_status,
    'result', v_result
  );
END;
$$;


ALTER FUNCTION "public"."admin_set_school_content_availability"("p_school_id" "uuid", "p_content_type" "text", "p_content_id" "text", "p_status" "text", "p_available_from" timestamp with time zone, "p_available_until" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_student_credential_status"("p_student_id" "uuid", "p_status" "text", "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_credential public.student_institutional_credentials%rowtype;
  v_status text := lower(btrim(coalesce(p_status, '')));
  v_action text;
begin
  if v_status not in ('active', 'blocked') then
    raise exception 'INVALID_CREDENTIAL_STATUS';
  end if;

  select * into v_credential
  from public.student_institutional_credentials
  where student_id = p_student_id
  for update;

  if v_credential.id is null then
    raise exception 'CREDENTIAL_NOT_FOUND';
  end if;

  if public.current_platform_role() <> 'service_role' and not public.secretaria_can_manage_school(v_credential.school_id) then
    raise exception 'UNAUTHORIZED_STATUS_CHANGE' using errcode = '42501';
  end if;

  v_action := case when v_status = 'blocked' then 'ACCESS_BLOCKED' else 'ACCESS_UNBLOCKED' end;

  update public.student_institutional_credentials
  set status = v_status,
      blocked_at = case when v_status = 'blocked' then now() else blocked_at end,
      unblocked_at = case when v_status = 'active' then now() else unblocked_at end,
      updated_at = now()
  where id = v_credential.id
  returning * into v_credential;

  insert into public.student_credential_events (
    credential_id,
    student_id,
    school_id,
    actor_profile_id,
    action,
    result,
    metadata
  ) values (
    v_credential.id,
    v_credential.student_id,
    v_credential.school_id,
    coalesce(p_actor_id, auth.uid()),
    v_action,
    'success',
    jsonb_build_object('login', v_credential.login, 'status', v_credential.status)
  );

  return jsonb_build_object(
    'ok', true,
    'credential_id', v_credential.id,
    'student_id', v_credential.student_id,
    'school_id', v_credential.school_id,
    'login', v_credential.login,
    'status', v_credential.status,
    'auth_user_id', v_credential.auth_user_id
  );
end;
$$;


ALTER FUNCTION "public"."admin_set_student_credential_status"("p_student_id" "uuid", "p_status" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_validate_activate_school"("p_school_id" "uuid", "p_activate" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_admin_user_id uuid := auth.uid();
  v_admin_role text;
  v_school public.schools%rowtype;
  v_installation public.rs_school_installations%rowtype;
  v_checks jsonb := '{}'::jsonb;
  v_failures int := 0;
  v_next_stage text := 'pronta_para_validacao';
  v_action text := 'school_activation_validated';
  v_result text := 'created';
BEGIN
  IF v_admin_user_id IS NULL THEN
    RAISE EXCEPTION 'Usuario autenticado obrigatorio.' USING errcode = '42501';
  END IF;

  SELECT p.platform_role
    INTO v_admin_role
    FROM public.profiles p
   WHERE p.id = v_admin_user_id
     AND p.status = 'active';

  IF coalesce(v_admin_role, '') NOT IN ('admin', 'admin_ti', 'administrador', 'administrador_nacional') THEN
    RAISE EXCEPTION 'Perfil sem permissao administrativa para validar escola.' USING errcode = '42501';
  END IF;

  SELECT *
    INTO v_school
    FROM public.schools s
   WHERE s.id = p_school_id
     AND s.status <> 'archived'
   FOR UPDATE;

  IF v_school.id IS NULL THEN
    RAISE EXCEPTION 'Escola nao encontrada.' USING errcode = '22023';
  END IF;

  SELECT *
    INTO v_installation
    FROM public.rs_school_installations i
   WHERE i.school_id = p_school_id
   FOR UPDATE;

  v_checks := jsonb_build_object(
    'school_exists', v_school.id IS NOT NULL,
    'school_not_archived', coalesce(v_school.status, '') <> 'archived',
    'school_year_configured', EXISTS (
      SELECT 1 FROM public.classes c
       WHERE c.school_id = p_school_id
         AND nullif(btrim(coalesce(c.school_year::text, '')), '') IS NOT NULL
      UNION
      SELECT 1 FROM public.enrollments e
       WHERE e.school_id = p_school_id
         AND nullif(btrim(coalesce(e.school_year::text, '')), '') IS NOT NULL
      LIMIT 1
    ),
    'classes_configured', EXISTS (
      SELECT 1 FROM public.classes c
       WHERE c.school_id = p_school_id
         AND lower(coalesce(c.status, 'active')) = 'active'
    ),
    'teachers_configured', EXISTS (
      SELECT 1 FROM public.teachers t
       WHERE t.school_id = p_school_id
         AND lower(coalesce(t.status, 'active')) = 'active'
    ),
    'teacher_links_configured', EXISTS (
      SELECT 1
        FROM public.class_teacher_memberships ctm
        JOIN public.classes c ON c.id = ctm.class_id
        JOIN public.teachers t ON t.id = ctm.teacher_id
       WHERE c.school_id = p_school_id
         AND t.school_id = p_school_id
         AND lower(coalesce(ctm.status, 'active')) = 'active'
    ),
    'students_configured', EXISTS (
      SELECT 1 FROM public.students s
       WHERE s.school_id = p_school_id
         AND lower(coalesce(s.status, 'active')) = 'active'
    ),
    'enrollments_configured', EXISTS (
      SELECT 1
        FROM public.enrollments e
        JOIN public.students s ON s.id = e.student_id
        JOIN public.classes c ON c.id = e.class_id
       WHERE e.school_id = p_school_id
         AND s.school_id = p_school_id
         AND c.school_id = p_school_id
         AND lower(coalesce(e.status, 'active')) = 'active'
    ),
    'guardians_configured', EXISTS (
      SELECT 1 FROM public.guardians g
       WHERE g.school_id = p_school_id
         AND lower(coalesce(g.status, 'active')) = 'active'
    ),
    'family_links_configured', EXISTS (
      SELECT 1
        FROM public.student_guardian_links sgl
        JOIN public.students s ON s.id = sgl.student_id
        JOIN public.guardians g ON g.id = sgl.guardian_id
       WHERE s.school_id = p_school_id
         AND g.school_id = p_school_id
         AND lower(coalesce(sgl.status, 'active')) = 'active'
    ),
    'no_orphan_enrollments', NOT EXISTS (
      SELECT 1
        FROM public.enrollments e
        JOIN public.students s ON s.id = e.student_id
        JOIN public.classes c ON c.id = e.class_id
       WHERE (e.school_id = p_school_id OR s.school_id = p_school_id OR c.school_id = p_school_id)
         AND (e.school_id <> p_school_id OR s.school_id <> p_school_id OR c.school_id <> p_school_id)
    ),
    'no_orphan_teacher_links', NOT EXISTS (
      SELECT 1
        FROM public.class_teacher_memberships ctm
        JOIN public.classes c ON c.id = ctm.class_id
        JOIN public.teachers t ON t.id = ctm.teacher_id
       WHERE (c.school_id = p_school_id OR t.school_id = p_school_id)
         AND c.school_id <> t.school_id
    ),
    'no_orphan_family_links', NOT EXISTS (
      SELECT 1
        FROM public.student_guardian_links sgl
        JOIN public.students s ON s.id = sgl.student_id
        JOIN public.guardians g ON g.id = sgl.guardian_id
       WHERE (s.school_id = p_school_id OR g.school_id = p_school_id)
         AND s.school_id <> g.school_id
    ),
    'installation_package_valid', v_installation.id IS NOT NULL
      AND coalesce(v_installation.schema_version, '') = 'RS-SCHOOL-TEMPLATE V1'
      AND coalesce(v_installation.package_version, '') = 'RS-SCHOOL-V1-DEPLOYMENT-2026-09-01'
      AND coalesce(v_installation.current_stage, '') IN ('pronta_para_validacao', 'ativa')
  );

  SELECT count(*)
    INTO v_failures
    FROM jsonb_each(v_checks) AS item(key, value)
   WHERE item.value <> 'true'::jsonb;

  IF v_failures > 0 THEN
    v_action := 'school_activation_blocked';
    v_result := 'blocked';
    v_next_stage := coalesce(v_installation.current_stage, 'dados_parciais');

    INSERT INTO public.admin_school_deployment_events (
      admin_user_id,
      school_id,
      school_code,
      action,
      stage,
      result,
      reason
    ) VALUES (
      v_admin_user_id,
      p_school_id,
      coalesce(v_installation.school_code, v_school.codigo_inep, v_school.nome),
      v_action,
      v_next_stage,
      v_result,
      jsonb_build_object('activate', p_activate, 'checks', v_checks, 'failures', v_failures)::text
    );

    RETURN jsonb_build_object(
      'ok', false,
      'activated', false,
      'school_id', p_school_id,
      'stage', v_next_stage,
      'validation_status', 'failed',
      'checks', v_checks,
      'failures', v_failures
    );
  END IF;

  IF p_activate THEN
    UPDATE public.schools
       SET status = 'active',
           updated_at = now()
     WHERE id = p_school_id;

    UPDATE public.rs_school_installations
       SET current_stage = 'ativa',
           validation_status = 'passed',
           activated_at = coalesce(activated_at, now()),
           updated_at = now()
     WHERE school_id = p_school_id;

    v_action := 'school_activated';
    v_next_stage := 'ativa';
  ELSE
    UPDATE public.rs_school_installations
       SET current_stage = CASE WHEN current_stage = 'ativa' THEN 'ativa' ELSE 'pronta_para_validacao' END,
           validation_status = 'passed',
           updated_at = now()
     WHERE school_id = p_school_id;

    v_action := 'school_activation_validated';
    v_next_stage := CASE WHEN coalesce(v_installation.current_stage, '') = 'ativa' THEN 'ativa' ELSE 'pronta_para_validacao' END;
  END IF;

  INSERT INTO public.admin_school_deployment_events (
    admin_user_id,
    school_id,
    school_code,
    action,
    stage,
    result,
    reason
  ) VALUES (
    v_admin_user_id,
    p_school_id,
    coalesce(v_installation.school_code, v_school.codigo_inep, v_school.nome),
    v_action,
    v_next_stage,
    v_result,
    jsonb_build_object('activate', p_activate, 'checks', v_checks, 'failures', 0)::text
  );

  RETURN jsonb_build_object(
    'ok', true,
    'activated', p_activate,
    'school_id', p_school_id,
    'stage', v_next_stage,
    'validation_status', 'passed',
    'checks', v_checks,
    'failures', 0
  );
END;
$$;


ALTER FUNCTION "public"."admin_validate_activate_school"("p_school_id" "uuid", "p_activate" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_validate_activate_school"("p_school_id" "uuid", "p_activate" boolean) IS 'Admin-only final validation and controlled activation for RS School deployments. Does not create Auth, passwords, tokens, links, or expose service-role credentials.';



CREATE OR REPLACE FUNCTION "public"."ai_can_access_student_context"("p_student_id" "uuid", "p_class_id" "uuid" DEFAULT NULL::"uuid", "p_school_id" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select auth.uid() is not null and (public.is_platform_admin() or (p_school_id is not null and public.secretaria_can_manage_school(p_school_id)) or public.institutional_is_current_student(p_student_id) or exists (select 1 from public.enrollments e where e.student_id = p_student_id and (p_class_id is null or e.class_id = p_class_id) and (p_school_id is null or e.school_id = p_school_id) and public.avalia_plus_teacher_can_manage_class(e.class_id, e.school_id)) or exists (select 1 from public.enrollments e where e.student_id = p_student_id and (p_class_id is null or e.class_id = p_class_id) and (p_school_id is null or e.school_id = p_school_id) and public.communication_guardian_can_read(e.school_id, e.class_id, e.student_id, 'student')));
$$;


ALTER FUNCTION "public"."ai_can_access_student_context"("p_student_id" "uuid", "p_class_id" "uuid", "p_school_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_current_role"() RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select lower(coalesce((select p.platform_role from public.profiles p where p.id = auth.uid() and p.status = 'active'), (select u.perfil from public.users u where u.id = auth.uid() and coalesce(u.ativo, true)), ''));
$$;


ALTER FUNCTION "public"."ai_current_role"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_current_student_id"() RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select s.id from public.students s where s.user_id = auth.uid() and coalesce(s.status, 'active') in ('active', 'ativo') order by s.updated_at desc nulls last, s.created_at desc nulls last limit 1;
$$;


ALTER FUNCTION "public"."ai_current_student_id"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_has_active_assessment"("p_student_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select exists (select 1 from public.assessment_assignments aa join public.enrollments e on e.student_id = p_student_id and e.school_id = aa.school_id and e.class_id = aa.class_id and e.status in ('active', 'ativo') where aa.status = 'published' and aa.available_from <= now() and (aa.available_until is null or aa.available_until >= now()) and (aa.target_type = 'class' or (aa.target_type = 'student' and aa.student_id = p_student_id)) and not exists (select 1 from public.assessment_results ar where ar.assignment_id = aa.id and ar.student_id = p_student_id));
$$;


ALTER FUNCTION "public"."ai_has_active_assessment"("p_student_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_pedagogy_build_context"("p_audience" "text", "p_student_id" "uuid" DEFAULT NULL::"uuid", "p_class_id" "uuid" DEFAULT NULL::"uuid", "p_component" "text" DEFAULT NULL::"text", "p_skill" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_audience text := lower(btrim(coalesce(p_audience, '')));
  v_role text := public.ai_current_role();
  v_student_id uuid := p_student_id;
  v_student public.students%rowtype;
  v_enrollment public.enrollments%rowtype;
  v_class public.classes%rowtype;
  v_teacher_id uuid;
  v_gap_map jsonb := null;
  v_recommendations jsonb := jsonb_build_object('status', 'EMPTY_REAL', 'items', '[]'::jsonb);
  v_active_assessment boolean := false;
  v_recent_results jsonb := '[]'::jsonb;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode = '42501'; end if;
  if v_audience not in ('student', 'teacher', 'management') then raise exception 'AI_AUDIENCE_INVALID' using errcode = '22023'; end if;

  if v_audience = 'student' then
    v_student_id := coalesce(v_student_id, public.ai_current_student_id());
    if v_student_id is null then raise exception 'STUDENT_CONTEXT_REQUIRED' using errcode = '22023'; end if;
    select * into v_student from public.students where id = v_student_id;
    if v_student.id is null then raise exception 'STUDENT_NOT_FOUND' using errcode = '22023'; end if;
    select * into v_enrollment from public.enrollments e where e.student_id = v_student.id and e.status in ('active', 'ativo') order by e.enrolled_at desc limit 1;
    if v_enrollment.id is null then raise exception 'ACTIVE_ENROLLMENT_REQUIRED' using errcode = '22023'; end if;
    if not public.ai_can_access_student_context(v_student.id, v_enrollment.class_id, v_enrollment.school_id) then raise exception 'AI_STUDENT_CONTEXT_FORBIDDEN' using errcode = '42501'; end if;

    select coalesce(jsonb_agg(to_jsonb(src)), '[]'::jsonb) into v_recent_results from (select ar.assessment_id, ar.assignment_id, ar.score_percentage, ar.status, ar.finalized_at from public.assessment_results ar where ar.student_id = v_student.id and ar.school_id = v_enrollment.school_id order by ar.finalized_at desc limit 5) src;
    v_active_assessment := public.ai_has_active_assessment(v_student.id);

    select jsonb_build_object('status', case when count(*) > 0 then 'PASS' else 'EMPTY_REAL' end, 'items', coalesce(jsonb_agg(jsonb_build_object('content_type', pr.content_type, 'content_id', pr.content_id, 'content_title', pr.content_title, 'source', 'pedagogical_recommendations', 'recommendation_id', pr.id, 'note', pr.note) order by pr.created_at desc), '[]'::jsonb)) into v_recommendations
    from (select * from public.pedagogical_recommendations pr where pr.school_id = v_enrollment.school_id and pr.class_id = v_enrollment.class_id and pr.status = 'published' and pr.deleted_at is null and (pr.target_type = 'class' or (pr.target_type = 'student' and pr.student_id = v_student.id)) and (nullif(btrim(coalesce(p_skill, '')), '') is null or pr.content_title ilike '%' || p_skill || '%' or coalesce(pr.note, '') ilike '%' || p_skill || '%') order by pr.created_at desc limit 8) pr;

    return jsonb_build_object('audience', v_audience, 'role', v_role, 'student', jsonb_build_object('id', v_student.id, 'name', v_student.nome, 'school_id', v_enrollment.school_id, 'class_id', v_enrollment.class_id), 'component', p_component, 'skill', p_skill, 'recent_results', v_recent_results, 'recommendations', v_recommendations, 'active_assessment', v_active_assessment, 'provider', public.ai_provider_status());
  end if;

  v_teacher_id := public.avalia_current_teacher_id();
  if v_audience = 'teacher' and v_teacher_id is null and not public.is_platform_admin() then raise exception 'TEACHER_CONTEXT_REQUIRED' using errcode = '42501'; end if;

  if p_class_id is not null then
    select * into v_class from public.classes where id = p_class_id;
  elsif v_teacher_id is not null then
    select c.* into v_class from public.teacher_class_links tcl join public.classes c on c.id = tcl.class_id where tcl.teacher_id = v_teacher_id and tcl.status = 'active' and c.status = 'active' order by c.nome limit 1;
  end if;

  if v_class.id is not null then
    if not (public.is_platform_admin() or public.secretaria_can_manage_school(v_class.school_id) or public.avalia_plus_teacher_can_manage_class(v_class.id, v_class.school_id)) then raise exception 'AI_CLASS_CONTEXT_FORBIDDEN' using errcode = '42501'; end if;
    v_gap_map := public.recomposition_get_learning_gap_map(v_class.id);
    v_recommendations := public.recomposition_content_recommendations(v_class.id, p_skill, 8);
  end if;

  return jsonb_build_object('audience', v_audience, 'role', v_role, 'teacher_id', v_teacher_id, 'class', case when v_class.id is null then null else jsonb_build_object('id', v_class.id, 'name', v_class.nome, 'school_id', v_class.school_id) end, 'component', p_component, 'skill', p_skill, 'learning_gap_map', v_gap_map, 'recommendations', v_recommendations, 'provider', public.ai_provider_status());
end;
$$;


ALTER FUNCTION "public"."ai_pedagogy_build_context"("p_audience" "text", "p_student_id" "uuid", "p_class_id" "uuid", "p_component" "text", "p_skill" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_pedagogy_prepare_request"("p_audience" "text", "p_prompt" "text", "p_student_id" "uuid" DEFAULT NULL::"uuid", "p_class_id" "uuid" DEFAULT NULL::"uuid", "p_component" "text" DEFAULT NULL::"text", "p_skill" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_audience text := lower(btrim(coalesce(p_audience, '')));
  v_prompt text := coalesce(p_prompt, '');
  v_role text := public.ai_current_role();
  v_context jsonb;
  v_provider jsonb;
  v_status text := 'provider_empty_real';
  v_blocked boolean := false;
  v_active_assessment boolean := false;
  v_log_id uuid;
  v_refs jsonb := '[]'::jsonb;
  v_school_id uuid;
  v_student_id uuid;
  v_class_id uuid;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode = '42501'; end if;
  if length(btrim(v_prompt)) = 0 then raise exception 'PROMPT_REQUIRED' using errcode = '22023'; end if;

  v_context := public.ai_pedagogy_build_context(v_audience, p_student_id, p_class_id, p_component, p_skill);
  v_provider := public.ai_provider_status();
  v_active_assessment := coalesce((v_context ->> 'active_assessment')::boolean, false);
  v_school_id := coalesce(nullif(v_context #>> '{student,school_id}', '')::uuid, nullif(v_context #>> '{class,school_id}', '')::uuid);
  v_student_id := coalesce(p_student_id, nullif(v_context #>> '{student,id}', '')::uuid);
  v_class_id := coalesce(p_class_id, nullif(v_context #>> '{student,class_id}', '')::uuid, nullif(v_context #>> '{class,id}', '')::uuid);
  v_refs := coalesce(v_context #> '{recommendations,items}', '[]'::jsonb);

  if v_audience = 'student' and v_active_assessment and v_prompt ~* '(gabarito|resposta\s+correta|qual\s+alternativa|resolver\s+a\s+prova|responda\s+a\s+questao|responda\s+a\s+questão)' then
    v_blocked := true;
    v_status := 'blocked';
  elsif coalesce((v_provider ->> 'configured')::boolean, false) then
    v_status := 'prepared';
  end if;

  insert into public.ai_interaction_logs (user_role, school_id, class_id, student_id, request_type, audience, prompt_hash, prompt_excerpt, provider_key, model_name, status, context_summary, references_used, active_assessment_protected, error_code)
  values (v_role, v_school_id, v_class_id, v_student_id, case when v_audience = 'teacher' then 'teacher_support' else 'student_question' end, v_audience, encode(digest(v_prompt, 'sha256'), 'hex'), left(regexp_replace(v_prompt, '\s+', ' ', 'g'), 160), v_provider ->> 'provider_key', v_provider ->> 'model_name', v_status, jsonb_build_object('component', p_component, 'skill', p_skill, 'provider_status', v_provider ->> 'status', 'active_assessment', v_active_assessment), v_refs, v_blocked, case when v_blocked then 'ACTIVE_ASSESSMENT_PROTECTION' else null end)
  returning id into v_log_id;

  insert into public.ai_context_references (interaction_id, school_id, source_type, source_id, title, href, metadata)
  select v_log_id, v_school_id, case when item ->> 'content_type' = 'book' then 'library' when item ->> 'content_type' in ('activity', 'printable_activity') then 'activity' else 'pedagogical_recommendation' end, coalesce(item ->> 'content_id', item ->> 'recommendation_id'), coalesce(item ->> 'content_title', 'Referencia pedagogica'), item ->> 'href', item
  from jsonb_array_elements(v_refs) item;

  return jsonb_build_object('interaction_id', v_log_id, 'status', case when v_status = 'prepared' then 'PASS' when v_status = 'blocked' then 'BLOCKED' else 'EMPTY_REAL' end, 'provider', v_provider, 'active_assessment_protection', case when v_blocked then 'PASS' else 'NOT_TRIGGERED' end, 'context', v_context, 'references', v_refs, 'response_contract', jsonb_build_object('server_side_provider_required', true, 'no_frontend_secret', true, 'do_not_answer_active_assessment', true, 'trace_sources', true));
end;
$$;


ALTER FUNCTION "public"."ai_pedagogy_prepare_request"("p_audience" "text", "p_prompt" "text", "p_student_id" "uuid", "p_class_id" "uuid", "p_component" "text", "p_skill" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ai_pedagogy_prepare_request"("p_audience" "text", "p_prompt" "text", "p_student_id" "uuid", "p_class_id" "uuid", "p_component" "text", "p_skill" "text") IS 'Prepara contexto canonico e registra auditoria para assistente pedagogico. Retorna EMPTY_REAL quando nao houver provedor IA configurado.';



CREATE OR REPLACE FUNCTION "public"."ai_pedagogy_recommendations"("p_audience" "text", "p_student_id" "uuid" DEFAULT NULL::"uuid", "p_class_id" "uuid" DEFAULT NULL::"uuid", "p_skill" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_context jsonb; v_items jsonb; v_status text; v_role text := public.ai_current_role(); v_school_id uuid; v_run_id uuid;
begin
  v_context := public.ai_pedagogy_build_context(p_audience, p_student_id, p_class_id, null, p_skill);
  v_items := coalesce(v_context #> '{recommendations,items}', '[]'::jsonb);
  v_status := case when jsonb_array_length(v_items) > 0 then 'pass' else 'empty_real' end;
  v_school_id := coalesce(nullif(v_context #>> '{student,school_id}', '')::uuid, nullif(v_context #>> '{class,school_id}', '')::uuid);
  insert into public.ai_recommendation_runs (user_role, school_id, class_id, student_id, target_skill, status, recommendations) values (v_role, v_school_id, coalesce(p_class_id, nullif(v_context #>> '{student,class_id}', '')::uuid), p_student_id, p_skill, v_status, v_items) returning id into v_run_id;
  return jsonb_build_object('run_id', v_run_id, 'status', upper(v_status), 'items', v_items, 'source_context', 'AVALIA+ ANALYTICS + LEARNING GAP MAP + RECOMPOSICAO + ATIVIDADES/BIBLIOTECA');
end;
$$;


ALTER FUNCTION "public"."ai_pedagogy_recommendations"("p_audience" "text", "p_student_id" "uuid", "p_class_id" "uuid", "p_skill" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ai_pedagogy_recommendations"("p_audience" "text", "p_student_id" "uuid", "p_class_id" "uuid", "p_skill" "text") IS 'Recomendacoes personalizadas usando Avalia+, learning gap map, recomposicao e recomendacoes pedagogicas reais.';



CREATE OR REPLACE FUNCTION "public"."ai_provider_status"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select coalesce((select jsonb_build_object('status', case when status = 'configured' then 'PASS' else 'EMPTY_REAL' end, 'provider_key', provider_key, 'provider_label', provider_label, 'model_name', model_name, 'configured', status = 'configured') from public.ai_provider_configs where status = 'configured' order by updated_at desc limit 1), jsonb_build_object('status', 'EMPTY_REAL', 'provider_key', null, 'provider_label', null, 'model_name', null, 'configured', false));
$$;


ALTER FUNCTION "public"."ai_provider_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_assigned_student_count"("p_assignment_id" "uuid", "p_school_year" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT coalesce((
    SELECT CASE
      WHEN aa.target_type = 'student' THEN 1
      WHEN aa.target_type = 'class' THEN (
        SELECT count(*)::integer
        FROM public.enrollments e
        JOIN public.students s ON s.id = e.student_id
        JOIN public.classes c ON c.id = e.class_id
        WHERE e.class_id = aa.class_id
          AND e.school_id = aa.school_id
          AND e.status = 'active'
          AND coalesce(s.status, 'active') = 'active'
          AND (p_school_year IS NULL OR e.school_year = p_school_year OR c.school_year = p_school_year)
          AND e.enrolled_at <= now()
          AND (e.ended_at IS NULL OR e.ended_at > now())
      )
      ELSE 0
    END
    FROM public.assessment_assignments aa
    WHERE aa.id = p_assignment_id
  ), 0);
$$;


ALTER FUNCTION "public"."analytics_assigned_student_count"("p_assignment_id" "uuid", "p_school_year" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_current_teacher_id"() RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT t.id
  FROM public.teachers t
  WHERE t.profile_id = auth.uid()
    AND coalesce(t.status, 'active') = 'active'
  ORDER BY t.created_at NULLS LAST
  LIMIT 1;
$$;


ALTER FUNCTION "public"."analytics_current_teacher_id"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_get_alerts"("p_school_id" "uuid" DEFAULT NULL::"uuid", "p_class_id" "uuid" DEFAULT NULL::"uuid", "p_date_from" "date" DEFAULT NULL::"date", "p_date_to" "date" DEFAULT NULL::"date", "p_attendance_threshold" numeric DEFAULT 80, "p_assessment_participation_threshold" numeric DEFAULT 70, "p_assessment_average_threshold" numeric DEFAULT 60, "p_bncc_threshold" numeric DEFAULT 60, "p_require_diary" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_scope jsonb := public.analytics_resolve_authorized_scope(p_school_id, p_class_id, NULL);
  v_school_id uuid := (v_scope->>'school_id')::uuid;
  v_class_id uuid := nullif(v_scope->>'class_id', '')::uuid;
  v_from date := coalesce(p_date_from, current_date - 29);
  v_to date := coalesce(p_date_to, current_date);
  v_alerts jsonb := '[]'::jsonb;
BEGIN
  WITH eligible_classes AS (
    SELECT c.*
    FROM public.classes c
    WHERE c.school_id = v_school_id
      AND coalesce(c.status, 'active') = 'active'
      AND (v_class_id IS NULL OR c.id = v_class_id)
  ),
  class_metrics AS (
    SELECT c.id, c.nome, public.analytics_scope_period_metrics(v_school_id, c.id, NULL, v_from, v_to) AS metrics
    FROM eligible_classes c
  ),
  class_alerts AS (
    SELECT jsonb_build_object('level', 'ATENÇÃO', 'scope', 'class', 'class_id', id, 'class_name', nome, 'type', 'ATTENDANCE_BELOW_THRESHOLD', 'message', nome || ' — frequência abaixo do limiar definido', 'value', (metrics->>'attendance_rate')::numeric, 'threshold', p_attendance_threshold) AS alert
    FROM class_metrics WHERE (metrics->>'attendance_records')::numeric > 0 AND (metrics->>'attendance_rate')::numeric < p_attendance_threshold
    UNION ALL
    SELECT jsonb_build_object('level', 'ATENÇÃO', 'scope', 'class', 'class_id', id, 'class_name', nome, 'type', 'ASSESSMENT_PARTICIPATION_BELOW_THRESHOLD', 'message', nome || ' — participação Avalia+ abaixo do limiar definido', 'value', (metrics->>'assessment_participation')::numeric, 'threshold', p_assessment_participation_threshold)
    FROM class_metrics WHERE (metrics->>'assessment_assignments')::numeric > 0 AND (metrics->>'assessment_participation')::numeric < p_assessment_participation_threshold
    UNION ALL
    SELECT jsonb_build_object('level', 'ATENÇÃO', 'scope', 'class', 'class_id', id, 'class_name', nome, 'type', 'ASSESSMENT_AVERAGE_BELOW_THRESHOLD', 'message', nome || ' — média Avalia+ abaixo do limiar definido', 'value', (metrics->>'assessment_average')::numeric, 'threshold', p_assessment_average_threshold)
    FROM class_metrics WHERE (metrics->>'assessment_completed')::numeric > 0 AND (metrics->>'assessment_average')::numeric < p_assessment_average_threshold
    UNION ALL
    SELECT jsonb_build_object('level', 'ATENÇÃO', 'scope', 'class', 'class_id', id, 'class_name', nome, 'type', 'BNCC_BELOW_THRESHOLD', 'message', nome || ' — habilidade BNCC abaixo do limiar definido', 'value', (metrics->>'bncc_percentage')::numeric, 'threshold', p_bncc_threshold)
    FROM class_metrics WHERE (metrics->>'bncc_skills')::numeric > 0 AND (metrics->>'bncc_percentage')::numeric < p_bncc_threshold
    UNION ALL
    SELECT jsonb_build_object('level', 'ATENÇÃO', 'scope', 'class', 'class_id', id, 'class_name', nome, 'type', 'DIARY_WITHOUT_RECORDS', 'message', nome || ' — Diário sem registro no período selecionado', 'value', 0, 'threshold', 1)
    FROM class_metrics WHERE p_require_diary IS TRUE AND (metrics->>'diary_entries_count')::numeric = 0
  ),
  scoped_students AS (
    SELECT DISTINCT s.id, s.nome, c.id AS class_id, c.nome AS class_name
    FROM public.students s
    JOIN public.enrollments e ON e.student_id = s.id AND e.status = 'active'
    JOIN eligible_classes c ON c.id = e.class_id
    WHERE coalesce(s.status, 'active') = 'active'
  ),
  student_attendance AS (
    SELECT st.*,
      count(ar.id)::integer AS records,
      CASE WHEN count(ar.id) > 0 THEN round((count(ar.id) FILTER (WHERE ar.status = 'present')::numeric / count(ar.id)) * 100, 2) ELSE 0 END AS attendance_rate
    FROM scoped_students st
    LEFT JOIN public.attendance_records ar ON ar.student_id = st.id AND ar.attendance_date BETWEEN v_from AND v_to
    GROUP BY st.id, st.nome, st.class_id, st.class_name
  ),
  student_alerts AS (
    SELECT jsonb_build_object('level', 'ATENÇÃO', 'scope', 'student', 'student_id', id, 'student_name', nome, 'class_id', class_id, 'class_name', class_name, 'type', 'STUDENT_ATTENDANCE_BELOW_THRESHOLD', 'message', nome || ' — frequência abaixo de ' || p_attendance_threshold || '%', 'value', attendance_rate, 'threshold', p_attendance_threshold) AS alert
    FROM student_attendance
    WHERE records > 0 AND attendance_rate < p_attendance_threshold
  )
  SELECT coalesce(jsonb_agg(alert), '[]'::jsonb)
  INTO v_alerts
  FROM (
    SELECT alert FROM class_alerts
    UNION ALL
    SELECT alert FROM student_alerts
  ) all_alerts;

  RETURN jsonb_build_object(
    'scope', v_scope,
    'period', jsonb_build_object('date_from', v_from, 'date_to', v_to),
    'thresholds', jsonb_build_object(
      'attendance', p_attendance_threshold,
      'assessment_participation', p_assessment_participation_threshold,
      'assessment_average', p_assessment_average_threshold,
      'bncc', p_bncc_threshold,
      'diary_required', p_require_diary
    ),
    'alerts', v_alerts,
    'alert_count', jsonb_array_length(v_alerts),
    'language', 'ATENÇÃO / REQUER ACOMPANHAMENTO'
  );
END;
$$;


ALTER FUNCTION "public"."analytics_get_alerts"("p_school_id" "uuid", "p_class_id" "uuid", "p_date_from" "date", "p_date_to" "date", "p_attendance_threshold" numeric, "p_assessment_participation_threshold" numeric, "p_assessment_average_threshold" numeric, "p_bncc_threshold" numeric, "p_require_diary" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_get_class_comparison"("p_school_id" "uuid", "p_date_from" "date" DEFAULT NULL::"date", "p_date_to" "date" DEFAULT NULL::"date", "p_metric" "text" DEFAULT 'attendance_rate'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_from date := coalesce(p_date_from, current_date - 29);
  v_to date := coalesce(p_date_to, current_date);
  v_metric text := coalesce(nullif(btrim(p_metric), ''), 'attendance_rate');
  v_teacher_id uuid := public.analytics_current_teacher_id();
  v_can_school boolean := public.is_platform_admin() OR public.secretaria_can_manage_school(p_school_id);
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED';
  END IF;
  IF p_school_id IS NULL THEN
    RAISE EXCEPTION 'SCHOOL_REQUIRED';
  END IF;
  IF v_metric NOT IN ('attendance_rate', 'assessment_average', 'assessment_participation', 'diary_entries_count', 'bncc_percentage') THEN
    RAISE EXCEPTION 'INVALID_METRIC';
  END IF;
  IF NOT v_can_school AND v_teacher_id IS NULL THEN
    RAISE EXCEPTION 'CLASS_COMPARISON_FORBIDDEN';
  END IF;

  RETURN jsonb_build_object(
    'school_id', p_school_id,
    'metric', v_metric,
    'period', jsonb_build_object('date_from', v_from, 'date_to', v_to),
    'school_comparison', 'FUTURE_AFTER_NETWORK_MODEL',
    'classes', coalesce((
      SELECT jsonb_agg(payload ORDER BY (payload->>'value')::numeric ASC, payload->>'class_name')
      FROM (
        SELECT jsonb_build_object(
          'class_id', c.id,
          'class_name', c.nome,
          'value', (metrics->>v_metric)::numeric,
          'attendance_rate', (metrics->>'attendance_rate')::numeric,
          'assessment_average', (metrics->>'assessment_average')::numeric,
          'assessment_participation', (metrics->>'assessment_participation')::numeric,
          'diary_entries_count', (metrics->>'diary_entries_count')::numeric,
          'bncc_percentage', (metrics->>'bncc_percentage')::numeric
        ) AS payload
        FROM public.classes c
        CROSS JOIN LATERAL public.analytics_scope_period_metrics(p_school_id, c.id, NULL, v_from, v_to) metrics
        WHERE c.school_id = p_school_id
          AND coalesce(c.status, 'active') = 'active'
          AND (v_can_school OR public.institutional_teacher_can_manage_class(v_teacher_id, c.id, p_school_id))
      ) rows
    ), '[]'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."analytics_get_class_comparison"("p_school_id" "uuid", "p_date_from" "date", "p_date_to" "date", "p_metric" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_get_class_overview"("p_class_id" "uuid", "p_date_from" "date" DEFAULT NULL::"date", "p_date_to" "date" DEFAULT NULL::"date", "p_school_year" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_from date := coalesce(p_date_from, current_date - 29);
  v_to date := coalesce(p_date_to, current_date);
  v_class public.classes%ROWTYPE;
  v_teacher_id uuid := public.analytics_current_teacher_id();
  v_payload jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED';
  END IF;
  IF p_class_id IS NULL THEN
    RAISE EXCEPTION 'CLASS_REQUIRED';
  END IF;
  IF v_from > v_to THEN
    RAISE EXCEPTION 'INVALID_PERIOD';
  END IF;

  SELECT * INTO v_class
  FROM public.classes
  WHERE id = p_class_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'CLASS_NOT_FOUND';
  END IF;

  IF NOT (
    public.is_platform_admin()
    OR public.secretaria_can_manage_school(v_class.school_id)
    OR (v_teacher_id IS NOT NULL AND public.institutional_teacher_can_manage_class(v_teacher_id, p_class_id, v_class.school_id))
  ) THEN
    RAISE EXCEPTION 'CLASS_ANALYTICS_FORBIDDEN';
  END IF;

  WITH
  active_enrollments AS (
    SELECT e.*, s.nome AS student_name
    FROM public.enrollments e
    JOIN public.students s ON s.id = e.student_id
    WHERE e.class_id = p_class_id
      AND e.school_id = v_class.school_id
      AND e.status = 'active'
      AND coalesce(s.status, 'active') = 'active'
      AND (p_school_year IS NULL OR e.school_year = p_school_year OR v_class.school_year = p_school_year)
      AND e.enrolled_at <= now()
      AND (e.ended_at IS NULL OR e.ended_at > now())
  ),
  attendance AS (
    SELECT
      count(*)::integer AS total_records,
      count(*) FILTER (WHERE ar.status = 'present')::integer AS present,
      count(*) FILTER (WHERE ar.status = 'absent')::integer AS absent,
      count(*) FILTER (WHERE ar.status = 'justified')::integer AS justified,
      CASE WHEN count(*) > 0
        THEN round((count(*) FILTER (WHERE ar.status = 'present')::numeric / count(*)) * 100, 2)
        ELSE 0
      END AS attendance_rate
    FROM public.attendance_records ar
    WHERE ar.class_id = p_class_id
      AND ar.attendance_date BETWEEN v_from AND v_to
  ),
  assignment_scope AS (
    SELECT aa.*
    FROM public.assessment_assignments aa
    WHERE aa.school_id = v_class.school_id
      AND aa.status = 'published'
      AND (
        (aa.target_type = 'class' AND aa.class_id = p_class_id)
        OR (aa.target_type = 'student' AND EXISTS (SELECT 1 FROM active_enrollments e WHERE e.student_id = aa.student_id))
      )
      AND coalesce(aa.available_from, aa.created_at)::date <= v_to
      AND coalesce(aa.available_until, v_to::timestamptz)::date >= v_from
  ),
  assessment_summary AS (
    SELECT
      count(*)::integer AS assignments,
      coalesce(sum(public.analytics_assigned_student_count(aa.id, p_school_year)), 0)::integer AS assigned_students,
      count(distinct res.student_id)::integer AS completed_students,
      CASE WHEN coalesce(sum(public.analytics_assigned_student_count(aa.id, p_school_year)), 0) > 0
        THEN round((count(distinct res.student_id)::numeric / sum(public.analytics_assigned_student_count(aa.id, p_school_year))) * 100, 2)
        ELSE 0
      END AS participation_percentage,
      coalesce(round(avg(res.score_percentage), 2), 0) AS average_percentage
    FROM assignment_scope aa
    LEFT JOIN public.assessment_results res
      ON res.assignment_id = aa.id
      AND res.finalized_at::date BETWEEN v_from AND v_to
  ),
  bncc_skills AS (
    SELECT
      nullif(btrim(qi.bncc_skill), '') AS bncc_skill,
      count(distinct aq.question_id)::integer AS questions,
      count(resp.id)::integer AS responses,
      count(resp.id) FILTER (WHERE resp.is_correct IS TRUE)::integer AS correct,
      CASE WHEN count(resp.id) > 0
        THEN round((count(resp.id) FILTER (WHERE resp.is_correct IS TRUE)::numeric / count(resp.id)) * 100, 2)
        ELSE 0
      END AS percentage
    FROM public.assessment_results res
    JOIN assignment_scope aa ON aa.id = res.assignment_id
    JOIN public.assessment_responses resp ON resp.attempt_id = res.attempt_id
    JOIN public.assessment_questions aq ON aq.assessment_id = res.assessment_id AND aq.question_id = resp.question_id
    JOIN public.question_items qi ON qi.id = aq.question_id
    WHERE res.finalized_at::date BETWEEN v_from AND v_to
      AND nullif(btrim(coalesce(qi.bncc_skill, '')), '') IS NOT NULL
    GROUP BY nullif(btrim(qi.bncc_skill), '')
  ),
  diary AS (
    SELECT
      count(*)::integer AS entries,
      count(distinct cde.entry_date)::integer AS days_with_diary,
      count(*) FILTER (WHERE cde.status = 'closed')::integer AS closed_entries,
      count(cdal.id)::integer AS activity_links
    FROM public.class_diary_entries cde
    LEFT JOIN public.class_diary_activity_links cdal ON cdal.diary_entry_id = cde.id
    WHERE cde.class_id = p_class_id
      AND cde.deleted_at IS NULL
      AND cde.entry_date BETWEEN v_from AND v_to
  ),
  student_rows AS (
    SELECT
      e.student_id,
      e.student_name,
      coalesce(sa.attendance_rate, 0) AS attendance_rate,
      coalesce(sr.completed_assessments, 0) AS completed_assessments,
      coalesce(sr.average_percentage, 0) AS average_percentage
    FROM active_enrollments e
    LEFT JOIN LATERAL (
      SELECT CASE WHEN count(*) > 0
        THEN round((count(*) FILTER (WHERE ar.status = 'present')::numeric / count(*)) * 100, 2)
        ELSE 0 END AS attendance_rate
      FROM public.attendance_records ar
      WHERE ar.student_id = e.student_id
        AND ar.attendance_date BETWEEN v_from AND v_to
    ) sa ON true
    LEFT JOIN LATERAL (
      SELECT count(*)::integer AS completed_assessments, coalesce(round(avg(res.score_percentage), 2), 0) AS average_percentage
      FROM public.assessment_results res
      JOIN assignment_scope aa ON aa.id = res.assignment_id
      WHERE res.student_id = e.student_id
        AND res.finalized_at::date BETWEEN v_from AND v_to
    ) sr ON true
  )
  SELECT jsonb_build_object(
    'period', jsonb_build_object('date_from', v_from, 'date_to', v_to, 'school_year', p_school_year),
    'class', jsonb_build_object('id', v_class.id, 'name', v_class.nome, 'school_id', v_class.school_id, 'school_year', v_class.school_year),
    'summary', jsonb_build_object(
      'active_students', (SELECT count(*) FROM active_enrollments),
      'attendance_rate', (SELECT attendance_rate FROM attendance),
      'assessment_participation', (SELECT participation_percentage FROM assessment_summary),
      'assessment_average', (SELECT average_percentage FROM assessment_summary),
      'diary_entries', (SELECT entries FROM diary),
      'bncc_skills', (SELECT count(*) FROM bncc_skills)
    ),
    'attendance', (SELECT to_jsonb(attendance) FROM attendance),
    'assessment', (SELECT to_jsonb(assessment_summary) FROM assessment_summary),
    'bncc', coalesce((SELECT jsonb_agg(to_jsonb(bncc_skills) ORDER BY percentage ASC, bncc_skill) FROM bncc_skills), '[]'::jsonb),
    'diary', (SELECT to_jsonb(diary) FROM diary),
    'students', coalesce((SELECT jsonb_agg(to_jsonb(student_rows) ORDER BY student_name) FROM student_rows), '[]'::jsonb)
  ) INTO v_payload;

  RETURN v_payload;
END;
$$;


ALTER FUNCTION "public"."analytics_get_class_overview"("p_class_id" "uuid", "p_date_from" "date", "p_date_to" "date", "p_school_year" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_get_period_comparison"("p_school_id" "uuid" DEFAULT NULL::"uuid", "p_class_id" "uuid" DEFAULT NULL::"uuid", "p_student_id" "uuid" DEFAULT NULL::"uuid", "p_current_from" "date" DEFAULT NULL::"date", "p_current_to" "date" DEFAULT NULL::"date", "p_previous_from" "date" DEFAULT NULL::"date", "p_previous_to" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_scope jsonb := public.analytics_resolve_authorized_scope(p_school_id, p_class_id, p_student_id);
  v_school_id uuid := (v_scope->>'school_id')::uuid;
  v_class_id uuid := nullif(v_scope->>'class_id', '')::uuid;
  v_student_id uuid := nullif(v_scope->>'student_id', '')::uuid;
  v_current_to date := coalesce(p_current_to, current_date);
  v_current_from date := coalesce(p_current_from, v_current_to - 29);
  v_previous_to date := coalesce(p_previous_to, v_current_from - 1);
  v_previous_from date := coalesce(p_previous_from, v_previous_to - (v_current_to - v_current_from));
  v_current jsonb;
  v_previous jsonb;
BEGIN
  v_current := public.analytics_scope_period_metrics(v_school_id, v_class_id, v_student_id, v_current_from, v_current_to);
  v_previous := public.analytics_scope_period_metrics(v_school_id, v_class_id, v_student_id, v_previous_from, v_previous_to);

  RETURN jsonb_build_object(
    'scope', v_scope,
    'current_period', jsonb_build_object('date_from', v_current_from, 'date_to', v_current_to),
    'previous_period', jsonb_build_object('date_from', v_previous_from, 'date_to', v_previous_to),
    'metrics', (
      SELECT jsonb_object_agg(metric, jsonb_build_object(
        'current', (v_current->>metric)::numeric,
        'previous', (v_previous->>metric)::numeric,
        'delta_absolute', round(((v_current->>metric)::numeric - (v_previous->>metric)::numeric), 2),
        'delta_percentage', CASE WHEN (v_previous->>metric)::numeric <> 0 THEN round((((v_current->>metric)::numeric - (v_previous->>metric)::numeric) / abs((v_previous->>metric)::numeric)) * 100, 2) ELSE NULL END
      ))
      FROM (VALUES
        ('attendance_rate'),
        ('assessment_participation'),
        ('assessment_average'),
        ('bncc_percentage'),
        ('diary_entries_count')
      ) m(metric)
    ),
    'message', 'Comparativo objetivo entre períodos, sem inferência automática.'
  );
END;
$$;


ALTER FUNCTION "public"."analytics_get_period_comparison"("p_school_id" "uuid", "p_class_id" "uuid", "p_student_id" "uuid", "p_current_from" "date", "p_current_to" "date", "p_previous_from" "date", "p_previous_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_get_school_overview"("p_school_id" "uuid", "p_date_from" "date" DEFAULT NULL::"date", "p_date_to" "date" DEFAULT NULL::"date", "p_school_year" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_from date := coalesce(p_date_from, current_date - 29);
  v_to date := coalesce(p_date_to, current_date);
  v_school public.schools%ROWTYPE;
  v_payload jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED';
  END IF;
  IF p_school_id IS NULL THEN
    RAISE EXCEPTION 'SCHOOL_REQUIRED';
  END IF;
  IF v_from > v_to THEN
    RAISE EXCEPTION 'INVALID_PERIOD';
  END IF;

  SELECT * INTO v_school
  FROM public.schools
  WHERE id = p_school_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'SCHOOL_NOT_FOUND';
  END IF;

  IF NOT (public.is_platform_admin() OR public.secretaria_can_manage_school(p_school_id)) THEN
    RAISE EXCEPTION 'SCHOOL_ANALYTICS_FORBIDDEN';
  END IF;

  WITH
  active_classes AS (
    SELECT c.*
    FROM public.classes c
    WHERE c.school_id = p_school_id
      AND coalesce(c.status, 'active') = 'active'
      AND (p_school_year IS NULL OR c.school_year = p_school_year OR c.ano_escolar = p_school_year)
  ),
  active_enrollments AS (
    SELECT e.*
    FROM public.enrollments e
    JOIN active_classes c ON c.id = e.class_id
    JOIN public.students s ON s.id = e.student_id
    WHERE e.school_id = p_school_id
      AND e.status = 'active'
      AND coalesce(s.status, 'active') = 'active'
      AND (p_school_year IS NULL OR e.school_year = p_school_year OR c.school_year = p_school_year)
      AND e.enrolled_at <= now()
      AND (e.ended_at IS NULL OR e.ended_at > now())
  ),
  attendance AS (
    SELECT
      count(*)::integer AS total_records,
      count(*) FILTER (WHERE ar.status = 'present')::integer AS present,
      count(*) FILTER (WHERE ar.status = 'absent')::integer AS absent,
      count(*) FILTER (WHERE ar.status = 'justified')::integer AS justified,
      CASE WHEN count(*) > 0
        THEN round((count(*) FILTER (WHERE ar.status = 'present')::numeric / count(*)) * 100, 2)
        ELSE 0
      END AS attendance_rate
    FROM public.attendance_records ar
    WHERE ar.school_id = p_school_id
      AND ar.attendance_date BETWEEN v_from AND v_to
  ),
  assignment_scope AS (
    SELECT aa.*
    FROM public.assessment_assignments aa
    WHERE aa.school_id = p_school_id
      AND aa.status = 'published'
      AND coalesce(aa.available_from, aa.created_at)::date <= v_to
      AND coalesce(aa.available_until, v_to::timestamptz)::date >= v_from
  ),
  assessment_summary AS (
    SELECT
      count(*)::integer AS assignments,
      coalesce(sum(public.analytics_assigned_student_count(aa.id, p_school_year)), 0)::integer AS assigned_students,
      count(distinct res.student_id)::integer AS completed_students,
      CASE WHEN coalesce(sum(public.analytics_assigned_student_count(aa.id, p_school_year)), 0) > 0
        THEN round((count(distinct res.student_id)::numeric / sum(public.analytics_assigned_student_count(aa.id, p_school_year))) * 100, 2)
        ELSE 0
      END AS participation_percentage,
      coalesce(round(avg(res.score_percentage), 2), 0) AS average_percentage
    FROM assignment_scope aa
    LEFT JOIN public.assessment_results res
      ON res.assignment_id = aa.id
      AND res.school_id = p_school_id
      AND res.finalized_at::date BETWEEN v_from AND v_to
  ),
  bncc AS (
    SELECT
      count(distinct nullif(btrim(qi.bncc_skill), ''))::integer AS skills,
      count(distinct aq.question_id)::integer AS questions,
      count(resp.id)::integer AS responses,
      count(resp.id) FILTER (WHERE resp.is_correct IS TRUE)::integer AS correct,
      CASE WHEN count(resp.id) > 0
        THEN round((count(resp.id) FILTER (WHERE resp.is_correct IS TRUE)::numeric / count(resp.id)) * 100, 2)
        ELSE 0
      END AS percentage
    FROM public.assessment_results res
    JOIN public.assessment_responses resp ON resp.attempt_id = res.attempt_id
    JOIN public.assessment_questions aq ON aq.assessment_id = res.assessment_id AND aq.question_id = resp.question_id
    JOIN public.question_items qi ON qi.id = aq.question_id
    WHERE res.school_id = p_school_id
      AND res.finalized_at::date BETWEEN v_from AND v_to
      AND nullif(btrim(coalesce(qi.bncc_skill, '')), '') IS NOT NULL
  ),
  diary AS (
    SELECT
      count(*)::integer AS entries,
      count(distinct cde.entry_date)::integer AS days_with_diary,
      count(*) FILTER (WHERE cde.status = 'closed')::integer AS closed_entries,
      count(cdal.id)::integer AS activity_links
    FROM public.class_diary_entries cde
    LEFT JOIN public.class_diary_activity_links cdal ON cdal.diary_entry_id = cde.id
    WHERE cde.school_id = p_school_id
      AND cde.deleted_at IS NULL
      AND cde.entry_date BETWEEN v_from AND v_to
  ),
  class_rows AS (
    SELECT
      c.id,
      c.nome AS name,
      count(distinct e.student_id)::integer AS active_students,
      coalesce(att.attendance_rate, 0) AS attendance_rate,
      coalesce(asm.average_percentage, 0) AS average_percentage,
      coalesce(asm.completed_students, 0) AS completed_students,
      coalesce(d.entries, 0) AS diary_entries
    FROM active_classes c
    LEFT JOIN active_enrollments e ON e.class_id = c.id
    LEFT JOIN LATERAL (
      SELECT CASE WHEN count(*) > 0
        THEN round((count(*) FILTER (WHERE ar.status = 'present')::numeric / count(*)) * 100, 2)
        ELSE 0 END AS attendance_rate
      FROM public.attendance_records ar
      WHERE ar.class_id = c.id
        AND ar.attendance_date BETWEEN v_from AND v_to
    ) att ON true
    LEFT JOIN LATERAL (
      SELECT
        count(distinct res.student_id)::integer AS completed_students,
        coalesce(round(avg(res.score_percentage), 2), 0) AS average_percentage
      FROM public.assessment_results res
      JOIN public.assessment_assignments aa ON aa.id = res.assignment_id
      WHERE aa.class_id = c.id
        AND res.finalized_at::date BETWEEN v_from AND v_to
    ) asm ON true
    LEFT JOIN LATERAL (
      SELECT count(*)::integer AS entries
      FROM public.class_diary_entries cde
      WHERE cde.class_id = c.id
        AND cde.deleted_at IS NULL
        AND cde.entry_date BETWEEN v_from AND v_to
    ) d ON true
    GROUP BY c.id, c.nome, att.attendance_rate, asm.average_percentage, asm.completed_students, d.entries
  )
  SELECT jsonb_build_object(
    'period', jsonb_build_object('date_from', v_from, 'date_to', v_to, 'school_year', p_school_year),
    'school', jsonb_build_object('id', v_school.id, 'name', v_school.nome, 'status', v_school.status),
    'summary', jsonb_build_object(
      'active_students', (SELECT count(distinct student_id) FROM active_enrollments),
      'active_classes', (SELECT count(*) FROM active_classes),
      'teachers', (SELECT count(*) FROM public.teachers t WHERE t.school_id = p_school_id AND coalesce(t.status, 'active') = 'active'),
      'attendance_rate', (SELECT attendance_rate FROM attendance),
      'assessment_participation', (SELECT participation_percentage FROM assessment_summary),
      'assessment_average', (SELECT average_percentage FROM assessment_summary),
      'diary_entries', (SELECT entries FROM diary),
      'bncc_skills', (SELECT skills FROM bncc)
    ),
    'attendance', (SELECT to_jsonb(attendance) FROM attendance),
    'assessment', (SELECT to_jsonb(assessment_summary) FROM assessment_summary),
    'bncc', (SELECT to_jsonb(bncc) FROM bncc),
    'diary', (SELECT to_jsonb(diary) FROM diary),
    'classes', coalesce((SELECT jsonb_agg(to_jsonb(class_rows) ORDER BY name) FROM class_rows), '[]'::jsonb)
  ) INTO v_payload;

  RETURN v_payload;
END;
$$;


ALTER FUNCTION "public"."analytics_get_school_overview"("p_school_id" "uuid", "p_date_from" "date", "p_date_to" "date", "p_school_year" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_get_student_snapshot"("p_student_id" "uuid", "p_date_from" "date" DEFAULT NULL::"date", "p_date_to" "date" DEFAULT NULL::"date", "p_school_year" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_from date := coalesce(p_date_from, current_date - 29);
  v_to date := coalesce(p_date_to, current_date);
  v_student public.students%ROWTYPE;
  v_enrollment public.enrollments%ROWTYPE;
  v_class public.classes%ROWTYPE;
  v_teacher_id uuid := public.analytics_current_teacher_id();
  v_payload jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED';
  END IF;
  IF p_student_id IS NULL THEN
    RAISE EXCEPTION 'STUDENT_REQUIRED';
  END IF;
  IF v_from > v_to THEN
    RAISE EXCEPTION 'INVALID_PERIOD';
  END IF;

  SELECT * INTO v_student
  FROM public.students
  WHERE id = p_student_id
    AND coalesce(status, 'active') = 'active';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'STUDENT_NOT_FOUND';
  END IF;

  SELECT e.* INTO v_enrollment
  FROM public.enrollments e
  WHERE e.student_id = p_student_id
    AND e.school_id = v_student.school_id
    AND e.status = 'active'
    AND (p_school_year IS NULL OR e.school_year = p_school_year)
    AND e.enrolled_at <= now()
    AND (e.ended_at IS NULL OR e.ended_at > now())
  ORDER BY e.enrolled_at DESC
  LIMIT 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ACTIVE_ENROLLMENT_NOT_FOUND';
  END IF;

  SELECT * INTO v_class
  FROM public.classes
  WHERE id = v_enrollment.class_id;

  IF NOT (
    public.is_platform_admin()
    OR public.secretaria_can_manage_school(v_student.school_id)
    OR public.institutional_is_current_student(p_student_id)
    OR (v_teacher_id IS NOT NULL AND public.institutional_teacher_can_manage_class(v_teacher_id, v_enrollment.class_id, v_student.school_id))
  ) THEN
    RAISE EXCEPTION 'STUDENT_ANALYTICS_FORBIDDEN';
  END IF;

  WITH
  attendance AS (
    SELECT
      count(*)::integer AS total_records,
      count(*) FILTER (WHERE ar.status = 'present')::integer AS present,
      count(*) FILTER (WHERE ar.status = 'absent')::integer AS absent,
      count(*) FILTER (WHERE ar.status = 'justified')::integer AS justified,
      CASE WHEN count(*) > 0
        THEN round((count(*) FILTER (WHERE ar.status = 'present')::numeric / count(*)) * 100, 2)
        ELSE 0
      END AS attendance_rate
    FROM public.attendance_records ar
    WHERE ar.student_id = p_student_id
      AND ar.attendance_date BETWEEN v_from AND v_to
  ),
  assignment_scope AS (
    SELECT aa.*
    FROM public.assessment_assignments aa
    WHERE aa.school_id = v_student.school_id
      AND aa.status = 'published'
      AND (
        (aa.target_type = 'student' AND aa.student_id = p_student_id)
        OR (aa.target_type = 'class' AND aa.class_id = v_enrollment.class_id)
      )
      AND coalesce(aa.available_from, aa.created_at)::date <= v_to
      AND coalesce(aa.available_until, v_to::timestamptz)::date >= v_from
  ),
  assessment AS (
    SELECT
      count(distinct aa.id)::integer AS assigned_assessments,
      count(distinct res.id)::integer AS completed_assessments,
      coalesce(round(avg(res.score_percentage), 2), 0) AS average_percentage
    FROM assignment_scope aa
    LEFT JOIN public.assessment_results res
      ON res.assignment_id = aa.id
      AND res.student_id = p_student_id
      AND res.finalized_at::date BETWEEN v_from AND v_to
  ),
  bncc_skills AS (
    SELECT
      nullif(btrim(qi.bncc_skill), '') AS bncc_skill,
      count(distinct aq.question_id)::integer AS questions,
      count(resp.id)::integer AS responses,
      count(resp.id) FILTER (WHERE resp.is_correct IS TRUE)::integer AS correct,
      CASE WHEN count(resp.id) > 0
        THEN round((count(resp.id) FILTER (WHERE resp.is_correct IS TRUE)::numeric / count(resp.id)) * 100, 2)
        ELSE 0
      END AS percentage
    FROM public.assessment_results res
    JOIN public.assessment_responses resp ON resp.attempt_id = res.attempt_id
    JOIN public.assessment_questions aq ON aq.assessment_id = res.assessment_id AND aq.question_id = resp.question_id
    JOIN public.question_items qi ON qi.id = aq.question_id
    WHERE res.student_id = p_student_id
      AND res.finalized_at::date BETWEEN v_from AND v_to
      AND nullif(btrim(coalesce(qi.bncc_skill, '')), '') IS NOT NULL
    GROUP BY nullif(btrim(qi.bncc_skill), '')
  ),
  recommendation_summary AS (
    SELECT count(*)::integer AS recommendations
    FROM public.pedagogical_recommendations pr
    WHERE pr.school_id = v_student.school_id
      AND pr.status = 'published'
      AND pr.deleted_at IS NULL
      AND (
        (pr.target_type = 'student' AND pr.student_id = p_student_id)
        OR (pr.target_type = 'class' AND pr.class_id = v_enrollment.class_id)
      )
      AND pr.published_at::date BETWEEN v_from AND v_to
  ),
  diary_notes AS (
    SELECT count(*)::integer AS notes_count
    FROM public.class_diary_student_notes cdn
    WHERE cdn.student_id = p_student_id
      AND cdn.school_id = v_student.school_id
      AND cdn.status = 'active'
      AND cdn.deleted_at IS NULL
      AND cdn.note_date BETWEEN v_from AND v_to
  )
  SELECT jsonb_build_object(
    'period', jsonb_build_object('date_from', v_from, 'date_to', v_to, 'school_year', coalesce(p_school_year, v_enrollment.school_year)),
    'student', jsonb_build_object('id', v_student.id, 'name', v_student.nome, 'school_id', v_student.school_id, 'class_id', v_enrollment.class_id),
    'class', jsonb_build_object('id', v_class.id, 'name', v_class.nome, 'school_year', v_class.school_year),
    'attendance', (SELECT to_jsonb(attendance) FROM attendance),
    'assessment', (SELECT to_jsonb(assessment) FROM assessment),
    'bncc', coalesce((SELECT jsonb_agg(to_jsonb(bncc_skills) ORDER BY percentage ASC, bncc_skill) FROM bncc_skills), '[]'::jsonb),
    'recommendations', (SELECT to_jsonb(recommendation_summary) FROM recommendation_summary),
    'diary', (SELECT to_jsonb(diary_notes) FROM diary_notes)
  ) INTO v_payload;

  RETURN v_payload;
END;
$$;


ALTER FUNCTION "public"."analytics_get_student_snapshot"("p_student_id" "uuid", "p_date_from" "date", "p_date_to" "date", "p_school_year" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_get_trend_series"("p_school_id" "uuid" DEFAULT NULL::"uuid", "p_class_id" "uuid" DEFAULT NULL::"uuid", "p_student_id" "uuid" DEFAULT NULL::"uuid", "p_metric" "text" DEFAULT 'attendance_rate'::"text", "p_date_from" "date" DEFAULT NULL::"date", "p_date_to" "date" DEFAULT NULL::"date", "p_granularity" "text" DEFAULT 'week'::"text", "p_bncc_skill" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_scope jsonb := public.analytics_resolve_authorized_scope(p_school_id, p_class_id, p_student_id);
  v_school_id uuid := (v_scope->>'school_id')::uuid;
  v_class_id uuid := nullif(v_scope->>'class_id', '')::uuid;
  v_student_id uuid := nullif(v_scope->>'student_id', '')::uuid;
  v_from date := coalesce(p_date_from, current_date - 83);
  v_to date := coalesce(p_date_to, current_date);
  v_metric text := coalesce(nullif(btrim(p_metric), ''), 'attendance_rate');
  v_granularity text := coalesce(nullif(btrim(p_granularity), ''), 'week');
  v_step interval;
  v_points jsonb := '[]'::jsonb;
  v_values numeric[] := '{}';
  v_point_count integer := 0;
  v_previous numeric;
  v_current numeric;
BEGIN
  IF v_from > v_to THEN
    RAISE EXCEPTION 'INVALID_PERIOD';
  END IF;
  IF v_metric NOT IN ('attendance_rate', 'assessment_average', 'assessment_participation', 'diary_entries_count', 'bncc_skill_percentage') THEN
    RAISE EXCEPTION 'INVALID_METRIC';
  END IF;
  IF v_granularity NOT IN ('day', 'week', 'month') THEN
    RAISE EXCEPTION 'INVALID_GRANULARITY';
  END IF;
  v_step := CASE v_granularity WHEN 'day' THEN interval '1 day' WHEN 'week' THEN interval '1 week' ELSE interval '1 month' END;

  IF v_metric = 'attendance_rate' THEN
    WITH buckets AS (
      SELECT generate_series(date_trunc(v_granularity, v_from)::date, date_trunc(v_granularity, v_to)::date, v_step)::date AS bucket_start
    ),
    agg AS (
      SELECT date_trunc(v_granularity, ar.attendance_date)::date AS bucket_start,
        count(*)::integer AS sample_count,
        CASE WHEN count(*) > 0 THEN round((count(*) FILTER (WHERE ar.status = 'present')::numeric / count(*)) * 100, 2) ELSE 0 END AS value
      FROM public.attendance_records ar
      WHERE ar.school_id = v_school_id
        AND ar.attendance_date BETWEEN v_from AND v_to
        AND (v_class_id IS NULL OR ar.class_id = v_class_id)
        AND (v_student_id IS NULL OR ar.student_id = v_student_id)
      GROUP BY 1
    ),
    points AS (
      SELECT b.bucket_start, coalesce(a.value, 0) AS value, coalesce(a.sample_count, 0) AS sample_count
      FROM buckets b LEFT JOIN agg a USING (bucket_start)
      ORDER BY b.bucket_start
    )
    SELECT coalesce(jsonb_agg(jsonb_build_object('period', bucket_start, 'value', value, 'sample_count', sample_count)), '[]'::jsonb),
      coalesce(array_agg(value ORDER BY bucket_start) FILTER (WHERE sample_count > 0), '{}'),
      count(*) FILTER (WHERE sample_count > 0)
    INTO v_points, v_values, v_point_count
    FROM points;
  ELSIF v_metric IN ('assessment_average', 'assessment_participation') THEN
    WITH buckets AS (
      SELECT generate_series(date_trunc(v_granularity, v_from)::date, date_trunc(v_granularity, v_to)::date, v_step)::date AS bucket_start
    ),
    scoped_students AS (
      SELECT DISTINCT s.id AS student_id
      FROM public.students s
      LEFT JOIN public.enrollments e ON e.student_id = s.id AND e.status = 'active'
      WHERE s.school_id = v_school_id
        AND coalesce(s.status, 'active') = 'active'
        AND (v_class_id IS NULL OR e.class_id = v_class_id OR s.class_id = v_class_id)
        AND (v_student_id IS NULL OR s.id = v_student_id)
    ),
    assignments AS (
      SELECT aa.*, date_trunc(v_granularity, coalesce(aa.available_from, aa.created_at))::date AS bucket_start
      FROM public.assessment_assignments aa
      WHERE aa.school_id = v_school_id
        AND aa.status = 'published'
        AND coalesce(aa.available_from, aa.created_at)::date BETWEEN v_from AND v_to
        AND (v_class_id IS NULL OR aa.class_id = v_class_id OR aa.student_id IN (SELECT student_id FROM scoped_students))
        AND (v_student_id IS NULL OR aa.student_id = v_student_id OR (aa.target_type = 'class' AND aa.class_id IN (SELECT e.class_id FROM public.enrollments e WHERE e.student_id = v_student_id AND e.status = 'active')))
    ),
    results AS (
      SELECT ar.*, date_trunc(v_granularity, ar.finalized_at)::date AS bucket_start
      FROM public.assessment_results ar
      JOIN assignments aa ON aa.id = ar.assignment_id
      WHERE ar.finalized_at::date BETWEEN v_from AND v_to
        AND (v_student_id IS NULL OR ar.student_id = v_student_id)
        AND (v_class_id IS NULL OR ar.student_id IN (SELECT student_id FROM scoped_students))
    ),
    agg AS (
      SELECT b.bucket_start,
        count(distinct r.student_id)::integer AS sample_count,
        CASE
          WHEN v_metric = 'assessment_average' THEN coalesce(round(avg(r.score_percentage), 2), 0)
          WHEN coalesce(sum(CASE WHEN v_student_id IS NULL THEN public.analytics_assigned_student_count(a.id, NULL) ELSE 1 END), 0) > 0
            THEN round((count(distinct r.student_id)::numeric / sum(CASE WHEN v_student_id IS NULL THEN public.analytics_assigned_student_count(a.id, NULL) ELSE 1 END)) * 100, 2)
          ELSE 0
        END AS value
      FROM buckets b
      LEFT JOIN assignments a ON a.bucket_start = b.bucket_start
      LEFT JOIN results r ON r.bucket_start = b.bucket_start
      GROUP BY b.bucket_start
    )
    SELECT coalesce(jsonb_agg(jsonb_build_object('period', bucket_start, 'value', value, 'sample_count', sample_count) ORDER BY bucket_start), '[]'::jsonb),
      coalesce(array_agg(value ORDER BY bucket_start) FILTER (WHERE sample_count > 0), '{}'),
      count(*) FILTER (WHERE sample_count > 0)
    INTO v_points, v_values, v_point_count
    FROM agg;
  ELSIF v_metric = 'diary_entries_count' THEN
    WITH buckets AS (
      SELECT generate_series(date_trunc(v_granularity, v_from)::date, date_trunc(v_granularity, v_to)::date, v_step)::date AS bucket_start
    ),
    agg AS (
      SELECT date_trunc(v_granularity, cde.entry_date)::date AS bucket_start, count(*)::integer AS value, count(*)::integer AS sample_count
      FROM public.class_diary_entries cde
      WHERE cde.school_id = v_school_id
        AND cde.deleted_at IS NULL
        AND cde.entry_date BETWEEN v_from AND v_to
        AND (v_class_id IS NULL OR cde.class_id = v_class_id)
      GROUP BY 1
    ),
    points AS (
      SELECT b.bucket_start, coalesce(a.value, 0)::numeric AS value, coalesce(a.sample_count, 0) AS sample_count
      FROM buckets b LEFT JOIN agg a USING (bucket_start)
      ORDER BY b.bucket_start
    )
    SELECT coalesce(jsonb_agg(jsonb_build_object('period', bucket_start, 'value', value, 'sample_count', sample_count)), '[]'::jsonb),
      coalesce(array_agg(value ORDER BY bucket_start) FILTER (WHERE sample_count > 0), '{}'),
      count(*) FILTER (WHERE sample_count > 0)
    INTO v_points, v_values, v_point_count
    FROM points;
  ELSE
    WITH buckets AS (
      SELECT generate_series(date_trunc(v_granularity, v_from)::date, date_trunc(v_granularity, v_to)::date, v_step)::date AS bucket_start
    ),
    scoped_students AS (
      SELECT DISTINCT s.id AS student_id
      FROM public.students s
      LEFT JOIN public.enrollments e ON e.student_id = s.id AND e.status = 'active'
      WHERE s.school_id = v_school_id
        AND coalesce(s.status, 'active') = 'active'
        AND (v_class_id IS NULL OR e.class_id = v_class_id OR s.class_id = v_class_id)
        AND (v_student_id IS NULL OR s.id = v_student_id)
    ),
    agg AS (
      SELECT date_trunc(v_granularity, res.finalized_at)::date AS bucket_start,
        count(resp.id)::integer AS sample_count,
        CASE WHEN count(resp.id) > 0 THEN round((count(resp.id) FILTER (WHERE resp.is_correct IS TRUE)::numeric / count(resp.id)) * 100, 2) ELSE 0 END AS value
      FROM public.assessment_results res
      JOIN public.assessment_responses resp ON resp.attempt_id = res.attempt_id
      JOIN public.assessment_questions aq ON aq.assessment_id = res.assessment_id AND aq.question_id = resp.question_id
      JOIN public.question_items qi ON qi.id = aq.question_id
      WHERE res.school_id = v_school_id
        AND res.finalized_at::date BETWEEN v_from AND v_to
        AND (v_student_id IS NULL OR res.student_id = v_student_id)
        AND (v_class_id IS NULL OR res.student_id IN (SELECT student_id FROM scoped_students))
        AND (p_bncc_skill IS NULL OR qi.bncc_skill = p_bncc_skill)
        AND nullif(btrim(coalesce(qi.bncc_skill, '')), '') IS NOT NULL
      GROUP BY 1
    ),
    points AS (
      SELECT b.bucket_start, coalesce(a.value, 0) AS value, coalesce(a.sample_count, 0) AS sample_count
      FROM buckets b LEFT JOIN agg a USING (bucket_start)
      ORDER BY b.bucket_start
    )
    SELECT coalesce(jsonb_agg(jsonb_build_object('period', bucket_start, 'value', value, 'sample_count', sample_count)), '[]'::jsonb),
      coalesce(array_agg(value ORDER BY bucket_start) FILTER (WHERE sample_count > 0), '{}'),
      count(*) FILTER (WHERE sample_count > 0)
    INTO v_points, v_values, v_point_count
    FROM points;
  END IF;

  IF array_length(v_values, 1) >= 2 THEN
    v_current := v_values[array_length(v_values, 1)];
    v_previous := v_values[array_length(v_values, 1) - 1];
  END IF;

  RETURN jsonb_build_object(
    'scope', v_scope,
    'metric', v_metric,
    'granularity', v_granularity,
    'period', jsonb_build_object('date_from', v_from, 'date_to', v_to),
    'points', v_points,
    'point_count', v_point_count,
    'has_trend', v_point_count >= 2,
    'current_value', v_current,
    'previous_value', v_previous,
    'delta_absolute', CASE WHEN v_point_count >= 2 THEN round(v_current - v_previous, 2) ELSE NULL END,
    'delta_percentage', CASE WHEN v_point_count >= 2 AND v_previous <> 0 THEN round(((v_current - v_previous) / abs(v_previous)) * 100, 2) ELSE NULL END,
    'message', CASE WHEN v_point_count = 0 THEN 'Sem dados no período.' WHEN v_point_count = 1 THEN 'Dados insuficientes para comparar períodos.' ELSE 'Tendência calculada com dados reais.' END
  );
END;
$$;


ALTER FUNCTION "public"."analytics_get_trend_series"("p_school_id" "uuid", "p_class_id" "uuid", "p_student_id" "uuid", "p_metric" "text", "p_date_from" "date", "p_date_to" "date", "p_granularity" "text", "p_bncc_skill" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_resolve_authorized_scope"("p_school_id" "uuid" DEFAULT NULL::"uuid", "p_class_id" "uuid" DEFAULT NULL::"uuid", "p_student_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_school_id uuid := p_school_id;
  v_class_id uuid := p_class_id;
  v_student_id uuid := p_student_id;
  v_teacher_id uuid := public.analytics_current_teacher_id();
  v_student_school_id uuid;
  v_student_class_id uuid;
  v_class_school_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED';
  END IF;

  IF v_student_id IS NOT NULL THEN
    SELECT s.school_id, coalesce(e.class_id, s.class_id)
      INTO v_student_school_id, v_student_class_id
    FROM public.students s
    LEFT JOIN LATERAL (
      SELECT e.class_id
      FROM public.enrollments e
      WHERE e.student_id = s.id
        AND e.status = 'active'
        AND e.enrolled_at <= now()
        AND (e.ended_at IS NULL OR e.ended_at > now())
      ORDER BY e.enrolled_at DESC
      LIMIT 1
    ) e ON true
    WHERE s.id = v_student_id
      AND coalesce(s.status, 'active') = 'active';

    IF v_student_school_id IS NULL THEN
      RAISE EXCEPTION 'STUDENT_NOT_FOUND';
    END IF;
    IF v_school_id IS NOT NULL AND v_school_id <> v_student_school_id THEN
      RAISE EXCEPTION 'SCOPE_MISMATCH';
    END IF;
    IF v_class_id IS NOT NULL AND v_class_id <> v_student_class_id THEN
      RAISE EXCEPTION 'SCOPE_MISMATCH';
    END IF;
    v_school_id := v_student_school_id;
    v_class_id := v_student_class_id;
  END IF;

  IF v_class_id IS NOT NULL THEN
    SELECT c.school_id INTO v_class_school_id
    FROM public.classes c
    WHERE c.id = v_class_id
      AND coalesce(c.status, 'active') = 'active';

    IF v_class_school_id IS NULL THEN
      RAISE EXCEPTION 'CLASS_NOT_FOUND';
    END IF;
    IF v_school_id IS NOT NULL AND v_school_id <> v_class_school_id THEN
      RAISE EXCEPTION 'SCOPE_MISMATCH';
    END IF;
    v_school_id := v_class_school_id;
  END IF;

  IF v_school_id IS NULL THEN
    RAISE EXCEPTION 'SCHOOL_REQUIRED';
  END IF;

  IF v_student_id IS NOT NULL THEN
    IF NOT (
      public.is_platform_admin()
      OR public.secretaria_can_manage_school(v_school_id)
      OR public.institutional_is_current_student(v_student_id)
      OR (v_teacher_id IS NOT NULL AND v_class_id IS NOT NULL AND public.institutional_teacher_can_manage_class(v_teacher_id, v_class_id, v_school_id))
    ) THEN
      RAISE EXCEPTION 'STUDENT_ANALYTICS_FORBIDDEN';
    END IF;
  ELSIF v_class_id IS NOT NULL THEN
    IF NOT (
      public.is_platform_admin()
      OR public.secretaria_can_manage_school(v_school_id)
      OR (v_teacher_id IS NOT NULL AND public.institutional_teacher_can_manage_class(v_teacher_id, v_class_id, v_school_id))
    ) THEN
      RAISE EXCEPTION 'CLASS_ANALYTICS_FORBIDDEN';
    END IF;
  ELSE
    IF NOT (public.is_platform_admin() OR public.secretaria_can_manage_school(v_school_id)) THEN
      RAISE EXCEPTION 'SCHOOL_ANALYTICS_FORBIDDEN';
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'school_id', v_school_id,
    'class_id', v_class_id,
    'student_id', v_student_id,
    'teacher_id', v_teacher_id
  );
END;
$$;


ALTER FUNCTION "public"."analytics_resolve_authorized_scope"("p_school_id" "uuid", "p_class_id" "uuid", "p_student_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_scope_period_metrics"("p_school_id" "uuid", "p_class_id" "uuid" DEFAULT NULL::"uuid", "p_student_id" "uuid" DEFAULT NULL::"uuid", "p_date_from" "date" DEFAULT NULL::"date", "p_date_to" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_from date := coalesce(p_date_from, current_date - 29);
  v_to date := coalesce(p_date_to, current_date);
  v_payload jsonb;
BEGIN
  IF v_from > v_to THEN
    RAISE EXCEPTION 'INVALID_PERIOD';
  END IF;

  WITH
  scoped_students AS (
    SELECT DISTINCT s.id AS student_id
    FROM public.students s
    LEFT JOIN public.enrollments e ON e.student_id = s.id AND e.status = 'active'
    WHERE s.school_id = p_school_id
      AND coalesce(s.status, 'active') = 'active'
      AND (p_class_id IS NULL OR e.class_id = p_class_id OR s.class_id = p_class_id)
      AND (p_student_id IS NULL OR s.id = p_student_id)
  ),
  attendance AS (
    SELECT
      count(*)::integer AS total_records,
      count(*) FILTER (WHERE ar.status = 'present')::integer AS present,
      count(*) FILTER (WHERE ar.status = 'absent')::integer AS absent,
      count(*) FILTER (WHERE ar.status = 'justified')::integer AS justified,
      CASE WHEN count(*) > 0 THEN round((count(*) FILTER (WHERE ar.status = 'present')::numeric / count(*)) * 100, 2) ELSE 0 END AS attendance_rate
    FROM public.attendance_records ar
    WHERE ar.school_id = p_school_id
      AND ar.attendance_date BETWEEN v_from AND v_to
      AND (p_class_id IS NULL OR ar.class_id = p_class_id)
      AND (p_student_id IS NULL OR ar.student_id = p_student_id)
  ),
  assignments AS (
    SELECT aa.*
    FROM public.assessment_assignments aa
    WHERE aa.school_id = p_school_id
      AND aa.status = 'published'
      AND coalesce(aa.available_from, aa.created_at)::date <= v_to
      AND coalesce(aa.available_until, v_to::timestamptz)::date >= v_from
      AND (
        p_class_id IS NULL
        OR aa.class_id = p_class_id
        OR (aa.student_id IS NOT NULL AND aa.student_id IN (SELECT student_id FROM scoped_students))
      )
      AND (
        p_student_id IS NULL
        OR aa.student_id = p_student_id
        OR (aa.target_type = 'class' AND aa.class_id IN (SELECT e.class_id FROM public.enrollments e WHERE e.student_id = p_student_id AND e.status = 'active'))
      )
  ),
  results AS (
    SELECT ar.*
    FROM public.assessment_results ar
    JOIN assignments aa ON aa.id = ar.assignment_id
    WHERE ar.school_id = p_school_id
      AND ar.finalized_at::date BETWEEN v_from AND v_to
      AND (p_student_id IS NULL OR ar.student_id = p_student_id)
      AND (p_class_id IS NULL OR ar.student_id IN (SELECT student_id FROM scoped_students))
  ),
  assessment AS (
    SELECT
      count(distinct aa.id)::integer AS assignments,
      coalesce(sum(CASE WHEN p_student_id IS NULL THEN public.analytics_assigned_student_count(aa.id, NULL) ELSE 1 END), 0)::integer AS assigned_students,
      count(distinct r.student_id)::integer AS completed_students,
      CASE WHEN coalesce(sum(CASE WHEN p_student_id IS NULL THEN public.analytics_assigned_student_count(aa.id, NULL) ELSE 1 END), 0) > 0
        THEN round((count(distinct r.student_id)::numeric / sum(CASE WHEN p_student_id IS NULL THEN public.analytics_assigned_student_count(aa.id, NULL) ELSE 1 END)) * 100, 2)
        ELSE 0
      END AS participation_percentage,
      coalesce(round(avg(r.score_percentage), 2), 0) AS average_percentage
    FROM assignments aa
    LEFT JOIN results r ON r.assignment_id = aa.id
  ),
  bncc AS (
    SELECT
      count(distinct nullif(btrim(qi.bncc_skill), ''))::integer AS skills,
      count(distinct aq.question_id)::integer AS questions,
      count(resp.id)::integer AS responses,
      count(resp.id) FILTER (WHERE resp.is_correct IS TRUE)::integer AS correct,
      CASE WHEN count(resp.id) > 0 THEN round((count(resp.id) FILTER (WHERE resp.is_correct IS TRUE)::numeric / count(resp.id)) * 100, 2) ELSE 0 END AS percentage
    FROM results r
    JOIN public.assessment_responses resp ON resp.attempt_id = r.attempt_id
    JOIN public.assessment_questions aq ON aq.assessment_id = r.assessment_id AND aq.question_id = resp.question_id
    JOIN public.question_items qi ON qi.id = aq.question_id
    WHERE nullif(btrim(coalesce(qi.bncc_skill, '')), '') IS NOT NULL
  ),
  diary AS (
    SELECT count(*)::integer AS entries
    FROM public.class_diary_entries cde
    WHERE cde.school_id = p_school_id
      AND cde.deleted_at IS NULL
      AND cde.entry_date BETWEEN v_from AND v_to
      AND (p_class_id IS NULL OR cde.class_id = p_class_id)
  )
  SELECT jsonb_build_object(
    'attendance_rate', (SELECT attendance_rate FROM attendance),
    'attendance_records', (SELECT total_records FROM attendance),
    'assessment_average', (SELECT average_percentage FROM assessment),
    'assessment_participation', (SELECT participation_percentage FROM assessment),
    'assessment_assignments', (SELECT assignments FROM assessment),
    'assessment_completed', (SELECT completed_students FROM assessment),
    'bncc_percentage', (SELECT percentage FROM bncc),
    'bncc_skills', (SELECT skills FROM bncc),
    'diary_entries_count', (SELECT entries FROM diary)
  ) INTO v_payload;

  RETURN v_payload;
END;
$$;


ALTER FUNCTION "public"."analytics_scope_period_metrics"("p_school_id" "uuid", "p_class_id" "uuid", "p_student_id" "uuid", "p_date_from" "date", "p_date_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."attendance_guardian_can_read"("p_student_id" "uuid") RETURNS boolean
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.student_guardians sg
    where sg.student_id = p_student_id
      and sg.profile_id = auth.uid()
      and sg.status = 'active'
  );
$$;


ALTER FUNCTION "public"."attendance_guardian_can_read"("p_student_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."attendance_teacher_can_record"("p_class_id" "uuid", "p_student_id" "uuid", "p_enrollment_id" "uuid", "p_attendance_date" "date") RETURNS boolean
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.enrollments e
    join public.classes c on c.id = e.class_id
    join public.class_teacher_memberships ctm on ctm.class_id = c.id
    join public.teachers t on t.id = ctm.teacher_id
    where e.id = p_enrollment_id
      and e.student_id = p_student_id
      and e.class_id = p_class_id
      and e.school_id = c.school_id
      and e.status = 'active'
      and (e.enrolled_at is null or e.enrolled_at::date <= p_attendance_date)
      and (e.ended_at is null or e.ended_at::date >= p_attendance_date)
      and c.status = 'active'
      and ctm.status = 'active'
      and ctm.started_at <= now()
      and (ctm.ended_at is null or ctm.ended_at > now())
      and t.profile_id = auth.uid()
  );
$$;


ALTER FUNCTION "public"."attendance_teacher_can_record"("p_class_id" "uuid", "p_student_id" "uuid", "p_enrollment_id" "uuid", "p_attendance_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."avalia_assessment_is_assignable"("p_assessment_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.assessments a
    where a.id = p_assessment_id
      and a.archived_at is null
      and a.status in ('RASCUNHO', 'PRONTA', 'ATRIBUIDA', 'APLICADA')
      and exists (
        select 1
        from public.assessment_questions aq
        where aq.assessment_id = a.id
      )
  );
$$;


ALTER FUNCTION "public"."avalia_assessment_is_assignable"("p_assessment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."avalia_can_read_assignment"("p_assignment_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.assessment_assignments aa
    where aa.id = p_assignment_id
      and (
        public.is_platform_admin()
        or public.secretaria_can_manage_school(aa.school_id)
        or public.avalia_teacher_can_manage_assignment(aa.id)
        or public.avalia_student_can_access_assignment(aa.id, public.avalia_current_student_id())
      )
  );
$$;


ALTER FUNCTION "public"."avalia_can_read_assignment"("p_assignment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."avalia_can_read_attempt"("p_attempt_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.assessment_attempts at
    where at.id = p_attempt_id
      and (
        public.is_platform_admin()
        or public.secretaria_can_manage_school(at.school_id)
        or public.avalia_teacher_can_manage_assignment(at.assignment_id)
        or public.institutional_is_current_student(at.student_id)
      )
  );
$$;


ALTER FUNCTION "public"."avalia_can_read_attempt"("p_attempt_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."avalia_current_student_id"() RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT s.id
  FROM public.students s
  LEFT JOIN public.users u ON u.id = s.user_id
  WHERE lower(coalesce(s.status, 'active')) IN ('active', 'ativo')
    AND (
      s.user_id = auth.uid()
      OR lower(coalesce(s.email, '')) = lower(coalesce(auth.jwt() ->> 'email', ''))
      OR lower(coalesce(u.email, '')) = lower(coalesce(auth.jwt() ->> 'email', ''))
    )
  ORDER BY s.updated_at DESC NULLS LAST, s.created_at DESC NULLS LAST
  LIMIT 1;
$$;


ALTER FUNCTION "public"."avalia_current_student_id"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."avalia_current_teacher_id"() RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select t.id
  from public.teachers t
  where t.profile_id = auth.uid()
    and coalesce(t.status, 'active') = 'active'
  order by t.updated_at desc nulls last, t.created_at desc nulls last
  limit 1;
$$;


ALTER FUNCTION "public"."avalia_current_teacher_id"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."avalia_plus_alternative_order"("p_question_ids" "uuid"[], "p_attempt_id" "uuid", "p_shuffle" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select coalesce(jsonb_object_agg(question_id::text, alternatives), '{}'::jsonb)
  from (
    select qid as question_id,
      (
        select coalesce(jsonb_agg(id order by sort_key), '[]'::jsonb)
        from (
          select qa.id,
                 case when p_shuffle then md5(p_attempt_id::text || ':' || qid::text || ':' || qa.id::text) else lpad(qa.position::text, 8, '0') end as sort_key
          from public.question_alternatives qa
          where qa.question_id = qid
        ) alt
      ) as alternatives
    from unnest(coalesce(p_question_ids, '{}'::uuid[])) qid
  ) mapped;
$$;


ALTER FUNCTION "public"."avalia_plus_alternative_order"("p_question_ids" "uuid"[], "p_attempt_id" "uuid", "p_shuffle" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."avalia_plus_assert_intelligence_scope"("p_scope" "text", "p_assignment_id" "uuid" DEFAULT NULL::"uuid", "p_school_id" "uuid" DEFAULT NULL::"uuid", "p_class_id" "uuid" DEFAULT NULL::"uuid", "p_network_id" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_assignment public.assessment_assignments%rowtype;
begin
  if auth.uid() is null then
    raise exception 'AUTH_REQUIRED' using errcode = '42501';
  end if;

  if p_scope = 'assignment' then
    select * into v_assignment from public.assessment_assignments where id = p_assignment_id;
    if v_assignment.id is null then
      raise exception 'ASSIGNMENT_NOT_FOUND';
    end if;
    if not (
      public.is_platform_admin()
      or public.secretaria_can_manage_school(v_assignment.school_id)
      or public.avalia_plus_teacher_can_manage_class(v_assignment.class_id, v_assignment.school_id)
    ) then
      raise exception 'ASSESSMENT_INTELLIGENCE_FORBIDDEN' using errcode = '42501';
    end if;
    return true;
  end if;

  if p_scope = 'class' then
    if not exists (
      select 1
      from public.classes c
      where c.id = p_class_id
        and (public.is_platform_admin() or public.secretaria_can_manage_school(c.school_id) or public.avalia_plus_teacher_can_manage_class(c.id, c.school_id))
    ) then
      raise exception 'CLASS_INTELLIGENCE_FORBIDDEN' using errcode = '42501';
    end if;
    return true;
  end if;

  if p_scope = 'school' then
    if not (public.is_platform_admin() or public.secretaria_can_manage_school(p_school_id)) then
      raise exception 'SCHOOL_INTELLIGENCE_FORBIDDEN' using errcode = '42501';
    end if;
    return true;
  end if;

  if p_scope = 'network' then
    if not public.network_can_read(p_network_id) then
      raise exception 'NETWORK_INTELLIGENCE_FORBIDDEN' using errcode = '42501';
    end if;
    return true;
  end if;

  raise exception 'INVALID_INTELLIGENCE_SCOPE';
end;
$$;


ALTER FUNCTION "public"."avalia_plus_assert_intelligence_scope"("p_scope" "text", "p_assignment_id" "uuid", "p_school_id" "uuid", "p_class_id" "uuid", "p_network_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."assessment_assignments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
