    "closed_at" timestamp with time zone,
    CONSTRAINT "assessment_assignments_application_status_check" CHECK (("application_status" = ANY (ARRAY['AGENDADA'::"text", 'EM_ANDAMENTO'::"text", 'CONCLUIDA'::"text", 'INCOMPLETA'::"text", 'CANCELADA'::"text"]))),
    CONSTRAINT "assessment_assignments_max_attempts_check" CHECK (("max_attempts" > 0)),
    CONSTRAINT "assessment_assignments_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'published'::"text", 'closed'::"text", 'archived'::"text"]))),
    CONSTRAINT "assessment_assignments_target_shape_check" CHECK (((("target_type" = 'class'::"text") AND ("student_id" IS NULL)) OR (("target_type" = 'student'::"text") AND ("student_id" IS NOT NULL)))),
    CONSTRAINT "assessment_assignments_target_type_check" CHECK (("target_type" = ANY (ARRAY['class'::"text", 'student'::"text"]))),
    CONSTRAINT "assessment_assignments_time_limit_check" CHECK ((("time_limit_minutes" IS NULL) OR ("time_limit_minutes" > 0))),
    CONSTRAINT "assessment_assignments_window_check" CHECK ((("available_until" IS NULL) OR ("available_until" > "available_from")))
);


