CREATE OR REPLACE FUNCTION "public"."avalia_plus_build_progress"("p_attempt_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'question_count', at.question_count,
    'answered_count', coalesce(count(ar.id), 0),
    'remaining_seconds', case when at.deadline_at is null then null else greatest(0, floor(extract(epoch from (at.deadline_at - now())))::integer) end,
    'last_autosaved_at', at.last_autosaved_at
  )
  from public.assessment_attempts at
  left join public.assessment_responses ar on ar.attempt_id = at.id
  where at.id = p_attempt_id
  group by at.id;
$$;


ALTER FUNCTION "public"."avalia_plus_build_progress"("p_attempt_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."avalia_plus_build_skill_map"("p_assessment_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'skill', skill,
      'descriptor', descriptor,
      'questions', question_count,
      'points', points
    )
    order by skill, descriptor
  ), '[]'::jsonb)
  from (
    select
      coalesce(nullif(qi.bncc_skill, ''), 'NAO_INFORMADA') as skill,
      coalesce(nullif(qi.reference_matrix, ''), nullif(qi.curriculum_matrix, ''), 'NAO_INFORMADO') as descriptor,
      count(*)::integer as question_count,
      coalesce(sum(aq.points), 0) as points
    from public.assessment_questions aq
    join public.question_items qi on qi.id = aq.question_id
    where aq.assessment_id = p_assessment_id
    group by 1, 2
  ) mapped;
$$;


ALTER FUNCTION "public"."avalia_plus_build_skill_map"("p_assessment_id" "uuid") OWNER TO "postgres";


