    CONSTRAINT "question_items_check1" CHECK ((("legal_classification" <> 'ITEM_BLOQUEADO_PUBLICACAO'::"public"."question_legal_classification") OR ("publication_status" <> 'PUBLICADO'::"public"."question_publication_status"))),
    CONSTRAINT "question_items_curriculum_source_check" CHECK (("curriculum_source" = ANY (ARRAY['BNCC'::"text", 'SAEB'::"text", 'CURRICULO_PROPRIO'::"text", 'BNCC_SAEB'::"text", 'OUTRO'::"text"]))),
    CONSTRAINT "question_items_estimated_minutes_check" CHECK ((("estimated_minutes" IS NULL) OR ("estimated_minutes" > 0))),
    CONSTRAINT "question_items_workflow_status_check" CHECK (("workflow_status" = ANY (ARRAY['EM_ELABORACAO'::"text", 'EM_REVISAO'::"text", 'APROVADO'::"text", 'ARQUIVADO'::"text"]))),
