CREATE OR REPLACE FUNCTION "public"."avalia_plus_get_irt_analytics"("p_scope" "text" DEFAULT 'network'::"text", "p_assessment_id" "uuid" DEFAULT NULL::"uuid", "p_school_id" "uuid" DEFAULT NULL::"uuid", "p_class_id" "uuid" DEFAULT NULL::"uuid", "p_network_id" "uuid" DEFAULT NULL::"uuid", "p_date_from" "date" DEFAULT ((CURRENT_DATE - '365 days'::interval))::"date", "p_date_to" "date" DEFAULT CURRENT_DATE) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_scope text := lower(coalesce(nullif(p_scope, ''), 'network'));
  v_network_id uuid := p_network_id;
begin
  if v_network_id is null and v_scope = 'network' then
    v_network_id := public.network_resolve_requested_network(null);
  end if;

  perform public.avalia_plus_assert_intelligence_scope(v_scope, null, p_school_id, p_class_id, v_network_id);

  return (
    with scoped as (
      select
        isp.*,
        aa.class_id as assignment_class_id,
        c.nome as class_name,
        s.nome as school_name,
        nsm.network_id,
        a.title as assessment_title,
        a.component,
        a.school_year,
        cal.method,
        cal.status as calibration_status
      from public.assessment_irt_student_proficiencies isp
      join public.assessment_irt_calibrations cal on cal.id = isp.calibration_id
      join public.assessment_assignments aa on aa.id = isp.assignment_id
      join public.assessments a on a.id = isp.assessment_id
      left join public.classes c on c.id = coalesce(isp.class_id, aa.class_id)
      left join public.schools s on s.id = isp.school_id
      left join public.network_school_memberships nsm on nsm.school_id = isp.school_id and nsm.status = 'active'
      where isp.estimation_status = 'VALID'
        and isp.estimated_at::date between p_date_from and p_date_to
        and (p_assessment_id is null or isp.assessment_id = p_assessment_id)
        and (p_school_id is null or isp.school_id = p_school_id)
        and (p_class_id is null or coalesce(isp.class_id, aa.class_id) = p_class_id)
        and (v_network_id is null or nsm.network_id = v_network_id)
    ), student_rows as (
      select coalesce(jsonb_agg(to_jsonb(row_data) order by student_name), '[]'::jsonb) as data
      from (
        select sp.student_id, st.nome as student_name, sp.school_id, sp.school_name, sp.assignment_class_id as class_id, sp.class_name,
               count(*)::integer as estimates, round(avg(sp.theta), 4) as theta, round(avg(sp.tri_proficiency), 2) as tri_proficiency,
               round(avg(sp.raw_score_percentage), 2) as percentual_acerto, max(sp.estimated_at) as last_estimated_at
        from scoped sp
        join public.students st on st.id = sp.student_id
        group by sp.student_id, st.nome, sp.school_id, sp.school_name, sp.assignment_class_id, sp.class_name
      ) row_data
    ), class_rows as (
      select coalesce(jsonb_agg(to_jsonb(row_data) order by class_name), '[]'::jsonb) as data
      from (
        select assignment_class_id as class_id, class_name, school_id, school_name, count(distinct student_id)::integer as students,
               round(avg(theta), 4) as theta, round(avg(tri_proficiency), 2) as tri_proficiency, round(stddev_samp(tri_proficiency), 2) as distribution_sd
        from scoped
        group by assignment_class_id, class_name, school_id, school_name
      ) row_data
    ), school_rows as (
      select coalesce(jsonb_agg(to_jsonb(row_data) order by school_name), '[]'::jsonb) as data
      from (
        select school_id, school_name, count(distinct assignment_class_id)::integer as classes, count(distinct student_id)::integer as students,
               round(avg(theta), 4) as theta, round(avg(tri_proficiency), 2) as tri_proficiency
        from scoped
        group by school_id, school_name
      ) row_data
    ), evolution as (
      select coalesce(jsonb_agg(to_jsonb(row_data) order by period), '[]'::jsonb) as data
      from (
        select date_trunc('month', estimated_at)::date as period, count(*)::integer as estimates,
               round(avg(theta), 4) as theta, round(avg(tri_proficiency), 2) as tri_proficiency
        from scoped
        group by 1
      ) row_data
    )
    select jsonb_build_object(
      'status', case when (select count(*) from scoped) > 0 then 'PASS' else 'EMPTY_REAL' end,
      'scope', v_scope,
      'period', jsonb_build_object('from', p_date_from, 'to', p_date_to),
      'summary', jsonb_build_object(
        'estimates', coalesce((select count(*) from scoped), 0),
        'students', coalesce((select count(distinct student_id) from scoped), 0),
        'classes', coalesce((select count(distinct assignment_class_id) from scoped), 0),
        'schools', coalesce((select count(distinct school_id) from scoped), 0),
        'theta', coalesce((select round(avg(theta), 4) from scoped), 0),
        'tri_proficiency', coalesce((select round(avg(tri_proficiency), 2) from scoped), 0),
        'percentual_acerto', coalesce((select round(avg(raw_score_percentage), 2) from scoped), 0),
        'percentual_acerto_and_tri_are_distinct', true
      ),
      'hierarchy', jsonb_build_object(
        'students', (select data from student_rows),
        'classes', (select data from class_rows),
        'schools', (select data from school_rows),
        'network', jsonb_build_object('network_id', v_network_id, 'theta', coalesce((select round(avg(theta), 4) from scoped), 0), 'tri_proficiency', coalesce((select round(avg(tri_proficiency), 2) from scoped), 0))
      ),
      'evolution', (select data from evolution),
      'traceability', jsonb_build_object('calibration_required', true, 'client_side_tri_trust', 'ZERO', 'official_saeb_equivalence', 'NOT_DECLARED')
    )
  );
end;
$$;


ALTER FUNCTION "public"."avalia_plus_get_irt_analytics"("p_scope" "text", "p_assessment_id" "uuid", "p_school_id" "uuid", "p_class_id" "uuid", "p_network_id" "uuid", "p_date_from" "date", "p_date_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."avalia_plus_get_pedagogical_intelligence"("p_scope" "text", "p_assignment_id" "uuid" DEFAULT NULL::"uuid", "p_assessment_id" "uuid" DEFAULT NULL::"uuid", "p_school_id" "uuid" DEFAULT NULL::"uuid", "p_class_id" "uuid" DEFAULT NULL::"uuid", "p_network_id" "uuid" DEFAULT NULL::"uuid", "p_date_from" "date" DEFAULT NULL::"date", "p_date_to" "date" DEFAULT NULL::"date", "p_component" "text" DEFAULT NULL::"text", "p_school_year" "text" DEFAULT NULL::"text", "p_booklet_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_scope text := lower(coalesce(p_scope, ''));
  v_network_id uuid := p_network_id;
  v_from date := coalesce(p_date_from, current_date - 365);
  v_to date := coalesce(p_date_to, current_date);
  v_payload jsonb;
begin
  if v_scope = 'network' then
    v_network_id := public.network_resolve_requested_network(p_network_id);
  end if;

  perform public.avalia_plus_assert_intelligence_scope(v_scope, p_assignment_id, p_school_id, p_class_id, v_network_id);

  with scoped_results as (
    select
      ar.*,
      aa.class_id,
      aa.target_type,
      aa.booklet_id,
      a.title as assessment_title,
      a.component,
      a.school_year,
      c.nome as class_name,
      s.nome as school_name,
      nsm.network_id,
      public.avalia_plus_classify_proficiency(ar.score_percentage, ar.assessment_id, ar.school_id, nsm.network_id) as proficiency
    from public.assessment_results ar
    join public.assessment_assignments aa on aa.id = ar.assignment_id
    join public.assessments a on a.id = ar.assessment_id
    left join public.classes c on c.id = aa.class_id
    left join public.schools s on s.id = ar.school_id
    left join public.network_school_memberships nsm on nsm.school_id = ar.school_id
      and nsm.status = 'active'
      and nsm.joined_at <= now()
      and (nsm.ended_at is null or nsm.ended_at > now())
    where ar.status in ('submitted', 'graded')
      and ar.finalized_at::date between v_from and v_to
      and (p_assignment_id is null or ar.assignment_id = p_assignment_id)
      and (p_assessment_id is null or ar.assessment_id = p_assessment_id)
      and (p_school_id is null or ar.school_id = p_school_id)
      and (p_class_id is null or aa.class_id = p_class_id)
      and (v_network_id is null or nsm.network_id = v_network_id)
      and (p_component is null or a.component = p_component)
      and (p_school_year is null or a.school_year = p_school_year)
      and (p_booklet_id is null or aa.booklet_id = p_booklet_id)
  ), response_scope as (
    select
      sr.*,
      resp.id as response_id,
      resp.question_id,
      resp.is_correct,
      resp.score_awarded,
      aq.position as question_position,
      aq.points,
      qi.code,
      qi.internal_title,
      qi.statement,
      qi.component as question_component,
      qi.school_year as question_school_year,
      qi.thematic_unit,
      qi.knowledge_object,
      qi.bncc_skill,
      qi.reference_matrix,
      qi.curriculum_matrix,
      qi.difficulty
    from scoped_results sr
    join public.assessment_responses resp on resp.attempt_id = sr.attempt_id
    join public.assessment_questions aq on aq.assessment_id = sr.assessment_id and aq.question_id = resp.question_id
    join public.question_items qi on qi.id = resp.question_id
  ), hierarchy_student as (
    select coalesce(jsonb_agg(to_jsonb(row_data) order by student_name), '[]'::jsonb) as data
    from (
      select
        sr.student_id,
        st.nome as student_name,
        sr.class_id,
        sr.class_name,
        sr.school_id,
        sr.school_name,
        count(*)::integer as results,
        round(avg(sr.score_percentage), 2) as average_percentage,
        max(sr.finalized_at) as last_result_at,
        public.avalia_plus_classify_proficiency(avg(sr.score_percentage), null, sr.school_id, sr.network_id) as proficiency
      from scoped_results sr
      join public.students st on st.id = sr.student_id
      group by sr.student_id, st.nome, sr.class_id, sr.class_name, sr.school_id, sr.school_name, sr.network_id
    ) row_data
  ), hierarchy_class as (
    select coalesce(jsonb_agg(to_jsonb(row_data) order by class_name), '[]'::jsonb) as data
    from (
      select
        sr.class_id,
        sr.class_name,
        sr.school_id,
        sr.school_name,
        count(distinct sr.student_id)::integer as students,
        count(*)::integer as results,
        round(avg(sr.score_percentage), 2) as average_percentage,
        public.avalia_plus_classify_proficiency(avg(sr.score_percentage), null, sr.school_id, sr.network_id) as proficiency
      from scoped_results sr
      group by sr.class_id, sr.class_name, sr.school_id, sr.school_name, sr.network_id
    ) row_data
  ), hierarchy_school as (
    select coalesce(jsonb_agg(to_jsonb(row_data) order by school_name), '[]'::jsonb) as data
    from (
      select
        sr.school_id,
        sr.school_name,
        count(distinct sr.class_id)::integer as classes,
        count(distinct sr.student_id)::integer as students,
        count(*)::integer as results,
        round(avg(sr.score_percentage), 2) as average_percentage,
        public.avalia_plus_classify_proficiency(avg(sr.score_percentage), null, sr.school_id, sr.network_id) as proficiency
      from scoped_results sr
      group by sr.school_id, sr.school_name, sr.network_id
    ) row_data
  ), hierarchy_network as (
    select jsonb_build_object(
      'network_id', v_network_id,
      'schools', count(distinct school_id),
      'classes', count(distinct class_id),
      'students', count(distinct student_id),
      'results', count(*),
      'average_percentage', coalesce(round(avg(score_percentage), 2), 0),
      'proficiency', public.avalia_plus_classify_proficiency(avg(score_percentage), null, null, v_network_id)
    ) as data
    from scoped_results
  ), curriculum as (
    select coalesce(jsonb_agg(to_jsonb(row_data) order by performance_percentage asc, skill), '[]'::jsonb) as data
    from (
      select
        coalesce(nullif(btrim(rs.thematic_unit), ''), 'NAO_INFORMADA') as thematic_unit,
        coalesce(nullif(btrim(rs.knowledge_object), ''), 'NAO_INFORMADO') as knowledge_object,
        coalesce(nullif(btrim(rs.bncc_skill), ''), 'SEM_HABILIDADE') as skill,
        coalesce(nullif(btrim(rs.reference_matrix), ''), nullif(btrim(rs.curriculum_matrix), ''), 'SEM_DESCRITOR') as descriptor,
        count(distinct rs.question_id)::integer as questions,
        count(rs.response_id)::integer as responses,
        count(rs.response_id) filter (where rs.is_correct is true)::integer as correct,
        round((count(rs.response_id) filter (where rs.is_correct is true)::numeric / nullif(count(rs.response_id), 0)) * 100, 2) as performance_percentage,
        case
          when count(rs.response_id) < 5 then 'INSUFFICIENT_SAMPLE'
          when (count(rs.response_id) filter (where rs.is_correct is true)::numeric / nullif(count(rs.response_id), 0)) < 0.6 then 'CRITICAL'
          else 'OK'
        end as learning_status
      from response_scope rs
      group by 1, 2, 3, 4
    ) row_data
  ), proficiency_distribution as (
    select coalesce(jsonb_agg(to_jsonb(row_data) order by position), '[]'::jsonb) as data
    from (
      select
        sr.proficiency->>'level_code' as level_code,
        sr.proficiency->>'label' as label,
        coalesce((sr.proficiency->>'position')::integer, 0) as position,
        count(*)::integer as results,
        count(distinct sr.student_id)::integer as students,
        round(avg(sr.score_percentage), 2) as average_percentage
      from scoped_results sr
      group by sr.proficiency->>'level_code', sr.proficiency->>'label', coalesce((sr.proficiency->>'position')::integer, 0)
    ) row_data
  ), item_stats_base as (
    select
      rs.question_id,
      min(rs.question_position) as position,
      max(coalesce(rs.internal_title, left(rs.statement, 120), rs.code, 'Questao')) as title,
      max(rs.bncc_skill) as bncc_skill,
      max(coalesce(rs.reference_matrix, rs.curriculum_matrix)) as descriptor,
      max(rs.difficulty) as planned_difficulty,
      count(rs.response_id)::integer as responses,
      count(rs.response_id) filter (where rs.is_correct is true)::integer as correct,
      round((count(rs.response_id) filter (where rs.is_correct is true)::numeric / nullif(count(rs.response_id), 0)) * 100, 2) as percent_correct,
      round((count(rs.response_id) filter (where rs.is_correct is true)::numeric / nullif(count(rs.response_id), 0)), 4) as difficulty_index,
      round(corr(case when rs.is_correct is true then 1::double precision else 0::double precision end, sr.score_percentage::double precision)::numeric, 4) as point_biserial
    from response_scope rs
    join scoped_results sr on sr.attempt_id = rs.attempt_id
    group by rs.question_id
  ), item_discrimination as (
    select
      question_id,
      round(
        (
          avg(case when is_correct is true then 1::numeric else 0::numeric end) filter (where score_band = 'top')
          -
          avg(case when is_correct is true then 1::numeric else 0::numeric end) filter (where score_band = 'bottom')
        ),
        4
      ) as discrimination_index
    from (
      select
        rs.question_id,
        rs.is_correct,
        case
          when ntile(4) over (partition by rs.question_id order by sr.score_percentage desc) = 1 then 'top'
          when ntile(4) over (partition by rs.question_id order by sr.score_percentage asc) = 1 then 'bottom'
          else 'middle'
        end as score_band
      from response_scope rs
      join scoped_results sr on sr.attempt_id = rs.attempt_id
    ) ranked
    group by question_id
  ), item_stats as (
    select coalesce(jsonb_agg(
      jsonb_build_object(
        'question_id', b.question_id,
        'position', b.position,
        'title', b.title,
        'bncc_skill', b.bncc_skill,
        'descriptor', b.descriptor,
        'planned_difficulty', b.planned_difficulty,
        'responses', b.responses,
        'correct', b.correct,
        'percent_correct', coalesce(b.percent_correct, 0),
        'difficulty_index', case when b.responses >= 3 then b.difficulty_index else null end,
        'difficulty_status', case when b.responses >= 3 then 'PASS' else 'INSUFFICIENT_SAMPLE' end,
        'discrimination_index', case when b.responses >= 8 then d.discrimination_index else null end,
        'discrimination_status', case when b.responses >= 8 then 'PASS' else 'INSUFFICIENT_SAMPLE' end,
        'point_biserial', case when b.responses >= 5 then b.point_biserial else null end,
        'point_biserial_status', case when b.responses >= 5 then 'PASS' else 'INSUFFICIENT_SAMPLE' end
      )
      order by b.position
    ), '[]'::jsonb) as data
    from item_stats_base b
    left join item_discrimination d on d.question_id = b.question_id
  ), item_variances as (
    select
      question_id,
      var_samp(case when is_correct is true then 1::numeric else 0::numeric end) as item_variance
    from response_scope
    group by question_id
  ), attempt_scores as (
    select
      attempt_id,
      max(score_percentage) as total_score
    from response_scope
    group by attempt_id
  ), reliability as (
    select jsonb_build_object(
      'sample_size', attempt_stats.sample_size,
      'question_count', item_stats.question_count,
      'cronbach_alpha',
        case
          when attempt_stats.sample_size >= 5 and item_stats.question_count > 1 and nullif(attempt_stats.total_variance, 0) is not null
          then round(((item_stats.question_count::numeric / (item_stats.question_count::numeric - 1)) * (1 - (item_stats.item_variance_sum / nullif(attempt_stats.total_variance, 0))))::numeric, 4)
          else null
        end,
      'status',
        case
          when attempt_stats.sample_size >= 5 and item_stats.question_count > 1 and nullif(attempt_stats.total_variance, 0) is not null then 'PASS'
          else 'INSUFFICIENT_SAMPLE'
        end
    ) as data
    from (
      select
        coalesce(count(*)::integer, 0) as question_count,
        coalesce(sum(item_variance), 0) as item_variance_sum
      from item_variances
    ) item_stats
    cross join (
      select
        coalesce(count(*)::integer, 0) as sample_size,
        var_samp(total_score) as total_variance
      from attempt_scores
    ) attempt_stats
  ), evolution as (
    select coalesce(jsonb_agg(to_jsonb(row_data) order by period), '[]'::jsonb) as data
    from (
      select
        date_trunc('month', finalized_at)::date as period,
        count(*)::integer as results,
        round(avg(score_percentage), 2) as average_percentage
      from scoped_results
      group by 1
      having count(*) > 0
      order by 1
    ) row_data
  ), official_report_payload as (
    select jsonb_build_object(
      'report_type', 'avalia',
      'engine', 'official_reports_p0_live',
      'ready_for_export', true,
      'filters', jsonb_build_object(
        'scope', v_scope,
        'assignment_id', p_assignment_id,
        'assessment_id', p_assessment_id,
        'school_id', p_school_id,
        'class_id', p_class_id,
        'network_id', v_network_id,
        'date_from', v_from,
        'date_to', v_to,
        'component', p_component,
        'school_year', p_school_year,
        'booklet_id', p_booklet_id
      )
    ) as data
  )
  select jsonb_build_object(
    'scope', v_scope,
    'period', jsonb_build_object('date_from', v_from, 'date_to', v_to),
    'summary', jsonb_build_object(
      'students', (select count(distinct student_id) from scoped_results),
      'classes', (select count(distinct class_id) from scoped_results),
      'schools', (select count(distinct school_id) from scoped_results),
      'results', (select count(*) from scoped_results),
      'average_percentage', coalesce((select round(avg(score_percentage), 2) from scoped_results), 0)
    ),
    'hierarchy', jsonb_build_object(
      'students', (select data from hierarchy_student),
      'classes', (select data from hierarchy_class),
      'schools', (select data from hierarchy_school),
      'network', (select data from hierarchy_network)
    ),
    'curriculum', (select data from curriculum),
    'proficiency', jsonb_build_object(
      'thresholds', public.avalia_plus_default_proficiency_thresholds(),
      'distribution', (select data from proficiency_distribution)
    ),
    'items', (select data from item_stats),
    'reliability', (select data from reliability),
    'evolution', (select data from evolution),
    'official_report', (select data from official_report_payload),
    'metadata', jsonb_build_object('duplicate_analytics_engine', false, 'tri', false)
  ) into v_payload;

  return v_payload;
end;
$$;


ALTER FUNCTION "public"."avalia_plus_get_pedagogical_intelligence"("p_scope" "text", "p_assignment_id" "uuid", "p_assessment_id" "uuid", "p_school_id" "uuid", "p_class_id" "uuid", "p_network_id" "uuid", "p_date_from" "date", "p_date_to" "date", "p_component" "text", "p_school_year" "text", "p_booklet_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."avalia_plus_irt_can_manage_assessment"("p_assessment_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.assessments a
    where a.id = p_assessment_id
      and (
        public.is_platform_admin()
        or (a.school_id is not null and public.secretaria_can_manage_school(a.school_id))
        or exists (select 1 from public.assessment_assignments aa where aa.assessment_id = a.id and public.secretaria_can_manage_school(aa.school_id))
      )
  );
$$;


ALTER FUNCTION "public"."avalia_plus_irt_can_manage_assessment"("p_assessment_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."assessment_irt_scale_levels" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "assessment_id" "uuid",
    "school_id" "uuid",
    "network_id" "uuid",
    "level_code" "text" NOT NULL,
    "label" "text" NOT NULL,
    "min_theta" numeric(10,6) NOT NULL,
    "max_theta" numeric(10,6) NOT NULL,
    "min_tri_proficiency" numeric(10,2),
    "max_tri_proficiency" numeric(10,2),
    "position" integer NOT NULL,
    "active" boolean DEFAULT true NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "assessment_irt_scale_levels_position_check" CHECK (("position" > 0)),
    CONSTRAINT "assessment_irt_scale_levels_scope_check" CHECK ((("assessment_id" IS NOT NULL) OR ("school_id" IS NOT NULL) OR ("network_id" IS NOT NULL))),
    CONSTRAINT "assessment_irt_scale_levels_theta_check" CHECK (("min_theta" <= "max_theta"))
);


ALTER TABLE "public"."assessment_irt_scale_levels" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."avalia_plus_irt_configure_scale_level"("p_level" "jsonb") RETURNS "public"."assessment_irt_scale_levels"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_row public.assessment_irt_scale_levels%rowtype;
  v_assessment_id uuid := nullif(p_level->>'assessment_id', '')::uuid;
  v_school_id uuid := nullif(p_level->>'school_id', '')::uuid;
  v_network_id uuid := nullif(p_level->>'network_id', '')::uuid;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode = '42501'; end if;
  if not (public.is_platform_admin() or (v_assessment_id is not null and public.avalia_plus_irt_can_manage_assessment(v_assessment_id)) or (v_school_id is not null and public.secretaria_can_manage_school(v_school_id)) or (v_network_id is not null and public.network_can_read(v_network_id))) then
    raise exception 'IRT_SCALE_FORBIDDEN' using errcode = '42501';
  end if;
  insert into public.assessment_irt_scale_levels (assessment_id, school_id, network_id, level_code, label, min_theta, max_theta, min_tri_proficiency, max_tri_proficiency, position, metadata, created_by)
  values (v_assessment_id, v_school_id, v_network_id, upper(coalesce(nullif(p_level->>'level_code', ''), 'LEVEL')), coalesce(nullif(p_level->>'label', ''), upper(coalesce(nullif(p_level->>'level_code', ''), 'LEVEL'))), (p_level->>'min_theta')::numeric, (p_level->>'max_theta')::numeric, nullif(p_level->>'min_tri_proficiency', '')::numeric, nullif(p_level->>'max_tri_proficiency', '')::numeric, coalesce((p_level->>'position')::integer, 1), coalesce(p_level->'metadata', '{}'::jsonb), auth.uid())
  returning * into v_row;
  return v_row;
end;
$$;


ALTER FUNCTION "public"."avalia_plus_irt_configure_scale_level"("p_level" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."avalia_plus_irt_estimate_theta"("p_attempt_id" "uuid", "p_calibration_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_theta numeric := 0;
  v_score numeric;
  v_info numeric;
  v_p numeric;
  v_prime numeric;
  v_step numeric;
  v_iter integer;
  v_responses integer;
  v_cal public.assessment_irt_calibrations%rowtype;
  r record;
begin
  select * into v_cal from public.assessment_irt_calibrations where id = p_calibration_id and status = 'VALID';
  if not found then return jsonb_build_object('status', 'INSUFFICIENT_CALIBRATION'); end if;

  select count(*) into v_responses
  from public.assessment_responses resp
  join public.assessment_irt_item_parameters ip on ip.calibration_id = p_calibration_id and ip.question_id = resp.question_id
  where resp.attempt_id = p_attempt_id and ip.status = 'VALID' and resp.is_correct is not null;

  if coalesce(v_responses, 0) < 3 then
    return jsonb_build_object('status', 'INSUFFICIENT_RESPONSES', 'responses', coalesce(v_responses, 0));
  end if;

  for v_iter in 1..20 loop
    v_score := 0;
    v_info := 0;
    for r in
      select case when resp.is_correct is true then 1::numeric else 0::numeric end as u,
             coalesce(ip.parameter_a, 1) as a,
             coalesce(ip.parameter_b, 0) as b,
             coalesce(ip.parameter_c, 0) as c
      from public.assessment_responses resp
      join public.assessment_irt_item_parameters ip on ip.calibration_id = p_calibration_id and ip.question_id = resp.question_id
      where resp.attempt_id = p_attempt_id and ip.status = 'VALID' and resp.is_correct is not null
    loop
      v_p := public.avalia_plus_irt_probability(v_theta, r.a, r.b, r.c, v_cal.model_type);
      v_prime := 1.702 * r.a * (v_p - r.c) * (1 - v_p) / greatest(1 - r.c, 0.000001);
      v_score := v_score + ((r.u - v_p) * v_prime / greatest(v_p * (1 - v_p), 0.000001));
      v_info := v_info + ((v_prime * v_prime) / greatest(v_p * (1 - v_p), 0.000001));
    end loop;
    exit when v_info is null or v_info <= 0;
    v_step := greatest(least(v_score / v_info, 1), -1);
    v_theta := greatest(least(v_theta + v_step, 4), -4);
    exit when abs(v_step) < 0.001;
  end loop;

  return jsonb_build_object('status', 'VALID', 'theta', round(v_theta, 6), 'theta_se', case when v_info > 0 then round((1 / sqrt(v_info))::numeric, 6) else null end, 'responses', v_responses, 'iterations', v_iter, 'tri_proficiency', public.avalia_plus_irt_scale_score(v_theta));
end;
$$;


ALTER FUNCTION "public"."avalia_plus_irt_estimate_theta"("p_attempt_id" "uuid", "p_calibration_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."avalia_plus_irt_probability"("p_theta" numeric, "p_a" numeric, "p_b" numeric, "p_c" numeric DEFAULT 0, "p_model_type" "text" DEFAULT '2PL'::"text") RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
declare
  v_a numeric := case when upper(coalesce(p_model_type, '2PL')) = '1PL' then 1 else greatest(coalesce(p_a, 1), 0.05) end;
  v_b numeric := coalesce(p_b, 0);
  v_c numeric := case when upper(coalesce(p_model_type, '2PL')) = '3PL' then greatest(least(coalesce(p_c, 0), 0.95), 0) else 0 end;
  v_exp double precision;
  v_p numeric;
begin
  v_exp := exp((-1.702 * v_a * (coalesce(p_theta, 0) - v_b))::double precision);
  v_p := v_c + (1 - v_c) * (1 / (1 + v_exp))::numeric;
  return greatest(least(v_p, 0.999999), 0.000001);
end;
$$;


ALTER FUNCTION "public"."avalia_plus_irt_probability"("p_theta" numeric, "p_a" numeric, "p_b" numeric, "p_c" numeric, "p_model_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."avalia_plus_irt_run_calibration"("p_assessment_id" "uuid", "p_model_type" "text" DEFAULT '2PL'::"text", "p_method" "text" DEFAULT 'SERVER_SIDE_MLE'::"text", "p_min_sample_size" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_model text := upper(coalesce(nullif(p_model_type, ''), '2PL'));
  v_method text := upper(coalesce(nullif(p_method, ''), 'SERVER_SIDE_MLE'));
  v_min_sample integer := greatest(coalesce(p_min_sample_size, 30), 5);
  v_assessment public.assessments%rowtype;
  v_version integer;
  v_sample integer;
  v_item_count integer;
  v_status text;
  v_calibration_id uuid;
  v_result record;
  v_estimate jsonb;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode = '42501'; end if;
  if v_model not in ('1PL', '2PL', '3PL') then raise exception 'UNSUPPORTED_IRT_MODEL'; end if;
  if v_method not in ('SERVER_SIDE_MLE', 'CLASSICAL_INITIALIZATION', 'EXTERNAL_CALIBRATION') then raise exception 'UNSUPPORTED_IRT_METHOD'; end if;
  select * into v_assessment from public.assessments where id = p_assessment_id;
  if not found then raise exception 'ASSESSMENT_NOT_FOUND'; end if;
  if not public.avalia_plus_irt_can_manage_assessment(p_assessment_id) then raise exception 'UNAUTHORIZED_CALIBRATION' using errcode = '42501'; end if;

  select count(distinct student_id) into v_sample from public.assessment_results where assessment_id = p_assessment_id and status in ('submitted', 'graded');
  select count(*) into v_item_count from public.assessment_questions where assessment_id = p_assessment_id;
  select coalesce(max(version_number), 0) + 1 into v_version from public.assessment_irt_calibrations where assessment_id = p_assessment_id and model_type = v_model;
  v_status := case when coalesce(v_sample, 0) < v_min_sample or coalesce(v_item_count, 0) = 0 then 'INSUFFICIENT_SAMPLE' else 'VALID' end;

  insert into public.assessment_irt_calibrations (assessment_id, school_id, network_id, model_type, method, version_number, status, sample_size, item_count, min_sample_size, metrics, created_by, calibrated_at)
  values (p_assessment_id, v_assessment.school_id, null, v_model, v_method, v_version, v_status, coalesce(v_sample, 0), coalesce(v_item_count, 0), v_min_sample, jsonb_build_object('percentual_acerto_preserved', true, 'tri_proficiency_separate', true, 'client_side_tri_trust', 'ZERO', 'sample_status', v_status), auth.uid(), case when v_status = 'VALID' then now() else null end)
  returning id into v_calibration_id;

  with item_observed as (
    select aq.id as assessment_question_id,
           aq.question_id,
           qi.workflow_version as item_version,
           count(resp.id)::integer as response_count,
           count(resp.id) filter (where resp.is_correct is true)::integer as correct_count,
           (count(resp.id) filter (where resp.is_correct is true)::numeric / nullif(count(resp.id), 0)) as p_value,
           corr(case when resp.is_correct is true then 1::double precision else 0::double precision end, ar.score_percentage::double precision)::numeric as point_biserial,
           greatest(count(qa.id), 1)::numeric as alternatives_count
    from public.assessment_questions aq
    join public.question_items qi on qi.id = aq.question_id
    left join public.assessment_responses resp on resp.question_id = aq.question_id
    left join public.assessment_results ar on ar.attempt_id = resp.attempt_id and ar.assessment_id = aq.assessment_id
    left join public.question_alternatives qa on qa.question_id = aq.question_id
    where aq.assessment_id = p_assessment_id
    group by aq.id, aq.question_id, qi.workflow_version
  )
  insert into public.assessment_irt_item_parameters (calibration_id, assessment_id, assessment_question_id, question_id, item_version, parameter_a, parameter_b, parameter_c, response_count, correct_count, quality_metrics, status)
  select v_calibration_id,
         p_assessment_id,
         assessment_question_id,
         question_id,
         item_version,
         case when v_status <> 'VALID' then null when v_model = '1PL' then 1 else round(greatest(0.25, least(3, 1 + coalesce(point_biserial, 0)))::numeric, 6) end,
         case when v_status <> 'VALID' or p_value is null then null else round(greatest(least(ln((1 - greatest(least(p_value, 0.99), 0.01)) / greatest(least(p_value, 0.99), 0.01)), 4), -4)::numeric, 6) end,
         case when v_status <> 'VALID' then null when v_model = '3PL' then round(least(0.35, 1 / nullif(alternatives_count, 0))::numeric, 6) else 0 end,
         coalesce(response_count, 0),
         coalesce(correct_count, 0),
         jsonb_build_object('p_value', p_value, 'point_biserial', point_biserial, 'parameter_source', case when v_status = 'VALID' then 'SERVER_SIDE_OBSERVED_RESPONSES' else 'INSUFFICIENT_SAMPLE' end, 'c_source', case when v_model = '3PL' then 'ALTERNATIVE_COUNT' else 'NOT_APPLICABLE' end),
         case when v_status = 'VALID' then 'VALID' else 'INSUFFICIENT_SAMPLE' end
  from item_observed;

  if v_status = 'VALID' then
    for v_result in
      select ar.*, aa.class_id
      from public.assessment_results ar
      join public.assessment_assignments aa on aa.id = ar.assignment_id
      where ar.assessment_id = p_assessment_id and ar.status in ('submitted', 'graded')
    loop
      v_estimate := public.avalia_plus_irt_estimate_theta(v_result.attempt_id, v_calibration_id);
      insert into public.assessment_irt_student_proficiencies (calibration_id, assessment_id, assignment_id, assessment_result_id, attempt_id, student_id, school_id, class_id, model_type, calibration_version, theta, theta_se, tri_proficiency, raw_score_percentage, estimation_status, traceability)
      values (v_calibration_id, v_result.assessment_id, v_result.assignment_id, v_result.id, v_result.attempt_id, v_result.student_id, v_result.school_id, v_result.class_id, v_model, v_version, nullif(v_estimate->>'theta', '')::numeric, nullif(v_estimate->>'theta_se', '')::numeric, nullif(v_estimate->>'tri_proficiency', '')::numeric, v_result.score_percentage, coalesce(v_estimate->>'status', 'INSUFFICIENT_RESPONSES'), jsonb_build_object('model', v_model, 'calibration_id', v_calibration_id, 'calibration_version', v_version, 'method', v_method, 'estimated_server_side', true, 'percentual_acerto_preserved', v_result.score_percentage, 'estimate', v_estimate))
      on conflict (calibration_id, assessment_result_id) do update
      set theta = excluded.theta, theta_se = excluded.theta_se, tri_proficiency = excluded.tri_proficiency, estimation_status = excluded.estimation_status, traceability = excluded.traceability, estimated_at = now();
    end loop;
  end if;

  return jsonb_build_object('calibration_id', v_calibration_id, 'assessment_id', p_assessment_id, 'model_type', v_model, 'method', v_method, 'version_number', v_version, 'status', v_status, 'sample_size', coalesce(v_sample, 0), 'item_count', coalesce(v_item_count, 0), 'min_sample_size', v_min_sample, 'insufficient_sample', v_status = 'INSUFFICIENT_SAMPLE', 'client_side_tri_trust', 'ZERO');
end;
$$;


ALTER FUNCTION "public"."avalia_plus_irt_run_calibration"("p_assessment_id" "uuid", "p_model_type" "text", "p_method" "text", "p_min_sample_size" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."avalia_plus_irt_run_calibration"("p_assessment_id" "uuid", "p_model_type" "text", "p_method" "text", "p_min_sample_size" integer) IS 'Executa calibracao TRI server-side e grava rastreabilidade; nao confia em calculos do frontend.';



CREATE OR REPLACE FUNCTION "public"."avalia_plus_irt_scale_score"("p_theta" numeric) RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    AS $$ select round((500 + (coalesce(p_theta, 0) * 100))::numeric, 2); $$;


ALTER FUNCTION "public"."avalia_plus_irt_scale_score"("p_theta" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."avalia_plus_item_is_used"("p_question_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (select 1 from public.assessment_questions aq where aq.question_id = p_question_id)
    or exists (select 1 from public.assessment_booklet_questions abq where abq.question_id = p_question_id);
$$;


ALTER FUNCTION "public"."avalia_plus_item_is_used"("p_question_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."avalia_plus_question_order"("p_assessment_id" "uuid", "p_booklet_id" "uuid", "p_attempt_id" "uuid", "p_shuffle" boolean DEFAULT false) RETURNS "uuid"[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select coalesce(array_agg(question_id order by sort_key), '{}'::uuid[])
  from (
    select aq.question_id,
           case when p_shuffle then md5(p_attempt_id::text || ':' || aq.question_id::text) else lpad(aq.position::text, 8, '0') end as sort_key
    from public.assessment_questions aq
    where aq.assessment_id = p_assessment_id
      and (
        p_booklet_id is null
        or exists (
          select 1 from public.assessment_booklet_questions abq
          where abq.booklet_id = p_booklet_id and abq.assessment_question_id = aq.id
        )
      )
  ) ordered;
$$;


ALTER FUNCTION "public"."avalia_plus_question_order"("p_assessment_id" "uuid", "p_booklet_id" "uuid", "p_attempt_id" "uuid", "p_shuffle" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."avalia_plus_question_snapshot"("p_question_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select jsonb_build_object(
    'question', to_jsonb(qi),
    'alternatives', coalesce((
      select jsonb_agg(to_jsonb(qa) order by qa.position)
      from public.question_alternatives qa
      where qa.question_id = qi.id
    ), '[]'::jsonb),
    'media', coalesce((
      select jsonb_agg(to_jsonb(qm) order by qm.created_at)
      from public.question_media qm
      where qm.question_id = qi.id
    ), '[]'::jsonb),
    'version_number', qi.workflow_version,
    'snapshot_at', now()
  )
  from public.question_items qi
  where qi.id = p_question_id;
$$;


ALTER FUNCTION "public"."avalia_plus_question_snapshot"("p_question_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."avalia_plus_record_item_version"("p_question_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_item public.question_items%rowtype;
  v_version_id uuid;
begin
  select * into v_item from public.question_items where id = p_question_id;
  if not found then
    raise exception 'QUESTION_NOT_FOUND';
  end if;

  insert into public.question_item_versions (
    question_id,
    version_number,
    version_label,
    workflow_status,
    publication_status,
    curation_status,
    snapshot,
    created_by,
    reason
  )
  values (
    p_question_id,
    v_item.workflow_version,
    v_item.version,
    v_item.workflow_status,
    v_item.publication_status,
    v_item.curation_status,
    public.avalia_plus_question_snapshot(p_question_id),
    auth.uid(),
    p_reason
  )
  on conflict (question_id, version_number) do update
  set
    snapshot = excluded.snapshot,
    reason = coalesce(excluded.reason, public.question_item_versions.reason)
  returning id into v_version_id;

  return v_version_id;
end;
$$;


ALTER FUNCTION "public"."avalia_plus_record_item_version"("p_question_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."avalia_plus_replace_assessment_items"("p_assessment_id" "uuid", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_assessment public.assessments%rowtype;
  v_question jsonb;
  v_question_id uuid;
  v_position integer := 0;
  v_points numeric(8,2);
  v_booklet jsonb;
  v_booklet_row public.assessment_booklets%rowtype;
  v_booklet_count integer;
  v_assessment_question_id uuid;
begin
  select * into v_assessment
  from public.assessments
  where id = p_assessment_id
  for update;

  if not found then
    raise exception 'ASSESSMENT_NOT_FOUND';
  end if;

  if not (
    v_assessment.owner_user_id = auth.uid()
    or public.has_question_bank_role(array['admin', 'administrador', 'administrador_nacional', 'gestor', 'gestor_da_rede', 'service_role'])
  ) then
    raise exception 'UNAUTHORIZED_ASSESSMENT_ASSEMBLY';
  end if;

  update public.assessments
  set
    title = coalesce(nullif(p_payload->>'title', ''), title),
    description = coalesce(p_payload->>'description', description),
    instructions = coalesce(p_payload->>'instructions', instructions),
    application_date = coalesce(nullif(p_payload->>'application_date', '')::date, application_date),
    component = coalesce(p_payload->>'component', component),
    school_year = coalesce(p_payload->>'school_year', school_year),
    class_name = coalesce(p_payload->>'class_name', class_name),
    cover_template = coalesce(p_payload->>'cover_template', cover_template),
    assessment_year = coalesce(p_payload->>'assessment_year', assessment_year),
    matrix = coalesce(p_payload->>'matrix', matrix),
    max_booklets = least(greatest(coalesce(jsonb_array_length(coalesce(p_payload->'booklets', '[]'::jsonb)), 1), 1), 5),
    metadata = coalesce(p_payload->'metadata', metadata),
    updated_at = now()
  where id = p_assessment_id
  returning * into v_assessment;

  delete from public.assessment_booklets where assessment_id = p_assessment_id;
  delete from public.assessment_questions where assessment_id = p_assessment_id;

  for v_question in select * from jsonb_array_elements(coalesce(p_payload->'questions', '[]'::jsonb))
  loop
    v_question_id := nullif(v_question->>'question_id', '')::uuid;
    v_points := coalesce(nullif(v_question->>'points', '')::numeric, 1);

    if not exists (
      select 1 from public.question_items qi
      where qi.id = v_question_id
        and qi.workflow_status = 'APROVADO'
        and qi.publication_status = 'PUBLICADO'
    ) then
      raise exception 'ONLY_APPROVED_ITEMS_CAN_BE_USED:%', v_question_id;
    end if;

    v_position := v_position + 1;
    insert into public.assessment_questions (
      assessment_id,
      question_id,
      position,
      points,
      version_snapshot
    )
    values (
      p_assessment_id,
      v_question_id,
      v_position,
      v_points,
      public.avalia_plus_question_snapshot(v_question_id)
    );
  end loop;

  v_booklet_count := jsonb_array_length(coalesce(p_payload->'booklets', '[]'::jsonb));
  if v_booklet_count > 5 then
    raise exception 'MAX_FIVE_BOOKLETS';
  end if;

  if v_booklet_count = 0 then
    insert into public.assessment_booklets (assessment_id, code, title, position)
    values (p_assessment_id, 'A', 'Caderno A', 1)
    returning * into v_booklet_row;

    insert into public.assessment_booklet_questions (
      booklet_id,
      assessment_question_id,
      question_id,
      position,
      version_snapshot
    )
    select
      v_booklet_row.id,
      aq.id,
      aq.question_id,
      aq.position,
      aq.version_snapshot
    from public.assessment_questions aq
    where aq.assessment_id = p_assessment_id
    order by aq.position;

    update public.assessment_booklets
    set question_count = (select count(*) from public.assessment_booklet_questions where booklet_id = v_booklet_row.id),
        skill_map = public.avalia_plus_build_skill_map(p_assessment_id),
        updated_at = now()
    where id = v_booklet_row.id;
  else
    for v_booklet in select * from jsonb_array_elements(p_payload->'booklets')
    loop
      insert into public.assessment_booklets (assessment_id, code, title, position)
      values (
        p_assessment_id,
        coalesce(nullif(v_booklet->>'code', ''), chr(64 + coalesce(nullif(v_booklet->>'position', '')::integer, 1))),
        coalesce(v_booklet->>'title', 'Caderno ' || coalesce(v_booklet->>'code', '')),
        coalesce(nullif(v_booklet->>'position', '')::integer, 1)
      )
      returning * into v_booklet_row;

      for v_question in select * from jsonb_array_elements(coalesce(v_booklet->'questions', '[]'::jsonb))
      loop
        v_question_id := nullif(v_question->>'question_id', '')::uuid;
        select aq.id into v_assessment_question_id
        from public.assessment_questions aq
        where aq.assessment_id = p_assessment_id
          and aq.question_id = v_question_id
        limit 1;

        if v_assessment_question_id is null then
          raise exception 'BOOKLET_QUESTION_NOT_IN_ASSESSMENT:%', v_question_id;
        end if;

        insert into public.assessment_booklet_questions (
          booklet_id,
          assessment_question_id,
          question_id,
          position,
          version_snapshot
        )
        values (
          v_booklet_row.id,
          v_assessment_question_id,
          v_question_id,
          coalesce(nullif(v_question->>'position', '')::integer, 1),
          public.avalia_plus_question_snapshot(v_question_id)
        );
      end loop;

      update public.assessment_booklets
      set question_count = (select count(*) from public.assessment_booklet_questions where booklet_id = v_booklet_row.id),
          skill_map = public.avalia_plus_build_skill_map(p_assessment_id),
          updated_at = now()
      where id = v_booklet_row.id;
    end loop;
  end if;

  update public.assessments
  set
    total_points = coalesce((select sum(points) from public.assessment_questions where assessment_id = p_assessment_id), 0),
    skill_map = public.avalia_plus_build_skill_map(p_assessment_id),
    updated_at = now()
  where id = p_assessment_id
  returning * into v_assessment;

  return jsonb_build_object(
    'assessment', to_jsonb(v_assessment),
    'questions', (
      select coalesce(jsonb_agg(to_jsonb(aq) order by aq.position), '[]'::jsonb)
      from public.assessment_questions aq
      where aq.assessment_id = p_assessment_id
    ),
    'booklets', (
      select coalesce(jsonb_agg(to_jsonb(ab) order by ab.position), '[]'::jsonb)
      from public.assessment_booklets ab
      where ab.assessment_id = p_assessment_id
    ),
    'skill_map', v_assessment.skill_map
  );
end;
$$;


