CREATE OR REPLACE FUNCTION "public"."avalia_plus_token_hash"("p_token" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select encode(digest(coalesce(p_token, ''), 'sha256'), 'hex');
$$;


ALTER FUNCTION "public"."avalia_plus_token_hash"("p_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."avalia_plus_touch_item_version"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if tg_op = 'UPDATE' and (
    old.statement is distinct from new.statement
    or old.command_text is distinct from new.command_text
    or old.correct_answer is distinct from new.correct_answer
    or old.justification is distinct from new.justification
    or old.bncc_skill is distinct from new.bncc_skill
    or old.reference_matrix is distinct from new.reference_matrix
    or old.curriculum_matrix is distinct from new.curriculum_matrix
    or old.difficulty is distinct from new.difficulty
  ) then
    if public.avalia_plus_item_is_used(old.id) or old.workflow_status = 'APROVADO' then
      perform public.avalia_plus_record_item_version(old.id, 'before-content-update');
      new.workflow_version := old.workflow_version + 1;
      new.version := split_part(coalesce(old.version, '1.0'), '.', 1) || '.' || new.workflow_version::text;
      new.workflow_status := 'EM_ELABORACAO';
      new.curation_status := 'RASCUNHO';
      new.publication_status := 'NAO_PUBLICADO';
      new.approved_at := null;
      new.approver_user_id := null;
      new.published_at := null;
    end if;
  end if;

  new.updated_at := now();
  return new;
end;
$$;


ALTER FUNCTION "public"."avalia_plus_touch_item_version"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."avalia_plus_validate_token"("p_assignment_id" "uuid", "p_student_id" "uuid", "p_token" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_assignment public.assessment_assignments%rowtype;
  v_token public.assessment_application_tokens%rowtype;
begin
  select * into v_assignment from public.assessment_assignments where id = p_assignment_id;
  if v_assignment.id is null then
    raise exception 'Atribuicao nao encontrada.' using errcode = '42501';
  end if;
  if coalesce(v_assignment.token_required, false) is false then
    return null;
  end if;
  if nullif(btrim(coalesce(p_token, '')), '') is null then
    raise exception 'Token de aplicacao obrigatorio.' using errcode = '42501';
  end if;
  select * into v_token
  from public.assessment_application_tokens t
  where t.assignment_id = p_assignment_id
    and t.token_hash = public.avalia_plus_token_hash(p_token)
    and t.revoked_at is null
    and t.valid_from <= now()
    and (t.valid_until is null or t.valid_until > now())
    and (t.student_id is null or t.student_id = p_student_id)
    and (t.max_uses is null or t.use_count < t.max_uses)
  order by t.student_id nulls last, t.created_at desc
  limit 1
  for update;
  if v_token.id is null then
    raise exception 'Token de aplicacao invalido ou expirado.' using errcode = '42501';
  end if;
  update public.assessment_application_tokens set use_count = use_count + 1, last_used_at = now() where id = v_token.id;
  return v_token.id;
end;
$$;


ALTER FUNCTION "public"."avalia_plus_validate_token"("p_assignment_id" "uuid", "p_student_id" "uuid", "p_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."avalia_student_can_access_assignment"("p_assignment_id" "uuid", "p_student_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.assessment_assignments aa
    join public.enrollments e
      on e.student_id = p_student_id
     and e.class_id = aa.class_id
     and e.school_id = aa.school_id
     and e.status = 'active'
     and e.enrolled_at <= now()
     and (e.ended_at is null or e.ended_at > now())
    join public.students s on s.id = e.student_id
    left join public.users u on u.id = s.user_id
    where aa.id = p_assignment_id
      and aa.status = 'published'
      and aa.available_from <= now()
      and (aa.available_until is null or aa.available_until > now())
      and coalesce(s.status, 'active') = 'active'
      and (aa.target_type = 'class' or aa.student_id = p_student_id)
      and (
        s.user_id = auth.uid()
        or lower(coalesce(s.email, '')) = lower(coalesce(auth.jwt() ->> 'email', ''))
        or lower(coalesce(u.email, '')) = lower(coalesce(auth.jwt() ->> 'email', ''))
      )
  );
$$;


