    "school_id" "uuid",
    "professor_student_enabled" boolean DEFAULT true NOT NULL,
    "professor_professor_enabled" boolean DEFAULT true NOT NULL,
    "professor_coordination_enabled" boolean DEFAULT true NOT NULL,
    "student_student_enabled" boolean DEFAULT false NOT NULL,
    "external_guest_messages_enabled" boolean DEFAULT false NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "updated_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."communication_permission_settings" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."communication_permissions_for_school"("p_school_id" "uuid") RETURNS "public"."communication_permission_settings"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_settings public.communication_permission_settings%rowtype;
begin
  select * into v_settings
  from public.communication_permission_settings
  where school_id = p_school_id;

  if v_settings.id is null then
    select * into v_settings
    from public.communication_permission_settings
    where school_id is null
    limit 1;
  end if;

  if v_settings.id is null then
    v_settings.professor_student_enabled := true;
    v_settings.professor_professor_enabled := true;
    v_settings.professor_coordination_enabled := true;
    v_settings.student_student_enabled := false;
    v_settings.external_guest_messages_enabled := false;
  end if;

  return v_settings;
end;
$$;


ALTER FUNCTION "public"."communication_permissions_for_school"("p_school_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."communication_report_delivery"("p_delivery_id" "uuid", "p_reason" "text", "p_description" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_delivery public.communication_deliveries%rowtype;
  v_report public.communication_moderation_reports%rowtype;
begin
  select * into v_delivery
  from public.communication_deliveries
  where id = p_delivery_id;

  if v_delivery.id is null or v_delivery.recipient_profile_id <> auth.uid() then
    raise exception 'Entrega nao encontrada ou nao autorizada';
  end if;

  insert into public.communication_moderation_reports (
    communication_id, delivery_id, school_id, reporter_profile_id, reason, description
  )
  values (v_delivery.communication_id, v_delivery.id, v_delivery.school_id, auth.uid(), p_reason, p_description)
  returning * into v_report;

  insert into public.communication_events (communication_id, event_type, from_status, to_status, performed_by)
  values (v_delivery.communication_id, 'reported', null, 'REPORTADO', auth.uid());

  return jsonb_build_object('report', to_jsonb(v_report));
end;
$$;


ALTER FUNCTION "public"."communication_report_delivery"("p_delivery_id" "uuid", "p_reason" "text", "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."communication_review_report"("p_report_id" "uuid", "p_status" "text", "p_resolution_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_report public.communication_moderation_reports%rowtype;
begin
  select * into v_report
  from public.communication_moderation_reports
  where id = p_report_id
  for update;

  if v_report.id is null then
    raise exception 'Denuncia nao encontrada';
  end if;

  if not public.secretaria_can_manage_school(v_report.school_id) then
    raise exception 'Acesso negado para moderacao';
  end if;

  update public.communication_moderation_reports
     set status = p_status,
         reviewed_by = auth.uid(),
         reviewed_at = case when p_status = 'RESOLVIDO' then now() else reviewed_at end,
         resolution_notes = p_resolution_notes
   where id = p_report_id
   returning * into v_report;

  return jsonb_build_object('report', to_jsonb(v_report));
end;
$$;


ALTER FUNCTION "public"."communication_review_report"("p_report_id" "uuid", "p_status" "text", "p_resolution_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."communication_teacher_can_target"("p_school_id" "uuid", "p_class_id" "uuid", "p_student_id" "uuid", "p_audience_type" "text") RETURNS boolean
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.class_teacher_memberships ctm
    join public.teachers t on t.id = ctm.teacher_id
    join public.classes c on c.id = ctm.class_id
    where t.profile_id = auth.uid()
      and ctm.status = 'active'
      and ctm.started_at <= now()
      and (ctm.ended_at is null or ctm.ended_at > now())
      and c.status = 'active'
      and c.school_id = p_school_id
      and c.id = p_class_id
      and p_audience_type in ('class', 'student')
      and (
        p_audience_type = 'class'
        or exists (
          select 1
          from public.enrollments e
          where e.student_id = p_student_id
            and e.class_id = p_class_id
            and e.school_id = p_school_id
            and e.status = 'active'
            and e.ended_at is null
        )
      )
  );
$$;


ALTER FUNCTION "public"."communication_teacher_can_target"("p_school_id" "uuid", "p_class_id" "uuid", "p_student_id" "uuid", "p_audience_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."communication_upsert_system_notification"("p_source_type" "text", "p_source_id" "uuid", "p_school_id" "uuid", "p_author_profile_id" "uuid", "p_author_role" "text", "p_audience_type" "text", "p_class_id" "uuid", "p_student_id" "uuid", "p_title" "text", "p_body" "text", "p_communication_date" "date" DEFAULT CURRENT_DATE, "p_action_label" "text" DEFAULT NULL::"text", "p_href" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_source_type text := lower(nullif(btrim(coalesce(p_source_type, '')), ''));
  v_audience_type text := lower(nullif(btrim(coalesce(p_audience_type, '')), ''));
  v_comm public.communications%rowtype;
  v_deliveries integer := 0;
begin
  if v_source_type not in ('calendar', 'assessment') then
    raise exception 'Fonte de notificacao invalida.' using errcode = '22023';
  end if;

  if p_source_id is null or p_school_id is null then
    raise exception 'Origem e escola sao obrigatorias para notificacao.' using errcode = '22023';
  end if;

  if p_author_profile_id is null then
    raise exception 'Autor da notificacao obrigatorio.' using errcode = '42501';
  end if;

  if v_audience_type not in ('class', 'student') then
    raise exception 'Notificacao automatica deve ser de turma ou aluno.' using errcode = '22023';
  end if;

  if v_audience_type = 'class' and (p_class_id is null or p_student_id is not null) then
    raise exception 'Notificacao de turma deve informar somente class_id.' using errcode = '22023';
  end if;

  if v_audience_type = 'student' and (p_class_id is null or p_student_id is null) then
    raise exception 'Notificacao individual deve informar class_id e student_id.' using errcode = '22023';
  end if;

  if length(btrim(coalesce(p_title, ''))) = 0 or length(btrim(coalesce(p_body, ''))) = 0 then
    raise exception 'Titulo e corpo sao obrigatorios para notificacao.' using errcode = '22023';
  end if;

  insert into public.communications (
    school_id,
    author_profile_id,
    author_role,
    communication_type,
    audience_type,
    class_id,
    student_id,
    title,
    body,
    communication_date,
    status,
    source_type,
    source_id,
    action_label,
    href
  )
  values (
    p_school_id,
    p_author_profile_id,
    coalesce(nullif(btrim(coalesce(p_author_role, '')), ''), 'system'),
    'notice',
    v_audience_type,
    p_class_id,
    p_student_id,
    btrim(p_title),
    btrim(p_body),
    coalesce(p_communication_date, current_date),
    'published',
    v_source_type,
    p_source_id,
    nullif(btrim(coalesce(p_action_label, '')), ''),
    nullif(btrim(coalesce(p_href, '')), '')
  )
  on conflict (source_type, source_id)
  where source_type is not null and source_id is not null
  do update set
    school_id = excluded.school_id,
    author_profile_id = excluded.author_profile_id,
    author_role = excluded.author_role,
    communication_type = excluded.communication_type,
    audience_type = excluded.audience_type,
    class_id = excluded.class_id,
    student_id = excluded.student_id,
    title = excluded.title,
    body = excluded.body,
    communication_date = excluded.communication_date,
    status = 'published',
    deleted_at = null,
    deleted_by = null,
    action_label = excluded.action_label,
    href = excluded.href,
    updated_at = now()
  returning * into v_comm;

  insert into public.communication_events (communication_id, event_type, from_status, to_status, performed_by)
  values (v_comm.id, 'published', null, 'published', p_author_profile_id);

  v_deliveries := public.communication_generate_deliveries(v_comm.id);

  return jsonb_build_object(
    'communication_id', v_comm.id,
    'source_type', v_comm.source_type,
    'source_id', v_comm.source_id,
    'deliveries_created', v_deliveries
  );
end;
$$;


ALTER FUNCTION "public"."communication_upsert_system_notification"("p_source_type" "text", "p_source_id" "uuid", "p_school_id" "uuid", "p_author_profile_id" "uuid", "p_author_role" "text", "p_audience_type" "text", "p_class_id" "uuid", "p_student_id" "uuid", "p_title" "text", "p_body" "text", "p_communication_date" "date", "p_action_label" "text", "p_href" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."communication_user_can_access_advanced"("p_communication" "public"."communications") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select
    public.communication_can_read(p_communication)
    or exists (
      select 1
      from public.communication_deliveries d
      where d.communication_id = p_communication.id
        and d.recipient_profile_id = auth.uid()
    )
    or (
      p_communication.audience_type = 'staff'
      and exists (
        select 1
        from public.school_memberships sm
        where sm.school_id = p_communication.school_id
          and sm.profile_id = auth.uid()
          and sm.status = 'active'
          and sm.membership_role = p_communication.staff_role
          and sm.started_at <= now()
          and (sm.ended_at is null or sm.ended_at > now())
      )
    );
$$;


ALTER FUNCTION "public"."communication_user_can_access_advanced"("p_communication" "public"."communications") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."current_early_childhood_student_context"() RETURNS TABLE("student_id" "uuid", "school_id" "uuid", "class_id" "uuid", "age_group" "text", "school_year" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
  SELECT s.id AS student_id, e.school_id, e.class_id, c.age_group, COALESCE(c.school_year, e.school_year) AS school_year
  FROM public.students s
  JOIN public.enrollments e ON e.student_id = s.id
  JOIN public.classes c ON c.id = e.class_id
  WHERE s.user_id = auth.uid()
    AND COALESCE(s.status, 'active') = 'active'
    AND e.status = 'active'
    AND e.enrolled_at <= now()
    AND (e.ended_at IS NULL OR e.ended_at > now())
    AND COALESCE(c.status, 'active') = 'active'
  ORDER BY e.enrolled_at DESC, e.created_at DESC
  LIMIT 1;
$$;


ALTER FUNCTION "public"."current_early_childhood_student_context"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."current_institutional_school_ids"() RETURNS TABLE("school_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
  SELECT DISTINCT source.school_id
  FROM (
    SELECT sm.school_id
    FROM public.school_memberships sm
    WHERE sm.profile_id = auth.uid()
      AND sm.status = 'active'
      AND sm.started_at <= now()
      AND (sm.ended_at IS NULL OR sm.ended_at > now())

    UNION

    SELECT t.school_id
    FROM public.teachers t
    WHERE t.profile_id = auth.uid()
      AND t.status = 'active'

    UNION

    SELECT s.school_id
    FROM public.students s
    WHERE s.user_id = auth.uid()
      AND coalesce(s.status, 'active') = 'active'

    UNION

    SELECT g.school_id
    FROM public.guardians g
    WHERE g.profile_id = auth.uid()
      AND g.status = 'active'

    UNION

    SELECT e.school_id
    FROM public.student_guardians sg
    JOIN public.enrollments e ON e.student_id = sg.student_id
    WHERE sg.profile_id = auth.uid()
      AND sg.status = 'active'
      AND e.status = 'active'
      AND e.ended_at IS NULL
  ) source
  WHERE source.school_id IS NOT NULL;
$$;


ALTER FUNCTION "public"."current_institutional_school_ids"() OWNER TO "postgres";


