    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
  SELECT DISTINCT
    s.id AS student_id,
    e.school_id,
    e.class_id,
    c.nome::text AS class_name,
    e.school_year,
    c.ano_escolar::text AS class_school_year
