CREATE OR REPLACE FUNCTION "public"."derive_school_auth_namespace"("p_school_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_school public.schools%rowtype;
  v_candidate text;
  v_words text[];
  v_word text;
begin
  select * into v_school
  from public.schools
  where id = p_school_id;

  if v_school.id is null then
    raise exception 'SCHOOL_NOT_FOUND';
  end if;

  v_candidate := public.normalize_school_auth_namespace(split_part(coalesce(v_school.codigo_inep, ''), '-', 1));
  if length(coalesce(v_candidate, '')) >= 2 then
    return v_candidate;
  end if;

  v_words := regexp_split_to_array(coalesce(v_school.nome, ''), '\s+');
  v_candidate := '';
  foreach v_word in array v_words loop
    if length(v_word) >= 3 and lower(v_word) not in ('escola', 'municipal', 'estadual', 'de', 'da', 'do', 'das', 'dos', 'e') then
      v_candidate := v_candidate || left(public.normalize_school_auth_namespace(v_word), 1);
    end if;
    exit when length(v_candidate) >= 6;
  end loop;

  v_candidate := public.normalize_school_auth_namespace(v_candidate);
  if length(coalesce(v_candidate, '')) < 2 then
    v_candidate := 'ESC' || substring(replace(p_school_id::text, '-', '') from 1 for 6);
  end if;

  return substring(v_candidate from 1 for 12);
end;
$$;


ALTER FUNCTION "public"."derive_school_auth_namespace"("p_school_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_school_auth_namespace"("p_school_id" "uuid", "p_namespace" "text" DEFAULT NULL::"text", "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_namespace public.school_auth_namespaces%rowtype;
  v_school public.schools%rowtype;
  v_requested text;
begin
  if public.current_platform_role() <> 'service_role' and not public.secretaria_can_manage_school(p_school_id) then
    raise exception 'UNAUTHORIZED_SCHOOL_NAMESPACE' using errcode = '42501';
  end if;

  select * into v_school
  from public.schools
  where id = p_school_id;

  if v_school.id is null then
    raise exception 'SCHOOL_NOT_FOUND';
  end if;

  select * into v_namespace
  from public.school_auth_namespaces
  where school_id = p_school_id
  for update;

  if v_namespace.id is not null then
    return jsonb_build_object(
      'ok', true,
      'namespace_id', v_namespace.id,
      'school_id', v_namespace.school_id,
      'namespace', v_namespace.namespace,
      'existing', true,
      'next_sequence', v_namespace.next_sequence
    );
  end if;

  v_requested := coalesce(public.normalize_school_auth_namespace(p_namespace), public.derive_school_auth_namespace(p_school_id));
  if v_requested is null or v_requested !~ '^[A-Z0-9]{2,12}$' then
    raise exception 'INVALID_SCHOOL_NAMESPACE';
  end if;

  insert into public.school_auth_namespaces (
    school_id,
    namespace,
    source,
    next_sequence,
    locked,
    created_by
  ) values (
    p_school_id,
    v_requested,
    case when p_namespace is null then 'derived' else 'admin' end,
    1,
    true,
    coalesce(p_actor_id, auth.uid())
  )
  returning * into v_namespace;

  return jsonb_build_object(
    'ok', true,
    'namespace_id', v_namespace.id,
    'school_id', v_namespace.school_id,
    'namespace', v_namespace.namespace,
    'existing', false,
    'next_sequence', v_namespace.next_sequence
  );
end;
$_$;


ALTER FUNCTION "public"."ensure_school_auth_namespace"("p_school_id" "uuid", "p_namespace" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."equity_assert_scope"("p_scope" "text", "p_network_id" "uuid" DEFAULT NULL::"uuid", "p_school_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_scope text := lower(coalesce(nullif(p_scope, ''), 'network'));
  v_network_id uuid := p_network_id;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode = '42501'; end if;
  if v_scope = 'school' then
    if p_school_id is null then raise exception 'SCHOOL_REQUIRED'; end if;
    if not public.equity_can_read_school(p_school_id) then raise exception 'EQUITY_SCHOOL_FORBIDDEN' using errcode = '42501'; end if;
    return jsonb_build_object('scope', 'school', 'school_id', p_school_id, 'network_id', p_network_id);
  end if;
  if v_scope <> 'network' then raise exception 'UNSUPPORTED_EQUITY_SCOPE'; end if;
  if v_network_id is null then v_network_id := public.network_resolve_requested_network(null); end if;
  if v_network_id is null or not public.network_can_read(v_network_id) then raise exception 'EQUITY_NETWORK_FORBIDDEN' using errcode = '42501'; end if;
  return jsonb_build_object('scope', 'network', 'network_id', v_network_id, 'school_id', null);
end;
$$;


ALTER FUNCTION "public"."equity_assert_scope"("p_scope" "text", "p_network_id" "uuid", "p_school_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."equity_can_read_school"("p_school_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
  select coalesce(public.is_platform_admin(), false)
    or coalesce(public.secretaria_can_manage_school(p_school_id), false)
    or exists (
      select 1 from public.network_school_memberships nsm
      where nsm.school_id = p_school_id and nsm.status = 'active' and public.network_can_read(nsm.network_id)
    );
$$;


ALTER FUNCTION "public"."equity_can_read_school"("p_school_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."equity_create_official_report_export"("p_scope" "text" DEFAULT 'network'::"text", "p_network_id" "uuid" DEFAULT NULL::"uuid", "p_school_id" "uuid" DEFAULT NULL::"uuid", "p_date_from" "date" DEFAULT ((CURRENT_DATE - '365 days'::interval))::"date", "p_date_to" "date" DEFAULT CURRENT_DATE, "p_dimension" "text" DEFAULT 'race_ethnicity'::"text", "p_format" "text" DEFAULT 'pdf'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_payload jsonb;
  v_scope jsonb;
  v_format text := lower(coalesce(nullif(p_format, ''), 'pdf'));
  v_hash text;
  v_report_id uuid;
  v_identifier text;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode = '42501'; end if;
  if v_format not in ('pdf', 'xlsx') then raise exception 'UNSUPPORTED_REPORT_FORMAT'; end if;

  v_payload := public.equity_get_vaar_evidence(p_scope, p_network_id, p_school_id, p_date_from, p_date_to, p_dimension);
  v_scope := v_payload #> '{internal_indicators,scope}';
  v_hash := encode(digest(v_payload::text, 'sha256'), 'hex');

  insert into public.official_report_exports (status, report_type, format, scope_kind, school_id, network_id, date_from, date_to, requested_by, requested_role, params, snapshot_json, snapshot_hash, source, ready_at)
  values ('ready', case when v_scope->>'scope' = 'network' then 'network-analytics' else 'school-analytics' end, v_format, v_scope->>'scope', nullif(v_scope->>'school_id', '')::uuid, nullif(v_scope->>'network_id', '')::uuid, p_date_from, p_date_to, auth.uid(), v_scope->>'scope', jsonb_build_object('module', 'EQUIDADE_VAAR_FUNDEB_V1', 'dimension', p_dimension, 'format', v_format, 'data_kind', 'INDICADOR_INTERNO'), v_payload, v_hash, 'equity_vaar_v1', now())
  returning id, report_identifier into v_report_id, v_identifier;

  return jsonb_build_object('report_id', v_report_id, 'report_identifier', v_identifier, 'report_type', case when v_scope->>'scope' = 'network' then 'network-analytics' else 'school-analytics' end, 'format', v_format, 'snapshot_hash', v_hash, 'source', 'equity_vaar_v1');
end;
$$;


ALTER FUNCTION "public"."equity_create_official_report_export"("p_scope" "text", "p_network_id" "uuid", "p_school_id" "uuid", "p_date_from" "date", "p_date_to" "date", "p_dimension" "text", "p_format" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."equity_create_vaar_snapshot"("p_scope" "text" DEFAULT 'network'::"text", "p_network_id" "uuid" DEFAULT NULL::"uuid", "p_school_id" "uuid" DEFAULT NULL::"uuid", "p_date_from" "date" DEFAULT ((CURRENT_DATE - '365 days'::interval))::"date", "p_date_to" "date" DEFAULT CURRENT_DATE, "p_dimension" "text" DEFAULT 'race_ethnicity'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_payload jsonb;
  v_scope jsonb;
  v_hash text;
  v_snapshot_id uuid;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode = '42501'; end if;
  v_payload := public.equity_get_vaar_evidence(p_scope, p_network_id, p_school_id, p_date_from, p_date_to, p_dimension);
  v_scope := v_payload #> '{internal_indicators,scope}';
  v_hash := encode(digest(v_payload::text, 'sha256'), 'hex');

  insert into public.equity_vaar_evidence_snapshots (scope_kind, network_id, school_id, period_start, period_end, data_kind, indicator_payload, snapshot_hash, generated_by)
  values (v_scope->>'scope', nullif(v_scope->>'network_id', '')::uuid, nullif(v_scope->>'school_id', '')::uuid, p_date_from, p_date_to, 'INDICADOR_INTERNO', v_payload, v_hash, auth.uid())
  returning id into v_snapshot_id;

  return jsonb_build_object('snapshot_id', v_snapshot_id, 'snapshot_hash', v_hash, 'data_kind', 'INDICADOR_INTERNO', 'scope', v_scope, 'period', jsonb_build_object('from', p_date_from, 'to', p_date_to));
end;
$$;


ALTER FUNCTION "public"."equity_create_vaar_snapshot"("p_scope" "text", "p_network_id" "uuid", "p_school_id" "uuid", "p_date_from" "date", "p_date_to" "date", "p_dimension" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."equity_student_attributes" (
    "student_id" "uuid" NOT NULL,
    "school_id" "uuid" NOT NULL,
    "race_ethnicity" "text",
    "nse_band" "text",
    "territory" "text",
    "pcd_status" "text",
    "gender" "text",
    "source_type" "text" DEFAULT 'official_import'::"text" NOT NULL,
    "data_status" "text" DEFAULT 'available'::"text" NOT NULL,
    "legal_basis" "text" DEFAULT 'public_policy'::"text" NOT NULL,
    "effective_from" "date" DEFAULT CURRENT_DATE NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_by" "uuid",
    "updated_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "equity_student_attributes_data_status_check" CHECK (("data_status" = ANY (ARRAY['available'::"text", 'empty_real'::"text", 'archived'::"text"]))),
    CONSTRAINT "equity_student_attributes_source_type_check" CHECK (("source_type" = ANY (ARRAY['official_import'::"text", 'institutional_self_declaration'::"text", 'administrative_record'::"text", 'not_informed'::"text"])))
);


ALTER TABLE "public"."equity_student_attributes" OWNER TO "postgres";


COMMENT ON TABLE "public"."equity_student_attributes" IS 'Equidade/VAAR V1: dimensoes sensiveis autorizadas por estudante. Sem grant ao frontend; uso via agregacoes seguras.';



CREATE OR REPLACE FUNCTION "public"."equity_dimension_value"("p_attrs" "public"."equity_student_attributes", "p_dimension" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
begin
  case lower(coalesce(nullif(p_dimension, ''), 'race_ethnicity'))
    when 'race_ethnicity' then return nullif(btrim(p_attrs.race_ethnicity), '');
    when 'nse_band' then return nullif(btrim(p_attrs.nse_band), '');
    when 'territory' then return nullif(btrim(p_attrs.territory), '');
    when 'pcd_status' then return nullif(btrim(p_attrs.pcd_status), '');
    when 'gender' then return nullif(btrim(p_attrs.gender), '');
    else raise exception 'UNSUPPORTED_EQUITY_DIMENSION';
  end case;
end;
$$;


ALTER FUNCTION "public"."equity_dimension_value"("p_attrs" "public"."equity_student_attributes", "p_dimension" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."equity_dimensions_status"("p_scope" "text" DEFAULT 'network'::"text", "p_network_id" "uuid" DEFAULT NULL::"uuid", "p_school_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_scope jsonb;
  v_scope_kind text;
  v_network_id uuid;
  v_school_id uuid;
  v_counts jsonb;
begin
  v_scope := public.equity_assert_scope(p_scope, p_network_id, p_school_id);
  v_scope_kind := v_scope->>'scope';
  v_network_id := nullif(v_scope->>'network_id', '')::uuid;
  v_school_id := nullif(v_scope->>'school_id', '')::uuid;

  with scoped_schools as (
    select v_school_id as school_id where v_scope_kind = 'school'
    union
    select nsm.school_id
    from public.network_school_memberships nsm
    where v_scope_kind = 'network' and nsm.network_id = v_network_id and nsm.status = 'active'
  ), attrs as (
    select esa.*
    from public.equity_student_attributes esa
    join scoped_schools ss on ss.school_id = esa.school_id
    where esa.data_status = 'available'
  )
  select jsonb_build_object(
    'race_ethnicity', count(*) filter (where nullif(btrim(race_ethnicity), '') is not null),
    'nse_band', count(*) filter (where nullif(btrim(nse_band), '') is not null),
    'pcd_status', count(*) filter (where nullif(btrim(pcd_status), '') is not null),
    'territory', count(*) filter (where nullif(btrim(territory), '') is not null),
    'gender', count(*) filter (where nullif(btrim(gender), '') is not null),
    'students_with_any_dimension', count(*) filter (
      where nullif(btrim(coalesce(race_ethnicity, '')), '') is not null
         or nullif(btrim(coalesce(nse_band, '')), '') is not null
         or nullif(btrim(coalesce(pcd_status, '')), '') is not null
         or nullif(btrim(coalesce(territory, '')), '') is not null
         or nullif(btrim(coalesce(gender, '')), '') is not null
    )
  ) into v_counts
  from attrs;

  return jsonb_build_object(
    'status', case when (v_counts->>'students_with_any_dimension')::integer > 0 then 'PASS' else 'EMPTY_REAL' end,
    'scope', v_scope,
    'counts', v_counts,
    'source', 'AUTHORIZED_INSTITUTIONAL_DIMENSIONS_ONLY'
  );
end;
$$;


ALTER FUNCTION "public"."equity_dimensions_status"("p_scope" "text", "p_network_id" "uuid", "p_school_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."equity_get_dashboard"("p_scope" "text" DEFAULT 'network'::"text", "p_network_id" "uuid" DEFAULT NULL::"uuid", "p_school_id" "uuid" DEFAULT NULL::"uuid", "p_date_from" "date" DEFAULT ((CURRENT_DATE - '365 days'::interval))::"date", "p_date_to" "date" DEFAULT CURRENT_DATE, "p_dimension" "text" DEFAULT 'race_ethnicity'::"text", "p_min_group_size" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_scope jsonb;
  v_scope_kind text;
  v_network_id uuid;
  v_school_id uuid;
  v_min integer := greatest(coalesce(p_min_group_size, public.equity_small_group_minimum()), public.equity_small_group_minimum());
  v_dimension text := lower(coalesce(nullif(p_dimension, ''), 'race_ethnicity'));
  v_payload jsonb;
begin
  if v_dimension not in ('race_ethnicity', 'nse_band', 'territory', 'pcd_status', 'gender') then
    raise exception 'UNSUPPORTED_EQUITY_DIMENSION';
  end if;
  if p_date_to < p_date_from then raise exception 'INVALID_PERIOD'; end if;

  v_scope := public.equity_assert_scope(p_scope, p_network_id, p_school_id);
  v_scope_kind := v_scope->>'scope';
  v_network_id := nullif(v_scope->>'network_id', '')::uuid;
  v_school_id := nullif(v_scope->>'school_id', '')::uuid;

  with scoped_schools as (
    select v_school_id as school_id where v_scope_kind = 'school'
    union
    select nsm.school_id
    from public.network_school_memberships nsm
    where v_scope_kind = 'network' and nsm.network_id = v_network_id and nsm.status = 'active'
  ), active_students as (
    select distinct
      s.id as student_id,
      s.school_id,
      coalesce(e.class_id, s.class_id) as class_id,
      sc.nome as school_name,
      c.nome as class_name,
      coalesce(public.equity_dimension_value(esa, v_dimension), 'SEM_DADO') as dimension_value
    from public.students s
    join scoped_schools ss on ss.school_id = s.school_id
    join public.schools sc on sc.id = s.school_id
    left join public.enrollments e on e.student_id = s.id and e.school_id = s.school_id and e.status = 'active'
    left join public.classes c on c.id = coalesce(e.class_id, s.class_id)
    left join public.equity_student_attributes esa on esa.student_id = s.id and esa.data_status = 'available'
    where coalesce(s.status, 'ativo') in ('ativo', 'active')
  ), student_results as (
    select
      ar.student_id,
      ar.school_id,
      avg(ar.score_percentage) as avg_score,
      count(*)::integer as result_count,
      min(ar.finalized_at)::date as first_result_date,
      max(ar.finalized_at)::date as last_result_date
    from public.assessment_results ar
    join scoped_schools ss on ss.school_id = ar.school_id
    where ar.finalized_at::date between p_date_from and p_date_to
    group by ar.student_id, ar.school_id
  ), student_attendance as (
    select
      ar.student_id,
      ar.school_id,
      count(*)::integer as attendance_records,
      round((count(*) filter (where ar.status = 'present')::numeric / nullif(count(*), 0)) * 100, 2) as attendance_rate
    from public.attendance_records ar
    join scoped_schools ss on ss.school_id = ar.school_id
    where ar.attendance_date between p_date_from and p_date_to
    group by ar.student_id, ar.school_id
  ), joined as (
    select ast.*, sr.avg_score, sr.result_count, sr.first_result_date, sr.last_result_date, sa.attendance_records, sa.attendance_rate
    from active_students ast
    left join student_results sr on sr.student_id = ast.student_id and sr.school_id = ast.school_id
    left join student_attendance sa on sa.student_id = ast.student_id and sa.school_id = ast.school_id
  ), group_metrics as (
    select
      dimension_value,
      count(distinct student_id)::integer as student_count,
      count(distinct student_id) filter (where result_count is not null)::integer as participants,
      round(avg(avg_score) filter (where avg_score is not null), 2) as average_performance,
      round((count(distinct student_id) filter (where result_count is not null)::numeric / nullif(count(distinct student_id), 0)) * 100, 2) as participation_rate,
      round(avg(attendance_rate) filter (where attendance_rate is not null), 2) as attendance_rate,
      min(first_result_date) as first_result_date,
      max(last_result_date) as last_result_date
    from joined
    group by dimension_value
  ), safe_metrics as (
    select
      dimension_value,
      student_count,
      student_count < v_min as suppressed,
      case when student_count < v_min then null else participants end as participants,
      case when student_count < v_min then null else average_performance end as average_performance,
      case when student_count < v_min then null else participation_rate end as participation_rate,
      case when student_count < v_min then null else attendance_rate end as attendance_rate,
      case when student_count < v_min then null else first_result_date end as first_result_date,
      case when student_count < v_min then null else last_result_date end as last_result_date,
      case when student_count < v_min or average_performance is null then null
        else public.avalia_plus_classify_proficiency(average_performance, null, case when v_scope_kind = 'school' then v_school_id else null end, v_network_id)
      end as proficiency
    from group_metrics
  ), unsuppressed as (
    select * from safe_metrics where not suppressed and dimension_value <> 'SEM_DADO'
  ), summary as (
    select jsonb_build_object(
      'students', coalesce((select count(*) from joined), 0),
      'participants', coalesce((select count(*) from joined where result_count is not null), 0),
      'groups', coalesce((select count(*) from group_metrics), 0),
      'groups_with_authorized_dimension', coalesce((select count(*) from group_metrics where dimension_value <> 'SEM_DADO'), 0),
      'suppressed_groups', coalesce((select count(*) from safe_metrics where suppressed), 0),
      'mean_performance', coalesce((select round(avg(avg_score), 2) from joined where avg_score is not null), 0),
      'participation_rate', coalesce((select round((count(*) filter (where result_count is not null)::numeric / nullif(count(*), 0)) * 100, 2) from joined), 0),
      'attendance_rate', coalesce((select round(avg(attendance_rate), 2) from joined where attendance_rate is not null), 0),
      'equity_gap_points', coalesce((select round(max(average_performance) - min(average_performance), 2) from unsuppressed where average_performance is not null), 0)
    ) as data
  )
  select jsonb_build_object(
    'status', case when coalesce((select count(*) from group_metrics where dimension_value <> 'SEM_DADO'), 0) = 0 then 'EMPTY_REAL' else 'PASS' end,
    'scope', v_scope,
    'period', jsonb_build_object('from', p_date_from, 'to', p_date_to),
    'dimension', v_dimension,
    'data_kind', 'INDICADOR_INTERNO',
    'official_data_present', exists (
      select 1 from public.equity_official_indicator_imports eoi
      where eoi.period_start <= p_date_to and eoi.period_end >= p_date_from
        and ((v_scope_kind = 'network' and eoi.network_id = v_network_id) or (v_scope_kind = 'school' and eoi.school_id = v_school_id))
    ),
    'privacy', jsonb_build_object('minimum_group_size', v_min, 'small_group_reidentification', 'ZERO', 'suppression_rule', 'Groups below the minimum are suppressed before disclosure.'),
    'summary', (select data from summary),
    'groups', coalesce((
      select jsonb_agg(jsonb_build_object(
        'dimension_value', dimension_value,
        'privacy_status', case when suppressed then 'SUPPRESSED_SMALL_GROUP' else 'VISIBLE_AGGREGATE' end,
        'student_count', case when suppressed then null else student_count end,
        'student_count_bucket', case when suppressed then '<' || v_min::text else null end,
        'participants', participants,
        'average_performance', average_performance,
        'participation_rate', participation_rate,
        'attendance_rate', attendance_rate,
        'proficiency', proficiency,
        'first_result_date', first_result_date,
        'last_result_date', last_result_date
      ) order by suppressed asc, average_performance asc nulls last, dimension_value asc)
      from safe_metrics
    ), '[]'::jsonb),
    'attention_groups', coalesce((
      select jsonb_agg(jsonb_build_object(
        'dimension_value', dimension_value,
        'reason', 'LOWER_THAN_VISIBLE_GROUP_MEAN',
        'average_performance', average_performance,
        'participation_rate', participation_rate,
        'attendance_rate', attendance_rate
      ) order by average_performance asc nulls last)
      from unsuppressed
      where average_performance is not null and average_performance < coalesce((select avg(average_performance) from unsuppressed where average_performance is not null), 0)
    ), '[]'::jsonb),
    'official_internal_data_separation', jsonb_build_object('internal_indicator_label', 'INDICADOR_INTERNO', 'official_import_label', 'DADO_OFICIAL_IMPORTADO', 'automatic_vaar_eligibility_statement', 'NOT_DECLARED_BY_PLATFORM')
  ) into v_payload;

  return v_payload;
end;
$$;


