COMMENT ON FUNCTION "public"."equity_get_dashboard"("p_scope" "text", "p_network_id" "uuid", "p_school_id" "uuid", "p_date_from" "date", "p_date_to" "date", "p_dimension" "text", "p_min_group_size" integer) IS 'Retorna painel agregado de equidade com supressao de grupos pequenos e separacao INDICADOR_INTERNO/DADO_OFICIAL_IMPORTADO.';



CREATE OR REPLACE FUNCTION "public"."equity_get_vaar_evidence"("p_scope" "text" DEFAULT 'network'::"text", "p_network_id" "uuid" DEFAULT NULL::"uuid", "p_school_id" "uuid" DEFAULT NULL::"uuid", "p_date_from" "date" DEFAULT ((CURRENT_DATE - '365 days'::interval))::"date", "p_date_to" "date" DEFAULT CURRENT_DATE, "p_dimension" "text" DEFAULT 'race_ethnicity'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_dashboard jsonb;
  v_scope jsonb;
  v_scope_kind text;
  v_network_id uuid;
  v_school_id uuid;
begin
  v_dashboard := public.equity_get_dashboard(p_scope, p_network_id, p_school_id, p_date_from, p_date_to, p_dimension);
  v_scope := v_dashboard->'scope';
  v_scope_kind := v_scope->>'scope';
  v_network_id := nullif(v_scope->>'network_id', '')::uuid;
  v_school_id := nullif(v_scope->>'school_id', '')::uuid;

  return jsonb_build_object(
    'vaar_statement', 'A Plataforma fornece indicadores internos e evidencias de apoio; nao declara automaticamente habilitacao oficial ao VAAR-FUNDEB.',
    'internal_indicators', v_dashboard,
    'official_imports', coalesce((
      select jsonb_agg(jsonb_build_object('indicator_code', indicator_code, 'indicator_name', indicator_name, 'period_start', period_start, 'period_end', period_end, 'data_kind', data_kind, 'source_document', source_document, 'payload', payload) order by period_end desc, indicator_code asc)
      from public.equity_official_indicator_imports eoi
      where eoi.period_start <= p_date_to and eoi.period_end >= p_date_from
        and ((v_scope_kind = 'network' and eoi.network_id = v_network_id) or (v_scope_kind = 'school' and eoi.school_id = v_school_id))
    ), '[]'::jsonb),
    'privacy', jsonb_build_object('small_group_reidentification', 'ZERO', 'cross_school_leak', 'ZERO', 'sensitive_raw_data_exposure', 'ZERO')
  );
end;
$$;


ALTER FUNCTION "public"."equity_get_vaar_evidence"("p_scope" "text", "p_network_id" "uuid", "p_school_id" "uuid", "p_date_from" "date", "p_date_to" "date", "p_dimension" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."equity_get_vaar_evidence"("p_scope" "text", "p_network_id" "uuid", "p_school_id" "uuid", "p_date_from" "date", "p_date_to" "date", "p_dimension" "text") IS 'Monta evidencias de apoio ao VAAR-FUNDEB sem declarar elegibilidade oficial automatica.';



