CREATE OR REPLACE FUNCTION "public"."family_get_recomposition_context"("p_student_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_student public.students%rowtype; v_class_id uuid; v_payload jsonb;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if p_student_id is null then raise exception 'STUDENT_REQUIRED'; end if;
  select * into v_student from public.students where id = p_student_id and coalesce(status, 'active') in ('active', 'ativo');
  if not found then raise exception 'STUDENT_NOT_FOUND'; end if;
  select e.class_id into v_class_id from public.enrollments e where e.student_id = p_student_id and e.school_id = v_student.school_id and e.status in ('active', 'ativo') and e.enrolled_at <= now() and (e.ended_at is null or e.ended_at > now()) order by e.enrolled_at desc limit 1;
  if v_class_id is null or not public.communication_guardian_can_read(v_student.school_id, v_class_id, p_student_id, 'student') then raise exception 'FAMILY_RECOMPOSITION_FORBIDDEN'; end if;
  select jsonb_build_object('student_id', p_student_id, 'plans', coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'title', p.title, 'target_skill', p.target_skill, 'descriptor', p.descriptor, 'objective', p.objective, 'status', p.status, 'period_start', p.period_start, 'period_end', p.period_end, 'resources', coalesce((select jsonb_agg(jsonb_build_object('content_type', r.content_type, 'content_title', r.content_title, 'status', r.status) order by r.created_at) from public.recomposition_plan_resources r where r.plan_id = p.id and r.status <> 'removed'), '[]'::jsonb)) order by p.created_at desc), '[]'::jsonb)) into v_payload
  from public.recomposition_plans p join public.recomposition_plan_students ps on ps.plan_id = p.id
  where ps.student_id = p_student_id and ps.status <> 'removed' and p.status in ('active', 'in_progress', 'completed');
  return coalesce(v_payload, jsonb_build_object('student_id', p_student_id, 'plans', '[]'::jsonb));
end;
$$;


ALTER FUNCTION "public"."family_get_recomposition_context"("p_student_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."family_get_school_access_events"("p_student_id" "uuid", "p_date_from" "date" DEFAULT (CURRENT_DATE - 30), "p_date_to" "date" DEFAULT CURRENT_DATE) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_student public.students%rowtype;
  v_enrollment record;
begin
  select * into v_student from public.students where id = p_student_id;
  if v_student.id is null then
    raise exception 'Aluno nao encontrado.' using errcode = '22023';
  end if;

  select * into v_enrollment
  from public.school_access_current_enrollment(v_student.id, v_student.school_id);

  if v_enrollment.class_id is null or not public.communication_guardian_can_read(v_student.school_id, v_enrollment.class_id, v_student.id, 'student') then
    raise exception 'Responsavel sem permissao para consultar movimentacoes deste aluno.' using errcode = '42501';
  end if;

  return coalesce((
    select jsonb_agg(
      jsonb_build_object(
        'event_id', sae.id,
        'student_id', sae.student_id,
        'class_id', sae.class_id,
        'event_type', sae.event_type,
        'occurred_at', sae.occurred_at,
        'origin', sae.origin,
        'status', sae.status
      )
      order by sae.occurred_at desc
    )
    from public.school_access_events sae
    where sae.student_id = p_student_id
      and sae.school_id = v_student.school_id
      and sae.status = 'recorded'
      and sae.occurred_at >= p_date_from::timestamp with time zone
      and sae.occurred_at < (p_date_to + 1)::timestamp with time zone
  ), '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."family_get_school_access_events"("p_student_id" "uuid", "p_date_from" "date", "p_date_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gamification_award_event"("p_student_id" "uuid", "p_source_module" "text", "p_event_type" "text", "p_source_id" "text", "p_reason" "text" DEFAULT NULL::"text", "p_xp" integer DEFAULT NULL::integer, "p_coins" integer DEFAULT NULL::integer, "p_medal_id" "uuid" DEFAULT NULL::"uuid", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare v_profile public.student_gamification_profiles%rowtype; v_rule public.gamification_reward_rules%rowtype; v_xp integer; v_coins integer; v_idem text; v_tx public.gamification_transactions%rowtype;
begin
  if not public.gamification_can_manage_student(p_student_id) then raise exception 'Acesso negado para recompensar aluno'; end if;
  if p_source_module not in ('ATIVIDADES','BIBLIOTECA','AVALIA_PLUS','RECOMPOSICAO','TRILHA','CONQUISTA','MANUAL','OTHER') then raise exception 'Modulo invalido'; end if;
  v_profile := public.gamification_ensure_profile(p_student_id);
  select * into v_rule from public.gamification_reward_rules r where r.active and r.source_module = p_source_module and r.event_type = p_event_type and (r.school_id = v_profile.school_id or r.school_id is null) order by r.school_id is null, r.created_at desc limit 1;
  v_xp := greatest(coalesce(p_xp, v_rule.xp_amount, 0),0); v_coins := greatest(coalesce(p_coins, v_rule.coin_amount, 0),0); p_medal_id := coalesce(p_medal_id, v_rule.medal_id);
  v_idem := p_student_id::text || ':' || p_source_module || ':' || p_event_type || ':' || coalesce(p_source_id,'sem-origem');
  if exists(select 1 from public.gamification_transactions where idempotency_key in (v_idem || ':XP', v_idem || ':COIN')) or exists(select 1 from public.student_medals where idempotency_key = v_idem || ':MEDAL') then
    return jsonb_build_object('status','IDEMPOTENT_REPLAY','profile',to_jsonb(v_profile));
  end if;
  if v_xp > 0 then
    update public.student_gamification_profiles set xp_total = xp_total + v_xp, level_number = greatest(1, floor((xp_total + v_xp)/1000)::integer + 1), level_label = 'Nivel ' || greatest(1, floor((xp_total + v_xp)/1000)::integer + 1)::text, updated_at = now() where student_id = p_student_id returning * into v_profile;
    update public.students set xp_total = v_profile.xp_total, nivel = v_profile.level_number, updated_at = now() where id = p_student_id;
    insert into public.gamification_transactions(student_id, school_id, class_id, transaction_type, currency, amount, balance_after, reason, source_type, source_id, idempotency_key, created_by, metadata)
    values(p_student_id, v_profile.school_id, v_profile.class_id, 'credit', 'XP', v_xp, v_profile.xp_total, coalesce(p_reason,p_event_type), p_source_module, p_source_id, v_idem || ':XP', auth.uid(), coalesce(p_metadata,'{}'::jsonb)) returning * into v_tx;
  end if;
  if v_coins > 0 then
    update public.student_gamification_profiles set coin_balance = coin_balance + v_coins, updated_at = now() where student_id = p_student_id returning * into v_profile;
    insert into public.gamification_transactions(student_id, school_id, class_id, transaction_type, currency, amount, balance_after, reason, source_type, source_id, idempotency_key, created_by, metadata)
    values(p_student_id, v_profile.school_id, v_profile.class_id, 'credit', 'COIN', v_coins, v_profile.coin_balance, coalesce(p_reason,p_event_type), p_source_module, p_source_id, v_idem || ':COIN', auth.uid(), coalesce(p_metadata,'{}'::jsonb));
  end if;
  if p_medal_id is not null then
    insert into public.student_medals(student_id, medal_id, data_conquista, source_type, source_id, xp_awarded, coins_awarded, awarded_by, idempotency_key, metadata)
    values(p_student_id, p_medal_id, now(), p_source_module, p_source_id, v_xp, v_coins, auth.uid(), v_idem || ':MEDAL', coalesce(p_metadata,'{}'::jsonb)) on conflict(idempotency_key) do nothing;
  end if;
  insert into public.gamification_audit_events(student_id, school_id, actor_user_id, event_type, details) values(p_student_id, v_profile.school_id, auth.uid(), 'REWARD_GRANTED', jsonb_build_object('source_module',p_source_module,'event_type',p_event_type,'xp',v_xp,'coins',v_coins));
  return jsonb_build_object('status','PASS','profile',to_jsonb(v_profile),'idempotency_key',v_idem);
end; $$;


ALTER FUNCTION "public"."gamification_award_event"("p_student_id" "uuid", "p_source_module" "text", "p_event_type" "text", "p_source_id" "text", "p_reason" "text", "p_xp" integer, "p_coins" integer, "p_medal_id" "uuid", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gamification_can_manage_student"("p_student_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  with ctx as (select * from public.gamification_student_context(p_student_id))
  select exists(select 1 from ctx) and (
    exists(select 1 from ctx where public.secretaria_can_manage_school(ctx.school_id))
    or exists(
      select 1 from public.class_teacher_memberships ctm
      join public.teachers t on t.id = ctm.teacher_id
      join ctx on ctx.class_id = ctm.class_id
      where t.profile_id = auth.uid() and coalesce(t.status,'active') = 'active'
        and ctm.status = 'active' and ctm.started_at <= now() and (ctm.ended_at is null or ctm.ended_at > now())
    )
  );
$$;


ALTER FUNCTION "public"."gamification_can_manage_student"("p_student_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gamification_can_read_student"("p_student_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  with ctx as (select * from public.gamification_student_context(p_student_id))
  select exists(select 1 from ctx) and (
    public.institutional_is_current_student(p_student_id)
    or exists(select 1 from ctx where public.communication_guardian_can_read(ctx.school_id, ctx.class_id, p_student_id, 'student'))
    or exists(select 1 from ctx where public.secretaria_can_manage_school(ctx.school_id))
    or exists(
      select 1 from public.class_teacher_memberships ctm
      join public.teachers t on t.id = ctm.teacher_id
      join ctx on ctx.class_id = ctm.class_id
      where t.profile_id = auth.uid() and coalesce(t.status,'active') = 'active'
        and ctm.status = 'active' and ctm.started_at <= now() and (ctm.ended_at is null or ctm.ended_at > now())
    )
  );
$$;


ALTER FUNCTION "public"."gamification_can_read_student"("p_student_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."student_gamification_profiles" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "student_id" "uuid" NOT NULL,
    "school_id" "uuid",
    "class_id" "uuid",
    "xp_total" bigint DEFAULT 0 NOT NULL,
    "level_number" integer DEFAULT 1 NOT NULL,
    "level_label" "text" DEFAULT 'Nivel 1'::"text" NOT NULL,
    "coin_balance" bigint DEFAULT 0 NOT NULL,
    "goals" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "avatar_config" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "student_gamification_profiles_check" CHECK ((("xp_total" >= 0) AND ("coin_balance" >= 0) AND ("level_number" >= 1)))
);


ALTER TABLE "public"."student_gamification_profiles" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gamification_ensure_profile"("p_student_id" "uuid") RETURNS "public"."student_gamification_profiles"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare v_ctx record; v_profile public.student_gamification_profiles%rowtype;
begin
  select * into v_ctx from public.gamification_student_context(p_student_id);
  if v_ctx.student_id is null then raise exception 'Aluno nao encontrado ou inativo'; end if;
  insert into public.student_gamification_profiles(student_id, school_id, class_id, xp_total, level_number, level_label)
  select s.id, v_ctx.school_id, v_ctx.class_id, greatest(coalesce(s.xp_total,0),0), greatest(coalesce(s.nivel,1),1)::integer, 'Nivel ' || greatest(coalesce(s.nivel,1),1)::text
  from public.students s where s.id = p_student_id
  on conflict(student_id) do update set school_id = excluded.school_id, class_id = excluded.class_id, updated_at = now()
  returning * into v_profile;
  return v_profile;
end; $$;


ALTER FUNCTION "public"."gamification_ensure_profile"("p_student_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gamification_log_event"("p_student_id" "uuid", "p_school_id" "uuid", "p_event_type" "text", "p_details" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
begin
  insert into public.gamification_audit_events (student_id, school_id, actor_user_id, event_type, details)
  values (p_student_id, p_school_id, auth.uid(), p_event_type, coalesce(p_details, '{}'::jsonb));
end;
$$;


ALTER FUNCTION "public"."gamification_log_event"("p_student_id" "uuid", "p_school_id" "uuid", "p_event_type" "text", "p_details" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gamification_mark_path_step_complete"("p_path_id" "uuid", "p_step_id" "uuid", "p_student_id" "uuid", "p_progress" numeric DEFAULT 100, "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare v_step public.gamification_path_steps%rowtype; v_reward jsonb;
begin
  if not public.gamification_can_manage_student(p_student_id) then raise exception 'Acesso negado para atualizar trilha'; end if;
  select * into v_step from public.gamification_path_steps where id = p_step_id and path_id = p_path_id; if v_step.id is null then raise exception 'Etapa nao encontrada'; end if;
  insert into public.student_gamification_path_progress(path_id,step_id,student_id,status,progress_value,completed_at,metadata) values(p_path_id,p_step_id,p_student_id,case when p_progress >= 100 then 'completed' else 'in_progress' end,least(greatest(coalesce(p_progress,0),0),100),case when p_progress >= 100 then now() else null end,coalesce(p_metadata,'{}'::jsonb)) on conflict(path_id,step_id,student_id) where step_id is not null do update set status = excluded.status, progress_value = greatest(public.student_gamification_path_progress.progress_value, excluded.progress_value), completed_at = coalesce(public.student_gamification_path_progress.completed_at, excluded.completed_at), updated_at = now();
  if p_progress >= 100 then v_reward := public.gamification_award_event(p_student_id,'TRILHA','STEP_COMPLETED',p_step_id::text,'Etapa de trilha concluida',v_step.reward_xp,v_step.reward_coins,null,p_metadata); end if;
  return jsonb_build_object('status','PASS','reward',coalesce(v_reward,'{}'::jsonb));
end; $$;


ALTER FUNCTION "public"."gamification_mark_path_step_complete"("p_path_id" "uuid", "p_step_id" "uuid", "p_student_id" "uuid", "p_progress" numeric, "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gamification_rankings_enabled"("p_school_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select coalesce(
    (select gs.rankings_enabled from public.gamification_settings gs where gs.school_id = p_school_id),
    (select gs.rankings_enabled from public.gamification_settings gs where gs.school_id is null limit 1),
    true
  );
$$;


ALTER FUNCTION "public"."gamification_rankings_enabled"("p_school_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gamification_student_context"("p_student_id" "uuid") RETURNS TABLE("student_id" "uuid", "school_id" "uuid", "class_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select s.id, coalesce(e.school_id, s.school_id), coalesce(e.class_id, s.class_id)
  from public.students s
  left join lateral (
    select school_id, class_id from public.enrollments e
    where e.student_id = s.id and e.status = 'active' and e.ended_at is null
    order by e.enrolled_at desc, e.created_at desc limit 1
  ) e on true
  where s.id = p_student_id and coalesce(s.status,'active') in ('active','ativo')
  limit 1;
$$;


ALTER FUNCTION "public"."gamification_student_context"("p_student_id" "uuid") OWNER TO "postgres";


