    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object('version','v1','authentication','server-side institutional token hash + scoped RPC access','resources',jsonb_build_array('schools','users','teachers','students','guardians','classes','enrollments','components','calendar','attendance','results'),'bulk_import',jsonb_build_object('formats',jsonb_build_array('CSV','XLSX'),'pipeline',jsonb_build_array('preview','validation','confirm','batch_report'),'canonical_school_importer','admin_confirm_rs_school_import'),'webhooks',jsonb_build_array('enrollment.created','enrollment.updated','user.updated','result.consolidated'),'sso',jsonb_build_object('google_workspace','EMPTY_REAL','microsoft_entra','EMPTY_REAL'));
$$;


ALTER FUNCTION "public"."integration_api_v1_catalog"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."integration_api_v1_read"("p_resource" "text", "p_school_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 100, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_resource text := lower(btrim(coalesce(p_resource, ''))); v_limit integer := greatest(1, least(coalesce(p_limit, 100), 500)); v_offset integer := greatest(0, coalesce(p_offset, 0)); v_data jsonb := '[]'::jsonb;
begin
  if v_resource = '' then raise exception 'Recurso obrigatorio.' using errcode = '22023'; end if;
  if p_school_id is not null and not public.integration_can_manage_school(p_school_id) then raise exception 'Acesso negado ao escopo escolar solicitado.' using errcode = '42501'; end if;
  if v_resource = 'schools' then select coalesce(jsonb_agg(to_jsonb(src)), '[]'::jsonb) into v_data from (select s.id, s.nome, s.codigo_inep, s.municipio, s.estado, s.status, s.updated_at from public.schools s where s.status <> 'archived' and ((p_school_id is null and (public.is_platform_admin() or public.secretaria_can_manage_school(s.id))) or (p_school_id is not null and s.id = p_school_id)) order by s.nome limit v_limit offset v_offset) src;
  elsif v_resource = 'users' then select coalesce(jsonb_agg(to_jsonb(src)), '[]'::jsonb) into v_data from (select u.id, u.nome, u.email, u.perfil, u.school_id, u.class_id, u.ativo from public.users u where (p_school_id is null and public.integration_can_manage_school(u.school_id)) or (p_school_id is not null and u.school_id = p_school_id) order by u.nome limit v_limit offset v_offset) src;
  elsif v_resource = 'teachers' then select coalesce(jsonb_agg(to_jsonb(src)), '[]'::jsonb) into v_data from (select t.id, t.user_id, t.school_id, t.profile_id, t.disciplina, t.status, t.updated_at from public.teachers t where ((p_school_id is null and public.integration_can_manage_school(t.school_id)) or (p_school_id is not null and t.school_id = p_school_id)) and t.status <> 'archived' order by t.updated_at desc nulls last limit v_limit offset v_offset) src;
  elsif v_resource = 'students' then select coalesce(jsonb_agg(to_jsonb(src)), '[]'::jsonb) into v_data from (select s.id, s.user_id, s.school_id, s.class_id, s.matricula, s.nome, s.email, s.status, s.turma, s.updated_at from public.students s where ((p_school_id is null and public.integration_can_manage_school(s.school_id)) or (p_school_id is not null and s.school_id = p_school_id)) and coalesce(s.status, 'active') not in ('archived', 'arquivado') order by s.nome limit v_limit offset v_offset) src;
  elsif v_resource = 'guardians' then select coalesce(jsonb_agg(to_jsonb(src)), '[]'::jsonb) into v_data from (select g.id, g.school_id, g.profile_id, g.full_name, g.email, g.phone, g.status, g.access_status, g.updated_at from public.guardians g where ((p_school_id is null and public.integration_can_manage_school(g.school_id)) or (p_school_id is not null and g.school_id = p_school_id)) and g.status <> 'archived' order by g.full_name limit v_limit offset v_offset) src;
  elsif v_resource = 'classes' then select coalesce(jsonb_agg(to_jsonb(src)), '[]'::jsonb) into v_data from (select c.id, c.school_id, c.nome, c.ano_escolar, c.turno, c.teacher_id, c.age_group, c.school_year, c.status, c.updated_at from public.classes c where ((p_school_id is null and public.integration_can_manage_school(c.school_id)) or (p_school_id is not null and c.school_id = p_school_id)) and c.status <> 'archived' order by c.school_year desc nulls last, c.nome limit v_limit offset v_offset) src;
  elsif v_resource = 'enrollments' then select coalesce(jsonb_agg(to_jsonb(src)), '[]'::jsonb) into v_data from (select e.id, e.student_id, e.class_id, e.school_id, e.school_year, e.status, e.enrolled_at, e.ended_at, e.updated_at from public.enrollments e where ((p_school_id is null and public.integration_can_manage_school(e.school_id)) or (p_school_id is not null and e.school_id = p_school_id)) order by e.school_year desc, e.enrolled_at desc limit v_limit offset v_offset) src;
  elsif v_resource = 'components' then select coalesce(jsonb_agg(to_jsonb(src)), '[]'::jsonb) into v_data from (select distinct t.school_id, btrim(t.disciplina::text) as componente from public.teachers t where t.disciplina is not null and btrim(t.disciplina::text) <> '' and ((p_school_id is null and public.integration_can_manage_school(t.school_id)) or (p_school_id is not null and t.school_id = p_school_id)) order by componente limit v_limit offset v_offset) src;
  elsif v_resource = 'calendar' then select coalesce(jsonb_agg(to_jsonb(src)), '[]'::jsonb) into v_data from (select ce.id, ce.class_id, ce.school_id, ce.teacher_id, ce.entry_date, ce.start_time, ce.end_time, ce.title, ce.entry_type, ce.status, ce.updated_at from public.class_calendar_entries ce where ((p_school_id is null and public.integration_can_manage_school(ce.school_id)) or (p_school_id is not null and ce.school_id = p_school_id)) and ce.status <> 'archived' order by ce.entry_date desc, ce.start_time desc nulls last limit v_limit offset v_offset) src;
  elsif v_resource = 'attendance' then select coalesce(jsonb_agg(to_jsonb(src)), '[]'::jsonb) into v_data from (select ar.* from public.attendance_records ar where ((p_school_id is null and public.integration_can_manage_school(ar.school_id)) or (p_school_id is not null and ar.school_id = p_school_id)) order by ar.attendance_date desc, ar.created_at desc limit v_limit offset v_offset) src;
  elsif v_resource = 'results' then select coalesce(jsonb_agg(to_jsonb(src)), '[]'::jsonb) into v_data from (select r.id, r.assessment_id, r.assignment_id, r.student_id, r.school_id, r.status, r.score_raw, r.score_percentage, r.finalized_at, r.updated_at from public.assessment_results r where ((p_school_id is null and public.integration_can_manage_school(r.school_id)) or (p_school_id is not null and r.school_id = p_school_id)) order by r.finalized_at desc limit v_limit offset v_offset) src;
  else raise exception 'Recurso API V1 nao suportado: %', p_resource using errcode = '22023'; end if;
  return jsonb_build_object('version','v1','resource',v_resource,'school_id',p_school_id,'limit',v_limit,'offset',v_offset,'data',v_data);
end;
$$;


ALTER FUNCTION "public"."integration_api_v1_read"("p_resource" "text", "p_school_id" "uuid", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."integration_api_v1_read"("p_resource" "text", "p_school_id" "uuid", "p_limit" integer, "p_offset" integer) IS 'API V1: leitura institucional autorizada de recursos canonicos com isolamento por escola.';



CREATE OR REPLACE FUNCTION "public"."integration_can_manage_school"("p_school_id" "uuid") RETURNS boolean
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select case when public.is_platform_admin() then true when p_school_id is null then public.integration_is_admin() else public.secretaria_can_manage_school(p_school_id) or exists (select 1 from public.teachers t where t.school_id = p_school_id and t.status = 'active' and (t.profile_id = auth.uid() or t.user_id = auth.uid())) end;
$$;


ALTER FUNCTION "public"."integration_can_manage_school"("p_school_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."integration_confirm_bulk_import"("p_batch_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_batch public.integration_sync_batches%rowtype; v_report jsonb;
begin
  select * into v_batch from public.integration_sync_batches where id = p_batch_id;
  if v_batch.id is null then raise exception 'Lote de importacao nao encontrado.' using errcode = '22023'; end if;
  perform public.integration_require_scope(v_batch.client_id, 'import:write');
  if not public.integration_can_manage_school(v_batch.school_id) then raise exception 'Acesso negado ao lote informado.' using errcode = '42501'; end if;
  if v_batch.status <> 'validated' then raise exception 'Somente lotes validados podem ser confirmados.' using errcode = '22023'; end if;
  if v_batch.entity_type = 'rs_school_package' then v_report := public.admin_confirm_rs_school_import(v_batch.school_id, v_batch.preview -> 'payload', false); else v_report := jsonb_build_object('status','confirmed_validation_batch','note','Lote JSON validado para integracao. Escrita academica deve usar importador canonico ou conector homologado.','canonical_engine_preserved',true,'total_rows',v_batch.total_rows,'valid_rows',v_batch.valid_rows); end if;
  update public.integration_sync_batches set status = 'confirmed', confirmed_by = auth.uid(), confirmed_at = now(), report = v_report where id = p_batch_id;
  return jsonb_build_object('batch_id', p_batch_id, 'status', 'confirmed', 'report', v_report);
end;
$$;


ALTER FUNCTION "public"."integration_confirm_bulk_import"("p_batch_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."integration_confirm_bulk_import"("p_batch_id" "uuid") IS 'API V1: confirmacao de lote validado. Pacotes escolares usam o importador canonico; sem segundo motor de matricula.';



CREATE OR REPLACE FUNCTION "public"."integration_create_api_client"("p_client_name" "text", "p_client_code" "text", "p_school_id" "uuid", "p_scopes" "text"[], "p_token_hash" "text", "p_token_hint" "text" DEFAULT NULL::"text", "p_direction" "text" DEFAULT 'inbound'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_id uuid;
begin
  if not public.integration_can_manage_school(p_school_id) then raise exception 'Acesso negado para criar credencial de integracao.' using errcode = '42501'; end if;
  if p_token_hash is null or length(p_token_hash) < 32 then raise exception 'token_hash invalido. Gere o segredo fora do frontend e armazene somente o hash.' using errcode = '22023'; end if;
  if coalesce(array_length(p_scopes, 1), 0) = 0 then raise exception 'Credencial sem escopo nao permitida.' using errcode = '22023'; end if;
  insert into public.integration_api_clients (client_name, client_code, school_id, scopes, token_hash, token_hint, direction, created_by) values (btrim(p_client_name), lower(btrim(p_client_code)), p_school_id, p_scopes, p_token_hash, p_token_hint, p_direction, auth.uid()) returning id into v_id;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."integration_create_api_client"("p_client_name" "text", "p_client_code" "text", "p_school_id" "uuid", "p_scopes" "text"[], "p_token_hash" "text", "p_token_hint" "text", "p_direction" "text") OWNER TO "postgres";


