CREATE OR REPLACE FUNCTION "public"."integration_log_api_access"("p_client_id" "uuid", "p_endpoint" "text", "p_method" "text" DEFAULT 'RPC'::"text", "p_status_code" integer DEFAULT 200, "p_request_hash" "text" DEFAULT NULL::"text", "p_response_summary" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_client public.integration_api_clients%rowtype; v_log_id uuid;
begin
  select * into v_client from public.integration_api_clients where id = p_client_id;
  if v_client.id is null then raise exception 'Integracao nao encontrada.' using errcode = '22023'; end if;
  if not public.integration_can_manage_school(v_client.school_id) then raise exception 'Acesso negado para auditar integracao.' using errcode = '42501'; end if;
  insert into public.integration_api_audit_logs (client_id, school_id, endpoint, method, status_code, request_hash, response_summary) values (p_client_id, v_client.school_id, p_endpoint, upper(coalesce(p_method, 'RPC')), p_status_code, p_request_hash, coalesce(p_response_summary, '{}'::jsonb)) returning id into v_log_id;
  update public.integration_api_clients set last_used_at = now() where id = p_client_id;
  return v_log_id;
end;
$$;


ALTER FUNCTION "public"."integration_log_api_access"("p_client_id" "uuid", "p_endpoint" "text", "p_method" "text", "p_status_code" integer, "p_request_hash" "text", "p_response_summary" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."integration_preview_bulk_import"("p_client_id" "uuid", "p_school_id" "uuid", "p_entity_type" "text", "p_payload" "jsonb", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_existing public.integration_sync_batches%rowtype; v_client public.integration_api_clients%rowtype; v_entity text := lower(btrim(coalesce(p_entity_type, ''))); v_report jsonb; v_errors jsonb := '[]'::jsonb; v_total integer := 0; v_valid integer := 0; v_batch_id uuid; v_item jsonb; v_idx integer := 0;
begin
  perform public.integration_require_scope(p_client_id, 'import:write');
  select * into v_client from public.integration_api_clients where id = p_client_id and status = 'active';
  if v_client.school_id is not null and v_client.school_id <> p_school_id then raise exception 'Credencial nao autorizada para a escola informada.' using errcode = '42501'; end if;
  if not public.integration_can_manage_school(p_school_id) then raise exception 'Acesso negado ao escopo escolar solicitado.' using errcode = '42501'; end if;
  if p_idempotency_key is not null then select * into v_existing from public.integration_sync_batches where client_id = p_client_id and idempotency_key = p_idempotency_key; if v_existing.id is not null then return jsonb_build_object('batch_id', v_existing.id, 'status', v_existing.status, 'idempotent_replay', true, 'report', v_existing.report, 'errors', v_existing.errors); end if; end if;
  if v_entity = 'rs_school_package' then v_report := public.admin_confirm_rs_school_import(p_school_id, p_payload, true); v_total := coalesce((v_report #>> '{counts,valid_rows}')::integer, 0); v_valid := v_total;
  else
    if jsonb_typeof(coalesce(p_payload, '[]'::jsonb)) <> 'array' then raise exception 'Payload de CSV/XLSX deve chegar como array JSON ja parseado pelo servidor.' using errcode = '22023'; end if;
    v_total := jsonb_array_length(p_payload);
    for v_item in select * from jsonb_array_elements(p_payload) loop
      v_idx := v_idx + 1;
      if v_entity in ('students', 'alunos') and coalesce(nullif(btrim(v_item ->> 'nome'), ''), nullif(btrim(v_item ->> 'name'), '')) is null then v_errors := v_errors || jsonb_build_array(jsonb_build_object('row', v_idx, 'field', 'nome', 'error', 'REQUIRED'));
      elsif v_entity in ('enrollments', 'matriculas') and coalesce(nullif(btrim(v_item ->> 'student_external_id'), ''), nullif(btrim(v_item ->> 'student_id'), '')) is null then v_errors := v_errors || jsonb_build_array(jsonb_build_object('row', v_idx, 'field', 'student_external_id', 'error', 'REQUIRED'));
      elsif v_entity in ('users', 'usuarios') and coalesce(nullif(btrim(v_item ->> 'email'), ''), nullif(btrim(v_item ->> 'nome'), '')) is null then v_errors := v_errors || jsonb_build_array(jsonb_build_object('row', v_idx, 'field', 'email_or_nome', 'error', 'REQUIRED'));
      else v_valid := v_valid + 1; end if;
    end loop;
    v_report := jsonb_build_object('status', case when jsonb_array_length(v_errors) = 0 then 'validated' else 'validated_with_errors' end, 'total_rows', v_total, 'valid_rows', v_valid, 'error_rows', jsonb_array_length(v_errors), 'canonical_engine', case when v_entity in ('students','alunos','enrollments','matriculas') then 'admin_confirm_rs_school_import' else 'integration_mapping_validation' end);
  end if;
  insert into public.integration_sync_batches (client_id, school_id, source_system, direction, entity_type, status, total_rows, valid_rows, error_rows, idempotency_key, preview, errors, report, created_by) values (p_client_id, p_school_id, v_client.client_code, 'external_to_raizes', v_entity, case when jsonb_array_length(v_errors) = 0 then 'validated' else 'draft' end, v_total, v_valid, jsonb_array_length(v_errors), p_idempotency_key, jsonb_build_object('entity_type', v_entity, 'payload', p_payload, 'report', v_report), v_errors, v_report, auth.uid()) returning id into v_batch_id;
  return jsonb_build_object('batch_id', v_batch_id, 'status', case when jsonb_array_length(v_errors) = 0 then 'validated' else 'draft' end, 'report', v_report, 'errors', v_errors);
end;
$$;


ALTER FUNCTION "public"."integration_preview_bulk_import"("p_client_id" "uuid", "p_school_id" "uuid", "p_entity_type" "text", "p_payload" "jsonb", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."integration_preview_bulk_import"("p_client_id" "uuid", "p_school_id" "uuid", "p_entity_type" "text", "p_payload" "jsonb", "p_idempotency_key" "text") IS 'API V1: preview/validacao de importacao CSV/XLSX parseada em JSON. rs_school_package reutiliza admin_confirm_rs_school_import em dry-run.';



CREATE OR REPLACE FUNCTION "public"."integration_queue_webhook_event"("p_event_type" "text", "p_entity_type" "text", "p_entity_id" "uuid", "p_school_id" "uuid", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_endpoint record; v_count integer := 0; v_payload jsonb;
begin
  if not public.integration_can_manage_school(p_school_id) then raise exception 'Acesso negado ao escopo escolar solicitado.' using errcode = '42501'; end if;
  v_payload := jsonb_build_object('event_type', p_event_type, 'entity_type', p_entity_type, 'entity_id', p_entity_id, 'school_id', p_school_id, 'occurred_at', now(), 'data', coalesce(p_payload, '{}'::jsonb));
  for v_endpoint in select we.* from public.integration_webhook_endpoints we join public.integration_api_clients c on c.id = we.client_id where we.status = 'active' and c.status = 'active' and (we.school_id is null or we.school_id = p_school_id) and p_event_type = any(we.events) loop
    insert into public.integration_webhook_deliveries (endpoint_id, event_type, entity_type, entity_id, school_id, payload, signature, status) values (v_endpoint.id, p_event_type, p_entity_type, p_entity_id, p_school_id, v_payload, 'sha256=' || encode(hmac(v_payload::text, v_endpoint.secret_hash, 'sha256'), 'hex'), 'pending');
    v_count := v_count + 1;
  end loop;
  return jsonb_build_object('queued', v_count, 'event_type', p_event_type);
end;
$$;


ALTER FUNCTION "public"."integration_queue_webhook_event"("p_event_type" "text", "p_entity_type" "text", "p_entity_id" "uuid", "p_school_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."integration_register_external_mapping"("p_client_id" "uuid", "p_school_id" "uuid", "p_entity_type" "text", "p_entity_id" "uuid", "p_external_system" "text", "p_external_id" "text", "p_direction" "text" DEFAULT 'external_to_raizes'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_id uuid;
begin
  perform public.integration_require_scope(p_client_id, 'sync:write');
  if not public.integration_can_manage_school(p_school_id) then raise exception 'Acesso negado ao escopo escolar solicitado.' using errcode = '42501'; end if;
  insert into public.integration_external_mappings (client_id, school_id, entity_type, entity_id, external_system, external_id, direction, sync_status, last_synced_at, metadata) values (p_client_id, p_school_id, lower(btrim(p_entity_type)), p_entity_id, lower(btrim(p_external_system)), btrim(p_external_id), p_direction, 'synced', now(), coalesce(p_metadata, '{}'::jsonb)) on conflict (client_id, entity_type, external_system, external_id) do update set entity_id = excluded.entity_id, school_id = excluded.school_id, direction = excluded.direction, sync_status = 'synced', last_synced_at = now(), last_error = null, metadata = excluded.metadata, updated_at = now() returning id into v_id;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."integration_register_external_mapping"("p_client_id" "uuid", "p_school_id" "uuid", "p_entity_type" "text", "p_entity_id" "uuid", "p_external_system" "text", "p_external_id" "text", "p_direction" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."integration_register_webhook"("p_client_id" "uuid", "p_school_id" "uuid", "p_endpoint_url" "text", "p_events" "text"[], "p_secret_hash" "text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_id uuid;
begin
  perform public.integration_require_scope(p_client_id, 'webhooks:write');
  if not public.integration_can_manage_school(p_school_id) then raise exception 'Acesso negado ao escopo escolar solicitado.' using errcode = '42501'; end if;
  if p_endpoint_url !~* '^https://' then raise exception 'Webhook deve usar HTTPS.' using errcode = '22023'; end if;
  if p_secret_hash is null or length(p_secret_hash) < 32 then raise exception 'secret_hash invalido. Armazene somente hash/identificador seguro do segredo.' using errcode = '22023'; end if;
  insert into public.integration_webhook_endpoints (client_id, school_id, endpoint_url, events, secret_hash, created_by, metadata) values (p_client_id, p_school_id, p_endpoint_url, p_events, p_secret_hash, auth.uid(), coalesce(p_metadata, '{}'::jsonb)) returning id into v_id;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."integration_register_webhook"("p_client_id" "uuid", "p_school_id" "uuid", "p_endpoint_url" "text", "p_events" "text"[], "p_secret_hash" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."integration_require_scope"("p_client_id" "uuid", "p_scope" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_client public.integration_api_clients%rowtype;
begin
  select * into v_client from public.integration_api_clients where id = p_client_id and status = 'active';
  if v_client.id is null then raise exception 'Integracao ativa nao encontrada.' using errcode = '42501'; end if;
  if not (p_scope = any(v_client.scopes) or '*:*' = any(v_client.scopes)) then raise exception 'Escopo nao autorizado: %', p_scope using errcode = '42501'; end if;
end;
$$;


ALTER FUNCTION "public"."integration_require_scope"("p_client_id" "uuid", "p_scope" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."integration_revoke_api_client"("p_client_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_client public.integration_api_clients%rowtype;
begin
  select * into v_client from public.integration_api_clients where id = p_client_id;
  if v_client.id is null then raise exception 'Integracao nao encontrada.' using errcode = '22023'; end if;
  if not public.integration_can_manage_school(v_client.school_id) then raise exception 'Acesso negado para revogar integracao.' using errcode = '42501'; end if;
  update public.integration_api_clients set status = 'revoked', revoked_at = now() where id = p_client_id;
  return jsonb_build_object('client_id', p_client_id, 'status', 'revoked');
end;
$$;


ALTER FUNCTION "public"."integration_revoke_api_client"("p_client_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."integration_verify_webhook_signature"("p_endpoint_id" "uuid", "p_payload" "text", "p_signature" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_endpoint public.integration_webhook_endpoints%rowtype; v_expected text;
begin
  select * into v_endpoint from public.integration_webhook_endpoints where id = p_endpoint_id and status = 'active';
  if v_endpoint.id is null then return false; end if;
  if not public.integration_can_manage_school(v_endpoint.school_id) then return false; end if;
  v_expected := 'sha256=' || encode(hmac(coalesce(p_payload, ''), v_endpoint.secret_hash, 'sha256'), 'hex');
  return v_expected = coalesce(p_signature, '');
end;
$$;


ALTER FUNCTION "public"."integration_verify_webhook_signature"("p_endpoint_id" "uuid", "p_payload" "text", "p_signature" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."is_content_available_for_school"("p_school_id" "uuid", "p_content_type" "text", "p_content_id" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.school_content_availability sca
    WHERE sca.school_id = p_school_id
      AND sca.content_type = public.normalize_school_content_type(p_content_type)
      AND lower(btrim(sca.content_id)) = lower(btrim(coalesce(p_content_id, '')))
      AND sca.status = 'available'
      AND sca.deleted_at IS NULL
      AND (sca.available_from IS NULL OR sca.available_from <= now())
      AND (sca.available_until IS NULL OR sca.available_until >= now())
  );
$$;


ALTER FUNCTION "public"."is_content_available_for_school"("p_school_id" "uuid", "p_content_type" "text", "p_content_id" "text") OWNER TO "postgres";


