ALTER FUNCTION "public"."is_platform_admin"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."live_join_session"("p_session_id" "uuid", "p_student_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_session public.live_sessions%rowtype;
  v_participant public.live_session_participants%rowtype;
begin
  select * into v_session
  from public.live_sessions
  where id = p_session_id;

  if v_session.id is null or not public.live_session_can_access(p_session_id) then
    raise exception 'Acesso negado a aula ao vivo';
  end if;

  select * into v_participant
  from public.live_session_participants
  where session_id = p_session_id
    and profile_id = auth.uid()
    and (p_student_id is null or student_id = p_student_id)
  order by created_at desc
  limit 1;

  if v_participant.id is null then
    raise exception 'Participante nao autorizado para esta sessao';
  end if;

  update public.live_session_participants
     set join_status = 'JOINED',
         joined_at = coalesce(joined_at, now()),
         updated_at = now()
   where id = v_participant.id
   returning * into v_participant;

  insert into public.live_session_events (session_id, actor_profile_id, event_type, details)
  values (p_session_id, auth.uid(), 'JOINED', jsonb_build_object('participant_id', v_participant.id));

  return jsonb_build_object(
    'session_id', p_session_id,
    'join_status', v_participant.join_status,
    'provider_status', v_session.provider_status,
    'room_url', case when v_session.provider_status = 'PASS' then v_session.room_url else null end,
    'capabilities', v_session.capabilities
  );
end;
$$;


ALTER FUNCTION "public"."live_join_session"("p_session_id" "uuid", "p_student_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."live_sessions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "school_id" "uuid" NOT NULL,
    "class_id" "uuid",
    "host_teacher_id" "uuid",
    "host_profile_id" "uuid" DEFAULT "auth"."uid"() NOT NULL,
    "audience_type" "text" DEFAULT 'class'::"text" NOT NULL,
    "title" "text" NOT NULL,
    "description" "text",
    "starts_at" timestamp with time zone NOT NULL,
    "ends_at" timestamp with time zone,
    "duration_minutes" integer,
    "status" "text" DEFAULT 'SCHEDULED'::"text" NOT NULL,
    "provider" "text",
    "provider_status" "text" DEFAULT 'EMPTY_REAL'::"text" NOT NULL,
    "room_url" "text",
    "room_external_id" "text",
    "recording_url" "text",
    "replay_available" boolean DEFAULT false NOT NULL,
    "capabilities" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "live_sessions_audience_check" CHECK (("audience_type" = ANY (ARRAY['class'::"text", 'school'::"text", 'group'::"text"]))),
    CONSTRAINT "live_sessions_duration_check" CHECK ((("duration_minutes" IS NULL) OR ("duration_minutes" > 0))),
    CONSTRAINT "live_sessions_provider_check" CHECK (("provider_status" = ANY (ARRAY['PASS'::"text", 'EMPTY_REAL'::"text", 'FAIL'::"text"]))),
    CONSTRAINT "live_sessions_status_check" CHECK (("status" = ANY (ARRAY['SCHEDULED'::"text", 'LIVE'::"text", 'ENDED'::"text", 'CANCELLED'::"text", 'ARCHIVED'::"text"])))
);


ALTER TABLE "public"."live_sessions" OWNER TO "postgres";


COMMENT ON TABLE "public"."live_sessions" IS 'Motor canonico de aulas ao vivo. Provedor externo fica desacoplado e pode permanecer EMPTY_REAL.';



CREATE OR REPLACE FUNCTION "public"."live_list_sessions"("p_student_id" "uuid" DEFAULT NULL::"uuid") RETURNS SETOF "public"."live_sessions"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select distinct ls.*
  from public.live_sessions ls
  left join public.live_session_participants lsp on lsp.session_id = ls.id
  where public.secretaria_can_manage_school(ls.school_id)
     or ls.host_profile_id = auth.uid()
     or lsp.profile_id = auth.uid()
     or (
       p_student_id is not null
       and lsp.student_id = p_student_id
       and public.communication_current_student_can_read(ls.school_id, ls.class_id, p_student_id, 'class')
     )
  order by ls.starts_at desc;
$$;


ALTER FUNCTION "public"."live_list_sessions"("p_student_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."live_session_can_access"("p_session_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.live_sessions ls
    where ls.id = p_session_id
      and (
        ls.host_profile_id = auth.uid()
        or public.secretaria_can_manage_school(ls.school_id)
        or exists (
          select 1
          from public.class_teacher_memberships ctm
          join public.teachers t on t.id = ctm.teacher_id
          where ctm.class_id = ls.class_id
            and t.profile_id = auth.uid()
            and ctm.status = 'active'
            and ctm.started_at <= now()
            and (ctm.ended_at is null or ctm.ended_at > now())
        )
        or exists (
          select 1
          from public.live_session_participants lsp
          where lsp.session_id = ls.id
            and lsp.profile_id = auth.uid()
            and lsp.join_status <> 'BLOCKED'
        )
      )
  );
$$;


ALTER FUNCTION "public"."live_session_can_access"("p_session_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."management_get_school_access_summary"("p_school_id" "uuid", "p_date_from" "date" DEFAULT CURRENT_DATE, "p_date_to" "date" DEFAULT CURRENT_DATE) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if not public.school_access_operator_can_manage(p_school_id) then
    raise exception 'Usuario sem permissao para consultar resumo de acesso escolar.' using errcode = '42501';
  end if;

  return coalesce((
    select jsonb_build_object(
      'school_id', p_school_id,
      'date_from', p_date_from,
      'date_to', p_date_to,
      'entries', count(*) filter (where event_type = 'entry' and status = 'recorded'),
      'exits', count(*) filter (where event_type = 'exit' and status = 'recorded'),
      'duplicates', count(*) filter (where status = 'duplicate'),
      'students_moved', count(distinct student_id) filter (where status = 'recorded')
    )
    from public.school_access_events
    where school_id = p_school_id
      and occurred_at >= p_date_from::timestamp with time zone
      and occurred_at < (p_date_to + 1)::timestamp with time zone
  ), jsonb_build_object('school_id', p_school_id, 'entries', 0, 'exits', 0, 'duplicates', 0, 'students_moved', 0));
end;
$$;


ALTER FUNCTION "public"."management_get_school_access_summary"("p_school_id" "uuid", "p_date_from" "date", "p_date_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."network_can_manage_school"("p_network_id" "uuid", "p_school_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.network_user_memberships num
    join public.network_school_memberships nsm on nsm.network_id = num.network_id
    where num.network_id = p_network_id
      and num.profile_id = auth.uid()
      and num.role = 'secretaria_municipal'
      and num.status = 'active'
      and num.started_at <= now()
      and (num.ended_at is null or num.ended_at > now())
      and nsm.school_id = p_school_id
      and nsm.status = 'active'
      and nsm.joined_at <= now()
      and (nsm.ended_at is null or nsm.ended_at > now())
  );
$$;


ALTER FUNCTION "public"."network_can_manage_school"("p_network_id" "uuid", "p_school_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."network_can_read"("p_network_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
  select coalesce(public.is_platform_admin(), false)
    or exists (
      select 1
      from public.network_user_memberships num
      where num.network_id = p_network_id
        and num.profile_id = auth.uid()
        and num.role = 'secretaria_municipal'
        and num.status = 'active'
        and num.started_at <= now()
        and (num.ended_at is null or num.ended_at > now())
    );
$$;


ALTER FUNCTION "public"."network_can_read"("p_network_id" "uuid") OWNER TO "postgres";


