CREATE OR REPLACE FUNCTION "public"."network_get_overview"("p_network_id" "uuid" DEFAULT NULL::"uuid", "p_date_from" "date" DEFAULT NULL::"date", "p_date_to" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_network_id uuid;
  v_network public.education_networks%rowtype;
  v_schools jsonb;
  v_summary jsonb;
begin
  v_network_id := public.network_resolve_requested_network(p_network_id);

  select * into v_network from public.education_networks where id = v_network_id;

  with metrics as (
    select * from public.network_school_metric_rows(v_network_id, p_date_from, p_date_to)
  )
  select
    coalesce(jsonb_agg(to_jsonb(metrics) order by school_name), '[]'::jsonb),
    jsonb_build_object(
      'schools_total', count(*),
      'schools_active', count(*) filter (where school_status = 'active'),
      'active_students', coalesce(sum(active_students), 0),
      'active_classes', coalesce(sum(active_classes), 0),
      'active_teachers', coalesce(sum(active_teachers), 0),
      'attendance_rate', case when count(attendance_rate) = 0 then null else round(avg(attendance_rate), 2) end,
      'assessment_assignments', coalesce(sum(assessment_assignments), 0),
      'assigned_students', coalesce(sum(assigned_students), 0),
      'completed_students', coalesce(sum(completed_students), 0),
      'assessment_participation', case when coalesce(sum(assigned_students), 0) = 0 then null else round((sum(completed_students)::numeric / sum(assigned_students)::numeric) * 100, 2) end,
      'assessment_average', case when count(nullif(assessment_average, 0)) = 0 then null else round(avg(nullif(assessment_average, 0)), 2) end,
      'bncc_skills', coalesce(sum(bncc_skills), 0),
      'bncc_questions', coalesce(sum(bncc_questions), 0),
      'bncc_responses', coalesce(sum(bncc_responses), 0),
      'bncc_correct', coalesce(sum(bncc_correct), 0),
      'bncc_percentage', case when coalesce(sum(bncc_responses), 0) = 0 then null else round((sum(bncc_correct)::numeric / sum(bncc_responses)::numeric) * 100, 2) end,
      'diary_entries', coalesce(sum(diary_entries), 0)
    )
  into v_schools, v_summary
  from metrics;

  return jsonb_build_object(
    'network', jsonb_build_object(
      'id', v_network.id,
      'name', v_network.name,
      'code', v_network.code,
      'municipality', v_network.municipality,
      'state', v_network.state,
      'status', v_network.status
    ),
    'period', jsonb_build_object('date_from', p_date_from, 'date_to', p_date_to),
    'summary', coalesce(v_summary, '{}'::jsonb),
    'schools', coalesce(v_schools, '[]'::jsonb),
    'scope', jsonb_build_object('kind', 'network', 'global_school_access', false)
  );
end;
$$;


ALTER FUNCTION "public"."network_get_overview"("p_network_id" "uuid", "p_date_from" "date", "p_date_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."network_get_school_comparison"("p_network_id" "uuid" DEFAULT NULL::"uuid", "p_date_from" "date" DEFAULT NULL::"date", "p_date_to" "date" DEFAULT NULL::"date", "p_metric" "text" DEFAULT 'attendance_rate'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_network_id uuid;
  v_metric text := coalesce(nullif(p_metric, ''), 'attendance_rate');
  v_rows jsonb;
begin
  v_network_id := public.network_resolve_requested_network(p_network_id);

  with metrics as (
    select *,
      case v_metric
        when 'assessment_average' then assessment_average
        when 'assessment_participation' then assessment_participation
        when 'bncc_percentage' then bncc_percentage
        when 'diary_entries' then diary_entries::numeric
        else attendance_rate
      end as metric_value
    from public.network_school_metric_rows(v_network_id, p_date_from, p_date_to)
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'school_id', school_id,
    'school_name', school_name,
    'metric', v_metric,
    'value', metric_value,
    'attendance_rate', attendance_rate,
    'assessment_average', assessment_average,
    'assessment_participation', assessment_participation,
    'bncc_percentage', bncc_percentage,
    'diary_entries', diary_entries
  ) order by school_name), '[]'::jsonb)
  into v_rows
  from metrics;

  return jsonb_build_object(
    'network_id', v_network_id,
    'metric', v_metric,
    'schools', v_rows,
    'public_ranking', false
  );
end;
$$;


ALTER FUNCTION "public"."network_get_school_comparison"("p_network_id" "uuid", "p_date_from" "date", "p_date_to" "date", "p_metric" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."network_get_users"("p_network_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_network_id uuid;
  v_users jsonb;
begin
  v_network_id := public.network_resolve_requested_network(p_network_id);

  select coalesce(jsonb_agg(jsonb_build_object(
    'profile_id', p.id,
    'display_name', coalesce(p.display_name, p.id::text),
    'email', null,
    'role', num.role,
    'status', num.status,
    'started_at', num.started_at
  ) order by coalesce(p.display_name, p.id::text)), '[]'::jsonb)
  into v_users
  from public.network_user_memberships num
  join public.profiles p on p.id = num.profile_id
  where num.network_id = v_network_id
    and num.status = 'active'
    and num.started_at <= now()
    and (num.ended_at is null or num.ended_at > now());

  return jsonb_build_object('network_id', v_network_id, 'users', v_users);
end;
$$;


ALTER FUNCTION "public"."network_get_users"("p_network_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."network_resolve_requested_network"("p_network_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_network_id uuid;
begin
  if p_network_id is not null then
    v_network_id := p_network_id;
  else
    select cni.network_id
      into v_network_id
    from public.current_network_ids() cni
    order by cni.network_id
    limit 1;

    if v_network_id is null and public.is_platform_admin() then
      select en.id
        into v_network_id
      from public.education_networks en
      where en.status = 'active'
      order by en.created_at asc
      limit 1;
    end if;
  end if;

  if v_network_id is null or not public.network_can_read(v_network_id) then
    raise exception 'NETWORK_ACCESS_DENIED' using errcode = '42501';
  end if;

  return v_network_id;
end;
$$;


ALTER FUNCTION "public"."network_resolve_requested_network"("p_network_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."network_school_metric_rows"("p_network_id" "uuid", "p_date_from" "date" DEFAULT NULL::"date", "p_date_to" "date" DEFAULT NULL::"date") RETURNS TABLE("school_id" "uuid", "school_name" "text", "school_status" "text", "active_students" bigint, "active_classes" bigint, "active_teachers" bigint, "attendance_rate" numeric, "assessment_assignments" bigint, "assigned_students" bigint, "completed_students" bigint, "assessment_participation" numeric, "assessment_average" numeric, "bncc_skills" bigint, "bncc_questions" bigint, "bncc_responses" bigint, "bncc_correct" bigint, "bncc_percentage" numeric, "diary_entries" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
  with linked_schools as (
    select s.id, s.nome, s.status
    from public.network_school_memberships nsm
    join public.schools s on s.id = nsm.school_id
    where nsm.network_id = p_network_id
      and nsm.status = 'active'
      and nsm.joined_at <= now()
      and (nsm.ended_at is null or nsm.ended_at > now())
  ),
  attendance as (
    select ar.school_id,
      count(*) filter (where lower(ar.status) in ('present', 'presente')) as present_count,
      count(*) filter (where lower(ar.status) in ('present', 'presente', 'absent', 'ausente', 'justified', 'justificada')) as total_count
    from public.attendance_records ar
    join linked_schools ls on ls.id = ar.school_id
    where (p_date_from is null or ar.attendance_date >= p_date_from)
      and (p_date_to is null or ar.attendance_date <= p_date_to)
    group by ar.school_id
  ),
  assignment_stats as (
    select aa.school_id,
      count(distinct aa.id) as assessment_assignments,
      count(distinct coalesce(aa.student_id, e.student_id)) as assigned_students,
      count(distinct ar.student_id) as completed_students,
      avg(ar.score_percentage) filter (where ar.status in ('submitted', 'graded')) as assessment_average
    from public.assessment_assignments aa
    join linked_schools ls on ls.id = aa.school_id
    left join public.enrollments e on aa.target_type = 'class'
      and e.class_id = aa.class_id
      and e.school_id = aa.school_id
      and e.status = 'active'
    left join public.assessment_results ar on ar.assignment_id = aa.id
      and ar.school_id = aa.school_id
      and ar.status in ('submitted', 'graded')
    where aa.status = 'published'
      and (p_date_from is null or coalesce(aa.published_at, aa.created_at)::date >= p_date_from)
      and (p_date_to is null or coalesce(aa.published_at, aa.created_at)::date <= p_date_to)
    group by aa.school_id
  ),
  bncc_stats as (
    select ar.school_id,
      count(distinct qi.bncc_skill) filter (where nullif(qi.bncc_skill, '') is not null) as bncc_skills,
      count(distinct aq.question_id) as bncc_questions,
      count(resp.id) as bncc_responses,
      count(resp.id) filter (where resp.is_correct is true) as bncc_correct
    from public.assessment_results ar
    join linked_schools ls on ls.id = ar.school_id
    join public.assessment_questions aq on aq.assessment_id = ar.assessment_id
    join public.question_items qi on qi.id = aq.question_id
    left join public.assessment_responses resp on resp.attempt_id = ar.attempt_id
      and resp.question_id = aq.question_id
    where ar.status in ('submitted', 'graded')
      and (p_date_from is null or ar.finalized_at::date >= p_date_from)
      and (p_date_to is null or ar.finalized_at::date <= p_date_to)
    group by ar.school_id
  ),
  diary_stats as (
    select cde.school_id, count(*) as diary_entries
    from public.class_diary_entries cde
    join linked_schools ls on ls.id = cde.school_id
    where cde.deleted_at is null
      and (p_date_from is null or cde.entry_date >= p_date_from)
      and (p_date_to is null or cde.entry_date <= p_date_to)
    group by cde.school_id
  )
  select
    ls.id,
    ls.nome::text,
    coalesce(ls.status, 'active')::text,
    count(distinct st.id) filter (where coalesce(st.status, 'active') = 'active')::bigint,
    count(distinct cl.id) filter (where coalesce(cl.status, 'active') = 'active')::bigint,
    count(distinct t.id) filter (where coalesce(t.status, 'active') = 'active')::bigint,
    case when coalesce(att.total_count, 0) = 0 then null else round((att.present_count::numeric / att.total_count::numeric) * 100, 2) end,
    coalesce(ast.assessment_assignments, 0)::bigint,
    coalesce(ast.assigned_students, 0)::bigint,
    coalesce(ast.completed_students, 0)::bigint,
    case when coalesce(ast.assigned_students, 0) = 0 then null else round((ast.completed_students::numeric / ast.assigned_students::numeric) * 100, 2) end,
    round(coalesce(ast.assessment_average, 0), 2),
    coalesce(bncc.bncc_skills, 0)::bigint,
    coalesce(bncc.bncc_questions, 0)::bigint,
    coalesce(bncc.bncc_responses, 0)::bigint,
    coalesce(bncc.bncc_correct, 0)::bigint,
    case when coalesce(bncc.bncc_responses, 0) = 0 then null else round((bncc.bncc_correct::numeric / bncc.bncc_responses::numeric) * 100, 2) end,
    coalesce(ds.diary_entries, 0)::bigint
  from linked_schools ls
  left join public.students st on st.school_id = ls.id
  left join public.classes cl on cl.school_id = ls.id
  left join public.teachers t on t.school_id = ls.id
  left join attendance att on att.school_id = ls.id
  left join assignment_stats ast on ast.school_id = ls.id
  left join bncc_stats bncc on bncc.school_id = ls.id
  left join diary_stats ds on ds.school_id = ls.id
  group by
    ls.id, ls.nome, ls.status,
    att.present_count, att.total_count,
    ast.assessment_assignments, ast.assigned_students, ast.completed_students, ast.assessment_average,
    bncc.bncc_skills, bncc.bncc_questions, bncc.bncc_responses, bncc.bncc_correct,
    ds.diary_entries
  order by ls.nome;
$$;


ALTER FUNCTION "public"."network_school_metric_rows"("p_network_id" "uuid", "p_date_from" "date", "p_date_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_school_auth_namespace"("p_value" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select nullif(
    substring(
      upper(
        regexp_replace(
          translate(
            coalesce(p_value, ''),
            'ÁÀÃÂÄÉÈÊËÍÌÎÏÓÒÕÔÖÚÙÛÜÇÑáàãâäéèêëíìîïóòõôöúùûüçñ',
            'AAAAAEEEEIIIIOOOOOUUUUCNaaaaaeeeeiiiiooooouuuucn'
          ),
          '[^A-Za-z0-9]',
          '',
          'g'
        )
      )
      from 1 for 12
    ),
    ''
  );
$$;


ALTER FUNCTION "public"."normalize_school_auth_namespace"("p_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_school_content_type"("p_content_type" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_type text := lower(btrim(coalesce(p_content_type, '')));
BEGIN
  IF v_type IN ('book', 'livro') THEN
    RETURN 'book';
  ELSIF v_type IN ('activity', 'printable_activity', 'atividade', 'atividade_imprimivel') THEN
    RETURN 'activity';
  ELSIF v_type IN ('game', 'jogo') THEN
    RETURN 'game';
  ELSIF v_type IN ('experience', 'experiencia', 'experiência') THEN
    RETURN 'experience';
  ELSIF v_type IN ('video', 'videoaula') THEN
    RETURN 'video';
  ELSIF v_type IN ('other', 'outro', 'free_proposal', 'proposta_livre') THEN
    RETURN 'other';
  END IF;

  RAISE EXCEPTION 'Tipo de conteudo invalido: %', coalesce(p_content_type, '')
    USING errcode = '22023';
END;
$$;


ALTER FUNCTION "public"."normalize_school_content_type"("p_content_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notification_assessment_assignment_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if new.status = 'published'
     and (tg_op = 'INSERT' or old.status is distinct from new.status or old.available_from is distinct from new.available_from or old.available_until is distinct from new.available_until) then
    perform public.notification_upsert_assessment_available(new.id);
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."notification_assessment_assignment_trigger"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notification_calendar_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if tg_table_name = 'class_calendar_entries' then
    if new.status = 'published' and (tg_op = 'INSERT' or old.status is distinct from new.status or old.title is distinct from new.title or old.entry_date is distinct from new.entry_date or old.start_time is distinct from new.start_time) then
      perform public.notification_upsert_calendar_event(new.id, 'class_calendar', case when tg_op = 'INSERT' then 'calendar_event_created' else 'calendar_event_updated' end);
    end if;
  elsif tg_table_name = 'school_calendar_events' then
    if new.status = 'published' and (tg_op = 'INSERT' or old.status is distinct from new.status or old.title is distinct from new.title or old.event_date is distinct from new.event_date or old.start_time is distinct from new.start_time) then
      perform public.notification_upsert_calendar_event(new.id, 'school_calendar', case when tg_op = 'INSERT' then 'calendar_event_created' else 'calendar_event_updated' end);
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."notification_calendar_trigger"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notification_generate_deliveries"("p_notification_event_id" "uuid", "p_class_id" "uuid" DEFAULT NULL::"uuid", "p_student_id" "uuid" DEFAULT NULL::"uuid", "p_include_students" boolean DEFAULT true) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_event public.notification_events%rowtype;
  v_inserted integer := 0;
begin
  select * into v_event
  from public.notification_events
  where id = p_notification_event_id;

  if v_event.id is null then
    return 0;
  end if;

  if v_event.source_type = 'analytics_alert' then
    return 0;
  end if;

  insert into public.notification_deliveries (
    notification_event_id,
    recipient_profile_id,
    student_id,
    school_id,
    channel,
    status,
    delivered_at
  )
  select
    v_event.id,
    eligible.recipient_profile_id,
    eligible.student_id,
    eligible.school_id,
    'in_app',
    'unread',
    now()
  from public.notification_resolve_family_and_student_recipients(
    v_event.school_id,
    p_class_id,
    p_student_id,
    p_include_students
  ) eligible
  where eligible.recipient_profile_id is not null
  on conflict (
    notification_event_id,
    recipient_profile_id,
    (coalesce(student_id, '00000000-0000-0000-0000-000000000000'::uuid)),
    channel
  )
  do nothing;

  get diagnostics v_inserted = row_count;
  return v_inserted;
end;
$$;


ALTER FUNCTION "public"."notification_generate_deliveries"("p_notification_event_id" "uuid", "p_class_id" "uuid", "p_student_id" "uuid", "p_include_students" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notification_get_center"("p_student_id" "uuid" DEFAULT NULL::"uuid", "p_read_filter" "text" DEFAULT 'all'::"text", "p_period_days" integer DEFAULT 90, "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS TABLE("item_type" "text", "delivery_id" "uuid", "source_type" "text", "source_id" "uuid", "school_id" "uuid", "student_id" "uuid", "title" "text", "summary" "text", "origin_label" "text", "priority" "text", "deep_link" "text", "delivered_at" timestamp with time zone, "read_at" timestamp with time zone, "notification_status" "text", "child_name" "text", "class_name" "text", "unread_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_profile_id uuid := auth.uid();
  v_role text := lower(coalesce(auth.jwt() -> 'app_metadata' ->> 'platform_role', auth.jwt() -> 'app_metadata' ->> 'role', ''));
  v_filter text := lower(coalesce(nullif(trim(p_read_filter), ''), 'all'));
  v_limit integer := greatest(1, least(coalesce(p_limit, 50), 100));
  v_offset integer := greatest(0, coalesce(p_offset, 0));
  v_days integer := greatest(1, least(coalesce(p_period_days, 90), 365));
begin
  if v_profile_id is null then
    raise exception 'Usuario autenticado obrigatorio.' using errcode = '42501';
  end if;

  if v_filter not in ('all', 'read', 'unread') then
    raise exception 'Filtro de leitura invalido.' using errcode = '22023';
  end if;

  if p_student_id is not null and v_role = 'educacao_infantil' and not public.calendar_family_can_access_student(p_student_id) then
    raise exception 'Crianca fora do vinculo familiar.' using errcode = '42501';
  end if;

  return query
  with center_items as (
    select
      'communication'::text as item_type,
      cd.id as delivery_id,
      'communication'::text as source_type,
      c.id as source_id,
      cd.school_id,
      cd.student_id,
      c.title::text,
      c.body::text as summary,
      'Recados'::text as origin_label,
      'normal'::text as priority,
      'familia.html?view=recados'::text as deep_link,
      cd.delivered_at,
      cd.read_at,
      (case when cd.read_at is null then 'unread' else 'read' end)::text as notification_status,
      s.nome::text as child_name,
      cl.nome::text as class_name
    from public.communication_deliveries cd
    join public.communications c on c.id = cd.communication_id
    left join public.students s on s.id = cd.student_id
    left join public.enrollments e on e.student_id = cd.student_id
      and e.school_id = cd.school_id
      and e.status = 'active'
      and e.ended_at is null
    left join public.classes cl on cl.id = e.class_id
    where cd.recipient_profile_id = v_profile_id
      and public.communication_delivery_is_active(c)
      and cd.delivered_at >= now() - make_interval(days => v_days)
      and (p_student_id is null or cd.student_id = p_student_id)

    union all

    select
      'notification'::text,
      nd.id,
      ne.source_type,
      ne.source_id,
      nd.school_id,
      nd.student_id,
      ne.title::text,
      ne.summary::text,
      case
        when ne.source_type = 'calendar' then 'Agenda'
        when ne.source_type = 'assessment' then 'Avalia+'
        when ne.source_type = 'analytics_alert' then 'Analytics'
        else 'Notificacao'
      end::text,
      ne.priority::text,
      ne.deep_link::text,
      nd.delivered_at,
      nd.read_at,
      (case when nd.read_at is null then 'unread' else 'read' end)::text,
      s.nome::text,
      cl.nome::text
    from public.notification_deliveries nd
    join public.notification_events ne on ne.id = nd.notification_event_id
    left join public.students s on s.id = nd.student_id
    left join public.enrollments e on e.student_id = nd.student_id
      and e.school_id = nd.school_id
      and e.status = 'active'
      and e.ended_at is null
    left join public.classes cl on cl.id = e.class_id
    where nd.recipient_profile_id = v_profile_id
      and nd.delivered_at >= now() - make_interval(days => v_days)
      and (p_student_id is null or nd.student_id = p_student_id)
  ),
  filtered as (
    select *
    from center_items
    where v_filter = 'all'
       or (v_filter = 'read' and center_items.read_at is not null)
       or (v_filter = 'unread' and center_items.read_at is null)
  ),
  counted as (
    select
      filtered.*,
      count(*) filter (where filtered.read_at is null) over ()::integer as total_unread
    from filtered
  )
  select
    counted.item_type,
    counted.delivery_id,
    counted.source_type,
    counted.source_id,
    counted.school_id,
    counted.student_id,
    counted.title,
    counted.summary,
    counted.origin_label,
    counted.priority,
    counted.deep_link,
    counted.delivered_at,
    counted.read_at,
    counted.notification_status,
    counted.child_name,
    counted.class_name,
    counted.total_unread
  from counted
  order by counted.delivered_at desc, counted.source_id
  limit v_limit offset v_offset;
end;
$$;


ALTER FUNCTION "public"."notification_get_center"("p_student_id" "uuid", "p_read_filter" "text", "p_period_days" integer, "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notification_mark_read"("p_delivery_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_profile_id uuid := auth.uid();
  v_delivery public.notification_deliveries%rowtype;
  v_changed boolean := false;
begin
  if v_profile_id is null then
    raise exception 'Usuario autenticado obrigatorio.' using errcode = '42501';
  end if;

  select * into v_delivery
  from public.notification_deliveries
  where id = p_delivery_id
    and recipient_profile_id = v_profile_id
  for update;

  if v_delivery.id is null then
    raise exception 'Entrega de notificacao nao encontrada para este usuario.' using errcode = '42501';
  end if;

  if v_delivery.read_at is null then
    update public.notification_deliveries
    set read_at = now(),
        status = 'read'
    where id = v_delivery.id
    returning * into v_delivery;
    v_changed := true;
  end if;

  return jsonb_build_object(
    'delivery_id', v_delivery.id,
    'notification_event_id', v_delivery.notification_event_id,
    'read_at', v_delivery.read_at,
    'changed', v_changed
  );
end;
$$;


ALTER FUNCTION "public"."notification_mark_read"("p_delivery_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notification_resolve_family_and_student_recipients"("p_school_id" "uuid", "p_class_id" "uuid" DEFAULT NULL::"uuid", "p_student_id" "uuid" DEFAULT NULL::"uuid", "p_include_students" boolean DEFAULT true) RETURNS TABLE("recipient_profile_id" "uuid", "student_id" "uuid", "school_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  with eligible_enrollments as (
    select distinct e.student_id, e.school_id, e.class_id
    from public.enrollments e
    join public.students s on s.id = e.student_id
    where e.school_id = p_school_id
      and e.status = 'active'
      and e.enrolled_at <= now()
      and (e.ended_at is null or e.ended_at > now())
      and coalesce(s.status, 'active') = 'active'
      and (p_class_id is null or e.class_id = p_class_id)
      and (p_student_id is null or e.student_id = p_student_id)
  )
  select distinct
    g.profile_id as recipient_profile_id,
    ee.student_id,
    ee.school_id
  from eligible_enrollments ee
  join public.student_guardian_links sgl on sgl.student_id = ee.student_id
  join public.guardians g on g.id = sgl.guardian_id
  join public.profiles p on p.id = g.profile_id
  where g.profile_id is not null
    and g.status = 'active'
    and sgl.status = 'active'

  union

  select distinct
    sg.profile_id,
    ee.student_id,
    ee.school_id
  from eligible_enrollments ee
  join public.student_guardians sg on sg.student_id = ee.student_id
  join public.profiles p on p.id = sg.profile_id
  where sg.status = 'active'

  union

  select distinct
    s.user_id,
    ee.student_id,
    ee.school_id
  from eligible_enrollments ee
  join public.students s on s.id = ee.student_id
  join public.profiles p on p.id = s.user_id and p.platform_role = 'aluno'
  where p_include_students
    and s.user_id is not null;
$$;


ALTER FUNCTION "public"."notification_resolve_family_and_student_recipients"("p_school_id" "uuid", "p_class_id" "uuid", "p_student_id" "uuid", "p_include_students" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notification_upsert_assessment_available"("p_assignment_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_assignment public.assessment_assignments%rowtype;
  v_assessment record;
  v_event_id uuid;
begin
  select * into v_assignment
  from public.assessment_assignments
  where id = p_assignment_id;

  if v_assignment.id is null
     or v_assignment.status <> 'published'
     or v_assignment.available_from > now()
     or (v_assignment.available_until is not null and v_assignment.available_until <= now()) then
    return null;
  end if;

  select a.title, a.description
    into v_assessment
  from public.assessments a
  where a.id = v_assignment.assessment_id;

  insert into public.notification_events (
    source_type,
    source_id,
    event_type,
    school_id,
    title,
    summary,
    deep_link,
    priority,
    created_by,
    metadata
  )
  values (
    'assessment',
    v_assignment.id,
    'assessment_available',
    v_assignment.school_id,
    'Nova avaliação disponível',
    coalesce(v_assessment.title, 'Avalia+'),
    'aluno.html?view=avaliacoes',
    'important',
    v_assignment.assigned_by,
    jsonb_build_object(
      'assessment_id', v_assignment.assessment_id,
      'class_id', v_assignment.class_id,
      'target_type', v_assignment.target_type
    )
  )
  on conflict (source_type, source_id, event_type)
  do update set
    school_id = excluded.school_id,
    title = excluded.title,
    summary = excluded.summary,
    deep_link = excluded.deep_link,
    priority = excluded.priority,
    created_by = excluded.created_by,
    metadata = excluded.metadata,
    updated_at = now()
  returning id into v_event_id;

  perform public.notification_generate_deliveries(
    v_event_id,
    v_assignment.class_id,
    case when v_assignment.target_type = 'student' then v_assignment.student_id else null end,
    true
  );

  return v_event_id;
end;
$$;


ALTER FUNCTION "public"."notification_upsert_assessment_available"("p_assignment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notification_upsert_calendar_event"("p_source_id" "uuid", "p_source_kind" "text", "p_event_type" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_event_id uuid;
  v_class_entry public.class_calendar_entries%rowtype;
  v_school_event public.school_calendar_events%rowtype;
  v_title text;
  v_summary text;
  v_school_id uuid;
  v_class_id uuid;
  v_created_by uuid;
begin
  if p_event_type not in ('calendar_event_created', 'calendar_event_updated') then
    raise exception 'Tipo de evento de calendario invalido.' using errcode = '22023';
  end if;

  if p_source_kind = 'class_calendar' then
    select * into v_class_entry from public.class_calendar_entries where id = p_source_id;
    if v_class_entry.id is null or v_class_entry.status <> 'published' then
      return null;
    end if;
    v_title := 'Agenda da turma atualizada';
    v_summary := coalesce(v_class_entry.title, 'Novo compromisso da turma.');
    v_school_id := v_class_entry.school_id;
    v_class_id := v_class_entry.class_id;
    select t.profile_id into v_created_by
    from public.teachers t
    where t.id = v_class_entry.teacher_id;
  elsif p_source_kind = 'school_calendar' then
    select * into v_school_event from public.school_calendar_events where id = p_source_id;
    if v_school_event.id is null or v_school_event.status <> 'published' then
      return null;
    end if;
    v_title := 'Agenda da escola atualizada';
    v_summary := coalesce(v_school_event.title, 'Novo compromisso da escola.');
    v_school_id := v_school_event.school_id;
    v_class_id := v_school_event.class_id;
    v_created_by := v_school_event.created_by;
  else
    raise exception 'Origem de calendario invalida.' using errcode = '22023';
  end if;

  insert into public.notification_events (
    source_type,
    source_id,
    event_type,
    school_id,
    title,
    summary,
    deep_link,
    priority,
    created_by,
    metadata
  )
  values (
    'calendar',
    p_source_id,
    p_event_type,
    v_school_id,
    v_title,
    v_summary,
    'familia.html?view=semana',
    'normal',
    v_created_by,
    jsonb_build_object('source_kind', p_source_kind, 'class_id', v_class_id)
  )
  on conflict (source_type, source_id, event_type)
  do update set
    school_id = excluded.school_id,
    title = excluded.title,
    summary = excluded.summary,
    deep_link = excluded.deep_link,
    priority = excluded.priority,
    created_by = excluded.created_by,
    metadata = excluded.metadata,
    updated_at = now()
  returning id into v_event_id;

  perform public.notification_generate_deliveries(v_event_id, v_class_id, null, true);
  return v_event_id;
end;
$$;


ALTER FUNCTION "public"."notification_upsert_calendar_event"("p_source_id" "uuid", "p_source_kind" "text", "p_event_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."official_report_can_read"("p_report_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_report public.official_report_exports%rowtype;
begin
  if auth.uid() is null then
    return false;
  end if;

  select * into v_report
  from public.official_report_exports
  where id = p_report_id;

  if not found then
    return false;
  end if;

  return v_report.requested_by = auth.uid();
end;
$$;


ALTER FUNCTION "public"."official_report_can_read"("p_report_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."pedagogical_recommendations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "school_id" "uuid" NOT NULL,
    "teacher_id" "uuid" NOT NULL,
    "content_type" "text" NOT NULL,
    "content_id" "text" NOT NULL,
    "content_title" "text" NOT NULL,
    "target_type" "text" NOT NULL,
    "class_id" "uuid" NOT NULL,
    "student_id" "uuid",
    "note" "text",
    "status" "text" DEFAULT 'published'::"text" NOT NULL,
    "published_at" timestamp with time zone,
    "deleted_at" timestamp with time zone,
    "deleted_by" "uuid",
    "created_by" "uuid",
    "updated_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "pedagogical_recommendations_content_type_check" CHECK (("content_type" = ANY (ARRAY['printable_activity'::"text", 'book'::"text", 'game'::"text", 'experience'::"text", 'activity'::"text", 'free_proposal'::"text", 'other'::"text"]))),
    CONSTRAINT "pedagogical_recommendations_status_check" CHECK (("status" = ANY (ARRAY['published'::"text", 'archived'::"text", 'deleted'::"text"]))),
    CONSTRAINT "pedagogical_recommendations_target_shape_check" CHECK (((("target_type" = 'class'::"text") AND ("student_id" IS NULL)) OR (("target_type" = 'student'::"text") AND ("student_id" IS NOT NULL)))),
    CONSTRAINT "pedagogical_recommendations_target_type_check" CHECK (("target_type" = ANY (ARRAY['class'::"text", 'student'::"text"])))
);


ALTER TABLE "public"."pedagogical_recommendations" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pedagogical_recommendation_can_read"("p_recommendation" "public"."pedagogical_recommendations") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
  SELECT
    auth.uid() IS NOT NULL
    AND (
      public.secretaria_can_manage_school(p_recommendation.school_id)
      OR EXISTS (
        SELECT 1
        FROM public.teachers t
        WHERE t.id = p_recommendation.teacher_id
          AND t.profile_id = auth.uid()
          AND t.school_id = p_recommendation.school_id
      )
      OR (
        p_recommendation.status = 'published'
        AND public.is_content_available_for_school(
          p_recommendation.school_id,
          p_recommendation.content_type,
          p_recommendation.content_id
        )
        AND (
          public.communication_current_student_can_read(
            p_recommendation.school_id,
            p_recommendation.class_id,
            p_recommendation.student_id,
            p_recommendation.target_type
          )
          OR public.communication_guardian_can_read(
            p_recommendation.school_id,
            p_recommendation.class_id,
            p_recommendation.student_id,
            p_recommendation.target_type
          )
        )
      )
    )
$$;


ALTER FUNCTION "public"."pedagogical_recommendation_can_read"("p_recommendation" "public"."pedagogical_recommendations") OWNER TO "postgres";


