);


ALTER TABLE "public"."teachers" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pedagogical_recommendation_current_teacher"("p_school_id" "uuid") RETURNS "public"."teachers"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
  SELECT t
  FROM public.teachers t
  JOIN public.profiles p ON p.id = t.profile_id
  WHERE p.id = auth.uid()
    AND p.status = 'active'
    AND p.platform_role IN ('professor', 'teacher')
    AND t.school_id = p_school_id
    AND t.status = 'active'
  LIMIT 1
$$;


ALTER FUNCTION "public"."pedagogical_recommendation_current_teacher"("p_school_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pedagogical_recommendation_teacher_can_target"("p_teacher_id" "uuid", "p_school_id" "uuid", "p_class_id" "uuid", "p_student_id" "uuid", "p_target_type" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.class_teacher_memberships ctm
    JOIN public.classes c ON c.id = ctm.class_id
    WHERE ctm.teacher_id = p_teacher_id
      AND ctm.class_id = p_class_id
      AND ctm.status = 'active'
      AND c.school_id = p_school_id
      AND c.status = 'active'
      AND (
        p_target_type = 'class'
        OR EXISTS (
          SELECT 1
          FROM public.enrollments e
          JOIN public.students s ON s.id = e.student_id
          WHERE e.class_id = p_class_id
            AND e.student_id = p_student_id
            AND e.school_id = p_school_id
            AND e.status = 'active'
            AND s.school_id = p_school_id
            AND s.status = 'active'
        )
      )
  )
$$;


ALTER FUNCTION "public"."pedagogical_recommendation_teacher_can_target"("p_teacher_id" "uuid", "p_school_id" "uuid", "p_class_id" "uuid", "p_student_id" "uuid", "p_target_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prevent_official_report_file_mutation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  raise exception 'official report files are immutable';
end;
$$;


ALTER FUNCTION "public"."prevent_official_report_file_mutation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prevent_ready_official_report_mutation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'UPDATE' and old.status = 'ready' then
    raise exception 'official report snapshot is immutable after ready';
  end if;
  if tg_op = 'DELETE' and old.status = 'ready' then
    raise exception 'official report snapshot is immutable after ready';
  end if;
  return coalesce(new, old);
end;
$$;


ALTER FUNCTION "public"."prevent_ready_official_report_mutation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prevent_school_auth_namespace_mutation"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  if old.school_id is distinct from new.school_id then
    raise exception 'SCHOOL_NAMESPACE_IMMUTABLE';
  end if;

  if old.namespace is distinct from new.namespace then
    raise exception 'SCHOOL_NAMESPACE_IMMUTABLE';
  end if;

  if new.next_sequence < old.next_sequence then
    raise exception 'SCHOOL_NAMESPACE_SEQUENCE_CANNOT_REWIND';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."prevent_school_auth_namespace_mutation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."publish_advanced_communication"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_school_id uuid := nullif(p_payload->>'school_id', '')::uuid;
  v_class_id uuid := nullif(p_payload->>'class_id', '')::uuid;
  v_student_id uuid := nullif(p_payload->>'student_id', '')::uuid;
  v_group_id uuid := nullif(p_payload->>'target_group_id', '')::uuid;
  v_audience text := coalesce(nullif(p_payload->>'audience_type', ''), 'class');
  v_status text := coalesce(nullif(p_payload->>'status', ''), 'published');
  v_role text := lower(coalesce(auth.jwt() -> 'app_metadata' ->> 'platform_role', auth.jwt() -> 'app_metadata' ->> 'role', ''));
  v_settings public.communication_permission_settings%rowtype;
  v_comm public.communications%rowtype;
  v_attachment jsonb;
  v_deliveries integer := 0;
begin
  if auth.uid() is null then
    raise exception 'Usuario autenticado obrigatorio';
  end if;

  if v_school_id is null then
    raise exception 'school_id obrigatorio';
  end if;

  v_settings := public.communication_permissions_for_school(v_school_id);

  if v_audience not in ('student', 'class', 'school', 'group', 'grade', 'staff') then
    raise exception 'Tipo de destino invalido';
  end if;

  if v_role = 'aluno' and not v_settings.student_student_enabled then
    raise exception 'Comunicacao aluno-aluno bloqueada por padrao';
  end if;

  if v_role = 'professor' and v_audience in ('student', 'class', 'group', 'grade') and not v_settings.professor_student_enabled then
    raise exception 'Comunicacao professor-aluno bloqueada';
  end if;

  if public.secretaria_can_manage_school(v_school_id) then
    null;
  elsif v_role = 'professor' and v_audience in ('student', 'class') and public.communication_teacher_can_target(v_school_id, v_class_id, v_student_id, v_audience) then
    null;
  elsif v_role = 'professor' and v_audience = 'staff' and v_settings.professor_professor_enabled then
    null;
  elsif v_role = 'professor' and v_audience = 'group' and exists (
    select 1
    from public.recomposition_intervention_groups g
    where g.id = v_group_id
      and g.school_id = v_school_id
      and public.communication_teacher_can_target(v_school_id, g.class_id, null, 'class')
  ) then
    null;
  else
    raise exception 'Usuario sem permissao para publicar este comunicado';
  end if;

  insert into public.communications (
    school_id, author_profile_id, author_role, communication_type, audience_type,
    class_id, student_id, target_group_id, grade_label, staff_role,
    title, body, links, media, advanced_metadata,
    communication_date, expires_at, status
  )
  values (
    v_school_id, auth.uid(), coalesce(nullif(v_role, ''), 'authenticated'),
    coalesce(nullif(p_payload->>'communication_type', ''), 'message'),
    v_audience,
    v_class_id,
    v_student_id,
    v_group_id,
    nullif(p_payload->>'grade_label', ''),
    nullif(p_payload->>'staff_role', ''),
    btrim(coalesce(p_payload->>'title', '')),
    btrim(coalesce(p_payload->>'body', '')),
    coalesce(p_payload->'links', '[]'::jsonb),
    coalesce(p_payload->'media', '[]'::jsonb),
    coalesce(p_payload->'metadata', '{}'::jsonb),
    coalesce(nullif(p_payload->>'communication_date', '')::date, current_date),
    nullif(p_payload->>'expires_at', '')::timestamptz,
    v_status
  )
  returning * into v_comm;

  insert into public.communication_events (communication_id, event_type, from_status, to_status, performed_by)
  values (v_comm.id, 'created', null, v_comm.status, auth.uid());

  for v_attachment in
    select value from jsonb_array_elements(coalesce(p_payload->'attachments', '[]'::jsonb))
  loop
    insert into public.communication_attachments (
      communication_id, school_id, storage_bucket, storage_path, file_name,
      mime_type, file_size_bytes, visibility, metadata
    )
    values (
      v_comm.id,
      v_school_id,
      coalesce(nullif(v_attachment->>'storage_bucket', ''), 'communication-attachments'),
      v_attachment->>'storage_path',
      coalesce(nullif(v_attachment->>'file_name', ''), 'anexo'),
      v_attachment->>'mime_type',
      nullif(v_attachment->>'file_size_bytes', '')::bigint,
      'private',
      coalesce(v_attachment->'metadata', '{}'::jsonb)
    );
  end loop;

  if v_comm.status = 'published' then
    insert into public.communication_events (communication_id, event_type, from_status, to_status, performed_by)
    values (v_comm.id, 'published', 'draft', 'published', auth.uid());
    v_deliveries := public.communication_generate_deliveries(v_comm.id);
  end if;

  return jsonb_build_object('communication_id', v_comm.id, 'deliveries_created', v_deliveries);
end;
$$;


ALTER FUNCTION "public"."publish_advanced_communication"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."publish_communication"("p_school_id" "uuid", "p_communication_type" "text", "p_audience_type" "text", "p_title" "text", "p_body" "text", "p_class_id" "uuid" DEFAULT NULL::"uuid", "p_student_id" "uuid" DEFAULT NULL::"uuid", "p_status" "text" DEFAULT 'published'::"text", "p_communication_date" "date" DEFAULT CURRENT_DATE, "p_expires_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_role text := lower(coalesce(auth.jwt() -> 'app_metadata' ->> 'platform_role', auth.jwt() -> 'app_metadata' ->> 'role', ''));
  v_author uuid := auth.uid();
  v_comm public.communications%rowtype;
  v_deliveries integer := 0;
begin
  if v_author is null then
    raise exception 'Usuario autenticado obrigatorio.' using errcode = '42501';
  end if;

  if p_communication_type not in ('message', 'notice', 'weekly_information', 'institutional_announcement') then
    raise exception 'Tipo de comunicacao invalido.' using errcode = '22023';
  end if;

  if p_audience_type not in ('student', 'class', 'school') then
    raise exception 'Tipo de destino invalido.' using errcode = '22023';
  end if;

  if coalesce(p_status, 'published') not in ('draft', 'published', 'archived') then
    raise exception 'Status de comunicacao invalido.' using errcode = '22023';
  end if;

  if length(btrim(coalesce(p_title, ''))) = 0 or length(btrim(coalesce(p_body, ''))) = 0 then
    raise exception 'Titulo e mensagem sao obrigatorios.' using errcode = '22023';
  end if;

  if p_audience_type = 'school' and (p_class_id is not null or p_student_id is not null) then
    raise exception 'Comunicado escolar nao deve informar turma/aluno.' using errcode = '22023';
  end if;

  if p_audience_type = 'class' and (p_class_id is null or p_student_id is not null) then
    raise exception 'Comunicado de turma deve informar somente class_id.' using errcode = '22023';
  end if;

  if p_audience_type = 'student' and (p_class_id is null or p_student_id is null) then
    raise exception 'Comunicado individual deve informar class_id e student_id.' using errcode = '22023';
  end if;

  if public.secretaria_can_manage_school(p_school_id) then
    null;
  elsif v_role = 'professor' and public.communication_teacher_can_target(p_school_id, p_class_id, p_student_id, p_audience_type) then
    if p_audience_type = 'school' then
      raise exception 'Professor nao pode publicar comunicado institucional nesta V1.' using errcode = '42501';
    end if;
  else
    raise exception 'Usuario sem permissao para publicar este comunicado.' using errcode = '42501';
  end if;

  if p_audience_type in ('class', 'student') and not exists (
    select 1 from public.classes c
    where c.id = p_class_id
      and c.school_id = p_school_id
      and c.status = 'active'
  ) then
    raise exception 'Turma ativa nao pertence a escola informada.' using errcode = '42501';
  end if;

  if p_audience_type = 'student' and not exists (
    select 1 from public.enrollments e
    where e.student_id = p_student_id
      and e.class_id = p_class_id
      and e.school_id = p_school_id
      and e.status = 'active'
      and e.ended_at is null
  ) then
    raise exception 'Aluno nao possui matricula ativa nesta turma/escola.' using errcode = '42501';
  end if;

  insert into public.communications (
    school_id, author_profile_id, author_role, communication_type, audience_type,
    class_id, student_id, title, body, communication_date, expires_at, status
  ) values (
    p_school_id, v_author, coalesce(nullif(v_role, ''), 'authenticated'),
    p_communication_type, p_audience_type, p_class_id, p_student_id,
    btrim(p_title), btrim(p_body), coalesce(p_communication_date, current_date),
    p_expires_at, coalesce(p_status, 'published')
  ) returning * into v_comm;

  insert into public.communication_events (communication_id, event_type, from_status, to_status, performed_by)
  values (v_comm.id, 'created', null, v_comm.status, v_author);

  if v_comm.status = 'published' then
    insert into public.communication_events (communication_id, event_type, from_status, to_status, performed_by)
    values (v_comm.id, 'published', 'draft', 'published', v_author);
    v_deliveries := public.communication_generate_deliveries(v_comm.id);
  elsif v_comm.status = 'archived' then
    insert into public.communication_events (communication_id, event_type, from_status, to_status, performed_by)
    values (v_comm.id, 'archived', 'draft', 'archived', v_author);
  end if;

  return jsonb_build_object(
    'communication_id', v_comm.id,
    'audience_type', v_comm.audience_type,
    'communication_type', v_comm.communication_type,
    'status', v_comm.status,
    'deliveries_created', v_deliveries
  );
end;
$$;


ALTER FUNCTION "public"."publish_communication"("p_school_id" "uuid", "p_communication_type" "text", "p_audience_type" "text", "p_title" "text", "p_body" "text", "p_class_id" "uuid", "p_student_id" "uuid", "p_status" "text", "p_communication_date" "date", "p_expires_at" timestamp with time zone) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."recomposition_plans" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "school_id" "uuid" NOT NULL,
    "class_id" "uuid" NOT NULL,
    "teacher_id" "uuid" NOT NULL,
    "group_id" "uuid",
    "target_type" "text" NOT NULL,
    "title" "text" NOT NULL,
    "target_skill" "text",
    "descriptor" "text",
    "objective" "text",
    "period_start" "date",
    "period_end" "date",
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "responsible_teacher_id" "uuid",
    "created_by" "uuid" DEFAULT "auth"."uid"(),
    "updated_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    CONSTRAINT "recomposition_plans_period_check" CHECK ((("period_end" IS NULL) OR ("period_start" IS NULL) OR ("period_end" >= "period_start"))),
    CONSTRAINT "recomposition_plans_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'active'::"text", 'in_progress'::"text", 'completed'::"text", 'archived'::"text"]))),
    CONSTRAINT "recomposition_plans_target_type_check" CHECK (("target_type" = ANY (ARRAY['student'::"text", 'group'::"text", 'class'::"text"]))),
    CONSTRAINT "recomposition_plans_title_check" CHECK (("length"("btrim"("title")) > 0))
);


ALTER TABLE "public"."recomposition_plans" OWNER TO "postgres";


COMMENT ON TABLE "public"."recomposition_plans" IS 'Recomposicao V1: plano canonico de intervencao ligado ao diagnostico do Avalia+ e a recomendacoes pedagogicas existentes.';



CREATE OR REPLACE FUNCTION "public"."recomposition_can_read_plan"("p_plan" "public"."recomposition_plans") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select auth.uid() is not null and (
    public.is_platform_admin()
    or public.secretaria_can_manage_school(p_plan.school_id)
    or public.avalia_plus_teacher_can_manage_class(p_plan.class_id, p_plan.school_id)
    or exists (
      select 1 from public.recomposition_plan_students rps
      where rps.plan_id = p_plan.id and rps.status <> 'removed'
        and (public.institutional_is_current_student(rps.student_id)
          or public.communication_guardian_can_read(p_plan.school_id, p_plan.class_id, rps.student_id, 'student'))
    )
  );
$$;


ALTER FUNCTION "public"."recomposition_can_read_plan"("p_plan" "public"."recomposition_plans") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recomposition_content_recommendations"("p_class_id" "uuid", "p_skill" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 12) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_class public.classes%rowtype;
  v_items jsonb;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  select * into v_class from public.classes where id = p_class_id;
  if not found then raise exception 'CLASS_NOT_FOUND'; end if;
  if not (public.is_platform_admin() or public.secretaria_can_manage_school(v_class.school_id) or public.avalia_plus_teacher_can_manage_class(v_class.id, v_class.school_id)) then
    raise exception 'RECOMPOSITION_CLASS_FORBIDDEN';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object('content_type', pr.content_type, 'content_id', pr.content_id, 'content_title', pr.content_title, 'source', 'pedagogical_recommendations', 'recommendation_id', pr.id, 'note', pr.note) order by pr.created_at desc), '[]'::jsonb)
  into v_items
  from (
    select * from public.pedagogical_recommendations pr
    where pr.school_id = v_class.school_id and pr.class_id = v_class.id and pr.status = 'published'
      and (nullif(btrim(coalesce(p_skill, '')), '') is null or pr.content_title ilike '%' || p_skill || '%' or coalesce(pr.note, '') ilike '%' || p_skill || '%')
    order by pr.created_at desc
    limit greatest(1, least(coalesce(p_limit, 12), 50))
  ) pr;

  return jsonb_build_object('status', case when jsonb_array_length(v_items) > 0 then 'PASS' else 'EMPTY_REAL' end, 'items', v_items);
end;
$$;


ALTER FUNCTION "public"."recomposition_content_recommendations"("p_class_id" "uuid", "p_skill" "text", "p_limit" integer) OWNER TO "postgres";


