CREATE OR REPLACE FUNCTION "public"."recomposition_get_learning_gap_map"("p_class_id" "uuid", "p_date_from" "date" DEFAULT NULL::"date", "p_date_to" "date" DEFAULT NULL::"date", "p_threshold_developing" numeric DEFAULT 80, "p_threshold_critical" numeric DEFAULT 60) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_from date := coalesce(p_date_from, current_date - 89);
  v_to date := coalesce(p_date_to, current_date);
  v_class public.classes%rowtype;
  v_payload jsonb;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if p_class_id is null then raise exception 'CLASS_REQUIRED'; end if;
  if v_from > v_to then raise exception 'INVALID_PERIOD'; end if;

  select * into v_class from public.classes where id = p_class_id;
  if not found then raise exception 'CLASS_NOT_FOUND'; end if;
  if not (public.is_platform_admin() or public.secretaria_can_manage_school(v_class.school_id) or public.avalia_plus_teacher_can_manage_class(v_class.id, v_class.school_id)) then
    raise exception 'RECOMPOSITION_CLASS_FORBIDDEN';
  end if;

  with active_students as (
    select s.id as student_id, s.nome as student_name
    from public.enrollments e
    join public.students s on s.id = e.student_id
    where e.school_id = v_class.school_id
      and e.class_id = v_class.id
      and e.status in ('active', 'ativo')
      and coalesce(s.status, 'active') in ('active', 'ativo')
      and e.enrolled_at <= now()
      and (e.ended_at is null or e.ended_at > now())
  ),
  response_scope as (
    select
      ar.student_id,
      ast.student_name,
      nullif(btrim(coalesce(qi.bncc_skill, qi.reference_matrix, qi.curriculum_matrix, 'SEM_DESCRITOR')), '') as skill_code,
      nullif(btrim(coalesce(qi.knowledge_object, qi.thematic_unit, qi.internal_title, 'Habilidade avaliada')), '') as skill_label,
      count(resp.id)::integer as responses,
      count(resp.id) filter (where resp.is_correct is true)::integer as correct,
      round(avg(case when aq.points > 0 and resp.score_awarded is not null then greatest(0, least(100, (resp.score_awarded / aq.points) * 100)) when resp.is_correct is true then 100 else 0 end), 2) as mastery_percentage,
      max(ar.finalized_at) as last_result_at
    from public.assessment_results ar
    join public.assessment_assignments aa on aa.id = ar.assignment_id
    join active_students ast on ast.student_id = ar.student_id
    join public.assessment_responses resp on resp.attempt_id = ar.attempt_id
    join public.assessment_questions aq on aq.assessment_id = ar.assessment_id and aq.question_id = resp.question_id
    join public.question_items qi on qi.id = aq.question_id
    where aa.class_id = v_class.id
      and ar.finalized_at::date between v_from and v_to
    group by ar.student_id, ast.student_name, skill_code, skill_label
  ),
  classified as (
    select *, case when responses < 2 then 'AMOSTRA_INSUFICIENTE' when mastery_percentage < p_threshold_critical then 'CRITICA' when mastery_percentage < p_threshold_developing then 'EM_DESENVOLVIMENTO' else 'CONSOLIDADA' end as gap_status
    from response_scope
  ),
  skill_summary as (
    select skill_code, skill_label, count(distinct student_id)::integer as students_evaluated, round(avg(mastery_percentage), 2) as mastery_percentage,
      count(*) filter (where gap_status = 'CRITICA')::integer as critical_students,
      count(*) filter (where gap_status = 'EM_DESENVOLVIMENTO')::integer as developing_students,
      count(*) filter (where gap_status = 'CONSOLIDADA')::integer as consolidated_students
    from classified group by skill_code, skill_label
  ),
  student_rows as (
    select student_id, student_name,
      coalesce(jsonb_agg(jsonb_build_object('skill_code', skill_code, 'skill_label', skill_label, 'responses', responses, 'correct', correct, 'mastery_percentage', mastery_percentage, 'status', gap_status, 'last_result_at', last_result_at)
      order by case gap_status when 'CRITICA' then 1 when 'EM_DESENVOLVIMENTO' then 2 when 'AMOSTRA_INSUFICIENTE' then 3 else 4 end, skill_code), '[]'::jsonb) as skills
    from classified group by student_id, student_name
  )
  select jsonb_build_object(
    'period', jsonb_build_object('date_from', v_from, 'date_to', v_to),
    'class', jsonb_build_object('id', v_class.id, 'name', v_class.nome, 'school_id', v_class.school_id),
    'thresholds', jsonb_build_object('critical', p_threshold_critical, 'developing', p_threshold_developing),
    'summary', jsonb_build_object('students', (select count(*) from active_students), 'students_with_results', (select count(distinct student_id) from classified), 'skills', (select count(*) from skill_summary), 'critical_skills', (select count(*) from skill_summary where critical_students > 0), 'developing_skills', (select count(*) from skill_summary where developing_students > 0)),
    'skills', coalesce((select jsonb_agg(to_jsonb(skill_summary) order by critical_students desc, mastery_percentage asc, skill_code) from skill_summary), '[]'::jsonb),
    'students', coalesce((select jsonb_agg(to_jsonb(student_rows) order by student_name) from student_rows), '[]'::jsonb)
  ) into v_payload;
  return v_payload;
end;
$$;


ALTER FUNCTION "public"."recomposition_get_learning_gap_map"("p_class_id" "uuid", "p_date_from" "date", "p_date_to" "date", "p_threshold_developing" numeric, "p_threshold_critical" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recomposition_student_in_class"("p_school_id" "uuid", "p_class_id" "uuid", "p_student_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1 from public.enrollments e join public.students s on s.id = e.student_id
    where e.school_id = p_school_id and e.class_id = p_class_id and e.student_id = p_student_id
      and e.status in ('active', 'ativo') and coalesce(s.status, 'active') in ('active', 'ativo')
      and e.enrolled_at <= now() and (e.ended_at is null or e.ended_at > now())
  );
$$;


ALTER FUNCTION "public"."recomposition_student_in_class"("p_school_id" "uuid", "p_class_id" "uuid", "p_student_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."report_can_read_class"("p_class_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.classes c
    where c.id = p_class_id
      and (
        public.report_can_read_school(c.school_id)
        or exists (
          select 1
          from public.teachers t
          where t.school_id = c.school_id
            and t.profile_id = auth.uid()
            and t.status = 'active'
            and public.institutional_teacher_can_manage_class(t.id, c.id, c.school_id)
        )
      )
  );
$$;


ALTER FUNCTION "public"."report_can_read_class"("p_class_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."report_can_read_school"("p_school_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
  select coalesce(public.is_platform_admin(), false)
    or public.secretaria_can_manage_school(p_school_id)
    or exists (
      select 1
      from public.current_network_school_ids() cns
      where cns.school_id = p_school_id
    );
$$;


ALTER FUNCTION "public"."report_can_read_school"("p_school_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."report_get_attendance"("p_scope" "text" DEFAULT 'school'::"text", "p_school_id" "uuid" DEFAULT NULL::"uuid", "p_class_id" "uuid" DEFAULT NULL::"uuid", "p_student_id" "uuid" DEFAULT NULL::"uuid", "p_network_id" "uuid" DEFAULT NULL::"uuid", "p_date_from" "date" DEFAULT NULL::"date", "p_date_to" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_from date := coalesce(p_date_from, current_date - 29);
  v_to date := coalesce(p_date_to, current_date);
  v_scope text := coalesce(nullif(lower(trim(p_scope)), ''), 'school');
  v_school_id uuid := p_school_id;
  v_network_id uuid := p_network_id;
  v_summary jsonb := '{}'::jsonb;
  v_rows jsonb := '[]'::jsonb;
begin
  if v_to < v_from then
    raise exception 'REPORT_INVALID_PERIOD' using errcode = '22023';
  end if;

  if p_class_id is not null then
    select c.school_id into v_school_id from public.classes c where c.id = p_class_id;
  elsif p_student_id is not null then
    select s.school_id into v_school_id from public.students s where s.id = p_student_id;
  end if;

  if v_scope = 'network' or v_network_id is not null then
    v_network_id := public.network_resolve_requested_network(v_network_id);
    with scoped as (
      select ar.*
      from public.attendance_records ar
      join public.network_school_memberships nsm on nsm.school_id = ar.school_id
      where nsm.network_id = v_network_id
        and nsm.status = 'active'
        and nsm.joined_at <= now()
        and (nsm.ended_at is null or nsm.ended_at > now())
        and ar.attendance_date between v_from and v_to
    )
    select jsonb_build_object(
        'total', count(*),
        'present', count(*) filter (where status = 'present'),
        'absent', count(*) filter (where status = 'absent'),
        'justified', count(*) filter (where status = 'justified'),
        'attendance_rate', round(100 * count(*) filter (where status = 'present')::numeric / nullif(count(*), 0), 2)
      )
    into v_summary
    from scoped;

    with school_rows as (
      select s.id as school_id, s.nome as school_name,
        count(ar.*) as total,
        count(*) filter (where ar.status = 'present') as present,
        count(*) filter (where ar.status = 'absent') as absent,
        count(*) filter (where ar.status = 'justified') as justified,
        round(100 * count(*) filter (where ar.status = 'present')::numeric / nullif(count(ar.*), 0), 2) as attendance_rate
      from public.network_school_memberships nsm
      join public.schools s on s.id = nsm.school_id
      left join public.attendance_records ar on ar.school_id = s.id and ar.attendance_date between v_from and v_to
      where nsm.network_id = v_network_id
        and nsm.status = 'active'
        and nsm.joined_at <= now()
        and (nsm.ended_at is null or nsm.ended_at > now())
      group by s.id, s.nome
      order by s.nome
    )
    select coalesce(jsonb_agg(to_jsonb(school_rows)), '[]'::jsonb) into v_rows from school_rows;
  else
    if v_school_id is null or not public.report_can_read_school(v_school_id) then
      if p_class_id is null or not public.report_can_read_class(p_class_id) then
        raise exception 'REPORT_ACCESS_DENIED' using errcode = '42501';
      end if;
    end if;

    with scoped as (
      select ar.*
      from public.attendance_records ar
      where ar.attendance_date between v_from and v_to
        and (v_school_id is null or ar.school_id = v_school_id)
        and (p_class_id is null or ar.class_id = p_class_id)
        and (p_student_id is null or ar.student_id = p_student_id)
    )
    select jsonb_build_object(
        'total', count(*),
        'present', count(*) filter (where status = 'present'),
        'absent', count(*) filter (where status = 'absent'),
        'justified', count(*) filter (where status = 'justified'),
        'attendance_rate', round(100 * count(*) filter (where status = 'present')::numeric / nullif(count(*), 0), 2)
      )
    into v_summary
    from scoped;

    with student_rows as (
      select st.id as student_id, st.nome as student_name, c.id as class_id, c.nome as class_name,
        count(ar.*) as total,
        count(*) filter (where ar.status = 'present') as present,
        count(*) filter (where ar.status = 'absent') as absent,
        count(*) filter (where ar.status = 'justified') as justified,
        round(100 * count(*) filter (where ar.status = 'present')::numeric / nullif(count(ar.*), 0), 2) as attendance_rate
      from public.students st
      join public.classes c on c.id = st.class_id
      left join public.attendance_records ar on ar.student_id = st.id and ar.attendance_date between v_from and v_to
      where st.school_id = v_school_id
        and (p_class_id is null or st.class_id = p_class_id)
        and (p_student_id is null or st.id = p_student_id)
      group by st.id, st.nome, c.id, c.nome
      order by c.nome, st.nome
    )
    select coalesce(jsonb_agg(to_jsonb(student_rows)), '[]'::jsonb) into v_rows from student_rows;
  end if;

  return jsonb_build_object(
    'report_type', 'attendance',
    'period', jsonb_build_object('date_from', v_from, 'date_to', v_to),
    'summary', coalesce(v_summary, '{}'::jsonb),
    'rows', coalesce(v_rows, '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."report_get_attendance"("p_scope" "text", "p_school_id" "uuid", "p_class_id" "uuid", "p_student_id" "uuid", "p_network_id" "uuid", "p_date_from" "date", "p_date_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."report_get_avalia"("p_scope" "text" DEFAULT 'school'::"text", "p_school_id" "uuid" DEFAULT NULL::"uuid", "p_class_id" "uuid" DEFAULT NULL::"uuid", "p_assignment_id" "uuid" DEFAULT NULL::"uuid", "p_network_id" "uuid" DEFAULT NULL::"uuid", "p_date_from" "date" DEFAULT NULL::"date", "p_date_to" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_from date := coalesce(p_date_from, current_date - 29);
  v_to date := coalesce(p_date_to, current_date);
  v_scope text := coalesce(nullif(lower(trim(p_scope)), ''), 'school');
  v_school_id uuid := p_school_id;
  v_network_id uuid := p_network_id;
  v_summary jsonb := '{}'::jsonb;
  v_rows jsonb := '[]'::jsonb;
begin
  if v_to < v_from then
    raise exception 'REPORT_INVALID_PERIOD' using errcode = '22023';
  end if;

  if p_class_id is not null then
    select c.school_id into v_school_id
    from public.classes c
    where c.id = p_class_id;
  elsif p_assignment_id is not null then
    select aa.school_id into v_school_id
    from public.assessment_assignments aa
    where aa.id = p_assignment_id;
  end if;

  if v_scope = 'network' or v_network_id is not null then
    v_network_id := public.network_resolve_requested_network(v_network_id);

    with assignments as (
      select aa.*
      from public.assessment_assignments aa
      join public.network_school_memberships nsm on nsm.school_id = aa.school_id
      where nsm.network_id = v_network_id
        and nsm.status = 'active'
        and nsm.joined_at <= now()
        and (nsm.ended_at is null or nsm.ended_at > now())
        and aa.status = 'published'
        and aa.available_from::date <= v_to
        and coalesce(aa.available_until::date, v_to) >= v_from
        and (p_class_id is null or aa.class_id = p_class_id)
        and (p_assignment_id is null or aa.id = p_assignment_id)
    ),
    aggregates as (
      select
        count(distinct a.id) as assignments,
        count(distinct e.student_id) as assigned_students,
        count(distinct ar.student_id) as completed_students,
        round(100 * count(distinct ar.student_id)::numeric / nullif(count(distinct e.student_id), 0), 2) as participation_percentage,
        round(avg(ar.score_percentage), 2) as average_percentage
      from assignments a
      left join public.enrollments e on e.class_id = a.class_id and e.status = 'active'
      left join public.assessment_results ar on ar.assignment_id = a.id
    )
    select to_jsonb(aggregates) into v_summary from aggregates;

    with rows as (
      select
        aa.id,
        aa.school_id,
        s.nome as school_name,
        a.title as assessment_title,
        c.nome as class_name,
        aa.status,
        count(distinct e.student_id) as assigned_students,
        count(distinct ar.student_id) as completed_students,
        round(100 * count(distinct ar.student_id)::numeric / nullif(count(distinct e.student_id), 0), 2) as participation_percentage,
        round(avg(ar.score_percentage), 2) as average_percentage
      from public.assessment_assignments aa
      join public.network_school_memberships nsm on nsm.school_id = aa.school_id
      join public.schools s on s.id = aa.school_id
      join public.assessments a on a.id = aa.assessment_id
      join public.classes c on c.id = aa.class_id
      left join public.enrollments e on e.class_id = aa.class_id and e.status = 'active'
      left join public.assessment_results ar on ar.assignment_id = aa.id
      where nsm.network_id = v_network_id
        and nsm.status = 'active'
        and nsm.joined_at <= now()
        and (nsm.ended_at is null or nsm.ended_at > now())
        and aa.status = 'published'
        and aa.available_from::date <= v_to
        and coalesce(aa.available_until::date, v_to) >= v_from
        and (p_class_id is null or aa.class_id = p_class_id)
        and (p_assignment_id is null or aa.id = p_assignment_id)
      group by aa.id, aa.school_id, s.nome, a.title, c.nome, aa.status
      order by s.nome asc, a.title asc, c.nome asc
    )
    select coalesce(jsonb_agg(to_jsonb(rows)), '[]'::jsonb) into v_rows from rows;

    return jsonb_build_object(
      'report_type', 'avalia',
      'report_scope', 'network',
      'network_id', v_network_id,
      'period', jsonb_build_object('date_from', v_from, 'date_to', v_to),
      'summary', coalesce(v_summary, '{}'::jsonb),
      'rows', coalesce(v_rows, '[]'::jsonb)
    );
  end if;

  if v_school_id is null or not public.report_can_read_school(v_school_id) then
    if p_class_id is null or not public.report_can_read_class(p_class_id) then
      raise exception 'REPORT_ACCESS_DENIED' using errcode = '42501';
    end if;
  end if;

  with assignments as (
    select aa.*
    from public.assessment_assignments aa
    where aa.status = 'published'
      and aa.available_from::date <= v_to
      and coalesce(aa.available_until::date, v_to) >= v_from
      and (v_school_id is null or aa.school_id = v_school_id)
      and (p_class_id is null or aa.class_id = p_class_id)
      and (p_assignment_id is null or aa.id = p_assignment_id)
  ),
  aggregates as (
    select
      count(distinct a.id) as assignments,
      count(distinct e.student_id) as assigned_students,
      count(distinct ar.student_id) as completed_students,
      round(100 * count(distinct ar.student_id)::numeric / nullif(count(distinct e.student_id), 0), 2) as participation_percentage,
      round(avg(ar.score_percentage), 2) as average_percentage
    from assignments a
    left join public.enrollments e on e.class_id = a.class_id and e.status = 'active'
    left join public.assessment_results ar on ar.assignment_id = a.id
  )
  select to_jsonb(aggregates) into v_summary from aggregates;

  with rows as (
    select aa.id, a.title as assessment_title, c.nome as class_name, aa.status,
      count(distinct e.student_id) as assigned_students,
      count(distinct ar.student_id) as completed_students,
      round(100 * count(distinct ar.student_id)::numeric / nullif(count(distinct e.student_id), 0), 2) as participation_percentage,
      round(avg(ar.score_percentage), 2) as average_percentage
    from public.assessment_assignments aa
    join public.assessments a on a.id = aa.assessment_id
    join public.classes c on c.id = aa.class_id
    left join public.enrollments e on e.class_id = aa.class_id and e.status = 'active'
    left join public.assessment_results ar on ar.assignment_id = aa.id
    where aa.status = 'published'
      and aa.available_from::date <= v_to
      and coalesce(aa.available_until::date, v_to) >= v_from
      and (v_school_id is null or aa.school_id = v_school_id)
      and (p_class_id is null or aa.class_id = p_class_id)
      and (p_assignment_id is null or aa.id = p_assignment_id)
    group by aa.id, a.title, c.nome, aa.status
    order by a.title asc, c.nome asc
  )
  select coalesce(jsonb_agg(to_jsonb(rows)), '[]'::jsonb) into v_rows from rows;

  return jsonb_build_object(
    'report_type', 'avalia',
    'report_scope', case when p_class_id is not null then 'class' else 'school' end,
    'school_id', v_school_id,
    'period', jsonb_build_object('date_from', v_from, 'date_to', v_to),
    'summary', coalesce(v_summary, '{}'::jsonb),
    'rows', coalesce(v_rows, '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."report_get_avalia"("p_scope" "text", "p_school_id" "uuid", "p_class_id" "uuid", "p_assignment_id" "uuid", "p_network_id" "uuid", "p_date_from" "date", "p_date_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."report_get_class_diary"("p_school_id" "uuid" DEFAULT NULL::"uuid", "p_class_id" "uuid" DEFAULT NULL::"uuid", "p_teacher_id" "uuid" DEFAULT NULL::"uuid", "p_date_from" "date" DEFAULT NULL::"date", "p_date_to" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_from date := coalesce(p_date_from, current_date - 29);
  v_to date := coalesce(p_date_to, current_date);
  v_school_id uuid := p_school_id;
  v_summary jsonb;
  v_rows jsonb;
begin
  if p_class_id is not null then
    select c.school_id into v_school_id from public.classes c where c.id = p_class_id;
  end if;

  if v_school_id is null or not public.report_can_read_school(v_school_id) then
    if p_class_id is null or not public.report_can_read_class(p_class_id) then
      raise exception 'REPORT_ACCESS_DENIED' using errcode = '42501';
    end if;
  end if;

  with scoped as (
    select cde.*
    from public.class_diary_entries cde
    where cde.entry_date between v_from and v_to
      and cde.deleted_at is null
      and (v_school_id is null or cde.school_id = v_school_id)
      and (p_class_id is null or cde.class_id = p_class_id)
      and (p_teacher_id is null or cde.teacher_id = p_teacher_id)
  )
  select jsonb_build_object(
      'entries', count(*),
      'closed_entries', count(*) filter (where status = 'closed'),
      'draft_entries', count(*) filter (where status = 'draft')
    )
  into v_summary
  from scoped;

  with rows as (
    select cde.id, cde.entry_date, cde.title, cde.status, c.nome as class_name,
      coalesce(p.display_name, 'Professor') as teacher_name,
      cde.taught_content, cde.pedagogical_notes,
      (select count(*) from public.attendance_records ar where ar.class_id = cde.class_id and ar.attendance_date = cde.entry_date) as attendance_records,
      (select count(*) from public.class_diary_activity_links l where l.diary_entry_id = cde.id) as activity_links
    from public.class_diary_entries cde
    join public.classes c on c.id = cde.class_id
    join public.teachers t on t.id = cde.teacher_id
    left join public.profiles p on p.id = t.profile_id
    where cde.entry_date between v_from and v_to
      and cde.deleted_at is null
      and (v_school_id is null or cde.school_id = v_school_id)
      and (p_class_id is null or cde.class_id = p_class_id)
      and (p_teacher_id is null or cde.teacher_id = p_teacher_id)
    order by cde.entry_date desc, c.nome asc
  )
  select coalesce(jsonb_agg(to_jsonb(rows)), '[]'::jsonb) into v_rows from rows;

  return jsonb_build_object(
    'report_type', 'class_diary',
    'period', jsonb_build_object('date_from', v_from, 'date_to', v_to),
    'summary', coalesce(v_summary, '{}'::jsonb),
    'rows', coalesce(v_rows, '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."report_get_class_diary"("p_school_id" "uuid", "p_class_id" "uuid", "p_teacher_id" "uuid", "p_date_from" "date", "p_date_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."school_access_current_enrollment"("p_student_id" "uuid", "p_school_id" "uuid") RETURNS TABLE("enrollment_id" "uuid", "class_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select e.id, e.class_id
  from public.enrollments e
  where e.student_id = p_student_id
    and e.school_id = p_school_id
    and coalesce(e.status, 'active') in ('active', 'ativo')
    and e.ended_at is null
  order by e.enrolled_at desc nulls last, e.created_at desc nulls last
  limit 1;
$$;


ALTER FUNCTION "public"."school_access_current_enrollment"("p_student_id" "uuid", "p_school_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."school_access_get_history"("p_school_id" "uuid", "p_student_id" "uuid" DEFAULT NULL::"uuid", "p_date_from" "date" DEFAULT (CURRENT_DATE - 30), "p_date_to" "date" DEFAULT CURRENT_DATE, "p_class_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if not public.school_access_operator_can_manage(p_school_id) then
    raise exception 'Usuario sem permissao para consultar historico escolar.' using errcode = '42501';
  end if;

  return coalesce((
    select jsonb_agg(
      jsonb_build_object(
        'event_id', sae.id,
        'student_id', sae.student_id,
        'student_name', s.nome,
        'class_id', sae.class_id,
        'class_name', c.nome,
        'event_type', sae.event_type,
        'occurred_at', sae.occurred_at,
        'origin', sae.origin,
        'status', sae.status
      )
      order by sae.occurred_at desc
    )
    from public.school_access_events sae
    join public.students s on s.id = sae.student_id
    left join public.classes c on c.id = sae.class_id
    where sae.school_id = p_school_id
      and (p_student_id is null or sae.student_id = p_student_id)
      and (p_class_id is null or sae.class_id = p_class_id)
      and sae.occurred_at >= p_date_from::timestamp with time zone
      and sae.occurred_at < (p_date_to + 1)::timestamp with time zone
  ), '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."school_access_get_history"("p_school_id" "uuid", "p_student_id" "uuid", "p_date_from" "date", "p_date_to" "date", "p_class_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."school_access_issue_student_identifier"("p_student_id" "uuid", "p_status" "text" DEFAULT 'active'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_student public.students%rowtype;
  v_enrollment record;
  v_code text;
  v_identifier public.school_access_identifiers%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Usuario autenticado obrigatorio.' using errcode = '42501';
  end if;

  if coalesce(p_status, 'active') <> 'active' then
    raise exception 'Somente identificadores ativos sao emitidos por este fluxo.' using errcode = '22023';
  end if;

  select * into v_student from public.students where id = p_student_id;
  if v_student.id is null or v_student.school_id is null then
    raise exception 'Aluno nao encontrado.' using errcode = '22023';
  end if;

  if not public.school_access_operator_can_manage(v_student.school_id) then
    raise exception 'Operador sem permissao para emitir identificador escolar.' using errcode = '42501';
  end if;

  select * into v_enrollment
  from public.school_access_current_enrollment(v_student.id, v_student.school_id);

  if v_enrollment.class_id is null then
    raise exception 'Aluno sem matricula ativa para emissao de identificador.' using errcode = '22023';
  end if;

  update public.school_access_identifiers
  set status = 'revoked',
      revoked_at = now(),
      updated_at = now(),
      metadata = metadata || jsonb_build_object('revoked_reason', 'replaced_by_new_identifier')
  where school_id = v_student.school_id
    and student_id = v_student.id
    and status = 'active'
    and revoked_at is null;

  v_code := 'RS-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 16));

  insert into public.school_access_identifiers (
    school_id,
    student_id,
    code_public,
    token_hash,
    barcode_value,
    status,
    issued_by,
    metadata
  ) values (
    v_student.school_id,
    v_student.id,
    v_code,
    encode(digest(v_code, 'sha256'), 'hex'),
    v_code,
    'active',
    auth.uid(),
    jsonb_build_object('payload_version', 1, 'contains_personal_data', false)
  )
  returning * into v_identifier;

  return jsonb_build_object(
    'identifier_id', v_identifier.id,
    'student_id', v_identifier.student_id,
    'school_id', v_identifier.school_id,
    'class_id', v_enrollment.class_id,
    'qr_payload', 'RSACCESS:' || v_identifier.code_public,
    'barcode_value', v_identifier.barcode_value,
    'status', v_identifier.status,
    'contains_personal_data', false
  );
end;
$$;


ALTER FUNCTION "public"."school_access_issue_student_identifier"("p_student_id" "uuid", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."school_access_list_daily_events"("p_school_id" "uuid", "p_event_date" "date" DEFAULT CURRENT_DATE, "p_class_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if not public.school_access_operator_can_manage(p_school_id) then
    raise exception 'Usuario sem permissao para consultar movimentacoes escolares.' using errcode = '42501';
  end if;

  return coalesce((
    select jsonb_agg(
      jsonb_build_object(
        'event_id', sae.id,
        'student_id', sae.student_id,
        'student_name', s.nome,
        'class_id', sae.class_id,
        'class_name', c.nome,
        'event_type', sae.event_type,
        'occurred_at', sae.occurred_at,
        'operator_profile_id', sae.operator_profile_id,
        'origin', sae.origin,
        'status', sae.status,
        'duplicate_of', sae.duplicate_of,
        'communication_id', sae.communication_id
      )
      order by sae.occurred_at desc
    )
    from public.school_access_events sae
    join public.students s on s.id = sae.student_id
    left join public.classes c on c.id = sae.class_id
    where sae.school_id = p_school_id
      and sae.occurred_at >= p_event_date::timestamp with time zone
      and sae.occurred_at < (p_event_date + 1)::timestamp with time zone
      and (p_class_id is null or sae.class_id = p_class_id)
  ), '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."school_access_list_daily_events"("p_school_id" "uuid", "p_event_date" "date", "p_class_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."school_access_normalize_code"("p_code" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_code text := btrim(coalesce(p_code, ''));
begin
  if left(v_code, 9) = 'RSACCESS:' then
    v_code := substr(v_code, 10);
  end if;
  return upper(regexp_replace(v_code, '\s+', '', 'g'));
end;
$$;


ALTER FUNCTION "public"."school_access_normalize_code"("p_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."school_access_operator_can_manage"("p_school_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select coalesce(public.is_platform_admin(), false)
    or coalesce(public.secretaria_can_manage_school(p_school_id), false);
$$;


ALTER FUNCTION "public"."school_access_operator_can_manage"("p_school_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."school_access_register_event"("p_code" "text", "p_event_type" "text", "p_origin" "text" DEFAULT 'manual_code'::"text", "p_occurred_at" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_code text := public.school_access_normalize_code(p_code);
  v_identifier public.school_access_identifiers%rowtype;
  v_enrollment record;
  v_event_type text := lower(coalesce(p_event_type, ''));
  v_origin text := lower(coalesce(p_origin, 'manual_code'));
  v_duplicate public.school_access_events%rowtype;
  v_event public.school_access_events%rowtype;
  v_comm jsonb := null;
  v_comm_id uuid := null;
  v_title text;
  v_body text;
begin
  if auth.uid() is null then
    raise exception 'Usuario autenticado obrigatorio.' using errcode = '42501';
  end if;

  if v_event_type not in ('entry', 'exit') then
    raise exception 'Tipo de evento invalido.' using errcode = '22023';
  end if;

  if v_origin not in ('qr_camera', 'manual_code', 'barcode', 'admin', 'api') then
    v_origin := 'manual_code';
  end if;

  select * into v_identifier
  from public.school_access_identifiers
  where code_public = v_code
    and status = 'active'
    and revoked_at is null;

  if v_identifier.id is null then
    raise exception 'Identificador escolar invalido ou inativo.' using errcode = '22023';
  end if;

  if not public.school_access_operator_can_manage(v_identifier.school_id) then
    raise exception 'Operador sem permissao para registrar entrada/saida.' using errcode = '42501';
  end if;

  select * into v_enrollment
  from public.school_access_current_enrollment(v_identifier.student_id, v_identifier.school_id);

  if v_enrollment.class_id is null then
    raise exception 'Aluno sem matricula ativa para registro de entrada/saida.' using errcode = '22023';
  end if;

  select * into v_duplicate
  from public.school_access_events sae
  where sae.school_id = v_identifier.school_id
    and sae.student_id = v_identifier.student_id
    and sae.event_type = v_event_type
    and sae.status = 'recorded'
    and sae.occurred_at >= coalesce(p_occurred_at, now()) - interval '2 minutes'
  order by sae.occurred_at desc
  limit 1;

  insert into public.school_access_events (
    school_id,
    student_id,
    class_id,
    identifier_id,
    event_type,
    occurred_at,
    operator_profile_id,
    origin,
    source_hint,
    status,
    duplicate_of,
    metadata
  ) values (
    v_identifier.school_id,
    v_identifier.student_id,
    v_enrollment.class_id,
    v_identifier.id,
    v_event_type,
    coalesce(p_occurred_at, now()),
    auth.uid(),
    v_origin,
    right(v_code, 4),
    case when v_duplicate.id is null then 'recorded' else 'duplicate' end,
    v_duplicate.id,
    jsonb_build_object('duplicate_control_window_minutes', 2)
  )
  returning * into v_event;

  insert into public.school_access_event_audit (event_id, school_id, action, actor_profile_id, details)
  values (
    v_event.id,
    v_event.school_id,
    case when v_event.status = 'duplicate' then 'duplicate_scan_controlled' else 'event_registered' end,
    auth.uid(),
    jsonb_build_object('event_type', v_event.event_type, 'origin', v_event.origin, 'student_id', v_event.student_id)
  );

  if v_event.status = 'recorded' then
    v_title := case when v_event_type = 'entry' then 'Entrada registrada' else 'Saída registrada' end;
    v_body := case when v_event_type = 'entry'
      then 'A entrada do estudante foi registrada pela escola.'
      else 'A saída do estudante foi registrada pela escola.'
    end;

    begin
      v_comm := public.publish_communication(
        v_event.school_id,
        'notice',
        'student',
        v_title,
        v_body,
        v_event.class_id,
        v_event.student_id,
        'published',
        current_date,
        null
      );
      v_comm_id := nullif(v_comm ->> 'communication_id', '')::uuid;
      update public.school_access_events
      set communication_id = v_comm_id,
          metadata = metadata || jsonb_build_object('notification_status', 'published')
      where id = v_event.id;
      v_event.communication_id := v_comm_id;
    exception when others then
      update public.school_access_events
      set metadata = metadata || jsonb_build_object('notification_status', 'failed', 'notification_error', sqlerrm)
      where id = v_event.id;
    end;
  end if;

  return jsonb_build_object(
    'event_id', v_event.id,
    'school_id', v_event.school_id,
    'student_id', v_event.student_id,
    'class_id', v_event.class_id,
    'event_type', v_event.event_type,
    'occurred_at', v_event.occurred_at,
    'status', v_event.status,
    'duplicate_of', v_event.duplicate_of,
    'communication_id', v_event.communication_id
  );
end;
$$;


ALTER FUNCTION "public"."school_access_register_event"("p_code" "text", "p_event_type" "text", "p_origin" "text", "p_occurred_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."school_access_register_event"("p_code" "text", "p_event_type" "text", "p_origin" "text", "p_occurred_at" timestamp with time zone) IS 'Registers entry/exit from QR/barcode/manual code and publishes a canonical notice when applicable.';



CREATE OR REPLACE FUNCTION "public"."secretaria_archive_school_calendar_event"("p_event_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_event public.school_calendar_events%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Usuario autenticado obrigatorio.' using errcode = '42501';
  end if;

  select * into v_event
  from public.school_calendar_events
  where id = p_event_id;

  if v_event.id is null then
    raise exception 'Evento institucional nao encontrado.' using errcode = 'P0002';
  end if;

  if not (public.is_platform_admin() or public.secretaria_can_manage_school(v_event.school_id)) then
    raise exception 'Secretaria nao autorizada para este evento.' using errcode = '42501';
  end if;

  update public.school_calendar_events
  set status = 'archived',
      updated_at = now()
  where id = p_event_id;

  return jsonb_build_object('event_id', p_event_id, 'status', 'archived');
end;
$$;


ALTER FUNCTION "public"."secretaria_archive_school_calendar_event"("p_event_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."secretaria_can_manage_school"("p_school_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
  select
    coalesce(public.is_platform_admin(), false)
    or exists (
      select 1
      from public.school_memberships sm
      where sm.school_id = p_school_id
        and sm.profile_id = auth.uid()
        and sm.status = 'active'
        and sm.membership_role in ('gestor', 'coordenador', 'direcao', 'secretaria', 'admin', 'admin_ti')
        and sm.started_at <= now()
        and (sm.ended_at is null or sm.ended_at > now())
    )
    or exists (
      select 1
      from public.current_network_school_ids() cns
      where cns.school_id = p_school_id
    );
$$;


ALTER FUNCTION "public"."secretaria_can_manage_school"("p_school_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."secretaria_close_enrollment"("p_enrollment_id" "uuid", "p_to_status" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_enrollment public.enrollments%rowtype;
  v_to_status text := nullif(trim(p_to_status), '');
  v_reason text := nullif(trim(p_reason), '');
  v_movement_id uuid;
begin
  if v_to_status is null or v_to_status not in ('ended', 'cancelled', 'archived') then
    raise exception 'Encerramento permite somente ended, cancelled ou archived.' using errcode = '22023';
  end if;

  if v_reason is null then
    raise exception 'Motivo do encerramento e obrigatorio.' using errcode = '22023';
  end if;

  select * into v_enrollment
  from public.enrollments
  where id = p_enrollment_id
  for update;

  if v_enrollment.id is null then
    raise exception 'Matricula nao encontrada.' using errcode = '22023';
  end if;

  if not public.secretaria_can_manage_school(v_enrollment.school_id) then
    raise exception 'Perfil institucional sem permissao para movimentar esta matricula.' using errcode = '42501';
  end if;

  update public.enrollments
  set status = v_to_status,
      ended_at = coalesce(ended_at, now())
  where id = v_enrollment.id;

  insert into public.enrollment_movements (
    school_id,
    student_id,
    enrollment_id,
    movement_type,
    from_class_id,
    to_class_id,
    from_status,
    to_status,
    reason,
    performed_by
  )
  values (
    v_enrollment.school_id,
    v_enrollment.student_id,
    v_enrollment.id,
    'enrollment_closed',
    v_enrollment.class_id,
    v_enrollment.class_id,
    v_enrollment.status,
    v_to_status,
    v_reason,
    auth.uid()
  )
  returning id into v_movement_id;

  return jsonb_build_object(
    'movement_id', v_movement_id,
    'enrollment_id', v_enrollment.id,
    'student_id', v_enrollment.student_id,
    'from_status', v_enrollment.status,
    'to_status', v_to_status,
    'performed_by', auth.uid(),
    'created_at', now()
  );
end;
$$;


ALTER FUNCTION "public"."secretaria_close_enrollment"("p_enrollment_id" "uuid", "p_to_status" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."secretaria_create_class"("p_school_id" "uuid", "p_nome" "text", "p_school_year" "text", "p_status" "text" DEFAULT 'active'::"text", "p_age_group" "text" DEFAULT NULL::"text", "p_turno" "text" DEFAULT NULL::"text", "p_ano_escolar" "text" DEFAULT NULL::"text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_class_id uuid;
  v_status text := coalesce(nullif(trim(p_status), ''), 'active');
  v_nome text := nullif(trim(p_nome), '');
  v_school_year text := nullif(trim(p_school_year), '');
begin
  if v_nome is null or v_school_year is null then
    raise exception 'Nome da turma e ano letivo sao obrigatorios.' using errcode = '22023';
  end if;

  if v_status not in ('active', 'inactive', 'archived') then
    raise exception 'Status de turma incompativel com o schema.' using errcode = '22023';
  end if;

  if not public.secretaria_can_manage_school(p_school_id) then
    raise exception 'Perfil institucional sem permissao para criar turma nesta escola.' using errcode = '42501';
  end if;

  if exists (
    select 1
    from public.classes c
    where c.school_id = p_school_id
      and lower(trim(c.nome)) = lower(v_nome)
      and coalesce(c.school_year, '') = v_school_year
      and c.status <> 'archived'
  ) then
    raise exception 'Turma semelhante ja existe nesta escola e ano letivo.' using errcode = '23505';
  end if;

  insert into public.classes (
    school_id,
    nome,
    school_year,
    status,
    age_group,
    turno,
    ano_escolar
  )
  values (
    p_school_id,
    v_nome,
    v_school_year,
    v_status,
    nullif(trim(p_age_group), ''),
    nullif(trim(p_turno), ''),
    nullif(trim(p_ano_escolar), '')
  )
  returning id into v_class_id;

  return jsonb_build_object(
    'class_id', v_class_id,
    'school_id', p_school_id,
    'status', v_status,
    'created_by', auth.uid(),
    'created_at', now()
  );
end;
$$;


ALTER FUNCTION "public"."secretaria_create_class"("p_school_id" "uuid", "p_nome" "text", "p_school_year" "text", "p_status" "text", "p_age_group" "text", "p_turno" "text", "p_ano_escolar" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."secretaria_create_enrollment_import_batch"("p_school_id" "uuid", "p_file_name" "text", "p_rows" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_batch_id uuid; v_row jsonb; v_row_number integer := 0; v_success integer := 0; v_failed integer := 0; v_result jsonb; v_row_id uuid;
BEGIN
  IF NOT public.secretaria_can_manage_school(p_school_id) THEN RAISE EXCEPTION 'Perfil sem permissao para importar matriculas.' USING errcode = '42501'; END IF;
  IF jsonb_typeof(p_rows) <> 'array' THEN RAISE EXCEPTION 'Linhas CSV devem chegar como array JSON.' USING errcode = '22023'; END IF;
  INSERT INTO public.academic_import_batches (school_id, file_name, status, summary, created_by) VALUES (p_school_id, NULLIF(btrim(p_file_name), ''), 'processing', jsonb_build_object('total', jsonb_array_length(p_rows)), auth.uid()) RETURNING id INTO v_batch_id;
  FOR v_row IN SELECT * FROM jsonb_array_elements(p_rows) LOOP
    v_row_number := v_row_number + 1;
    INSERT INTO public.academic_import_rows (batch_id, school_id, row_number, raw_data, status) VALUES (v_batch_id, p_school_id, v_row_number, v_row, 'pending') RETURNING id INTO v_row_id;
    BEGIN
      IF NOT EXISTS (SELECT 1 FROM public.classes c WHERE c.id = (v_row ->> 'class_id')::uuid AND c.school_id = p_school_id AND c.status = 'active') THEN RAISE EXCEPTION 'Turma ativa da escola nao encontrada.' USING errcode = '22023'; END IF;
      v_result := public.secretaria_create_student_enrollment(v_row ->> 'nome', NULLIF(v_row ->> 'data_nascimento', '')::date, (v_row ->> 'class_id')::uuid, v_row ->> 'school_year', COALESCE(NULLIF(v_row ->> 'status', ''), 'active'));
      UPDATE public.academic_import_rows SET status = 'completed', target_student_id = (v_result ->> 'student_id')::uuid, target_enrollment_id = (v_result ->> 'enrollment_id')::uuid, movement_id = (v_result ->> 'movement_id')::uuid WHERE id = v_row_id;
      v_success := v_success + 1;
    EXCEPTION WHEN OTHERS THEN
      UPDATE public.academic_import_rows SET status = 'failed', error_message = SQLERRM WHERE id = v_row_id;
      v_failed := v_failed + 1;
    END;
  END LOOP;
  UPDATE public.academic_import_batches SET status = CASE WHEN v_failed = 0 THEN 'completed' WHEN v_success = 0 THEN 'failed' ELSE 'completed_with_errors' END, summary = jsonb_build_object('total', v_row_number, 'completed', v_success, 'failed', v_failed), processed_at = now() WHERE id = v_batch_id;
  RETURN jsonb_build_object('batch_id', v_batch_id, 'total', v_row_number, 'completed', v_success, 'failed', v_failed, 'status', CASE WHEN v_failed = 0 THEN 'completed' WHEN v_success = 0 THEN 'failed' ELSE 'completed_with_errors' END);
END;
$$;


ALTER FUNCTION "public"."secretaria_create_enrollment_import_batch"("p_school_id" "uuid", "p_file_name" "text", "p_rows" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."secretaria_create_guardian_link"("p_student_id" "uuid", "p_full_name" "text", "p_relationship" "text", "p_phone" "text" DEFAULT NULL::"text", "p_email" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT 'active'::"text", "p_is_primary" boolean DEFAULT false, "p_guardian_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_student public.students%rowtype;
  v_enrollment public.enrollments%rowtype;
  v_guardian public.guardians%rowtype;
  v_link_id uuid;
  v_relationship text := coalesce(nullif(trim(p_relationship), ''), 'responsavel');
  v_status text := coalesce(nullif(trim(p_status), ''), 'active');
  v_name text := nullif(trim(p_full_name), '');
  v_email text := nullif(lower(trim(p_email)), '');
  v_phone text := nullif(trim(p_phone), '');
begin
  if v_status <> 'active' then
    raise exception 'Nesta missao somente status active esta autorizado.'
      using errcode = '22023';
  end if;

  if v_relationship not in ('responsavel', 'mae', 'pai', 'avo', 'tutor', 'outro') then
    raise exception 'Tipo de vinculo invalido.'
      using errcode = '22023';
  end if;

  select *
    into v_student
  from public.students s
  where s.id = p_student_id
    and coalesce(s.status, 'active') = 'active'
  limit 1;

  if v_student.id is null then
    raise exception 'Aluno ativo nao encontrado.'
      using errcode = '22023';
  end if;

  select *
    into v_enrollment
  from public.enrollments e
  where e.student_id = v_student.id
    and e.status = 'active'
    and e.ended_at is null
  order by e.enrolled_at desc
  limit 1;

  if v_enrollment.id is null then
    raise exception 'Matricula ativa do aluno nao encontrada.'
      using errcode = '22023';
  end if;

  if not (
    public.is_platform_admin()
    or exists (
      select 1
      from public.school_memberships sm
      where sm.school_id = v_enrollment.school_id
        and sm.profile_id = auth.uid()
        and sm.status = 'active'
        and sm.membership_role in ('gestor', 'coordenador', 'direcao', 'secretaria', 'admin', 'admin_ti')
        and sm.started_at <= now()
        and (sm.ended_at is null or sm.ended_at > now())
    )
  ) then
    raise exception 'Perfil institucional sem permissao para vincular responsavel nesta escola.'
      using errcode = '42501';
  end if;

  if p_guardian_id is not null then
    select *
      into v_guardian
    from public.guardians g
    where g.id = p_guardian_id
      and g.school_id = v_enrollment.school_id
      and g.status = 'active'
    limit 1;

    if v_guardian.id is null then
      raise exception 'Responsavel existente nao encontrado nesta escola.'
        using errcode = '22023';
    end if;
  else
    if v_name is null then
      raise exception 'Nome completo do responsavel e obrigatorio.'
        using errcode = '22023';
    end if;

    select *
      into v_guardian
    from public.guardians g
    where g.school_id = v_enrollment.school_id
      and g.status = 'active'
      and (
        lower(trim(g.full_name)) = lower(v_name)
        or (v_email is not null and lower(g.email) = v_email)
        or (v_phone is not null and g.phone = v_phone)
      )
    order by
      case
        when v_email is not null and lower(g.email) = v_email then 1
        when v_phone is not null and g.phone = v_phone then 2
        else 3
      end
    limit 1;

    if v_guardian.id is null then
      insert into public.guardians (
        school_id,
        full_name,
        email,
        phone,
        status,
        access_status
      )
      values (
        v_enrollment.school_id,
        v_name,
        v_email,
        v_phone,
        v_status,
        'not_configured'
      )
      returning * into v_guardian;
    end if;
  end if;

  insert into public.student_guardian_links (
    student_id,
    guardian_id,
    relationship,
    is_primary,
    status
  )
  values (
    v_student.id,
    v_guardian.id,
    v_relationship,
    p_is_primary,
    'active'
  )
  on conflict (student_id, guardian_id, relationship)
    where status = 'active'
  do update set
    is_primary = excluded.is_primary,
    updated_at = now()
  returning id into v_link_id;

  return jsonb_build_object(
    'guardian_id', v_guardian.id,
    'link_id', v_link_id,
    'student_id', v_student.id,
    'school_id', v_enrollment.school_id,
    'relationship', v_relationship,
    'is_primary', p_is_primary,
    'access_status', v_guardian.access_status,
    'created_by', auth.uid(),
    'created_at', now()
  );
end;
$$;


ALTER FUNCTION "public"."secretaria_create_guardian_link"("p_student_id" "uuid", "p_full_name" "text", "p_relationship" "text", "p_phone" "text", "p_email" "text", "p_status" "text", "p_is_primary" boolean, "p_guardian_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."secretaria_create_student_enrollment"("p_nome" "text", "p_data_nascimento" "date", "p_class_id" "uuid", "p_school_year" "text", "p_status" "text" DEFAULT 'active'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_class public.classes%rowtype;
  v_student_id uuid;
  v_enrollment_id uuid;
  v_status text := coalesce(nullif(trim(p_status), ''), 'active');
  v_school_year text := nullif(trim(p_school_year), '');
begin
  if not (
    public.is_platform_admin()
    or exists (
      select 1
      from public.school_memberships sm
      where sm.profile_id = auth.uid()
        and sm.status = 'active'
        and sm.membership_role in ('gestor', 'coordenador', 'direcao', 'secretaria', 'admin', 'admin_ti')
        and sm.started_at <= now()
        and (sm.ended_at is null or sm.ended_at > now())
    )
  ) then
    raise exception 'Perfil institucional sem permissao para cadastrar aluno.'
      using errcode = '42501';
  end if;

  if nullif(trim(p_nome), '') is null then
    raise exception 'Nome completo do aluno e obrigatorio.'
      using errcode = '22023';
  end if;

  if v_status <> 'active' then
    raise exception 'Nesta missao somente status active esta autorizado.'
      using errcode = '22023';
  end if;

  select *
    into v_class
  from public.classes c
  where c.id = p_class_id
    and c.status = 'active'
  limit 1;

  if v_class.id is null then
    raise exception 'Turma ativa nao encontrada.'
      using errcode = '22023';
  end if;

  if v_class.school_year is not null and v_school_year is distinct from v_class.school_year then
    raise exception 'Ano letivo inconsistente com a turma selecionada.'
      using errcode = '22023';
  end if;

  if v_school_year is null then
    v_school_year := coalesce(v_class.school_year, '2026');
  end if;

  if not (
    public.is_platform_admin()
    or exists (
      select 1
      from public.school_memberships sm
      where sm.school_id = v_class.school_id
        and sm.profile_id = auth.uid()
        and sm.status = 'active'
        and sm.membership_role in ('gestor', 'coordenador', 'direcao', 'secretaria', 'admin', 'admin_ti')
        and sm.started_at <= now()
        and (sm.ended_at is null or sm.ended_at > now())
    )
  ) then
    raise exception 'Perfil institucional sem permissao para esta escola.'
      using errcode = '42501';
  end if;

  if exists (
    select 1
    from public.students s
    where s.school_id = v_class.school_id
      and lower(trim(s.nome)) = lower(trim(p_nome))
      and (
        p_data_nascimento is null
        or s.data_nascimento is null
        or s.data_nascimento = p_data_nascimento
      )
      and coalesce(s.status, 'active') = 'active'
  ) then
    raise exception 'Possivel duplicidade: ja existe aluno ativo semelhante nesta escola.'
      using errcode = '23505';
  end if;

  insert into public.students (
    nome,
    data_nascimento,
    school_id,
    class_id,
    turma,
    status
  )
  values (
    trim(p_nome),
    p_data_nascimento,
    v_class.school_id,
    v_class.id,
    v_class.nome,
    v_status
  )
  returning id into v_student_id;

  insert into public.enrollments (
    student_id,
    class_id,
    school_id,
    school_year,
    status
  )
  values (
    v_student_id,
    v_class.id,
    v_class.school_id,
    v_school_year,
    'active'
  )
  returning id into v_enrollment_id;

  return jsonb_build_object(
    'student_id', v_student_id,
    'enrollment_id', v_enrollment_id,
    'school_id', v_class.school_id,
    'class_id', v_class.id,
    'school_year', v_school_year,
    'status', v_status,
    'created_by', auth.uid(),
    'created_at', now()
  );
end;
$$;


ALTER FUNCTION "public"."secretaria_create_student_enrollment"("p_nome" "text", "p_data_nascimento" "date", "p_class_id" "uuid", "p_school_year" "text", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."secretaria_create_teacher"("p_school_id" "uuid", "p_full_name" "text", "p_status" "text" DEFAULT 'active'::"text", "p_disciplina" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_teacher_id uuid;
  v_full_name text := nullif(trim(p_full_name), '');
  v_status text := coalesce(nullif(trim(p_status), ''), 'active');
  v_disciplina text := nullif(trim(p_disciplina), '');
begin
  if v_full_name is null then
    raise exception 'Nome completo do professor e obrigatorio.' using errcode = '22023';
  end if;

  if v_status not in ('active', 'inactive', 'archived') then
    raise exception 'Status de professor incompativel com o schema.' using errcode = '22023';
  end if;

  if not exists (
    select 1 from public.schools s where s.id = p_school_id and s.status <> 'archived'
  ) then
    raise exception 'Escola nao encontrada.' using errcode = '22023';
  end if;

  if not public.secretaria_can_manage_school(p_school_id) and not public.is_platform_admin() then
    raise exception 'Perfil institucional sem permissao para criar professor nesta escola.' using errcode = '42501';
  end if;

  select t.id
    into v_teacher_id
  from public.teachers t
  left join public.profiles p on p.id = t.profile_id
  where t.school_id = p_school_id
    and lower(coalesce(nullif(btrim(t.full_name), ''), btrim(p.display_name))) = lower(v_full_name)
    and t.status <> 'archived'
  order by case when t.status = 'active' then 0 else 1 end, t.created_at
  limit 1;

  if v_teacher_id is null then
    insert into public.teachers (
      school_id,
      full_name,
      email,
      profile_id,
      disciplina,
      status
    )
    values (
      p_school_id,
      v_full_name,
      null,
      null,
      v_disciplina,
      v_status
    )
    returning id into v_teacher_id;
  else
    update public.teachers
       set full_name = v_full_name,
           disciplina = v_disciplina,
           status = v_status,
           updated_at = now()
     where id = v_teacher_id;
  end if;

  return jsonb_build_object(
    'teacher_id', v_teacher_id,
    'profile_id', null,
    'membership_id', null,
    'school_id', p_school_id,
    'status', v_status,
    'created_by', auth.uid(),
    'created_at', now()
  );
end;
$$;


ALTER FUNCTION "public"."secretaria_create_teacher"("p_school_id" "uuid", "p_full_name" "text", "p_status" "text", "p_disciplina" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."secretaria_delete_communication"("p_communication_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_author uuid := auth.uid();
  v_comm public.communications%rowtype;
  v_from_status text;
begin
  if v_author is null then
    raise exception 'Usuario autenticado obrigatorio.' using errcode = '42501';
  end if;

  select * into v_comm
  from public.communications
  where id = p_communication_id
  for update;

  if v_comm.id is null then
    raise exception 'Comunicado nao encontrado.' using errcode = '22023';
  end if;

  if v_comm.status = 'deleted' then
    return jsonb_build_object(
      'communication_id', v_comm.id,
      'deleted', true,
      'changed', false
    );
  end if;

  if not (
    public.secretaria_can_manage_school(v_comm.school_id)
    or (
      v_comm.author_profile_id = v_author
      and public.communication_teacher_can_target(v_comm.school_id, v_comm.class_id, v_comm.student_id, v_comm.audience_type)
    )
  ) then
    raise exception 'Usuario sem permissao para excluir este comunicado.' using errcode = '42501';
  end if;

  v_from_status := v_comm.status;

  update public.communications
  set status = 'deleted',
      deleted_at = now(),
      deleted_by = v_author
  where id = v_comm.id
  returning * into v_comm;

  insert into public.communication_events (communication_id, event_type, from_status, to_status, performed_by)
  values (v_comm.id, 'deleted', v_from_status, 'deleted', v_author);

  return jsonb_build_object(
    'communication_id', v_comm.id,
    'deleted', true,
    'changed', true
  );
end;
$$;


ALTER FUNCTION "public"."secretaria_delete_communication"("p_communication_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."secretaria_end_teacher_class_membership"("p_membership_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_membership public.class_teacher_memberships%rowtype;
  v_class public.classes%rowtype;
  v_movement_id uuid;
  v_reason text := nullif(trim(p_reason), '');
begin
  if v_reason is null then
    raise exception 'Motivo do encerramento e obrigatorio.' using errcode = '22023';
  end if;

  select * into v_membership
  from public.class_teacher_memberships
  where id = p_membership_id
  for update;

  if v_membership.id is null then
    raise exception 'Vinculo professor-turma nao encontrado.' using errcode = '22023';
  end if;

  select * into v_class
  from public.classes
  where id = v_membership.class_id
  for update;

  if v_class.id is null then
    raise exception 'Turma do vinculo nao encontrada.' using errcode = '22023';
  end if;

  if not public.secretaria_can_manage_school(v_class.school_id) then
    raise exception 'Perfil institucional sem permissao para encerrar vinculo nesta escola.' using errcode = '42501';
  end if;

  update public.class_teacher_memberships
  set status = 'ended',
      ended_at = coalesce(ended_at, now())
  where id = v_membership.id;

  if v_class.teacher_id = v_membership.teacher_id and not exists (
    select 1
    from public.class_teacher_memberships ctm
    where ctm.class_id = v_class.id
      and ctm.teacher_id <> v_membership.teacher_id
      and ctm.role = 'principal'
      and ctm.status = 'active'
      and ctm.ended_at is null
  ) then
    update public.classes
    set teacher_id = null
    where id = v_class.id;
  end if;

  insert into public.teacher_class_movements (
    school_id,
    teacher_id,
    class_id,
    membership_id,
    movement_type,
    from_status,
    to_status,
    role,
    reason,
    performed_by
  )
  values (
    v_class.school_id,
    v_membership.teacher_id,
    v_class.id,
    v_membership.id,
    'teacher_unlinked',
    v_membership.status,
    'ended',
    v_membership.role,
    v_reason,
    auth.uid()
  )
  returning id into v_movement_id;

  return jsonb_build_object(
    'movement_id', v_movement_id,
    'membership_id', v_membership.id,
    'teacher_id', v_membership.teacher_id,
    'class_id', v_class.id,
    'from_status', v_membership.status,
    'to_status', 'ended',
    'performed_by', auth.uid(),
    'created_at', now()
  );
end;
$$;


ALTER FUNCTION "public"."secretaria_end_teacher_class_membership"("p_membership_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."secretaria_get_assessment_pedagogical_intelligence"("p_school_id" "uuid", "p_date_from" "date" DEFAULT NULL::"date", "p_date_to" "date" DEFAULT NULL::"date", "p_component" "text" DEFAULT NULL::"text", "p_school_year" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
  select public.avalia_plus_get_pedagogical_intelligence('school', null, null, p_school_id, null, null, p_date_from, p_date_to, p_component, p_school_year, null);
$$;


ALTER FUNCTION "public"."secretaria_get_assessment_pedagogical_intelligence"("p_school_id" "uuid", "p_date_from" "date", "p_date_to" "date", "p_component" "text", "p_school_year" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."secretaria_get_assessment_school_results"("p_school_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_payload jsonb;
begin
  if auth.uid() is null then
    raise exception 'Usuario autenticado obrigatorio.' using errcode = '42501';
  end if;

  if p_school_id is null then
    raise exception 'school_id obrigatorio.' using errcode = '22023';
  end if;

  if not (public.is_platform_admin() or public.secretaria_can_manage_school(p_school_id)) then
    raise exception 'Acesso negado aos resultados desta escola.' using errcode = '42501';
  end if;

  with assignments as (
    select
      aa.*,
      a.title as assessment_title,
      a.component as component,
      c.nome as class_name
    from public.assessment_assignments aa
    join public.assessments a on a.id = aa.assessment_id
    join public.classes c on c.id = aa.class_id
    where aa.school_id = p_school_id
      and aa.status in ('published', 'closed', 'archived')
  ),
  assignment_rows as (
    select
      aa.id,
      aa.assessment_id,
      aa.assessment_title,
      aa.component,
      aa.class_id,
      aa.class_name,
      aa.created_at,
      coalesce(roster.assigned_students, 0) as assigned_students,
      coalesce(started.started_students, 0) as started_students,
      coalesce(completed.completed_students, 0) as completed_students,
      coalesce(results.average_percentage, 0) as average_percentage
    from assignments aa
    left join lateral (
      select count(distinct st.id)::integer as assigned_students
      from public.enrollments e
      join public.students st on st.id = e.student_id and coalesce(st.status, 'active') = 'active'
      where e.class_id = aa.class_id
        and e.school_id = aa.school_id
        and e.status = 'active'
        and e.enrolled_at <= now()
        and (e.ended_at is null or e.ended_at > now())
        and (aa.target_type = 'class' or st.id = aa.student_id)
    ) roster on true
    left join lateral (
      select count(distinct at.student_id)::integer as started_students
      from public.assessment_attempts at
      where at.assignment_id = aa.id
    ) started on true
    left join lateral (
      select count(distinct ar.student_id)::integer as completed_students
      from public.assessment_results ar
      where ar.assignment_id = aa.id
    ) completed on true
    left join lateral (
      select round(avg(ar.score_percentage)::numeric, 2) as average_percentage
      from public.assessment_results ar
      where ar.assignment_id = aa.id
    ) results on true
  ),
  summary as (
    select
      count(distinct class_id)::integer as classes_participating,
      sum(assigned_students)::integer as assigned_students,
      sum(started_students)::integer as started_students,
      sum(completed_students)::integer as completed_students,
      coalesce(round(avg(nullif(average_percentage, 0))::numeric, 2), 0) as average_percentage
    from assignment_rows
  ),
  performance_distribution as (
    select jsonb_build_object(
      'attention', count(*) filter (where score_percentage < 50),
      'developing', count(*) filter (where score_percentage >= 50 and score_percentage < 70),
      'adequate', count(*) filter (where score_percentage >= 70)
    ) as data
    from public.assessment_results
    where school_id = p_school_id
  ),
  skills as (
    select coalesce(jsonb_agg(
      jsonb_build_object(
        'bncc_skill', bncc_skill,
        'questions', question_count,
        'responses', responses,
        'correct', correct,
        'incorrect', incorrect,
        'performance_percentage', case when responses > 0 then round((correct::numeric / responses) * 100, 2) else 0 end
      )
      order by case when responses > 0 then (correct::numeric / responses) else 0 end asc, bncc_skill
    ), '[]'::jsonb) as data
    from (
      select
        coalesce(nullif(btrim(qi.bncc_skill), ''), 'SEM_HABILIDADE') as bncc_skill,
        count(distinct aq.question_id)::integer as question_count,
        count(ar.id)::integer as responses,
        count(ar.id) filter (where ar.is_correct is true)::integer as correct,
        count(ar.id) filter (where coalesce(ar.is_correct, false) is false)::integer as incorrect
      from assignments aa
      join public.assessment_questions aq on aq.assessment_id = aa.assessment_id
      join public.question_items qi on qi.id = aq.question_id
      left join public.assessment_attempts at
        on at.assignment_id = aa.id
       and at.status in ('submitted', 'graded')
      left join public.assessment_responses ar
        on ar.attempt_id = at.id
       and ar.question_id = aq.question_id
      group by coalesce(nullif(btrim(qi.bncc_skill), ''), 'SEM_HABILIDADE')
    ) skill_rows
  ),
  assignments_payload as (
    select coalesce(jsonb_agg(
      jsonb_build_object(
        'assignment_id', id,
        'assessment_id', assessment_id,
        'assessment_title', assessment_title,
        'component', component,
        'class_id', class_id,
        'class_name', class_name,
        'assigned_students', assigned_students,
        'started_students', started_students,
        'completed_students', completed_students,
        'participation_percentage', case when assigned_students > 0 then round((completed_students::numeric / assigned_students) * 100, 2) else 0 end,
        'average_percentage', average_percentage
      )
      order by created_at desc
    ), '[]'::jsonb) as data
    from assignment_rows
  )
  select jsonb_build_object(
    'school_id', p_school_id,
    'summary', jsonb_build_object(
      'classes_participating', coalesce(sm.classes_participating, 0),
      'assigned_students', coalesce(sm.assigned_students, 0),
      'started_students', coalesce(sm.started_students, 0),
      'completed_students', coalesce(sm.completed_students, 0),
      'participation_percentage', case when coalesce(sm.assigned_students, 0) > 0 then round((coalesce(sm.completed_students, 0)::numeric / sm.assigned_students) * 100, 2) else 0 end,
      'average_percentage', coalesce(sm.average_percentage, 0)
    ),
    'distribution', pd.data,
    'skills', sk.data,
    'assignments', ap.data
  )
  into v_payload
  from summary sm
  cross join performance_distribution pd
  cross join skills sk
  cross join assignments_payload ap;

  return coalesce(v_payload, jsonb_build_object(
    'school_id', p_school_id,
    'summary', jsonb_build_object(),
    'distribution', jsonb_build_object(),
    'skills', '[]'::jsonb,
    'assignments', '[]'::jsonb
  ));
end;
$$;


ALTER FUNCTION "public"."secretaria_get_assessment_school_results"("p_school_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."secretaria_get_class_diary_period_summary"("p_class_id" "uuid", "p_from" "date", "p_to" "date") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  WITH ctx AS (
    SELECT
      cl.id AS class_id,
      cl.school_id,
      cl.nome::text AS class_name,
      sc.nome::text AS school_name
    FROM public.classes cl
    JOIN public.schools sc ON sc.id = cl.school_id
    WHERE cl.id = p_class_id
      AND (
        public.is_platform_admin()
        OR public.secretaria_can_manage_school(cl.school_id)
      )
    LIMIT 1
  ),
  diary AS (
    SELECT cde.*
    FROM public.class_diary_entries cde
    JOIN ctx ON ctx.class_id = cde.class_id AND ctx.school_id = cde.school_id
    WHERE cde.status <> 'deleted'
      AND cde.entry_date BETWEEN p_from AND p_to
  ),
  attendance AS (
    SELECT
      count(*)::bigint AS total,
      count(*) FILTER (WHERE ar.status = 'present')::bigint AS present,
      count(*) FILTER (WHERE ar.status = 'absent')::bigint AS absent,
      count(*) FILTER (WHERE ar.status = 'justified')::bigint AS justified
    FROM public.attendance_records ar
    JOIN ctx ON ctx.school_id = ar.school_id AND ctx.class_id = ar.class_id
    WHERE ar.attendance_date BETWEEN p_from AND p_to
  ),
  plans AS (
    SELECT tp.*
    FROM public.teacher_plans tp
    JOIN ctx ON ctx.school_id = tp.school_id AND ctx.class_id = tp.class_id
    WHERE tp.status <> 'archived'
      AND tp.plan_date BETWEEN p_from AND p_to
  ),
  published AS (
    SELECT cce.*
    FROM public.class_calendar_entries cce
    JOIN ctx ON ctx.school_id = cce.school_id AND ctx.class_id = cce.class_id
    WHERE cce.status = 'published'
      AND cce.entry_date BETWEEN p_from AND p_to
  ),
  links AS (
    SELECT count(*)::bigint AS total
    FROM public.class_diary_activity_links cdl
    JOIN diary ON diary.id = cdl.diary_entry_id
  ),
  notes AS (
    SELECT cdn.*, st.nome AS student_name
    FROM public.class_diary_student_notes cdn
    JOIN ctx ON ctx.school_id = cdn.school_id AND ctx.class_id = cdn.class_id
    JOIN public.students st ON st.id = cdn.student_id
    WHERE cdn.status <> 'deleted'
      AND cdn.note_date BETWEEN p_from AND p_to
  )
  SELECT CASE
    WHEN NOT EXISTS (SELECT 1 FROM ctx) THEN
      jsonb_build_object('error', 'Secretaria sem permissao para consolidar esta turma.')
    ELSE
      jsonb_build_object(
        'class_id', (SELECT class_id FROM ctx),
        'school_id', (SELECT school_id FROM ctx),
        'class_name', (SELECT class_name FROM ctx),
        'school_name', (SELECT school_name FROM ctx),
        'from', p_from,
        'to', p_to,
        'registered_classes', (SELECT count(*) FROM diary),
        'attendance_total', coalesce((SELECT total FROM attendance), 0),
        'attendance_present', coalesce((SELECT present FROM attendance), 0),
        'attendance_absent', coalesce((SELECT absent FROM attendance), 0),
        'attendance_justified', coalesce((SELECT justified FROM attendance), 0),
        'planned_count', (SELECT count(*) FROM plans),
        'published_count', (SELECT count(*) FROM published),
        'activity_link_count', coalesce((SELECT total FROM links), 0),
        'individual_note_count', (SELECT count(*) FROM notes),
        'diary_entries', coalesce((SELECT jsonb_agg(jsonb_build_object(
          'id', id,
          'entry_date', entry_date,
          'title', title,
          'status', status,
          'taught_content', taught_content,
          'pedagogical_notes', pedagogical_notes
        ) ORDER BY entry_date DESC, updated_at DESC) FROM diary), '[]'::jsonb),
        'planned_items', coalesce((SELECT jsonb_agg(jsonb_build_object(
          'id', id,
          'plan_date', plan_date,
          'title', title,
          'resource_type', resource_type,
          'status', status
        ) ORDER BY plan_date ASC, created_at ASC) FROM plans), '[]'::jsonb),
        'published_items', coalesce((SELECT jsonb_agg(jsonb_build_object(
          'id', id,
          'entry_date', entry_date,
          'title', title,
          'entry_type', entry_type,
          'status', status
        ) ORDER BY entry_date ASC, created_at ASC) FROM published), '[]'::jsonb),
        'individual_notes', coalesce((SELECT jsonb_agg(jsonb_build_object(
          'id', id,
          'note_date', note_date,
          'student_id', student_id,
          'student_name', student_name,
          'note_text', note_text,
          'diary_entry_id', diary_entry_id
        ) ORDER BY note_date DESC, created_at DESC) FROM notes), '[]'::jsonb)
      )
    END;
$$;


ALTER FUNCTION "public"."secretaria_get_class_diary_period_summary"("p_class_id" "uuid", "p_from" "date", "p_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."secretaria_get_recomposition_overview"("p_school_id" "uuid", "p_date_from" "date" DEFAULT NULL::"date", "p_date_to" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_from date := coalesce(p_date_from, current_date - 89);
  v_to date := coalesce(p_date_to, current_date);
  v_payload jsonb;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if p_school_id is null then raise exception 'SCHOOL_REQUIRED'; end if;
  if not (public.is_platform_admin() or public.secretaria_can_manage_school(p_school_id)) then raise exception 'RECOMPOSITION_SCHOOL_FORBIDDEN'; end if;

  with plans as (
    select p.*, c.nome as class_name from public.recomposition_plans p join public.classes c on c.id = p.class_id
    where p.school_id = p_school_id and p.created_at::date between v_from and v_to
  ), skills as (
    select target_skill, count(*)::integer as plans, count(distinct class_id)::integer as classes from plans where target_skill is not null group by target_skill
  )
  select jsonb_build_object(
    'period', jsonb_build_object('date_from', v_from, 'date_to', v_to),
    'summary', jsonb_build_object('plans', (select count(*) from plans), 'active_plans', (select count(*) from plans where status in ('active', 'in_progress')), 'completed_plans', (select count(*) from plans where status = 'completed'), 'students', (select count(distinct ps.student_id) from public.recomposition_plan_students ps join plans p on p.id = ps.plan_id where ps.status <> 'removed'), 'classes', (select count(distinct class_id) from plans)),
    'skills', coalesce((select jsonb_agg(to_jsonb(skills) order by plans desc, target_skill) from skills), '[]'::jsonb),
    'plans', coalesce((select jsonb_agg(jsonb_build_object('id', id, 'title', title, 'class_id', class_id, 'class_name', class_name, 'target_type', target_type, 'target_skill', target_skill, 'status', status, 'created_at', created_at) order by created_at desc) from plans), '[]'::jsonb)
  ) into v_payload;
  return v_payload;
end;
$$;


ALTER FUNCTION "public"."secretaria_get_recomposition_overview"("p_school_id" "uuid", "p_date_from" "date", "p_date_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."secretaria_link_teacher_to_class"("p_teacher_id" "uuid", "p_class_id" "uuid", "p_role" "text" DEFAULT 'principal'::"text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_teacher public.teachers%rowtype;
  v_class public.classes%rowtype;
  v_role text := coalesce(nullif(trim(p_role), ''), 'principal');
  v_reason text := nullif(trim(p_reason), '');
  v_membership_id uuid;
  v_movement_id uuid;
begin
  if v_reason is null then
    raise exception 'Motivo do vinculo e obrigatorio.' using errcode = '22023';
  end if;

  if v_role not in ('principal', 'auxiliar', 'especialista', 'substituto') then
    raise exception 'Papel do professor incompativel com o schema.' using errcode = '22023';
  end if;

  select * into v_teacher from public.teachers where id = p_teacher_id and status = 'active' limit 1;
  select * into v_class from public.classes where id = p_class_id and status = 'active' limit 1;

  if v_teacher.id is null or v_class.id is null then
    raise exception 'Professor ou turma ativa nao encontrados.' using errcode = '22023';
  end if;

  if v_teacher.school_id <> v_class.school_id then
    raise exception 'Professor e turma devem pertencer a mesma escola.' using errcode = '22023';
  end if;

  if not public.secretaria_can_manage_school(v_class.school_id) then
    raise exception 'Perfil institucional sem permissao para vincular professor nesta escola.' using errcode = '42501';
  end if;

  select id into v_membership_id
  from public.class_teacher_memberships
  where class_id = v_class.id
    and teacher_id = v_teacher.id
    and role = v_role
    and status = 'active'
    and ended_at is null
  limit 1;

  if v_membership_id is null then
    insert into public.class_teacher_memberships (
      class_id,
      teacher_id,
      role,
      status,
      started_at
    )
    values (
      v_class.id,
      v_teacher.id,
      v_role,
      'active',
      now()
    )
    returning id into v_membership_id;
  end if;

  if v_role = 'principal' then
    update public.classes
    set teacher_id = v_teacher.id
    where id = v_class.id;
  end if;

  insert into public.teacher_class_movements (
    school_id,
    teacher_id,
    class_id,
    membership_id,
    movement_type,
    to_status,
    role,
    reason,
    performed_by
  )
  values (
    v_class.school_id,
    v_teacher.id,
    v_class.id,
    v_membership_id,
    'teacher_linked',
    'active',
    v_role,
    v_reason,
    auth.uid()
  )
  returning id into v_movement_id;

  return jsonb_build_object(
    'movement_id', v_movement_id,
    'membership_id', v_membership_id,
    'teacher_id', v_teacher.id,
    'class_id', v_class.id,
    'to_status', 'active',
    'performed_by', auth.uid(),
    'created_at', now()
  );
end;
$$;


ALTER FUNCTION "public"."secretaria_link_teacher_to_class"("p_teacher_id" "uuid", "p_class_id" "uuid", "p_role" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."secretaria_list_academic_core"("p_school_id" "uuid" DEFAULT NULL::"uuid", "p_school_year" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_school_ids uuid[];
BEGIN
  SELECT array_agg(s.id ORDER BY s.nome) INTO v_school_ids
  FROM public.schools s
  WHERE (p_school_id IS NULL OR s.id = p_school_id)
    AND public.secretaria_can_manage_school(s.id);
  IF coalesce(array_length(v_school_ids, 1), 0) = 0 THEN
    RETURN jsonb_build_object('academic_years','[]'::jsonb,'academic_terms','[]'::jsonb,'school_days','[]'::jsonb,'class_subjects','[]'::jsonb,'class_schedule_slots','[]'::jsonb,'import_batches','[]'::jsonb,'import_rows','[]'::jsonb);
  END IF;
  RETURN jsonb_build_object(
    'academic_years', COALESCE((SELECT jsonb_agg(to_jsonb(ay) ORDER BY ay.school_year DESC, ay.start_date) FROM public.academic_years ay WHERE ay.school_id = ANY(v_school_ids) AND (p_school_year IS NULL OR ay.school_year = p_school_year)), '[]'::jsonb),
    'academic_terms', COALESCE((SELECT jsonb_agg(to_jsonb(atm) ORDER BY atm.start_date, atm.term_order) FROM public.academic_terms atm JOIN public.academic_years ay ON ay.id = atm.academic_year_id WHERE atm.school_id = ANY(v_school_ids) AND (p_school_year IS NULL OR ay.school_year = p_school_year)), '[]'::jsonb),
    'school_days', COALESCE((SELECT jsonb_agg(to_jsonb(sdc) ORDER BY sdc.day_date) FROM public.school_day_calendar sdc LEFT JOIN public.academic_years ay ON ay.id = sdc.academic_year_id WHERE sdc.school_id = ANY(v_school_ids) AND (p_school_year IS NULL OR ay.school_year = p_school_year)), '[]'::jsonb),
    'class_subjects', COALESCE((SELECT jsonb_agg(to_jsonb(cs) ORDER BY cs.component_name) FROM public.class_subjects cs JOIN public.classes c ON c.id = cs.class_id WHERE cs.school_id = ANY(v_school_ids) AND (p_school_year IS NULL OR c.school_year = p_school_year)), '[]'::jsonb),
    'class_schedule_slots', COALESCE((SELECT jsonb_agg(to_jsonb(slot) ORDER BY slot.weekday, slot.start_time) FROM public.class_schedule_slots slot JOIN public.classes c ON c.id = slot.class_id WHERE slot.school_id = ANY(v_school_ids) AND (p_school_year IS NULL OR c.school_year = p_school_year)), '[]'::jsonb),
    'import_batches', COALESCE((SELECT jsonb_agg(to_jsonb(batch) ORDER BY batch.created_at DESC) FROM public.academic_import_batches batch WHERE batch.school_id = ANY(v_school_ids)), '[]'::jsonb),
    'import_rows', COALESCE((SELECT jsonb_agg(to_jsonb(row_item) ORDER BY row_item.created_at DESC, row_item.row_number) FROM public.academic_import_rows row_item WHERE row_item.school_id = ANY(v_school_ids)), '[]'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."secretaria_list_academic_core"("p_school_id" "uuid", "p_school_year" "text") OWNER TO "postgres";


