CREATE OR REPLACE FUNCTION "public"."secretaria_list_calendar_events"("p_school_id" "uuid", "p_from" "date", "p_to" "date", "p_class_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("source_type" "text", "source_id" "uuid", "school_id" "uuid", "class_id" "uuid", "event_date" "date", "start_time" time without time zone, "end_time" time without time zone, "title" "text", "description" "text", "event_type" "text", "status" "text", "created_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  with allowed as (
    select 1
    where auth.uid() is not null
      and (public.is_platform_admin() or public.secretaria_can_manage_school(p_school_id))
  ),
  events as (
    select
      'class_calendar'::text as source_type,
      cce.id as source_id,
      cce.school_id,
      cce.class_id,
      cce.entry_date as event_date,
      cce.start_time,
      cce.end_time,
      cce.title,
      cce.description,
      cce.entry_type as event_type,
      cce.status,
      cce.created_at
    from allowed
    join public.class_calendar_entries cce on cce.school_id = p_school_id
    where cce.status = 'published'
      and cce.entry_date between p_from and p_to
      and (p_class_id is null or cce.class_id = p_class_id)

    union all

    select
      'school_calendar'::text,
      sce.id,
      sce.school_id,
      sce.class_id,
      sce.event_date,
      sce.start_time,
      sce.end_time,
      sce.title,
      sce.description,
      sce.event_type,
      sce.status,
      sce.created_at
    from allowed
    join public.school_calendar_events sce on sce.school_id = p_school_id
    where sce.status = 'published'
      and sce.event_date between p_from and p_to
      and (p_class_id is null or sce.class_id is null or sce.class_id = p_class_id)

    union all

    select
      'assessment_available'::text,
      aa.id,
      aa.school_id,
      aa.class_id,
      aa.available_from::date,
      aa.available_from::time,
      null::time,
      ('Avaliação disponível: ' || coalesce(a.title, 'Avalia+'))::text,
      coalesce(a.description, 'Avaliação publicada.')::text,
      'avaliacao'::text,
      aa.status,
      aa.created_at
    from allowed
    join public.assessment_assignments aa on aa.school_id = p_school_id
    join public.assessments a on a.id = aa.assessment_id
    where aa.status = 'published'
      and aa.available_from::date between p_from and p_to
      and (p_class_id is null or aa.class_id = p_class_id)
  )
  select *
  from events
  order by event_date asc, start_time asc nulls last, created_at asc;
$$;


ALTER FUNCTION "public"."secretaria_list_calendar_events"("p_school_id" "uuid", "p_from" "date", "p_to" "date", "p_class_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."secretaria_list_class_diary_entries"("p_class_id" "uuid" DEFAULT NULL::"uuid", "p_from" "date" DEFAULT NULL::"date", "p_to" "date" DEFAULT NULL::"date") RETURNS TABLE("id" "uuid", "school_id" "uuid", "school_name" "text", "class_id" "uuid", "class_name" "text", "teacher_id" "uuid", "teacher_name" "text", "entry_date" "date", "title" "text", "taught_content" "text", "pedagogical_notes" "text", "plan_id" "uuid", "plan_title" "text", "calendar_entry_id" "uuid", "calendar_title" "text", "status" "text", "closed_at" timestamp with time zone, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "activity_link_count" bigint, "attendance_total" bigint, "attendance_present" bigint, "attendance_absent" bigint, "attendance_justified" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    cde.id,
    cde.school_id,
    s.nome AS school_name,
    cde.class_id,
    c.nome AS class_name,
    cde.teacher_id,
    COALESCE(p.display_name, t.full_name, 'Professor') AS teacher_name,
    cde.entry_date,
    cde.title,
    cde.taught_content,
    cde.pedagogical_notes,
    cde.plan_id,
    tp.title AS plan_title,
    cde.calendar_entry_id,
    cce.title AS calendar_title,
    cde.status,
    cde.closed_at,
    cde.created_at,
    cde.updated_at,
    COALESCE(links.count, 0) AS activity_link_count,
    COALESCE(attendance.total, 0) AS attendance_total,
    COALESCE(attendance.present, 0) AS attendance_present,
    COALESCE(attendance.absent, 0) AS attendance_absent,
    COALESCE(attendance.justified, 0) AS attendance_justified
  FROM public.class_diary_entries cde
  JOIN public.schools s ON s.id = cde.school_id
  JOIN public.classes c ON c.id = cde.class_id
  JOIN public.teachers t ON t.id = cde.teacher_id
  LEFT JOIN public.profiles p ON p.id = t.profile_id
  LEFT JOIN public.teacher_plans tp ON tp.id = cde.plan_id
  LEFT JOIN public.class_calendar_entries cce ON cce.id = cde.calendar_entry_id
  LEFT JOIN LATERAL (
    SELECT count(*)::bigint
    FROM public.class_diary_activity_links l
    WHERE l.diary_entry_id = cde.id
  ) links(count) ON true
  LEFT JOIN LATERAL (
    SELECT
      count(*)::bigint AS total,
      count(*) FILTER (WHERE ar.status = 'present')::bigint AS present,
      count(*) FILTER (WHERE ar.status = 'absent')::bigint AS absent,
      count(*) FILTER (WHERE ar.status = 'justified')::bigint AS justified
    FROM public.attendance_records ar
    WHERE ar.school_id = cde.school_id
      AND ar.class_id = cde.class_id
      AND ar.attendance_date = cde.entry_date
  ) attendance ON true
  WHERE cde.status <> 'deleted'
    AND (p_class_id IS NULL OR cde.class_id = p_class_id)
    AND (p_from IS NULL OR cde.entry_date >= p_from)
    AND (p_to IS NULL OR cde.entry_date <= p_to)
    AND (
      public.is_platform_admin()
      OR public.secretaria_can_manage_school(cde.school_id)
    )
  ORDER BY cde.entry_date DESC, cde.updated_at DESC;
$$;


ALTER FUNCTION "public"."secretaria_list_class_diary_entries"("p_class_id" "uuid", "p_from" "date", "p_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."secretaria_list_class_diary_student_notes"("p_class_id" "uuid" DEFAULT NULL::"uuid", "p_student_id" "uuid" DEFAULT NULL::"uuid", "p_from" "date" DEFAULT NULL::"date", "p_to" "date" DEFAULT NULL::"date") RETURNS TABLE("id" "uuid", "school_id" "uuid", "school_name" "text", "class_id" "uuid", "class_name" "text", "teacher_id" "uuid", "teacher_name" "text", "student_id" "uuid", "student_name" "text", "diary_entry_id" "uuid", "diary_entry_title" "text", "note_date" "date", "note_text" "text", "status" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    cdn.id,
    cdn.school_id,
    sc.nome::text AS school_name,
    cdn.class_id,
    cl.nome::text AS class_name,
    cdn.teacher_id,
    coalesce(p.display_name, 'Professor')::text AS teacher_name,
    cdn.student_id,
    coalesce(st.nome, 'Aluno')::text AS student_name,
    cdn.diary_entry_id,
    cde.title AS diary_entry_title,
    cdn.note_date,
    cdn.note_text,
    cdn.status,
    cdn.created_at,
    cdn.updated_at
  FROM public.class_diary_student_notes cdn
  JOIN public.schools sc ON sc.id = cdn.school_id
  JOIN public.classes cl ON cl.id = cdn.class_id
  JOIN public.students st ON st.id = cdn.student_id
  JOIN public.teachers t ON t.id = cdn.teacher_id
  LEFT JOIN public.profiles p ON p.id = t.profile_id
  LEFT JOIN public.class_diary_entries cde ON cde.id = cdn.diary_entry_id
  WHERE cdn.status <> 'deleted'
    AND (p_class_id IS NULL OR cdn.class_id = p_class_id)
    AND (p_student_id IS NULL OR cdn.student_id = p_student_id)
    AND (p_from IS NULL OR cdn.note_date >= p_from)
    AND (p_to IS NULL OR cdn.note_date <= p_to)
    AND (
      public.is_platform_admin()
      OR public.secretaria_can_manage_school(cdn.school_id)
    )
  ORDER BY cdn.note_date DESC, cdn.created_at DESC;
$$;


ALTER FUNCTION "public"."secretaria_list_class_diary_student_notes"("p_class_id" "uuid", "p_student_id" "uuid", "p_from" "date", "p_to" "date") OWNER TO "postgres";


