CREATE TABLE IF NOT EXISTS "public"."communication_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "communication_id" "uuid" NOT NULL,
    "event_type" "text" NOT NULL,
