    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "communication_events_status_check" CHECK (((("from_status" IS NULL) OR ("from_status" = ANY (ARRAY['draft'::"text", 'published'::"text", 'archived'::"text", 'deleted'::"text", 'REPORTADO'::"text", 'EM_ANALISE'::"text", 'RESOLVIDO'::"text"]))) AND (("to_status" IS NULL) OR ("to_status" = ANY (ARRAY['draft'::"text", 'published'::"text", 'archived'::"text", 'deleted'::"text", 'REPORTADO'::"text", 'EM_ANALISE'::"text", 'RESOLVIDO'::"text"]))))),
    CONSTRAINT "communication_events_type_check" CHECK (("event_type" = ANY (ARRAY['created'::"text", 'published'::"text", 'edited'::"text", 'archived'::"text", 'deleted'::"text", 'reported'::"text", 'moderation_updated'::"text"])))
);


