CREATE OR REPLACE FUNCTION "public"."secretaria_reenroll_student"("p_student_id" "uuid", "p_class_id" "uuid", "p_school_year" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_student public.students%rowtype;
  v_class public.classes%rowtype;
  v_school_year text := nullif(trim(p_school_year), '');
  v_reason text := nullif(trim(p_reason), '');
  v_enrollment_id uuid;
  v_movement_id uuid;
begin
  if v_school_year is null then
    raise exception 'Ano letivo da rematricula e obrigatorio.' using errcode = '22023';
  end if;

  if v_reason is null then
    raise exception 'Motivo da rematricula e obrigatorio.' using errcode = '22023';
  end if;

  select * into v_student
  from public.students
  where id = p_student_id
  for update;

  if v_student.id is null then
    raise exception 'Aluno nao encontrado.' using errcode = '22023';
  end if;

  select * into v_class
  from public.classes
  where id = p_class_id
    and status = 'active'
  limit 1;

  if v_class.id is null then
    raise exception 'Turma ativa nao encontrada.' using errcode = '22023';
  end if;

  if coalesce(v_class.school_year, v_school_year) <> v_school_year then
    raise exception 'Ano letivo inconsistente com a turma selecionada.' using errcode = '22023';
  end if;

  if not public.secretaria_can_manage_school(v_class.school_id) then
    raise exception 'Perfil institucional sem permissao para rematricular nesta escola.' using errcode = '42501';
  end if;

  if exists (
    select 1
    from public.enrollments e
    where e.student_id = v_student.id
      and e.school_year = v_school_year
      and e.status = 'active'
      and e.ended_at is null
  ) then
    raise exception 'Aluno ja possui matricula ativa neste ano letivo.' using errcode = '23505';
  end if;

  insert into public.enrollments (
    student_id,
    class_id,
    school_id,
    school_year,
    status
  )
  values (
    v_student.id,
    v_class.id,
    v_class.school_id,
    v_school_year,
    'active'
  )
  returning id into v_enrollment_id;

  update public.students
  set class_id = v_class.id,
      school_id = v_class.school_id,
      turma = v_class.nome,
      status = coalesce(nullif(status, ''), 'active')
  where id = v_student.id;

  insert into public.enrollment_movements (
    school_id,
    student_id,
    enrollment_id,
    movement_type,
    to_class_id,
    to_status,
    reason,
    performed_by
  )
  values (
    v_class.school_id,
    v_student.id,
    v_enrollment_id,
    'reenrollment',
    v_class.id,
    'active',
    v_reason,
    auth.uid()
  )
  returning id into v_movement_id;

  return jsonb_build_object(
    'movement_id', v_movement_id,
    'enrollment_id', v_enrollment_id,
    'student_id', v_student.id,
    'to_class_id', v_class.id,
    'to_status', 'active',
    'performed_by', auth.uid(),
    'created_at', now()
  );
end;
$$;


ALTER FUNCTION "public"."secretaria_reenroll_student"("p_student_id" "uuid", "p_class_id" "uuid", "p_school_year" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."secretaria_set_communication_status"("p_communication_id" "uuid", "p_to_status" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_author uuid := auth.uid();
  v_to_status text := lower(nullif(trim(p_to_status), ''));
  v_comm public.communications%rowtype;
  v_from_status text;
  v_event_type text;
  v_deliveries integer := 0;
begin
  if v_author is null then
    raise exception 'Usuario autenticado obrigatorio.' using errcode = '42501';
  end if;

  if v_to_status not in ('published', 'archived') then
    raise exception 'Status de comunicacao invalido.' using errcode = '22023';
  end if;

  select * into v_comm from public.communications where id = p_communication_id for update;

  if v_comm.id is null then
    raise exception 'Comunicado nao encontrado.' using errcode = '22023';
  end if;

  if v_comm.status = 'deleted' then
    raise exception 'Comunicado excluido nao pode ser republicado.' using errcode = '42501';
  end if;

  if not (
    public.secretaria_can_manage_school(v_comm.school_id)
    or (
      v_comm.author_profile_id = v_author
      and public.communication_teacher_can_target(v_comm.school_id, v_comm.class_id, v_comm.student_id, v_comm.audience_type)
    )
  ) then
    raise exception 'Usuario sem permissao para alterar este comunicado.' using errcode = '42501';
  end if;

  if v_comm.status = v_to_status then
    if v_to_status = 'published' then
      v_deliveries := public.communication_generate_deliveries(v_comm.id);
    end if;
    return jsonb_build_object('communication_id', v_comm.id, 'from_status', v_comm.status, 'to_status', v_to_status, 'changed', false, 'deliveries_created', v_deliveries);
  end if;

  if v_comm.status = 'published' and v_to_status <> 'archived' then
    raise exception 'Comunicado publicado permite somente retirada da publicacao.' using errcode = '22023';
  end if;

  if v_comm.status in ('draft', 'archived') and v_to_status <> 'published' then
    raise exception 'Rascunho ou comunicado retirado permite somente publicacao.' using errcode = '22023';
  end if;

  v_from_status := v_comm.status;

  update public.communications
  set status = v_to_status, deleted_at = null, deleted_by = null
  where id = v_comm.id
  returning * into v_comm;

  v_event_type := case when v_to_status = 'published' then 'published' when v_to_status = 'archived' then 'archived' else 'edited' end;
  insert into public.communication_events (communication_id, event_type, from_status, to_status, performed_by)
  values (v_comm.id, v_event_type, v_from_status, v_to_status, v_author);

  if v_to_status = 'published' then
    v_deliveries := public.communication_generate_deliveries(v_comm.id);
  end if;

  return jsonb_build_object('communication_id', v_comm.id, 'from_status', v_from_status, 'to_status', v_to_status, 'changed', true, 'deliveries_created', v_deliveries);
end;
$$;


ALTER FUNCTION "public"."secretaria_set_communication_status"("p_communication_id" "uuid", "p_to_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."secretaria_set_student_document_status"("p_student_id" "uuid", "p_document_type_id" "uuid", "p_status" "text", "p_notes" "text" DEFAULT NULL::"text", "p_file_reference" "text" DEFAULT NULL::"text", "p_received_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_expires_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_student public.students%rowtype;
  v_document_type public.document_types%rowtype;
  v_document public.student_documents%rowtype;
  v_document_id uuid;
  v_previous_status text;
  v_status text := lower(nullif(trim(p_status), ''));
  v_event_type text;
begin
  if v_status not in ('pending', 'received', 'waived') then
    raise exception 'Status documental invalido.' using errcode = '22023';
  end if;

  select * into v_student
  from public.students
  where id = p_student_id
  limit 1;

  if v_student.id is null then
    raise exception 'Aluno nao encontrado.' using errcode = '22023';
  end if;

  if not public.secretaria_can_manage_school(v_student.school_id) then
    raise exception 'Perfil institucional sem permissao para documentos desta escola.' using errcode = '42501';
  end if;

  select * into v_document_type
  from public.document_types
  where id = p_document_type_id
    and status = 'active'
    and (school_id is null or school_id = v_student.school_id)
  limit 1;

  if v_document_type.id is null then
    raise exception 'Tipo de documento ativo nao encontrado para a escola.' using errcode = '22023';
  end if;

  select * into v_document
  from public.student_documents
  where student_id = p_student_id
    and document_type_id = p_document_type_id
  for update;

  if v_document.id is null then
    v_previous_status := null;
    insert into public.student_documents (
      school_id,
      student_id,
      document_type_id,
      status,
      notes,
      file_reference,
      received_at,
      expires_at,
      created_by,
      updated_by
    )
    values (
      v_student.school_id,
      p_student_id,
      p_document_type_id,
      v_status,
      nullif(trim(p_notes), ''),
      nullif(trim(p_file_reference), ''),
      case when v_status = 'received' then coalesce(p_received_at, now()) else p_received_at end,
      p_expires_at,
      auth.uid(),
      auth.uid()
    )
    returning * into v_document;
    v_event_type := 'created';
  else
    v_previous_status := v_document.status;
    update public.student_documents
      set status = v_status,
        notes = nullif(trim(p_notes), ''),
        file_reference = coalesce(nullif(trim(p_file_reference), ''), file_reference),
        received_at = case
          when v_status = 'received' then coalesce(p_received_at, received_at, now())
          else null
        end,
        expires_at = p_expires_at,
        updated_by = auth.uid(),
        updated_at = now()
    where id = v_document.id
    returning * into v_document;
    v_event_type := case
      when nullif(trim(p_file_reference), '') is not null then 'file_referenced'
      else 'status_changed'
    end;
  end if;

  v_document_id := v_document.id;

  insert into public.student_document_events (
    school_id,
    student_document_id,
    student_id,
    document_type_id,
    event_type,
    from_status,
    to_status,
    notes,
    file_reference,
    actor_id
  )
  values (
    v_student.school_id,
    v_document_id,
    p_student_id,
    p_document_type_id,
    v_event_type,
    v_previous_status,
    v_status,
    nullif(trim(p_notes), ''),
    nullif(trim(p_file_reference), ''),
    auth.uid()
  );

  return jsonb_build_object(
    'document_id', v_document_id,
    'student_id', p_student_id,
    'document_type_id', p_document_type_id,
    'status', v_status,
    'updated_by', auth.uid(),
    'updated_at', now()
  );
end;
$$;


ALTER FUNCTION "public"."secretaria_set_student_document_status"("p_student_id" "uuid", "p_document_type_id" "uuid", "p_status" "text", "p_notes" "text", "p_file_reference" "text", "p_received_at" timestamp with time zone, "p_expires_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."secretaria_transfer_enrollment"("p_enrollment_id" "uuid", "p_to_class_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_enrollment public.enrollments%rowtype;
  v_to_class public.classes%rowtype;
  v_movement_id uuid;
  v_reason text := nullif(trim(p_reason), '');
begin
  if v_reason is null then
    raise exception 'Motivo da transferencia e obrigatorio.' using errcode = '22023';
  end if;

  select * into v_enrollment
  from public.enrollments
  where id = p_enrollment_id
  for update;

  if v_enrollment.id is null then
    raise exception 'Matricula nao encontrada.' using errcode = '22023';
  end if;

  if v_enrollment.status <> 'active' or v_enrollment.ended_at is not null then
    raise exception 'Somente matricula ativa pode ser transferida.' using errcode = '22023';
  end if;

  if not public.secretaria_can_manage_school(v_enrollment.school_id) then
    raise exception 'Perfil institucional sem permissao para movimentar esta matricula.' using errcode = '42501';
  end if;

  select * into v_to_class
  from public.classes
  where id = p_to_class_id
    and status = 'active'
  limit 1;

  if v_to_class.id is null then
    raise exception 'Turma ativa de destino nao encontrada.' using errcode = '22023';
  end if;

  if v_to_class.school_id <> v_enrollment.school_id then
    raise exception 'Transferencia entre escolas nao esta autorizada nesta etapa.' using errcode = '22023';
  end if;

  if coalesce(v_to_class.school_year, v_enrollment.school_year) <> v_enrollment.school_year then
    raise exception 'Transferencia deve permanecer no mesmo ano letivo.' using errcode = '22023';
  end if;

  if v_to_class.id = v_enrollment.class_id then
    raise exception 'A turma de destino deve ser diferente da turma atual.' using errcode = '22023';
  end if;

  update public.enrollments
  set class_id = v_to_class.id,
      school_id = v_to_class.school_id,
      status = 'active',
      ended_at = null
  where id = v_enrollment.id;

  update public.students
  set class_id = v_to_class.id,
      school_id = v_to_class.school_id,
      turma = v_to_class.nome
  where id = v_enrollment.student_id;

  insert into public.enrollment_movements (
    school_id,
    student_id,
    enrollment_id,
    movement_type,
    from_class_id,
    to_class_id,
    from_status,
    to_status,
    reason,
    performed_by
  )
  values (
    v_enrollment.school_id,
    v_enrollment.student_id,
    v_enrollment.id,
    'class_transfer',
    v_enrollment.class_id,
    v_to_class.id,
    v_enrollment.status,
    'active',
    v_reason,
    auth.uid()
  )
  returning id into v_movement_id;

  return jsonb_build_object(
    'movement_id', v_movement_id,
    'enrollment_id', v_enrollment.id,
    'student_id', v_enrollment.student_id,
    'from_class_id', v_enrollment.class_id,
    'to_class_id', v_to_class.id,
    'from_status', v_enrollment.status,
    'to_status', 'active',
    'performed_by', auth.uid(),
    'created_at', now()
  );
end;
$$;


ALTER FUNCTION "public"."secretaria_transfer_enrollment"("p_enrollment_id" "uuid", "p_to_class_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."secretaria_update_class_basic"("p_class_id" "uuid", "p_nome" "text", "p_status" "text", "p_age_group" "text" DEFAULT NULL::"text", "p_turno" "text" DEFAULT NULL::"text", "p_ano_escolar" "text" DEFAULT NULL::"text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_class public.classes%rowtype;
  v_status text := coalesce(nullif(trim(p_status), ''), 'active');
  v_nome text := nullif(trim(p_nome), '');
begin
  select * into v_class
  from public.classes
  where id = p_class_id
  for update;

  if v_class.id is null then
    raise exception 'Turma nao encontrada.' using errcode = '22023';
  end if;

  if not public.secretaria_can_manage_school(v_class.school_id) then
    raise exception 'Perfil institucional sem permissao para editar esta turma.' using errcode = '42501';
  end if;

  if v_nome is null then
    raise exception 'Nome da turma e obrigatorio.' using errcode = '22023';
  end if;

  if v_status not in ('active', 'inactive', 'archived') then
    raise exception 'Status de turma incompativel com o schema.' using errcode = '22023';
  end if;

  if exists (
    select 1
    from public.classes c
    where c.id <> v_class.id
      and c.school_id = v_class.school_id
      and lower(trim(c.nome)) = lower(v_nome)
      and coalesce(c.school_year, '') = coalesce(v_class.school_year, '')
      and c.status <> 'archived'
  ) then
    raise exception 'Turma semelhante ja existe nesta escola e ano letivo.' using errcode = '23505';
  end if;

  if v_status <> 'active' and exists (
    select 1
    from public.enrollments e
    where e.class_id = v_class.id
      and e.status = 'active'
      and e.ended_at is null
  ) then
    raise exception 'Nao e permitido inativar turma com matriculas ativas.' using errcode = '22023';
  end if;

  update public.classes
  set nome = v_nome,
      status = v_status,
      age_group = nullif(trim(p_age_group), ''),
      turno = nullif(trim(p_turno), ''),
      ano_escolar = nullif(trim(p_ano_escolar), '')
  where id = v_class.id;

  return jsonb_build_object(
    'class_id', v_class.id,
    'from_status', v_class.status,
    'to_status', v_status,
    'performed_by', auth.uid(),
    'updated_at', now()
  );
end;
$$;


ALTER FUNCTION "public"."secretaria_update_class_basic"("p_class_id" "uuid", "p_nome" "text", "p_status" "text", "p_age_group" "text", "p_turno" "text", "p_ano_escolar" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."secretaria_update_enrollment_status"("p_enrollment_id" "uuid", "p_to_status" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_enrollment public.enrollments%rowtype;
  v_to_status text := nullif(trim(p_to_status), '');
  v_reason text := nullif(trim(p_reason), '');
  v_movement_id uuid;
begin
  if v_to_status is null or not (v_to_status = any (array['active'::text, 'transferred'::text, 'ended'::text, 'cancelled'::text, 'archived'::text])) then
    raise exception 'Status de matricula incompativel com o schema.' using errcode = '22023';
  end if;

  if v_reason is null then
    raise exception 'Motivo da alteracao de status e obrigatorio.' using errcode = '22023';
  end if;

  select * into v_enrollment
  from public.enrollments
  where id = p_enrollment_id
  for update;

  if v_enrollment.id is null then
    raise exception 'Matricula nao encontrada.' using errcode = '22023';
  end if;

  if not public.secretaria_can_manage_school(v_enrollment.school_id) then
    raise exception 'Perfil institucional sem permissao para movimentar esta matricula.' using errcode = '42501';
  end if;

  update public.enrollments
  set status = v_to_status,
      ended_at = case when v_to_status = 'active' then null else ended_at end
  where id = v_enrollment.id;

  insert into public.enrollment_movements (
    school_id,
    student_id,
    enrollment_id,
    movement_type,
    from_class_id,
    to_class_id,
    from_status,
    to_status,
    reason,
    performed_by
  )
  values (
    v_enrollment.school_id,
    v_enrollment.student_id,
    v_enrollment.id,
    'status_change',
    v_enrollment.class_id,
    v_enrollment.class_id,
    v_enrollment.status,
    v_to_status,
    v_reason,
    auth.uid()
  )
  returning id into v_movement_id;

  return jsonb_build_object(
    'movement_id', v_movement_id,
    'enrollment_id', v_enrollment.id,
    'student_id', v_enrollment.student_id,
    'from_status', v_enrollment.status,
    'to_status', v_to_status,
    'performed_by', auth.uid(),
    'created_at', now()
  );
end;
$$;


ALTER FUNCTION "public"."secretaria_update_enrollment_status"("p_enrollment_id" "uuid", "p_to_status" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."secretaria_upsert_academic_term"("p_academic_year_id" "uuid", "p_term_name" "text", "p_term_order" integer, "p_start_date" "date", "p_end_date" "date", "p_term_type" "text" DEFAULT 'bimestre'::"text", "p_status" "text" DEFAULT 'active'::"text", "p_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_year public.academic_years%ROWTYPE; v_row public.academic_terms%ROWTYPE;
BEGIN
  SELECT * INTO v_year FROM public.academic_years WHERE id = p_academic_year_id;
  IF v_year.id IS NULL THEN RAISE EXCEPTION 'Ano letivo nao encontrado.' USING errcode = '22023'; END IF;
  IF NOT public.secretaria_can_manage_school(v_year.school_id) THEN RAISE EXCEPTION 'Perfil sem permissao para configurar periodo letivo.' USING errcode = '42501'; END IF;
  IF p_start_date < v_year.start_date OR p_end_date > v_year.end_date OR p_end_date < p_start_date THEN RAISE EXCEPTION 'Periodo fora dos limites do ano letivo.' USING errcode = '22023'; END IF;
  INSERT INTO public.academic_terms (id, academic_year_id, school_id, term_name, term_order, term_type, start_date, end_date, status, created_by)
  VALUES (COALESCE(p_id, gen_random_uuid()), v_year.id, v_year.school_id, btrim(p_term_name), p_term_order, COALESCE(NULLIF(btrim(p_term_type), ''), 'bimestre'), p_start_date, p_end_date, COALESCE(NULLIF(btrim(p_status), ''), 'active'), auth.uid())
  ON CONFLICT (academic_year_id, term_order) DO UPDATE SET term_name = EXCLUDED.term_name, term_type = EXCLUDED.term_type, start_date = EXCLUDED.start_date, end_date = EXCLUDED.end_date, status = EXCLUDED.status
  RETURNING * INTO v_row;
  RETURN to_jsonb(v_row);
END;
$$;


ALTER FUNCTION "public"."secretaria_upsert_academic_term"("p_academic_year_id" "uuid", "p_term_name" "text", "p_term_order" integer, "p_start_date" "date", "p_end_date" "date", "p_term_type" "text", "p_status" "text", "p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."secretaria_upsert_academic_year"("p_school_id" "uuid", "p_school_year" "text", "p_start_date" "date", "p_end_date" "date", "p_status" "text" DEFAULT 'active'::"text", "p_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_row public.academic_years%ROWTYPE;
BEGIN
  IF NOT public.secretaria_can_manage_school(p_school_id) THEN RAISE EXCEPTION 'Perfil sem permissao para configurar ano letivo.' USING errcode = '42501'; END IF;
  IF p_end_date < p_start_date THEN RAISE EXCEPTION 'Data final deve ser maior ou igual a inicial.' USING errcode = '22023'; END IF;
  INSERT INTO public.academic_years (id, school_id, school_year, start_date, end_date, status, created_by)
  VALUES (COALESCE(p_id, gen_random_uuid()), p_school_id, btrim(p_school_year), p_start_date, p_end_date, COALESCE(NULLIF(btrim(p_status), ''), 'active'), auth.uid())
  ON CONFLICT (school_id, school_year) DO UPDATE SET start_date = EXCLUDED.start_date, end_date = EXCLUDED.end_date, status = EXCLUDED.status
  RETURNING * INTO v_row;
  RETURN to_jsonb(v_row);
END;
$$;


ALTER FUNCTION "public"."secretaria_upsert_academic_year"("p_school_id" "uuid", "p_school_year" "text", "p_start_date" "date", "p_end_date" "date", "p_status" "text", "p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."secretaria_upsert_class_schedule_slot"("p_school_id" "uuid", "p_class_id" "uuid", "p_weekday" integer, "p_start_time" time without time zone, "p_end_time" time without time zone, "p_class_subject_id" "uuid" DEFAULT NULL::"uuid", "p_teacher_id" "uuid" DEFAULT NULL::"uuid", "p_room" "text" DEFAULT NULL::"text", "p_valid_from" "date" DEFAULT NULL::"date", "p_valid_until" "date" DEFAULT NULL::"date", "p_status" "text" DEFAULT 'active'::"text", "p_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_class public.classes%ROWTYPE; v_row public.class_schedule_slots%ROWTYPE;
BEGIN
  IF NOT public.secretaria_can_manage_school(p_school_id) THEN RAISE EXCEPTION 'Perfil sem permissao para configurar horario.' USING errcode = '42501'; END IF;
  SELECT * INTO v_class FROM public.classes WHERE id = p_class_id AND school_id = p_school_id;
  IF v_class.id IS NULL THEN RAISE EXCEPTION 'Turma nao pertence a escola informada.' USING errcode = '22023'; END IF;
  IF p_class_subject_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.class_subjects cs WHERE cs.id = p_class_subject_id AND cs.school_id = p_school_id AND cs.class_id = p_class_id) THEN RAISE EXCEPTION 'Componente nao pertence a turma informada.' USING errcode = '22023'; END IF;
  IF p_id IS NULL THEN
    INSERT INTO public.class_schedule_slots (school_id, class_id, class_subject_id, teacher_id, weekday, start_time, end_time, room, valid_from, valid_until, status, created_by)
    VALUES (p_school_id, p_class_id, p_class_subject_id, p_teacher_id, p_weekday, p_start_time, p_end_time, NULLIF(btrim(p_room), ''), p_valid_from, p_valid_until, COALESCE(NULLIF(btrim(p_status), ''), 'active'), auth.uid()) RETURNING * INTO v_row;
  ELSE
    UPDATE public.class_schedule_slots SET class_subject_id = p_class_subject_id, teacher_id = p_teacher_id, weekday = p_weekday, start_time = p_start_time, end_time = p_end_time, room = NULLIF(btrim(p_room), ''), valid_from = p_valid_from, valid_until = p_valid_until, status = COALESCE(NULLIF(btrim(p_status), ''), 'active') WHERE id = p_id AND school_id = p_school_id RETURNING * INTO v_row;
  END IF;
  IF v_row.id IS NULL THEN RAISE EXCEPTION 'Horario nao encontrado para atualização.' USING errcode = '22023'; END IF;
  RETURN to_jsonb(v_row);
END;
$$;


ALTER FUNCTION "public"."secretaria_upsert_class_schedule_slot"("p_school_id" "uuid", "p_class_id" "uuid", "p_weekday" integer, "p_start_time" time without time zone, "p_end_time" time without time zone, "p_class_subject_id" "uuid", "p_teacher_id" "uuid", "p_room" "text", "p_valid_from" "date", "p_valid_until" "date", "p_status" "text", "p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."secretaria_upsert_class_subject"("p_school_id" "uuid", "p_class_id" "uuid", "p_component_name" "text", "p_component_code" "text" DEFAULT NULL::"text", "p_teacher_id" "uuid" DEFAULT NULL::"uuid", "p_workload_minutes_weekly" integer DEFAULT NULL::integer, "p_status" "text" DEFAULT 'active'::"text", "p_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_class public.classes%ROWTYPE; v_row public.class_subjects%ROWTYPE;
BEGIN
  IF NOT public.secretaria_can_manage_school(p_school_id) THEN RAISE EXCEPTION 'Perfil sem permissao para configurar componente.' USING errcode = '42501'; END IF;
  SELECT * INTO v_class FROM public.classes WHERE id = p_class_id AND school_id = p_school_id;
  IF v_class.id IS NULL THEN RAISE EXCEPTION 'Turma nao pertence a escola informada.' USING errcode = '22023'; END IF;
  IF p_id IS NULL THEN
    INSERT INTO public.class_subjects (school_id, class_id, component_name, component_code, teacher_id, workload_minutes_weekly, status, created_by)
    VALUES (p_school_id, p_class_id, btrim(p_component_name), NULLIF(btrim(p_component_code), ''), p_teacher_id, p_workload_minutes_weekly, COALESCE(NULLIF(btrim(p_status), ''), 'active'), auth.uid()) RETURNING * INTO v_row;
  ELSE
    UPDATE public.class_subjects SET component_name = btrim(p_component_name), component_code = NULLIF(btrim(p_component_code), ''), teacher_id = p_teacher_id, workload_minutes_weekly = p_workload_minutes_weekly, status = COALESCE(NULLIF(btrim(p_status), ''), 'active') WHERE id = p_id AND school_id = p_school_id RETURNING * INTO v_row;
  END IF;
  IF v_row.id IS NULL THEN RAISE EXCEPTION 'Componente nao encontrado para atualização.' USING errcode = '22023'; END IF;
  RETURN to_jsonb(v_row);
END;
$$;


ALTER FUNCTION "public"."secretaria_upsert_class_subject"("p_school_id" "uuid", "p_class_id" "uuid", "p_component_name" "text", "p_component_code" "text", "p_teacher_id" "uuid", "p_workload_minutes_weekly" integer, "p_status" "text", "p_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."school_calendar_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "school_id" "uuid" NOT NULL,
    "class_id" "uuid",
    "created_by" "uuid" DEFAULT "auth"."uid"() NOT NULL,
    "event_date" "date" NOT NULL,
    "start_time" time without time zone,
    "end_time" time without time zone,
    "title" "text" NOT NULL,
    "description" "text",
    "event_type" "text" DEFAULT 'evento'::"text" NOT NULL,
    "status" "text" DEFAULT 'published'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "school_calendar_events_status_check" CHECK (("status" = ANY (ARRAY['published'::"text", 'cancelled'::"text", 'archived'::"text"]))),
    CONSTRAINT "school_calendar_events_time_check" CHECK ((("end_time" IS NULL) OR ("start_time" IS NULL) OR ("end_time" > "start_time"))),
    CONSTRAINT "school_calendar_events_title_not_blank" CHECK (("length"("btrim"("title")) > 0)),
    CONSTRAINT "school_calendar_events_type_check" CHECK (("event_type" = ANY (ARRAY['aula'::"text", 'atividade'::"text", 'avaliacao'::"text", 'lembrete'::"text", 'evento'::"text", 'reuniao'::"text", 'outro'::"text"])))
);


ALTER TABLE "public"."school_calendar_events" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."secretaria_upsert_school_calendar_event"("p_event_id" "uuid" DEFAULT NULL::"uuid", "p_school_id" "uuid" DEFAULT NULL::"uuid", "p_class_id" "uuid" DEFAULT NULL::"uuid", "p_event_date" "date" DEFAULT CURRENT_DATE, "p_start_time" time without time zone DEFAULT NULL::time without time zone, "p_end_time" time without time zone DEFAULT NULL::time without time zone, "p_title" "text" DEFAULT ''::"text", "p_description" "text" DEFAULT NULL::"text", "p_event_type" "text" DEFAULT 'evento'::"text", "p_status" "text" DEFAULT 'published'::"text") RETURNS "public"."school_calendar_events"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_event public.school_calendar_events%rowtype;
  v_type text := lower(coalesce(nullif(btrim(p_event_type), ''), 'evento'));
  v_status text := lower(coalesce(nullif(btrim(p_status), ''), 'published'));
begin
  if auth.uid() is null then
    raise exception 'Usuario autenticado obrigatorio.' using errcode = '42501';
  end if;

  if p_school_id is null or not (public.is_platform_admin() or public.secretaria_can_manage_school(p_school_id)) then
    raise exception 'Secretaria nao autorizada para esta escola.' using errcode = '42501';
  end if;

  if p_class_id is not null and not exists (
    select 1 from public.classes c
    where c.id = p_class_id
      and c.school_id = p_school_id
      and coalesce(c.status, 'active') = 'active'
  ) then
    raise exception 'Turma nao pertence a escola informada.' using errcode = '42501';
  end if;

  if length(btrim(coalesce(p_title, ''))) = 0 then
    raise exception 'Titulo obrigatorio.' using errcode = '22023';
  end if;

  if v_type not in ('aula', 'atividade', 'avaliacao', 'lembrete', 'evento', 'reuniao', 'outro') then
    v_type := 'evento';
  end if;

  if v_status not in ('published', 'cancelled', 'archived') then
    v_status := 'published';
  end if;

  if p_end_time is not null and p_start_time is not null and p_end_time <= p_start_time then
    raise exception 'Horario final deve ser posterior ao inicial.' using errcode = '22023';
  end if;

  if p_event_id is not null then
    update public.school_calendar_events
    set
      class_id = p_class_id,
      event_date = p_event_date,
      start_time = p_start_time,
      end_time = p_end_time,
      title = btrim(p_title),
      description = nullif(btrim(coalesce(p_description, '')), ''),
      event_type = v_type,
      status = v_status,
      updated_at = now()
    where id = p_event_id
      and school_id = p_school_id
    returning * into v_event;

    if v_event.id is null then
      raise exception 'Evento institucional nao encontrado para esta escola.' using errcode = '42501';
    end if;
  else
    insert into public.school_calendar_events (
      school_id, class_id, created_by, event_date, start_time, end_time,
      title, description, event_type, status
    ) values (
      p_school_id, p_class_id, auth.uid(), p_event_date, p_start_time, p_end_time,
      btrim(p_title), nullif(btrim(coalesce(p_description, '')), ''), v_type, v_status
    )
    returning * into v_event;
  end if;

  return v_event;
end;
$$;


