CREATE OR REPLACE FUNCTION "public"."secretaria_upsert_school_day"("p_school_id" "uuid", "p_day_date" "date", "p_day_type" "text", "p_academic_year_id" "uuid" DEFAULT NULL::"uuid", "p_title" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT 'active'::"text", "p_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_row public.school_day_calendar%ROWTYPE;
BEGIN
  IF NOT public.secretaria_can_manage_school(p_school_id) THEN RAISE EXCEPTION 'Perfil sem permissao para configurar dia letivo.' USING errcode = '42501'; END IF;
  INSERT INTO public.school_day_calendar (id, school_id, academic_year_id, day_date, day_type, title, description, status, created_by)
  VALUES (COALESCE(p_id, gen_random_uuid()), p_school_id, p_academic_year_id, p_day_date, COALESCE(NULLIF(btrim(p_day_type), ''), 'letivo'), NULLIF(btrim(p_title), ''), NULLIF(btrim(p_description), ''), COALESCE(NULLIF(btrim(p_status), ''), 'active'), auth.uid())
  ON CONFLICT (school_id, day_date) DO UPDATE SET academic_year_id = EXCLUDED.academic_year_id, day_type = EXCLUDED.day_type, title = EXCLUDED.title, description = EXCLUDED.description, status = EXCLUDED.status
  RETURNING * INTO v_row;
  RETURN to_jsonb(v_row);
END;
$$;


