CREATE OR REPLACE FUNCTION "public"."student_can_read_library_book"("p_book_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
  SELECT auth.uid() IS NOT NULL
    AND EXISTS (
      SELECT 1
      FROM public.books b
      JOIN public.current_student_library_enrollments() ce ON true
      WHERE b.id = p_book_id
        AND coalesce(b.ativo, false) = true
        AND (
          public.is_content_available_for_school(
            ce.school_id,
            'book',
            coalesce(nullif(btrim(b.legacy_id), ''), b.id::text)
          )
          OR public.is_content_available_for_school(
            ce.school_id,
            'book',
            b.id::text
          )
        )
        AND (
          b.ano_escolar IS NULL
          OR btrim(b.ano_escolar) = ''
          OR lower(btrim(b.ano_escolar)) = lower(btrim(coalesce(ce.class_school_year, ce.school_year, '')))
        )
    );
$$;


ALTER FUNCTION "public"."student_can_read_library_book"("p_book_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."student_complete_game_attempt"("p_attempt_id" "uuid", "p_raw_result" "jsonb" DEFAULT '{}'::"jsonb", "p_client_state" "jsonb" DEFAULT '{}'::"jsonb") RETURNS TABLE("attempt_id" "uuid", "game_id" "uuid", "status" "text", "score_percent" integer, "duration_seconds" integer, "canonical_result" "jsonb", "result_event_type" "text", "result_event_key" "text", "completed_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_student_id uuid;
  v_attempt public.student_game_attempts;
  v_game public.student_games;
  v_result jsonb;
  v_score integer;
  v_duration integer;
  v_event_key text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Usuario autenticado obrigatorio.' USING errcode = '42501';
  END IF;

  SELECT ctx.student_id INTO v_student_id
  FROM public.current_early_childhood_student_context() ctx
  LIMIT 1;

  SELECT *
    INTO v_attempt
  FROM public.student_game_attempts a
  WHERE a.id = p_attempt_id
    AND a.student_id = v_student_id
  LIMIT 1;

  IF v_attempt.id IS NULL THEN
    RAISE EXCEPTION 'Tentativa nao encontrada para este aluno.' USING errcode = '42501';
  END IF;

  SELECT *
    INTO v_game
  FROM public.student_games g
  WHERE g.id = v_attempt.game_id;

  IF v_game.id IS NULL OR NOT public.student_can_read_game(v_game.id) THEN
    RAISE EXCEPTION 'Jogo nao autorizado para este aluno.' USING errcode = '42501';
  END IF;

  IF v_attempt.status = 'COMPLETED' THEN
    RETURN QUERY
    SELECT
      v_attempt.id,
      v_attempt.game_id,
      v_attempt.status,
      v_attempt.score_percent,
      v_attempt.duration_seconds,
      v_attempt.canonical_result,
      v_attempt.canonical_result->>'result_event_type',
      v_attempt.result_event_key,
      v_attempt.completed_at;
    RETURN;
  END IF;

  v_result := public.student_game_canonical_result(v_game, p_raw_result, p_client_state, true);
  v_score := NULLIF(v_result->>'score_percent', '')::integer;
  v_duration := NULLIF(v_result->>'duration_seconds', '')::integer;
  v_event_key := v_result->>'result_event_key';

  UPDATE public.student_game_attempts
     SET status = 'COMPLETED',
         client_state = COALESCE(p_client_state, '{}'::jsonb),
         raw_result = COALESCE(p_raw_result, '{}'::jsonb),
         canonical_result = v_result,
         score_percent = v_score,
         duration_seconds = v_duration,
         result_event_key = v_event_key,
         completed_at = now(),
         last_event_at = now(),
         updated_at = now()
   WHERE id = v_attempt.id
   RETURNING * INTO v_attempt;

  RETURN QUERY
  SELECT
    v_attempt.id,
    v_attempt.game_id,
    v_attempt.status,
    v_attempt.score_percent,
    v_attempt.duration_seconds,
    v_attempt.canonical_result,
    v_attempt.canonical_result->>'result_event_type',
    v_attempt.result_event_key,
    v_attempt.completed_at;
END;
$$;


ALTER FUNCTION "public"."student_complete_game_attempt"("p_attempt_id" "uuid", "p_raw_result" "jsonb", "p_client_state" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."student_emit_reward"("p_student_id" "uuid", "p_source_type" "text", "p_source_id" "uuid", "p_source_legacy_id" "text", "p_event_type" "text", "p_event_key" "text", "p_reward_rule" "text", "p_xp_amount" integer, "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS TABLE("ledger_id" "uuid", "xp_amount" integer, "inserted" boolean, "achievements_unlocked" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_ledger_id uuid;
  v_inserted boolean := false;
  v_unlocked integer := 0;
BEGIN
  IF p_student_id IS NULL THEN
    RAISE EXCEPTION 'student_id obrigatorio.' USING errcode = '22023';
  END IF;

  IF p_xp_amount IS NULL OR p_xp_amount <= 0 OR p_xp_amount > 1000 THEN
    RAISE EXCEPTION 'xp_amount invalido.' USING errcode = '22023';
  END IF;

  IF p_event_key IS NULL OR length(btrim(p_event_key)) = 0 THEN
    RAISE EXCEPTION 'event_key obrigatorio.' USING errcode = '22023';
  END IF;

  INSERT INTO public.student_xp_ledger (
    student_id,
    source_type,
    source_id,
    source_legacy_id,
    event_type,
    event_key,
    reward_rule,
    xp_amount,
    metadata
  )
  VALUES (
    p_student_id,
    lower(btrim(p_source_type)),
    p_source_id,
    NULLIF(btrim(coalesce(p_source_legacy_id, '')), ''),
    upper(btrim(p_event_type)),
    btrim(p_event_key),
    btrim(p_reward_rule),
    p_xp_amount,
    COALESCE(p_metadata, '{}'::jsonb)
  )
  ON CONFLICT (student_id, (lower(btrim(event_key)))) DO NOTHING
  RETURNING id INTO v_ledger_id;

  IF v_ledger_id IS NOT NULL THEN
    v_inserted := true;
    v_unlocked := public.student_unlock_achievements_for_ledger(v_ledger_id);
  ELSE
    SELECT id INTO v_ledger_id
    FROM public.student_xp_ledger
    WHERE student_id = p_student_id
      AND lower(btrim(event_key)) = lower(btrim(p_event_key))
    LIMIT 1;
  END IF;

  RETURN QUERY
  SELECT v_ledger_id, p_xp_amount, v_inserted, v_unlocked;
END;
$$;


ALTER FUNCTION "public"."student_emit_reward"("p_student_id" "uuid", "p_source_type" "text", "p_source_id" "uuid", "p_source_legacy_id" "text", "p_event_type" "text", "p_event_key" "text", "p_reward_rule" "text", "p_xp_amount" integer, "p_metadata" "jsonb") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."student_games" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "legacy_id" "text" NOT NULL,
    "title" "text" NOT NULL,
    "description" "text",
    "student_instruction" "text",
    "segment" "text" DEFAULT 'educacao_infantil'::"text" NOT NULL,
    "age_group" "text",
    "school_year" "text",
    "game_type" "text" NOT NULL,
    "engine" "text" DEFAULT 'game-engine.js'::"text" NOT NULL,
    "entrypoint" "text",
    "orientation" "text" DEFAULT 'portrait'::"text" NOT NULL,
    "bncc_codes" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "bncc_skills" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "pedagogical_metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "engine_config" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "asset_manifest" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "completion_rule" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "score_rule" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "result_schema" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "reward_candidate" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "related_content" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "sort_order" integer DEFAULT 0 NOT NULL,
    "duration_seconds" integer,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "active" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "student_games_legacy_id_not_blank" CHECK (("length"("btrim"("legacy_id")) > 0)),
    CONSTRAINT "student_games_no_secret_check" CHECK ((("legacy_id" !~* '(password|senha|token|secret|service_role|access_token|refresh_token)'::"text") AND (COALESCE("entrypoint", ''::"text") !~* '(password|senha|token|secret|service_role|access_token|refresh_token)'::"text") AND (("pedagogical_metadata")::"text" !~* '(password|senha|token|secret|service_role|access_token|refresh_token)'::"text") AND (("engine_config")::"text" !~* '(password|senha|token|secret|service_role|access_token|refresh_token)'::"text") AND (("asset_manifest")::"text" !~* '(password|senha|token|secret|service_role|access_token|refresh_token)'::"text") AND (("completion_rule")::"text" !~* '(password|senha|token|secret|service_role|access_token|refresh_token)'::"text") AND (("score_rule")::"text" !~* '(password|senha|token|secret|service_role|access_token|refresh_token)'::"text") AND (("result_schema")::"text" !~* '(password|senha|token|secret|service_role|access_token|refresh_token)'::"text") AND (("reward_candidate")::"text" !~* '(password|senha|token|secret|service_role|access_token|refresh_token)'::"text") AND (("related_content")::"text" !~* '(password|senha|token|secret|service_role|access_token|refresh_token)'::"text"))),
    CONSTRAINT "student_games_orientation_check" CHECK (("orientation" = ANY (ARRAY['portrait'::"text", 'landscape'::"text", 'any'::"text"]))),
    CONSTRAINT "student_games_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'published'::"text", 'archived'::"text"])))
);


ALTER TABLE "public"."student_games" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."student_game_canonical_result"("p_game" "public"."student_games", "p_raw_result" "jsonb", "p_client_state" "jsonb", "p_complete" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_raw jsonb := COALESCE(p_raw_result, '{}'::jsonb);
  v_state jsonb := COALESCE(p_client_state, '{}'::jsonb);
  v_rule jsonb := COALESCE(p_game.score_rule, '{}'::jsonb);
  v_max_score integer := LEAST(GREATEST(COALESCE((v_rule->>'max_score')::integer, 100), 0), 100);
  v_reported_score integer := NULL;
  v_score integer := NULL;
  v_duration integer := NULL;
  v_event_key text;
BEGIN
  IF v_raw::text ~* '(password|senha|token|secret|service_role|access_token|refresh_token)'
     OR v_state::text ~* '(password|senha|token|secret|service_role|access_token|refresh_token)' THEN
    RAISE EXCEPTION 'Resultado do jogo contem termo sensivel.' USING errcode = '22023';
  END IF;

  IF jsonb_typeof(v_raw) <> 'object' OR jsonb_typeof(v_state) <> 'object' THEN
    RAISE EXCEPTION 'Resultado do jogo deve ser objeto JSON.' USING errcode = '22023';
  END IF;

  IF v_raw ? 'score' THEN
    v_reported_score := LEAST(GREATEST(COALESCE((v_raw->>'score')::integer, 0), 0), 100);
  ELSIF v_raw ? 'score_percent' THEN
    v_reported_score := LEAST(GREATEST(COALESCE((v_raw->>'score_percent')::integer, 0), 0), 100);
  END IF;

  IF p_complete THEN
    v_score := LEAST(COALESCE(v_reported_score, v_max_score), v_max_score);
  END IF;

  IF v_raw ? 'duration_seconds' THEN
    v_duration := LEAST(GREATEST(COALESCE((v_raw->>'duration_seconds')::integer, 0), 0), 86400);
  END IF;

  v_event_key := COALESCE(NULLIF(v_raw->>'event_key', ''), 'GAME_COMPLETED:' || p_game.legacy_id || ':ATTEMPT_SCOPED');

  RETURN jsonb_build_object(
    'game_id', p_game.id,
    'legacy_id', p_game.legacy_id,
    'status', CASE WHEN p_complete THEN 'COMPLETED' ELSE 'IN_PROGRESS' END,
    'score_percent', v_score,
    'duration_seconds', v_duration,
    'result_event_type', CASE WHEN p_complete THEN 'GAME_COMPLETED' ELSE NULL END,
    'result_event_key', CASE WHEN p_complete THEN v_event_key ELSE NULL END,
    'trust_strategy', COALESCE(v_rule->>'trust_strategy', 'server_bounded_client_events'),
    'raw_client_score_accepted', false,
    'xp_write', false
  );
END;
$$;


ALTER FUNCTION "public"."student_game_canonical_result"("p_game" "public"."student_games", "p_raw_result" "jsonb", "p_client_state" "jsonb", "p_complete" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."student_game_next_attempt_number"("p_student_id" "uuid", "p_game_id" "uuid") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
  SELECT COALESCE(MAX(a.attempt_number), 0) + 1
  FROM public.student_game_attempts a
  WHERE a.student_id = p_student_id
    AND a.game_id = p_game_id;
$$;


ALTER FUNCTION "public"."student_game_next_attempt_number"("p_student_id" "uuid", "p_game_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."student_gamification_current_student_id"() RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
  select s.id
  from public.students s
  where s.user_id = auth.uid()
    and coalesce(s.status, 'active') in ('active', 'ativo')
  order by s.updated_at desc nulls last, s.created_at desc nulls last
  limit 1;
$$;


ALTER FUNCTION "public"."student_gamification_current_student_id"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."student_get_achievements"() RETURNS TABLE("achievement_id" "uuid", "legacy_id" "text", "title" "text", "description" "text", "category" "text", "is_technical_test" boolean, "unlocked" boolean, "unlocked_at" timestamp with time zone, "source_event_key" "text", "metadata" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_student_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Usuario autenticado obrigatorio.' USING errcode = '42501';
  END IF;

  v_student_id := public.student_gamification_current_student_id();
  IF v_student_id IS NULL THEN
    RAISE EXCEPTION 'Aluno ativo nao encontrado.' USING errcode = '42501';
  END IF;

  RETURN QUERY
  SELECT
    c.id,
    c.legacy_id,
    c.title,
    c.description,
    c.category,
    c.is_technical_test,
    (sa.id IS NOT NULL) AS unlocked,
    sa.unlocked_at,
    sa.source_event_key,
    COALESCE(sa.metadata, '{}'::jsonb) AS metadata
  FROM public.achievement_catalog c
  LEFT JOIN public.student_achievements sa
    ON sa.achievement_id = c.id
   AND sa.student_id = v_student_id
   AND sa.status = 'UNLOCKED'
  WHERE c.active = true
    AND c.status = 'published'
  ORDER BY c.sort_order, c.legacy_id;
END;
$$;


ALTER FUNCTION "public"."student_get_achievements"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."student_get_activities"() RETURNS TABLE("id" "uuid", "legacy_id" "text", "title" "text", "description" "text", "instruction" "text", "activity_type" "text", "segment" "text", "age_group" "text", "book_legacy_id" "text", "page_start" integer, "page_end" integer, "bncc_codes" "text"[], "asset" "jsonb", "sort_order" integer, "duration_seconds" integer, "progress_status" "text", "percent_complete" integer, "updated_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
  SELECT a.id, a.legacy_id, a.title, a.description, a.instruction, a.activity_type, a.segment, a.age_group,
         a.book_legacy_id, a.page_start, a.page_end, a.bncc_codes, a.asset, a.sort_order, a.duration_seconds,
         COALESCE(p.status, 'NOT_STARTED') AS progress_status, COALESCE(p.percent_complete, 0) AS percent_complete,
         COALESCE(p.updated_at, a.updated_at) AS updated_at
  FROM public.current_early_childhood_student_context() ctx
  JOIN public.student_activities a ON true
  LEFT JOIN public.student_activity_progress p ON p.student_id = ctx.student_id AND p.activity_id = a.id
  WHERE a.active = true
    AND a.status = 'published'
    AND public.is_content_available_for_school(ctx.school_id, 'activity', a.legacy_id)
    AND (a.age_group IS NULL OR ctx.age_group IS NULL OR lower(a.age_group) = lower(ctx.age_group) OR lower(a.age_group) = lower(replace(ctx.age_group, ' ', '')))
  ORDER BY a.sort_order, a.title;
$$;


ALTER FUNCTION "public"."student_get_activities"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."student_get_activity"("p_activity_id" "uuid") RETURNS TABLE("id" "uuid", "legacy_id" "text", "discovery_id" "uuid", "title" "text", "description" "text", "instruction" "text", "narration_text" "text", "activity_type" "text", "segment" "text", "age_group" "text", "book_legacy_id" "text", "page_start" integer, "page_end" integer, "bncc_codes" "text"[], "bncc_skills" "text"[], "asset" "jsonb", "engine_metadata" "jsonb", "completion_rule" "jsonb", "reward" "jsonb", "progress_status" "text", "percent_complete" integer, "progress_data" "jsonb", "updated_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
  SELECT a.id, a.legacy_id, a.discovery_id, a.title, a.description, a.instruction, a.narration_text,
         a.activity_type, a.segment, a.age_group, a.book_legacy_id, a.page_start, a.page_end, a.bncc_codes,
         a.bncc_skills, a.asset, a.engine_metadata, a.completion_rule, a.reward,
         COALESCE(p.status, 'NOT_STARTED') AS progress_status, COALESCE(p.percent_complete, 0) AS percent_complete,
         COALESCE(p.progress_data, '{}'::jsonb) AS progress_data, COALESCE(p.updated_at, a.updated_at) AS updated_at
  FROM public.current_early_childhood_student_context() ctx
  JOIN public.student_activities a ON a.id = p_activity_id
  LEFT JOIN public.student_activity_progress p ON p.student_id = ctx.student_id AND p.activity_id = a.id
  WHERE public.student_can_read_activity(a.id);
$$;


ALTER FUNCTION "public"."student_get_activity"("p_activity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."student_get_context"() RETURNS TABLE("student_id" "uuid", "student_name" "text", "enrollment_id" "uuid", "class_id" "uuid", "class_name" "text", "school_id" "uuid", "school_name" "text", "segment" "text", "school_year" "text", "age_group" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
  select
    s.id as student_id,
    s.nome::text as student_name,
    e.id as enrollment_id,
    e.class_id,
    c.nome::text as class_name,
    e.school_id,
    sc.nome::text as school_name,
    case
      when lower(coalesce(c.age_group, '')) in (
        'educacao_infantil',
        'educação infantil',
        'infantil',
        'pre_escola',
        'pré-escola',
        'pre escola',
        'pré escola'
      )
        or lower(coalesce(c.school_year, e.school_year, c.ano_escolar, s.turma, '')) similar to '%(infantil|creche|maternal|pre|pré)%'
        then 'EDUCACAO_INFANTIL'
      when lower(coalesce(c.school_year, e.school_year, c.ano_escolar, s.turma, '')) similar to '%(medio|médio|ensino medio|ensino médio)%'
        then 'ENSINO_MEDIO'
      else 'ENSINO_FUNDAMENTAL'
    end as segment,
    coalesce(c.school_year, e.school_year, c.ano_escolar::text, s.turma::text) as school_year,
    c.age_group
  from public.students s
  join public.enrollments e on e.student_id = s.id
  join public.classes c on c.id = e.class_id
  join public.schools sc on sc.id = e.school_id
  left join public.users u on u.id = s.user_id
  where auth.uid() is not null
    and (
      s.user_id = auth.uid()
      or lower(coalesce(s.email, '')) = lower(coalesce(auth.jwt() ->> 'email', ''))
      or lower(coalesce(u.email, '')) = lower(coalesce(auth.jwt() ->> 'email', ''))
    )
    and lower(coalesce(s.status, 'active')) in ('active', 'ativo')
    and lower(coalesce(e.status, 'active')) in ('active', 'ativo')
    and e.enrolled_at <= now()
    and (e.ended_at is null or e.ended_at > now())
    and lower(coalesce(c.status, 'active')) in ('active', 'ativo')
    and lower(coalesce(sc.status, 'active')) not in ('archived', 'deleted', 'excluida', 'excluída')
  order by e.enrolled_at desc nulls last, e.created_at desc nulls last
  limit 1;
$$;


ALTER FUNCTION "public"."student_get_context"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."student_get_context"() IS 'Contexto canonico do aluno autenticado por auth.uid(), incluindo login institucional. Retorna aluno, matricula ativa, turma, escola e segmento sem depender de fallback demonstrativo.';



CREATE OR REPLACE FUNCTION "public"."student_get_discoveries"() RETURNS TABLE("id" "uuid", "legacy_id" "text", "title" "text", "description" "text", "student_instruction" "text", "discovery_type" "text", "segment" "text", "age_group" "text", "book_legacy_id" "text", "page_start" integer, "page_end" integer, "bncc_codes" "text"[], "experience_fields" "text"[], "resources" "jsonb", "sort_order" integer, "duration_seconds" integer, "progress_status" "text", "updated_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
  SELECT d.id, d.legacy_id, d.title, d.description, d.student_instruction, d.discovery_type, d.segment,
         d.age_group, d.book_legacy_id, d.page_start, d.page_end, d.bncc_codes, d.experience_fields,
         d.resources, d.sort_order, d.duration_seconds, COALESCE(p.status, 'NOT_STARTED') AS progress_status,
         COALESCE(p.updated_at, d.updated_at) AS updated_at
  FROM public.current_early_childhood_student_context() ctx
  JOIN public.student_discoveries d ON true
  LEFT JOIN public.student_discovery_progress p ON p.student_id = ctx.student_id AND p.discovery_id = d.id
  WHERE d.active = true
    AND d.status = 'published'
    AND public.is_content_available_for_school(ctx.school_id, 'experience', d.legacy_id)
    AND (d.age_group IS NULL OR ctx.age_group IS NULL OR lower(d.age_group) = lower(ctx.age_group) OR lower(d.age_group) = lower(replace(ctx.age_group, ' ', '')))
  ORDER BY d.sort_order, d.title;
$$;


ALTER FUNCTION "public"."student_get_discoveries"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."student_get_discovery"("p_discovery_id" "uuid") RETURNS TABLE("id" "uuid", "legacy_id" "text", "title" "text", "description" "text", "student_instruction" "text", "discovery_type" "text", "segment" "text", "age_group" "text", "book_legacy_id" "text", "page_start" integer, "page_end" integer, "bncc_codes" "text"[], "bncc_skills" "text"[], "experience_fields" "text"[], "resources" "jsonb", "completion_rule" "jsonb", "reward" "jsonb", "metadata" "jsonb", "hotspots" "jsonb", "progress_status" "text", "discovered_hotspots" "jsonb", "progress_data" "jsonb", "updated_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
  SELECT d.id, d.legacy_id, d.title, d.description, d.student_instruction, d.discovery_type, d.segment,
         d.age_group, d.book_legacy_id, d.page_start, d.page_end, d.bncc_codes, d.bncc_skills,
         d.experience_fields, d.resources, d.completion_rule, d.reward, d.metadata,
         COALESCE((
           SELECT jsonb_agg(jsonb_build_object(
             'id', h.id, 'legacy_id', h.legacy_id, 'title', h.title, 'description', h.description,
             'x_percent', h.x_percent, 'y_percent', h.y_percent, 'width_percent', h.width_percent,
             'height_percent', h.height_percent, 'action_type', h.action_type, 'target_type', h.target_type,
             'target_legacy_id', h.target_legacy_id, 'asset_legacy_id', h.asset_legacy_id,
             'audio_asset_legacy_id', h.audio_asset_legacy_id, 'accessibility_label', h.accessibility_label,
             'metadata', h.metadata
           ) ORDER BY h.sort_order, h.legacy_id)
           FROM public.discovery_hotspots h
           WHERE h.discovery_id = d.id
         ), '[]'::jsonb) AS hotspots,
         COALESCE(p.status, 'NOT_STARTED') AS progress_status,
         COALESCE(p.discovered_hotspots, '[]'::jsonb) AS discovered_hotspots,
         COALESCE(p.progress_data, '{}'::jsonb) AS progress_data,
         COALESCE(p.updated_at, d.updated_at) AS updated_at
  FROM public.current_early_childhood_student_context() ctx
  JOIN public.student_discoveries d ON d.id = p_discovery_id
  LEFT JOIN public.student_discovery_progress p ON p.student_id = ctx.student_id AND p.discovery_id = d.id
  WHERE public.student_can_read_discovery(d.id);
$$;


ALTER FUNCTION "public"."student_get_discovery"("p_discovery_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."student_get_game"("p_game_id" "uuid") RETURNS TABLE("id" "uuid", "legacy_id" "text", "title" "text", "description" "text", "student_instruction" "text", "game_type" "text", "engine" "text", "entrypoint" "text", "orientation" "text", "segment" "text", "age_group" "text", "bncc_codes" "text"[], "bncc_skills" "text"[], "pedagogical_metadata" "jsonb", "engine_config" "jsonb", "asset_manifest" "jsonb", "assets" "jsonb", "completion_rule" "jsonb", "score_rule" "jsonb", "result_schema" "jsonb", "reward_candidate" "jsonb", "related_content" "jsonb", "latest_attempt" "jsonb", "updated_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
  SELECT
    g.id,
    g.legacy_id,
    g.title,
    g.description,
    g.student_instruction,
    g.game_type,
    g.engine,
    g.entrypoint,
    g.orientation,
    g.segment,
    g.age_group,
    g.bncc_codes,
    g.bncc_skills,
    g.pedagogical_metadata,
    g.engine_config,
    g.asset_manifest,
    COALESCE(
      (
        SELECT jsonb_agg(
          jsonb_build_object(
            'id', a.id,
            'legacy_id', a.legacy_id,
            'role', a.role,
            'asset_type', a.asset_type,
            'title', a.title,
            'mime_type', a.mime_type,
            'storage_access', a.storage_access,
            'status', a.status,
            'metadata', a.metadata
          )
          ORDER BY a.sort_order, a.legacy_id
        )
        FROM public.student_game_assets a
        WHERE a.game_id = g.id
      ),
      '[]'::jsonb
    ) AS assets,
    g.completion_rule,
    g.score_rule,
    g.result_schema,
    g.reward_candidate,
    g.related_content,
    COALESCE(
      (
        SELECT jsonb_build_object(
          'id', a.id,
          'attempt_number', a.attempt_number,
          'status', a.status,
          'score_percent', a.score_percent,
          'duration_seconds', a.duration_seconds,
          'started_at', a.started_at,
          'completed_at', a.completed_at,
          'canonical_result', a.canonical_result
        )
        FROM public.current_early_childhood_student_context() ctx
        JOIN public.student_game_attempts a
          ON a.student_id = ctx.student_id
         AND a.game_id = g.id
        ORDER BY a.updated_at DESC
        LIMIT 1
      ),
      '{}'::jsonb
    ) AS latest_attempt,
    g.updated_at
  FROM public.student_games g
  WHERE g.id = p_game_id
    AND public.student_can_read_game(g.id);
$$;


ALTER FUNCTION "public"."student_get_game"("p_game_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."student_get_games"() RETURNS TABLE("id" "uuid", "legacy_id" "text", "title" "text", "description" "text", "student_instruction" "text", "game_type" "text", "engine" "text", "entrypoint" "text", "orientation" "text", "segment" "text", "age_group" "text", "bncc_codes" "text"[], "sort_order" integer, "duration_seconds" integer, "latest_attempt_status" "text", "latest_score_percent" integer, "latest_completed_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
  SELECT
    g.id,
    g.legacy_id,
    g.title,
    g.description,
    g.student_instruction,
    g.game_type,
    g.engine,
    g.entrypoint,
    g.orientation,
    g.segment,
    g.age_group,
    g.bncc_codes,
    g.sort_order,
    g.duration_seconds,
    latest.status AS latest_attempt_status,
    latest.score_percent AS latest_score_percent,
    latest.completed_at AS latest_completed_at,
    COALESCE(latest.updated_at, g.updated_at) AS updated_at
  FROM public.current_early_childhood_student_context() ctx
  JOIN public.student_games g ON true
  LEFT JOIN LATERAL (
    SELECT a.status, a.score_percent, a.completed_at, a.updated_at
    FROM public.student_game_attempts a
    WHERE a.student_id = ctx.student_id
      AND a.game_id = g.id
    ORDER BY a.updated_at DESC
    LIMIT 1
  ) latest ON true
  WHERE g.active = true
    AND g.status = 'published'
    AND public.is_content_available_for_school(ctx.school_id, 'game', g.legacy_id)
    AND (
      g.age_group IS NULL
      OR ctx.age_group IS NULL
      OR lower(g.age_group) = lower(ctx.age_group)
      OR lower(g.age_group) = lower(replace(ctx.age_group, ' ', ''))
    )
  ORDER BY g.sort_order, g.title;
$$;


ALTER FUNCTION "public"."student_get_games"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."student_get_gamification_profile"("p_student_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare v_student_id uuid; v_profile public.student_gamification_profiles%rowtype;
begin
  if p_student_id is null then select s.id into v_student_id from public.students s where s.user_id = auth.uid() and coalesce(s.status,'active') in ('active','ativo') order by s.updated_at desc nulls last, s.created_at desc nulls last limit 1; else v_student_id := p_student_id; end if;
  if v_student_id is null or not public.gamification_can_read_student(v_student_id) then raise exception 'Acesso negado ao perfil de gamificacao'; end if;
  v_profile := public.gamification_ensure_profile(v_student_id);
  return jsonb_build_object('profile',to_jsonb(v_profile),'transactions',coalesce((select jsonb_agg(to_jsonb(t) order by t.created_at desc) from (select * from public.gamification_transactions where student_id = v_student_id order by created_at desc limit 50) t),'[]'::jsonb),'inventory',coalesce((select jsonb_agg(to_jsonb(i)) from public.student_gamification_inventory i where i.student_id = v_student_id),'[]'::jsonb));
end; $$;


