CREATE OR REPLACE FUNCTION "public"."student_get_library_books"() RETURNS TABLE("book_id" "uuid", "legacy_id" "text", "title" "text", "description" "text", "category" "text", "segment" "text", "school_year" "text", "cover_url" "text", "has_cover" boolean, "has_reading_asset" boolean, "current_page" integer, "percent_complete" integer, "updated_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
  SELECT
    b.id AS book_id,
    nullif(btrim(b.legacy_id), '') AS legacy_id,
    b.titulo::text AS title,
    b.descricao::text AS description,
    coalesce(nullif(btrim(b.category), ''), nullif(btrim(b.ano_escolar), ''), 'Biblioteca')::text AS category,
    nullif(btrim(b.segment), '') AS segment,
    b.ano_escolar::text AS school_year,
    nullif(btrim(b.capa_url), '') AS cover_url,
    nullif(btrim(b.capa_url), '') IS NOT NULL AS has_cover,
    nullif(btrim(b.pdf_url), '') IS NOT NULL AS has_reading_asset,
    coalesce(bp.current_page, 1) AS current_page,
    coalesce(bp.percent_complete, 0) AS percent_complete,
    bp.updated_at
  FROM public.books b
  JOIN public.current_student_library_enrollments() ce ON true
  LEFT JOIN public.book_progress bp
    ON bp.book_id = b.id
   AND bp.student_id = ce.student_id
  WHERE coalesce(b.ativo, false) = true
    AND (
      public.is_content_available_for_school(
        ce.school_id,
        'book',
        coalesce(nullif(btrim(b.legacy_id), ''), b.id::text)
      )
      OR public.is_content_available_for_school(
        ce.school_id,
        'book',
        b.id::text
      )
    )
    AND (
      b.ano_escolar IS NULL
      OR btrim(b.ano_escolar) = ''
      OR lower(btrim(b.ano_escolar)) = lower(btrim(coalesce(ce.class_school_year, ce.school_year, '')))
    )
  ORDER BY b.created_at DESC NULLS LAST, b.titulo ASC;
$$;


ALTER FUNCTION "public"."student_get_library_books"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."student_get_library_read_asset"("p_book_id" "uuid") RETURNS TABLE("book_id" "uuid", "legacy_id" "text", "title" "text", "asset_kind" "text", "asset_bucket" "text", "asset_path" "text", "mime_type" "text", "expires_in_seconds" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_book public.books;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Usuario autenticado obrigatorio.' USING errcode = '42501';
  END IF;

  IF NOT public.student_can_read_library_book(p_book_id) THEN
    RAISE EXCEPTION 'Livro nao autorizado para este aluno.' USING errcode = '42501';
  END IF;

  SELECT *
    INTO v_book
  FROM public.books b
  WHERE b.id = p_book_id
    AND coalesce(b.ativo, false) = true
  LIMIT 1;

  IF v_book.id IS NULL THEN
    RAISE EXCEPTION 'Livro nao encontrado.' USING errcode = 'P0002';
  END IF;

  IF nullif(btrim(v_book.reading_asset_bucket), '') IS NULL
     OR nullif(btrim(v_book.reading_asset_path), '') IS NULL THEN
    RAISE EXCEPTION 'Asset de leitura nao configurado.' USING errcode = 'P0002';
  END IF;

  RETURN QUERY
  SELECT
    v_book.id AS book_id,
    nullif(btrim(v_book.legacy_id), '') AS legacy_id,
    v_book.titulo::text AS title,
    coalesce(nullif(btrim(v_book.reading_asset_kind), ''), 'pdf')::text AS asset_kind,
    btrim(v_book.reading_asset_bucket)::text AS asset_bucket,
    btrim(v_book.reading_asset_path)::text AS asset_path,
    coalesce(nullif(btrim(v_book.reading_asset_mime_type), ''), 'application/pdf')::text AS mime_type,
    300 AS expires_in_seconds;
END;
$$;


ALTER FUNCTION "public"."student_get_library_read_asset"("p_book_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."student_get_personal_schedule"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_context record;
  v_schedule public.student_personal_schedules%ROWTYPE;
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'Sessao do aluno obrigatoria.' USING errcode = '42501';
  END IF;

  SELECT * INTO v_context FROM public.student_personal_schedule_context();
  IF v_context.student_id IS NULL THEN
    RAISE EXCEPTION 'Aluno autenticado nao encontrado.' USING errcode = '42501';
  END IF;

  SELECT * INTO v_schedule
  FROM public.student_personal_schedules
  WHERE student_id = v_context.student_id;

  RETURN jsonb_build_object(
    'student_id', v_context.student_id,
    'school_id', v_context.school_id,
    'class_id', v_context.class_id,
    'school_year', v_context.school_year,
    'slots', COALESCE(v_schedule.slots, public.student_personal_schedule_default_slots()),
    'exists', v_schedule.student_id IS NOT NULL,
    'updated_at', v_schedule.updated_at
  );
END;
$$;


ALTER FUNCTION "public"."student_get_personal_schedule"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."student_get_recomposition_context"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_student_id uuid := public.avalia_current_student_id(); v_payload jsonb;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if v_student_id is null then raise exception 'STUDENT_CONTEXT_REQUIRED'; end if;
  select jsonb_build_object('student_id', v_student_id, 'plans', coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'title', p.title, 'target_skill', p.target_skill, 'descriptor', p.descriptor, 'objective', p.objective, 'status', p.status, 'period_start', p.period_start, 'period_end', p.period_end, 'resources', coalesce((select jsonb_agg(jsonb_build_object('content_type', r.content_type, 'content_id', r.content_id, 'content_title', r.content_title, 'status', r.status) order by r.created_at) from public.recomposition_plan_resources r where r.plan_id = p.id and r.status <> 'removed'), '[]'::jsonb), 'last_event_at', (select max(te.created_at) from public.recomposition_tracking_events te where te.plan_id = p.id and (te.student_id is null or te.student_id = v_student_id))) order by p.created_at desc), '[]'::jsonb)) into v_payload
  from public.recomposition_plans p join public.recomposition_plan_students ps on ps.plan_id = p.id
  where ps.student_id = v_student_id and ps.status <> 'removed' and p.status in ('active', 'in_progress', 'completed');
  return coalesce(v_payload, jsonb_build_object('student_id', v_student_id, 'plans', '[]'::jsonb));
end;
$$;


ALTER FUNCTION "public"."student_get_recomposition_context"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."student_get_xp_history"("p_limit" integer DEFAULT 20) RETURNS TABLE("id" "uuid", "source_type" "text", "source_id" "uuid", "source_legacy_id" "text", "event_type" "text", "event_key" "text", "reward_rule" "text", "xp_amount" integer, "metadata" "jsonb", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_student_id uuid;
  v_limit integer := least(greatest(coalesce(p_limit, 20), 1), 100);
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Usuario autenticado obrigatorio.' USING errcode = '42501';
  END IF;

  v_student_id := public.student_gamification_current_student_id();
  IF v_student_id IS NULL THEN
    RAISE EXCEPTION 'Aluno ativo nao encontrado.' USING errcode = '42501';
  END IF;

  RETURN QUERY
  SELECT
    l.id,
    l.source_type,
    l.source_id,
    l.source_legacy_id,
    l.event_type,
    l.event_key,
    l.reward_rule,
    l.xp_amount,
    l.metadata,
    l.created_at
  FROM public.student_xp_ledger l
  WHERE l.student_id = v_student_id
  ORDER BY l.created_at DESC
  LIMIT v_limit;
END;
$$;


ALTER FUNCTION "public"."student_get_xp_history"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."student_get_xp_summary"() RETURNS TABLE("student_id" "uuid", "total_xp" integer, "level_number" integer, "level_floor_xp" integer, "next_level_xp" integer, "credits_count" integer, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_student_id uuid;
  v_total integer;
  v_count integer;
  v_updated timestamptz;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Usuario autenticado obrigatorio.' USING errcode = '42501';
  END IF;

  v_student_id := public.student_gamification_current_student_id();
  IF v_student_id IS NULL THEN
    RAISE EXCEPTION 'Aluno ativo nao encontrado.' USING errcode = '42501';
  END IF;

  SELECT
    COALESCE(SUM(xp_amount), 0)::integer,
    COUNT(*)::integer,
    MAX(created_at)
    INTO v_total, v_count, v_updated
  FROM public.student_xp_ledger
  WHERE student_xp_ledger.student_id = v_student_id;

  RETURN QUERY
  SELECT
    v_student_id,
    v_total,
    (v_total / 100) + 1,
    (v_total / 100) * 100,
    ((v_total / 100) + 1) * 100,
    v_count,
    v_updated;
END;
$$;


ALTER FUNCTION "public"."student_get_xp_summary"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."student_institutional_login_check"("p_login" "text", "p_plain_password" "text", "p_request_fingerprint" "text" DEFAULT NULL::"text", "p_user_agent" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_login text := upper(btrim(coalesce(p_login, '')));
  v_password text := coalesce(p_plain_password, '');
  v_fingerprint text := nullif(btrim(coalesce(p_request_fingerprint, '')), '');
  v_credential public.student_institutional_credentials%rowtype;
  v_failed_count integer := 0;
  v_last_failure timestamptz;
  v_lockout_until timestamptz;
  v_now timestamptz := now();
  v_failure_code text;
begin
  if v_login = '' or v_password = '' then
    v_failure_code := 'invalid_credentials';
    insert into public.student_institutional_login_attempts (
      normalized_login,
      request_fingerprint,
      success,
      failure_code,
      metadata
    ) values (
      coalesce(nullif(v_login, ''), 'EMPTY'),
      v_fingerprint,
      false,
      v_failure_code,
      jsonb_build_object('reason', 'missing_login_or_password')
    );

    return jsonb_build_object('ok', false, 'code', v_failure_code);
  end if;

  select count(*)::integer, max(created_at)
    into v_failed_count, v_last_failure
  from public.student_institutional_login_attempts
  where created_at >= v_now - interval '15 minutes'
    and success = false
    and (
      normalized_login = v_login
      or (v_fingerprint is not null and request_fingerprint = v_fingerprint)
    )
    and coalesce(failure_code, '') <> 'temporary_lockout';

  if v_failed_count >= 8 then
    v_lockout_until := coalesce(v_last_failure, v_now) + interval '15 minutes';
    if v_lockout_until > v_now then
      insert into public.student_institutional_login_attempts (
        normalized_login,
        request_fingerprint,
        success,
        failure_code,
        metadata
      ) values (
        v_login,
        v_fingerprint,
        false,
        'temporary_lockout',
        jsonb_build_object(
          'failed_attempts_window', v_failed_count,
          'lockout_until', v_lockout_until,
          'ua_present', nullif(btrim(coalesce(p_user_agent, '')), '') is not null
        )
      );

      return jsonb_build_object(
        'ok', false,
        'code', 'temporary_lockout',
        'retry_after_seconds', greatest(1, ceil(extract(epoch from (v_lockout_until - v_now)))::integer)
      );
    end if;
  end if;

  select *
    into v_credential
  from public.student_institutional_credentials
  where upper(login) = v_login
  limit 1;

  if v_credential.id is null then
    insert into public.student_institutional_login_attempts (
      normalized_login,
      request_fingerprint,
      success,
      failure_code,
      metadata
    ) values (
      v_login,
      v_fingerprint,
      false,
      'invalid_credentials',
      jsonb_build_object('credential_found', false)
    );

    return jsonb_build_object('ok', false, 'code', 'invalid_credentials');
  end if;

  if lower(coalesce(v_credential.status, '')) = 'blocked' then
    insert into public.student_institutional_login_attempts (
      credential_id,
      student_id,
      school_id,
      normalized_login,
      request_fingerprint,
      success,
      failure_code,
      metadata
    ) values (
      v_credential.id,
      v_credential.student_id,
      v_credential.school_id,
      v_login,
      v_fingerprint,
      false,
      'blocked',
      jsonb_build_object('status', v_credential.status)
    );

    return jsonb_build_object('ok', false, 'code', 'blocked');
  end if;

  if lower(coalesce(v_credential.status, '')) = 'pending_auth' then
    insert into public.student_institutional_login_attempts (
      credential_id,
      student_id,
      school_id,
      normalized_login,
      request_fingerprint,
      success,
      failure_code,
      metadata
    ) values (
      v_credential.id,
      v_credential.student_id,
      v_credential.school_id,
      v_login,
      v_fingerprint,
      false,
      'pending_auth',
      jsonb_build_object('status', v_credential.status)
    );

    return jsonb_build_object('ok', false, 'code', 'pending_auth');
  end if;

  if lower(coalesce(v_credential.status, '')) <> 'active'
    or nullif(v_credential.password_hash, '') is null
    or v_credential.auth_user_id is null
    or nullif(v_credential.technical_email, '') is null
  then
    insert into public.student_institutional_login_attempts (
      credential_id,
      student_id,
      school_id,
      normalized_login,
      request_fingerprint,
      success,
      failure_code,
      metadata
    ) values (
      v_credential.id,
      v_credential.student_id,
      v_credential.school_id,
      v_login,
      v_fingerprint,
      false,
      'credential_not_ready',
      jsonb_build_object('status', v_credential.status)
    );

    return jsonb_build_object('ok', false, 'code', 'pending_auth');
  end if;

  if v_credential.password_hash <> extensions.crypt(v_password, v_credential.password_hash) then
    insert into public.student_institutional_login_attempts (
      credential_id,
      student_id,
      school_id,
      normalized_login,
      request_fingerprint,
      success,
      failure_code,
      metadata
    ) values (
      v_credential.id,
      v_credential.student_id,
      v_credential.school_id,
      v_login,
      v_fingerprint,
      false,
      'invalid_credentials',
      jsonb_build_object('credential_found', true)
    );

    return jsonb_build_object('ok', false, 'code', 'invalid_credentials');
  end if;

  update public.student_institutional_credentials
  set last_sign_in_at = v_now,
      updated_at = now()
  where id = v_credential.id
  returning * into v_credential;

  insert into public.student_institutional_login_attempts (
    credential_id,
    student_id,
    school_id,
    normalized_login,
    request_fingerprint,
    success,
    failure_code,
    metadata
  ) values (
    v_credential.id,
    v_credential.student_id,
    v_credential.school_id,
    v_login,
    v_fingerprint,
    true,
    null,
    jsonb_build_object('auth_user_id', v_credential.auth_user_id)
  );

  return jsonb_build_object(
    'ok', true,
    'credential_id', v_credential.id,
    'student_id', v_credential.student_id,
    'school_id', v_credential.school_id,
    'login', v_credential.login,
    'status', v_credential.status,
    'auth_user_id', v_credential.auth_user_id,
    'technical_email', v_credential.technical_email
  );
end;
$$;


ALTER FUNCTION "public"."student_institutional_login_check"("p_login" "text", "p_plain_password" "text", "p_request_fingerprint" "text", "p_user_agent" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."student_list_assessment_assignments"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_student_id uuid;
  v_payload jsonb;
begin
  if auth.uid() is null then raise exception 'Usuario autenticado obrigatorio.' using errcode = '42501'; end if;
  select public.avalia_current_student_id() into v_student_id;
  if v_student_id is null then raise exception 'Aluno institucional ativo nao encontrado.' using errcode = '42501'; end if;
  select jsonb_build_object(
    'assignments', coalesce((
      select jsonb_agg(row_payload order by available_from desc)
      from (
        select aa.available_from,
          jsonb_build_object(
            'id', aa.id,
            'school_id', aa.school_id,
            'assessment_id', aa.assessment_id,
            'target_type', aa.target_type,
            'class_id', aa.class_id,
            'student_id', aa.student_id,
            'available_from', aa.available_from,
            'available_until', aa.available_until,
            'time_limit_minutes', aa.time_limit_minutes,
            'max_attempts', aa.max_attempts,
            'status', aa.status,
            'application_status', aa.application_status,
            'token_required', aa.token_required,
            'shuffle_questions', aa.shuffle_questions,
            'shuffle_alternatives', aa.shuffle_alternatives,
            'assessment', jsonb_build_object(
              'id', a.id,
              'title', a.title,
              'description', a.description,
              'component', a.component,
              'school_year', a.school_year,
              'instructions', a.instructions,
              'total_points', a.total_points,
              'status', a.status,
              'questions', coalesce(q.questions, '[]'::jsonb)
            )
          ) as row_payload
        from public.assessment_assignments aa
        join public.assessments a on a.id = aa.assessment_id
        left join lateral (
          select at.* from public.assessment_attempts at
          where at.assignment_id = aa.id and at.student_id = v_student_id
          order by at.started_at desc limit 1
        ) at on true
        left join lateral (
          select jsonb_agg(
            jsonb_build_object(
              'id', aq.id,
              'question_id', aq.question_id,
              'position', aq.position,
              'points', aq.points,
              'question', jsonb_build_object(
                'id', qi.id,
                'code', qi.code,
                'internal_title', qi.internal_title,
                'statement', qi.statement,
                'base_text', qi.base_text,
                'bncc_skill', qi.bncc_skill,
                'question_type', qi.question_type,
                'alternatives', coalesce(alt.alternatives, '[]'::jsonb)
              )
            )
            order by case when at.question_order is not null and aq.question_id = any(at.question_order) then array_position(at.question_order, aq.question_id) else aq.position end
          ) as questions
          from public.assessment_questions aq
          join public.question_items qi on qi.id = aq.question_id
          left join lateral (
            select jsonb_agg(
              jsonb_build_object('id', qa.id, 'label', qa.label, 'body', qa.body, 'position', qa.position)
              order by case
                when at.alternative_order ? qi.id::text then (
                  select ordinality
                  from jsonb_array_elements_text(at.alternative_order -> qi.id::text) with ordinality alt_order(id, ordinality)
                  where alt_order.id::uuid = qa.id limit 1
                )
                else qa.position
              end
            ) as alternatives
            from public.question_alternatives qa
            where qa.question_id = qi.id
          ) alt on true
          where aq.assessment_id = a.id
            and (aa.booklet_id is null or exists (select 1 from public.assessment_booklet_questions abq where abq.booklet_id = aa.booklet_id and abq.assessment_question_id = aq.id))
        ) q on true
        where public.avalia_student_can_access_assignment(aa.id, v_student_id)
      ) assignments_scope
    ), '[]'::jsonb),
    'attempts', coalesce((
      select jsonb_agg(to_jsonb(at) || jsonb_build_object('progress', public.avalia_plus_build_progress(at.id), 'responses', coalesce((select jsonb_agg(to_jsonb(ar) order by ar.answered_at asc) from public.assessment_responses ar where ar.attempt_id = at.id), '[]'::jsonb)) order by at.started_at desc)
      from public.assessment_attempts at where at.student_id = v_student_id
    ), '[]'::jsonb)
  ) into v_payload;
  return v_payload;
end;
$$;


ALTER FUNCTION "public"."student_list_assessment_assignments"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."student_list_calendar_events"("p_from" "date", "p_to" "date") RETURNS TABLE("source_type" "text", "source_id" "uuid", "school_id" "uuid", "class_id" "uuid", "student_id" "uuid", "event_date" "date", "start_time" time without time zone, "end_time" time without time zone, "title" "text", "description" "text", "event_type" "text", "status" "text", "action_label" "text", "href" "text", "created_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  with current_student as (
    select s.id as student_id, e.school_id, e.class_id
    from public.students s
    join public.enrollments e on e.student_id = s.id
    left join public.users u on u.id = s.user_id
    where e.status = 'active'
      and e.enrolled_at <= now()
      and (e.ended_at is null or e.ended_at > now())
      and coalesce(s.status, 'active') = 'active'
      and (
        s.user_id = auth.uid()
        or lower(coalesce(u.email, '')) = lower(coalesce(auth.jwt() ->> 'email', ''))
      )
    order by e.enrolled_at desc
    limit 1
  ),
  events as (
    select
      'class_calendar'::text as source_type,
      cce.id as source_id,
      cce.school_id,
      cce.class_id,
      cs.student_id,
      cce.entry_date as event_date,
      cce.start_time,
      cce.end_time,
      cce.title,
      cce.description,
      cce.entry_type as event_type,
      cce.status,
      'Ver na Minha Semana'::text as action_label,
      null::text as href,
      cce.created_at
    from current_student cs
    join public.class_calendar_entries cce
      on cce.class_id = cs.class_id
     and cce.school_id = cs.school_id
    where cce.status = 'published'
      and cce.entry_date between p_from and p_to

    union all

    select
      'school_calendar'::text,
      sce.id,
      sce.school_id,
      sce.class_id,
      cs.student_id,
      sce.event_date,
      sce.start_time,
      sce.end_time,
      sce.title,
      sce.description,
      sce.event_type,
      sce.status,
      'Ver na agenda'::text,
      null::text,
      sce.created_at
    from current_student cs
    join public.school_calendar_events sce
      on sce.school_id = cs.school_id
     and (sce.class_id is null or sce.class_id = cs.class_id)
    where sce.status = 'published'
      and sce.event_date between p_from and p_to

    union all

    select
      'assessment_available'::text,
      aa.id,
      aa.school_id,
      aa.class_id,
      cs.student_id,
      aa.available_from::date,
      aa.available_from::time,
      null::time,
      ('Avaliação disponível: ' || coalesce(a.title, 'Avalia+'))::text,
      coalesce(a.description, 'Avaliação publicada para a turma.')::text,
      'avaliacao'::text,
      aa.status,
      'Abrir Avalia+'::text,
      'aluno.html?view=avaliacoes'::text,
      aa.created_at
    from current_student cs
    join public.assessment_assignments aa
      on aa.school_id = cs.school_id
     and aa.class_id = cs.class_id
     and (
       (aa.target_type = 'class' and aa.student_id is null)
       or (aa.target_type = 'student' and aa.student_id = cs.student_id)
     )
    join public.assessments a on a.id = aa.assessment_id
    where aa.status = 'published'
      and aa.available_from::date between p_from and p_to

    union all

    select
      'assessment_deadline'::text,
      aa.id,
      aa.school_id,
      aa.class_id,
      cs.student_id,
      aa.available_until::date,
      aa.available_until::time,
      null::time,
      ('Prazo da avaliação: ' || coalesce(a.title, 'Avalia+'))::text,
      coalesce(a.description, 'Prazo para entrega da avaliação.')::text,
      'avaliacao'::text,
      aa.status,
      'Abrir Avalia+'::text,
      'aluno.html?view=avaliacoes'::text,
      aa.created_at
    from current_student cs
    join public.assessment_assignments aa
      on aa.school_id = cs.school_id
     and aa.class_id = cs.class_id
     and (
       (aa.target_type = 'class' and aa.student_id is null)
       or (aa.target_type = 'student' and aa.student_id = cs.student_id)
     )
    join public.assessments a on a.id = aa.assessment_id
    where aa.status = 'published'
      and aa.available_until is not null
      and aa.available_until::date between p_from and p_to
  )
  select *
  from events
  order by event_date asc, start_time asc nulls last, created_at asc;
$$;


ALTER FUNCTION "public"."student_list_calendar_events"("p_from" "date", "p_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."student_list_institutional_activities"() RETURNS TABLE("activity_id" "uuid", "title" "text", "description" "text", "school_year" "text", "xp" integer, "status" "text", "progress_status" "text", "started_at" timestamp with time zone, "completed_at" timestamp with time zone, "created_at" timestamp without time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
  SELECT
    a.id AS activity_id,
    a.titulo::text AS title,
    a.descricao AS description,
    a.ano_escolar::text AS school_year,
    a.xp,
    CASE WHEN coalesce(a.ativa, true) THEN 'published' ELSE 'inactive' END AS status,
    coalesce(ap.status, 'pendente') AS progress_status,
    ap.iniciado_em AS started_at,
    ap.concluido_em AS completed_at,
    a.created_at
  FROM public.student_get_context() ctx
  JOIN public.activities a ON true
  LEFT JOIN public.activity_progress ap
    ON ap.student_id = ctx.student_id
   AND ap.activity_id = a.id
  WHERE auth.uid() IS NOT NULL
    AND ctx.segment IN ('ENSINO_FUNDAMENTAL', 'ENSINO_MEDIO')
    AND coalesce(a.ativa, true) = true
    AND public.is_content_available_for_school(ctx.school_id, 'activity', a.id::text)
    AND (
      a.ano_escolar IS NULL
      OR ctx.school_year IS NULL
      OR lower(a.ano_escolar::text) = lower(ctx.school_year)
      OR lower(a.ano_escolar::text) = lower(replace(ctx.school_year, ' ', ''))
    )
  ORDER BY a.created_at DESC NULLS LAST, a.titulo ASC;
$$;


ALTER FUNCTION "public"."student_list_institutional_activities"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."student_personal_schedule_context"() RETURNS TABLE("student_id" "uuid", "school_id" "uuid", "class_id" "uuid", "school_year" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    s.id,
    COALESCE(e.school_id, s.school_id) AS school_id,
    COALESCE(e.class_id, s.class_id) AS class_id,
    COALESCE(e.school_year, c.school_year, s.turma) AS school_year
  FROM public.students s
  LEFT JOIN public.enrollments e
    ON e.student_id = s.id
   AND lower(COALESCE(e.status, '')) IN ('active', 'ativo')
  LEFT JOIN public.classes c
    ON c.id = COALESCE(e.class_id, s.class_id)
  WHERE s.user_id = (SELECT auth.uid())
    AND lower(COALESCE(s.status, '')) IN ('active', 'ativo')
  ORDER BY e.created_at DESC NULLS LAST, s.created_at DESC NULLS LAST
  LIMIT 1;
$$;


ALTER FUNCTION "public"."student_personal_schedule_context"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."student_personal_schedule_default_slots"() RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT jsonb_agg(
    jsonb_build_object(
      'slot', slot_number,
      'start_time', '',
      'end_time', '',
      'monday', '',
      'tuesday', '',
      'wednesday', '',
      'thursday', '',
      'friday', ''
    )
    ORDER BY slot_number
  )
  FROM generate_series(1, 6) AS slot_number;
$$;


ALTER FUNCTION "public"."student_personal_schedule_default_slots"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."student_personal_schedule_is_valid"("p_slots" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_item jsonb;
  v_slot integer;
  v_start text;
  v_end text;
  v_key text;
BEGIN
  IF jsonb_typeof(p_slots) <> 'array' OR jsonb_array_length(p_slots) <> 6 THEN
    RETURN false;
  END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_slots)
  LOOP
    IF jsonb_typeof(v_item) <> 'object' THEN
      RETURN false;
    END IF;

    v_slot := NULLIF(v_item->>'slot', '')::integer;
    IF v_slot IS NULL OR v_slot < 1 OR v_slot > 6 THEN
      RETURN false;
    END IF;

    v_start := COALESCE(v_item->>'start_time', '');
    v_end := COALESCE(v_item->>'end_time', '');

    IF v_start <> '' AND v_start !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' THEN
      RETURN false;
    END IF;
    IF v_end <> '' AND v_end !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' THEN
      RETURN false;
    END IF;
    IF v_start <> '' AND v_end <> '' AND v_end::time <= v_start::time THEN
      RETURN false;
    END IF;

    FOREACH v_key IN ARRAY ARRAY['monday', 'tuesday', 'wednesday', 'thursday', 'friday']
    LOOP
      IF length(COALESCE(v_item->>v_key, '')) > 80 THEN
        RETURN false;
      END IF;
    END LOOP;
  END LOOP;

  RETURN (
    SELECT count(DISTINCT NULLIF(item->>'slot', '')::integer) = 6
    FROM jsonb_array_elements(p_slots) AS item
  );
EXCEPTION
  WHEN others THEN
    RETURN false;
END;
$_$;


ALTER FUNCTION "public"."student_personal_schedule_is_valid"("p_slots" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."student_purchase_store_item"("p_item_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare v_student_id uuid; v_profile public.student_gamification_profiles%rowtype; v_item public.gamification_store_items%rowtype; v_tx public.gamification_transactions%rowtype;
begin
  select id into v_student_id from public.students where user_id = auth.uid() and coalesce(status,'active') in ('active','ativo') order by updated_at desc nulls last, created_at desc nulls last limit 1;
  if v_student_id is null or not public.institutional_is_current_student(v_student_id) then raise exception 'Aluno autenticado nao encontrado'; end if;
  select * into v_item from public.gamification_store_items where id = p_item_id and availability = 'available'; if v_item.id is null then raise exception 'Item indisponivel'; end if;
  v_profile := public.gamification_ensure_profile(v_student_id);
  if v_item.school_id is not null and v_item.school_id <> v_profile.school_id then raise exception 'Item nao pertence a escola do aluno'; end if;
  if exists(select 1 from public.student_gamification_inventory where student_id = v_student_id and item_id = p_item_id) then raise exception 'Item ja adquirido'; end if;
  if v_profile.coin_balance < v_item.price_coins then raise exception 'Saldo insuficiente'; end if;
  update public.student_gamification_profiles set coin_balance = coin_balance - v_item.price_coins, updated_at = now() where student_id = v_student_id returning * into v_profile;
  insert into public.gamification_transactions(student_id,school_id,class_id,transaction_type,currency,amount,balance_after,reason,source_type,source_id,idempotency_key,created_by,metadata)
  values(v_student_id,v_profile.school_id,v_profile.class_id,'debit','COIN',v_item.price_coins,v_profile.coin_balance,'Compra na loja virtual','STORE',p_item_id::text,v_student_id::text || ':STORE_PURCHASE:' || p_item_id::text,auth.uid(),jsonb_build_object('item_key',v_item.item_key)) returning * into v_tx;
  insert into public.student_gamification_inventory(student_id, school_id, item_id, acquisition_type, transaction_id) values(v_student_id, v_profile.school_id, p_item_id, 'purchase', v_tx.id);
  return jsonb_build_object('transaction',to_jsonb(v_tx),'item',to_jsonb(v_item),'profile',to_jsonb(v_profile));
end; $$;


