    CONSTRAINT "assessment_responses_has_answer_check" CHECK ((("selected_alternative_id" IS NOT NULL) OR (NULLIF("btrim"(COALESCE("response_text", ''::"text")), ''::"text") IS NOT NULL))),
    CONSTRAINT "assessment_responses_origin_check" CHECK (("origin" = ANY (ARRAY['ONLINE'::"text", 'OFFLINE_IMPORT'::"text", 'SCANNED_PHYSICAL'::"text"])))
