COMMENT ON TABLE "public"."assessment_responses" IS 'Avalia+ V1: respostas do aluno. V1 prioriza multipla escolha; response_text fica reservado para discursivas futuras.';



CREATE OR REPLACE FUNCTION "public"."student_save_assessment_response"("p_attempt_id" "uuid", "p_question_id" "uuid", "p_selected_alternative_id" "uuid" DEFAULT NULL::"uuid", "p_response_text" "text" DEFAULT NULL::"text") RETURNS "public"."assessment_responses"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_student_id uuid;
  v_attempt public.assessment_attempts%rowtype;
  v_response public.assessment_responses%rowtype;
  v_response_text text := nullif(btrim(coalesce(p_response_text, '')), '');
begin
  if auth.uid() is null then
    raise exception 'Usuario autenticado obrigatorio.' using errcode = '42501';
  end if;

  select public.avalia_current_student_id() into v_student_id;

  select *
    into v_attempt
  from public.assessment_attempts
  where id = p_attempt_id;

  if v_attempt.id is null or v_attempt.student_id <> v_student_id then
    raise exception 'Tentativa nao pertence ao aluno autenticado.' using errcode = '42501';
  end if;

  if v_attempt.status <> 'in_progress' then
    raise exception 'Tentativa ja encerrada.' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.assessment_questions aq
    where aq.assessment_id = v_attempt.assessment_id
      and aq.question_id = p_question_id
  ) then
    raise exception 'Questao nao pertence a avaliacao.' using errcode = '42501';
  end if;

  if p_selected_alternative_id is not null and not exists (
    select 1
    from public.question_alternatives qa
    where qa.id = p_selected_alternative_id
      and qa.question_id = p_question_id
  ) then
    raise exception 'Alternativa nao pertence a questao.' using errcode = '42501';
  end if;

  if p_selected_alternative_id is null and v_response_text is null then
    raise exception 'Informe uma alternativa ou resposta.' using errcode = '22023';
  end if;

  insert into public.assessment_responses (
    attempt_id,
    question_id,
    selected_alternative_id,
    response_text,
    is_correct,
    score_awarded,
    answered_at
  )
  values (
    p_attempt_id,
    p_question_id,
    p_selected_alternative_id,
    v_response_text,
    null,
    null,
    now()
  )
  on conflict (attempt_id, question_id)
  do update
     set selected_alternative_id = excluded.selected_alternative_id,
         response_text = excluded.response_text,
         is_correct = null,
         score_awarded = null,
         answered_at = now()
  returning * into v_response;

  return v_response;
end;
$$;


ALTER FUNCTION "public"."student_save_assessment_response"("p_attempt_id" "uuid", "p_question_id" "uuid", "p_selected_alternative_id" "uuid", "p_response_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."student_save_assessment_response_v2"("p_attempt_id" "uuid", "p_question_id" "uuid", "p_selected_alternative_id" "uuid" DEFAULT NULL::"uuid", "p_response_text" "text" DEFAULT NULL::"text", "p_autosave_sequence" integer DEFAULT 1, "p_client_state" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_student_id uuid;
  v_attempt public.assessment_attempts%rowtype;
  v_response public.assessment_responses%rowtype;
begin
  if auth.uid() is null then raise exception 'Usuario autenticado obrigatorio.' using errcode = '42501'; end if;
  select public.avalia_current_student_id() into v_student_id;
  select * into v_attempt from public.assessment_attempts where id = p_attempt_id for update;
  if v_student_id is null or v_attempt.id is null or v_attempt.student_id <> v_student_id or v_attempt.status <> 'in_progress' then
    raise exception 'Tentativa nao autorizada para autosave.' using errcode = '42501';
  end if;
  if v_attempt.deadline_at is not null and v_attempt.deadline_at <= now() then
    update public.assessment_attempts set status = 'expired', application_status = 'INCOMPLETA', remaining_seconds = 0, submitted_reason = 'time_expired', last_autosaved_at = now() where id = p_attempt_id;
    raise exception 'Tempo de aplicacao encerrado.' using errcode = '42501';
  end if;
  if not exists (select 1 from public.assessment_questions aq where aq.assessment_id = v_attempt.assessment_id and aq.question_id = p_question_id) then
    raise exception 'Questao nao pertence a avaliacao.' using errcode = '42501';
  end if;
  if p_selected_alternative_id is not null and not exists (select 1 from public.question_alternatives qa where qa.id = p_selected_alternative_id and qa.question_id = p_question_id) then
    raise exception 'Alternativa invalida para a questao.' using errcode = '42501';
  end if;
  insert into public.assessment_responses (attempt_id, question_id, selected_alternative_id, response_text, answered_at, answer_payload, autosave_sequence, client_saved_at)
  values (p_attempt_id, p_question_id, p_selected_alternative_id, nullif(p_response_text, ''), now(), jsonb_build_object('source', 'autosave_v2', 'has_text', nullif(p_response_text, '') is not null, 'has_objective', p_selected_alternative_id is not null), greatest(coalesce(p_autosave_sequence, 1), 1), now())
  on conflict (attempt_id, question_id)
  do update set selected_alternative_id = excluded.selected_alternative_id,
                response_text = excluded.response_text,
                answered_at = now(),
                answer_payload = excluded.answer_payload,
                autosave_sequence = greatest(public.assessment_responses.autosave_sequence, excluded.autosave_sequence),
                client_saved_at = now()
  returning * into v_response;
  update public.assessment_attempts
     set last_autosaved_at = now(),
         remaining_seconds = case when deadline_at is null then remaining_seconds else greatest(0, floor(extract(epoch from (deadline_at - now())))::integer) end,
         progress = public.avalia_plus_build_progress(id),
         client_state = coalesce(p_client_state, '{}'::jsonb)
   where id = p_attempt_id returning * into v_attempt;
  insert into public.assessment_attempt_events (attempt_id, assignment_id, student_id, actor_user_id, event_type, metadata)
  values (p_attempt_id, v_attempt.assignment_id, v_student_id, auth.uid(), 'AUTOSAVED', jsonb_build_object('question_id', p_question_id));
  return jsonb_build_object('response', to_jsonb(v_response), 'attempt', to_jsonb(v_attempt));
end;
$$;


ALTER FUNCTION "public"."student_save_assessment_response_v2"("p_attempt_id" "uuid", "p_question_id" "uuid", "p_selected_alternative_id" "uuid", "p_response_text" "text", "p_autosave_sequence" integer, "p_client_state" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."student_save_personal_schedule"("p_slots" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_context record;
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'Sessao do aluno obrigatoria.' USING errcode = '42501';
  END IF;

  IF NOT public.student_personal_schedule_is_valid(p_slots) THEN
    RAISE EXCEPTION 'Horario de aula invalido.' USING errcode = '22023';
  END IF;

  SELECT * INTO v_context FROM public.student_personal_schedule_context();
  IF v_context.student_id IS NULL OR v_context.school_id IS NULL OR v_context.class_id IS NULL THEN
    RAISE EXCEPTION 'Contexto escolar do aluno nao encontrado.' USING errcode = '42501';
  END IF;

  INSERT INTO public.student_personal_schedules (
    student_id, school_id, class_id, school_year, slots, updated_by
  )
  VALUES (
    v_context.student_id, v_context.school_id, v_context.class_id, v_context.school_year, p_slots, (SELECT auth.uid())
  )
  ON CONFLICT (student_id)
  DO UPDATE SET
    school_id = EXCLUDED.school_id,
    class_id = EXCLUDED.class_id,
    school_year = EXCLUDED.school_year,
    slots = EXCLUDED.slots,
    updated_at = now(),
    updated_by = (SELECT auth.uid());

  RETURN public.student_get_personal_schedule();
END;
$$;


ALTER FUNCTION "public"."student_save_personal_schedule"("p_slots" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."student_save_writing_draft"("p_prompt_id" "uuid", "p_text_content" "text", "p_attachment" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_student_id uuid := public.writing_current_student_id();
  v_prompt public.writing_prompts%rowtype;
  v_submission public.writing_submissions%rowtype;
  v_version public.writing_submission_versions%rowtype;
  v_version_number integer;
begin
  if auth.uid() is null then
    raise exception 'AUTH_REQUIRED' using errcode = '42501';
  end if;
  if v_student_id is null then
    raise exception 'STUDENT_CONTEXT_REQUIRED' using errcode = '22023';
  end if;

  select * into v_prompt from public.writing_prompts where id = p_prompt_id;
  if v_prompt.id is null or not public.writing_student_is_target(p_prompt_id, v_student_id) then
    raise exception 'WRITING_PROMPT_NOT_AVAILABLE' using errcode = '42501';
  end if;

  insert into public.writing_submissions (prompt_id, school_id, class_id, student_id, status)
  values (v_prompt.id, v_prompt.school_id, v_prompt.class_id, v_student_id, 'draft')
  on conflict (prompt_id, student_id) do update
    set status = case when public.writing_submissions.status in ('submitted', 'corrected') then public.writing_submissions.status else 'draft' end,
        updated_at = now()
  returning * into v_submission;

  if v_submission.status in ('submitted', 'corrected') then
    raise exception 'WRITING_SUBMISSION_LOCKED';
  end if;

  select coalesce(max(version_number), 0) + 1
    into v_version_number
  from public.writing_submission_versions
  where submission_id = v_submission.id;

  insert into public.writing_submission_versions (
    submission_id, version_number, text_content, attachment, source_type,
    word_count, is_final, autosaved_at, created_by
  )
  values (
    v_submission.id,
    v_version_number,
    p_text_content,
    p_attachment,
    case when p_attachment is null then 'typed' when coalesce(p_attachment->>'mime_type', '') like 'image/%' then 'image' else 'file' end,
    array_length(regexp_split_to_array(btrim(coalesce(p_text_content, '')), '\s+'), 1),
    false,
    now(),
    auth.uid()
  )
  returning * into v_version;

  update public.writing_submissions
     set current_version = v_version.version_number,
         updated_at = now()
   where id = v_submission.id
   returning * into v_submission;

  perform public.writing_log_event(v_prompt.id, v_submission.id, null, 'DRAFT_AUTOSAVED', jsonb_build_object('version_id', v_version.id));
  return jsonb_build_object('submission', to_jsonb(v_submission), 'version', to_jsonb(v_version));
end;
$$;


ALTER FUNCTION "public"."student_save_writing_draft"("p_prompt_id" "uuid", "p_text_content" "text", "p_attachment" "jsonb") OWNER TO "postgres";


