    CONSTRAINT "assessment_attempts_remaining_seconds_check" CHECK ((("remaining_seconds" IS NULL) OR ("remaining_seconds" >= 0))),
    CONSTRAINT "assessment_attempts_score_percentage_check" CHECK ((("score_percentage" IS NULL) OR (("score_percentage" >= (0)::numeric) AND ("score_percentage" <= (100)::numeric)))),
    CONSTRAINT "assessment_attempts_status_check" CHECK (("status" = ANY (ARRAY['in_progress'::"text", 'submitted'::"text", 'graded'::"text", 'cancelled'::"text", 'expired'::"text"]))),
