COMMENT ON TABLE "public"."assessment_attempts" IS 'Avalia+ V1: tentativas individuais de alunos em atribuicoes validas.';



CREATE OR REPLACE FUNCTION "public"."student_start_assessment_attempt"("p_assignment_id" "uuid") RETURNS "public"."assessment_attempts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_student_id uuid;
  v_assignment public.assessment_assignments%rowtype;
  v_attempt public.assessment_attempts%rowtype;
  v_attempt_count integer;
  v_next_number integer;
  v_question_count integer;
begin
  if auth.uid() is null then
    raise exception 'Usuario autenticado obrigatorio.' using errcode = '42501';
  end if;

  select public.avalia_current_student_id() into v_student_id;

  if v_student_id is null then
    raise exception 'Aluno institucional ativo nao encontrado.' using errcode = '42501';
  end if;

  select *
    into v_assignment
  from public.assessment_assignments
  where id = p_assignment_id;

  if v_assignment.id is null then
    raise exception 'Atribuicao nao encontrada.' using errcode = '42501';
  end if;

  if not public.avalia_student_can_access_assignment(p_assignment_id, v_student_id) then
    raise exception 'Aluno nao pode acessar esta avaliacao.' using errcode = '42501';
  end if;

  select *
    into v_attempt
  from public.assessment_attempts
  where assignment_id = p_assignment_id
    and student_id = v_student_id
    and status = 'in_progress'
  order by started_at desc
  limit 1;

  if v_attempt.id is not null then
    return v_attempt;
  end if;

  select count(*)
    into v_attempt_count
  from public.assessment_attempts
  where assignment_id = p_assignment_id
    and student_id = v_student_id
    and status in ('in_progress', 'submitted', 'graded');

  if v_attempt_count >= v_assignment.max_attempts then
    raise exception 'Limite de tentativas atingido.' using errcode = '42501';
  end if;

  v_next_number := v_attempt_count + 1;

  select count(*)
    into v_question_count
  from public.assessment_questions
  where assessment_id = v_assignment.assessment_id;

  insert into public.assessment_attempts (
    assignment_id,
    assessment_id,
    school_id,
    student_id,
    attempt_number,
    status,
    question_count
  )
  values (
    v_assignment.id,
    v_assignment.assessment_id,
    v_assignment.school_id,
    v_student_id,
    v_next_number,
    'in_progress',
    v_question_count
  )
  returning * into v_attempt;

  return v_attempt;
end;
$$;


ALTER FUNCTION "public"."student_start_assessment_attempt"("p_assignment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."student_start_assessment_attempt_v2"("p_assignment_id" "uuid", "p_application_token" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_student_id uuid;
  v_assignment public.assessment_assignments%rowtype;
  v_attempt public.assessment_attempts%rowtype;
  v_attempt_count integer;
  v_question_count integer;
  v_token_id uuid;
  v_order uuid[];
  v_deadline timestamptz;
begin
  if auth.uid() is null then raise exception 'Usuario autenticado obrigatorio.' using errcode = '42501'; end if;
  select public.avalia_current_student_id() into v_student_id;
  select * into v_assignment from public.assessment_assignments where id = p_assignment_id for update;
  if v_student_id is null or v_assignment.id is null or not public.avalia_student_can_access_assignment(p_assignment_id, v_student_id) then
    raise exception 'Aluno nao autorizado para esta avaliacao.' using errcode = '42501';
  end if;
  if not public.avalia_plus_assignment_is_open(v_assignment) then
    raise exception 'Aplicacao fora do periodo autorizado.' using errcode = '42501';
  end if;
  v_token_id := public.avalia_plus_validate_token(p_assignment_id, v_student_id, p_application_token);
  select count(*) into v_attempt_count from public.assessment_attempts where assignment_id = p_assignment_id and student_id = v_student_id and status <> 'cancelled';
  if v_attempt_count >= v_assignment.max_attempts then raise exception 'Limite de tentativas atingido.' using errcode = '42501'; end if;
  select count(*) into v_question_count from public.assessment_questions aq where aq.assessment_id = v_assignment.assessment_id;
  v_deadline := case when v_assignment.time_limit_minutes is null then null else now() + make_interval(mins => v_assignment.time_limit_minutes) end;
  insert into public.assessment_attempts (assignment_id, assessment_id, school_id, student_id, attempt_number, status, booklet_id, access_token_id, application_status, deadline_at, started_at, time_limit_minutes, remaining_seconds, question_count)
  values (p_assignment_id, v_assignment.assessment_id, v_assignment.school_id, v_student_id, v_attempt_count + 1, 'in_progress', v_assignment.booklet_id, v_token_id, 'EM_ANDAMENTO', v_deadline, now(), v_assignment.time_limit_minutes, case when v_assignment.time_limit_minutes is null then null else v_assignment.time_limit_minutes * 60 end, v_question_count)
  returning * into v_attempt;
  v_order := public.avalia_plus_question_order(v_assignment.assessment_id, v_assignment.booklet_id, v_attempt.id, v_assignment.shuffle_questions);
  update public.assessment_attempts
     set question_order = v_order,
         alternative_order = public.avalia_plus_alternative_order(v_order, v_attempt.id, v_assignment.shuffle_alternatives),
         progress = public.avalia_plus_build_progress(v_attempt.id)
   where id = v_attempt.id returning * into v_attempt;
  update public.assessment_assignments set application_status = 'EM_ANDAMENTO', updated_at = now() where id = p_assignment_id;
  insert into public.assessment_attempt_events (attempt_id, assignment_id, student_id, actor_user_id, event_type) values (v_attempt.id, p_assignment_id, v_student_id, auth.uid(), 'STARTED');
  return jsonb_build_object('attempt', to_jsonb(v_attempt));
end;
$$;


ALTER FUNCTION "public"."student_start_assessment_attempt_v2"("p_assignment_id" "uuid", "p_application_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."student_start_game_attempt"("p_game_id" "uuid") RETURNS TABLE("attempt_id" "uuid", "game_id" "uuid", "attempt_number" integer, "status" "text", "started_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_student_id uuid;
  v_attempt public.student_game_attempts;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Usuario autenticado obrigatorio.' USING errcode = '42501';
  END IF;

  IF NOT public.student_can_read_game(p_game_id) THEN
    RAISE EXCEPTION 'Jogo nao autorizado para este aluno.' USING errcode = '42501';
  END IF;

  SELECT ctx.student_id INTO v_student_id
  FROM public.current_early_childhood_student_context() ctx
  LIMIT 1;

  IF v_student_id IS NULL THEN
    RAISE EXCEPTION 'Aluno ativo nao encontrado.' USING errcode = '42501';
  END IF;

  SELECT *
    INTO v_attempt
  FROM public.student_game_attempts a
  WHERE a.student_id = v_student_id
    AND a.game_id = p_game_id
    AND a.status IN ('STARTED', 'IN_PROGRESS', 'PAUSED')
  ORDER BY a.updated_at DESC
  LIMIT 1;

  IF v_attempt.id IS NULL THEN
    INSERT INTO public.student_game_attempts (
      student_id,
      game_id,
      attempt_number,
      status,
      started_at,
      last_event_at
    )
    VALUES (
      v_student_id,
      p_game_id,
      public.student_game_next_attempt_number(v_student_id, p_game_id),
      'STARTED',
      now(),
      now()
    )
    RETURNING * INTO v_attempt;
  END IF;

  RETURN QUERY
  SELECT
    v_attempt.id,
    v_attempt.game_id,
    v_attempt.attempt_number,
    v_attempt.status,
    v_attempt.started_at;
END;
$$;


ALTER FUNCTION "public"."student_start_game_attempt"("p_game_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."student_start_writing_rewrite"("p_submission_id" "uuid", "p_text_content" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_submission public.writing_submissions%rowtype;
  v_version public.writing_submission_versions%rowtype;
  v_version_number integer;
begin
  if auth.uid() is null then
    raise exception 'AUTH_REQUIRED' using errcode = '42501';
  end if;
  select * into v_submission
  from public.writing_submissions
  where id = p_submission_id
    and public.institutional_is_current_student(student_id)
  for update;
  if v_submission.id is null then
    raise exception 'WRITING_SUBMISSION_NOT_FOUND' using errcode = '42501';
  end if;
  if v_submission.status not in ('revision_requested', 'corrected') then
    raise exception 'WRITING_REWRITE_NOT_AVAILABLE';
  end if;

  select coalesce(max(version_number), 0) + 1
    into v_version_number
  from public.writing_submission_versions
  where submission_id = v_submission.id;

  insert into public.writing_submission_versions (
    submission_id, version_number, text_content, source_type,
    word_count, is_final, autosaved_at, created_by
  )
  values (
    v_submission.id,
    v_version_number,
    p_text_content,
    'typed',
    array_length(regexp_split_to_array(btrim(coalesce(p_text_content, '')), '\s+'), 1),
    false,
    now(),
    auth.uid()
  )
  returning * into v_version;

  update public.writing_submissions
     set status = 'resubmitted',
         current_version = v_version.version_number,
         updated_at = now()
   where id = v_submission.id
   returning * into v_submission;

  perform public.writing_log_event(v_submission.prompt_id, v_submission.id, null, 'REWRITE_VERSION_CREATED', jsonb_build_object('version_id', v_version.id));
  return jsonb_build_object('submission', to_jsonb(v_submission), 'version', to_jsonb(v_version));
end;
$$;


ALTER FUNCTION "public"."student_start_writing_rewrite"("p_submission_id" "uuid", "p_text_content" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."assessment_results" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "assessment_id" "uuid" NOT NULL,
    "assignment_id" "uuid" NOT NULL,
    "student_id" "uuid" NOT NULL,
    "attempt_id" "uuid" NOT NULL,
    "school_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'graded'::"text" NOT NULL,
    "score_raw" numeric(10,2) DEFAULT 0 NOT NULL,
    "score_percentage" numeric(6,2) DEFAULT 0 NOT NULL,
    "question_count" integer DEFAULT 0 NOT NULL,
    "answered_count" integer DEFAULT 0 NOT NULL,
    "correct_count" integer DEFAULT 0 NOT NULL,
    "incorrect_count" integer DEFAULT 0 NOT NULL,
    "unanswered_count" integer DEFAULT 0 NOT NULL,
    "finalized_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "origin" "text" DEFAULT 'ONLINE'::"text" NOT NULL,
    "offline_import_batch_id" "uuid",
    "imported_by" "uuid",
    "imported_at" timestamp with time zone,
    "scan_file_id" "uuid",
    CONSTRAINT "assessment_results_origin_check" CHECK (("origin" = ANY (ARRAY['ONLINE'::"text", 'OFFLINE_IMPORT'::"text", 'SCANNED_PHYSICAL'::"text"]))),
    CONSTRAINT "assessment_results_score_percentage_check" CHECK ((("score_percentage" >= (0)::numeric) AND ("score_percentage" <= (100)::numeric))),
    CONSTRAINT "assessment_results_status_check" CHECK (("status" = ANY (ARRAY['submitted'::"text", 'graded'::"text"])))
);


ALTER TABLE "public"."assessment_results" OWNER TO "postgres";


COMMENT ON TABLE "public"."assessment_results" IS 'Avalia+ V1: consolidado idempotente do resultado final para evitar recalculo em relatorios futuros. assessment_attempts segue como fonte operacional canonica.';



CREATE OR REPLACE FUNCTION "public"."student_submit_assessment_attempt"("p_attempt_id" "uuid") RETURNS "public"."assessment_results"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_student_id uuid;
  v_attempt public.assessment_attempts%rowtype;
  v_result public.assessment_results%rowtype;
  v_total_points numeric(10,2);
  v_score_raw numeric(10,2);
  v_question_count integer;
  v_answered_count integer;
  v_correct_count integer;
  v_incorrect_count integer;
  v_unanswered_count integer;
  v_percentage numeric(6,2);
begin
  if auth.uid() is null then
    raise exception 'Usuario autenticado obrigatorio.' using errcode = '42501';
  end if;

  select public.avalia_current_student_id() into v_student_id;

  select *
    into v_attempt
  from public.assessment_attempts
  where id = p_attempt_id;

  if v_attempt.id is null or v_attempt.student_id <> v_student_id then
    raise exception 'Tentativa nao pertence ao aluno autenticado.' using errcode = '42501';
  end if;

  if v_attempt.status in ('submitted', 'graded') then
    select *
      into v_result
    from public.assessment_results
    where attempt_id = p_attempt_id;

    if v_result.id is not null then
      return v_result;
    end if;
  elsif v_attempt.status <> 'in_progress' then
    raise exception 'Tentativa nao pode ser enviada neste estado.' using errcode = '42501';
  end if;

  update public.assessment_responses ar
     set is_correct = coalesce((
           select qa.is_correct
           from public.question_alternatives qa
           where qa.id = ar.selected_alternative_id
             and qa.question_id = ar.question_id
         ), false),
         score_awarded = case
           when coalesce((
             select qa.is_correct
             from public.question_alternatives qa
             where qa.id = ar.selected_alternative_id
               and qa.question_id = ar.question_id
           ), false) then (
             select aq.points
             from public.assessment_questions aq
             where aq.assessment_id = v_attempt.assessment_id
               and aq.question_id = ar.question_id
             limit 1
           )
           else 0
         end
  where ar.attempt_id = p_attempt_id
    and exists (
      select 1
      from public.assessment_questions aq
      where aq.assessment_id = v_attempt.assessment_id
        and aq.question_id = ar.question_id
    );

  select
    coalesce(sum(aq.points), 0),
    count(*)
    into v_total_points, v_question_count
  from public.assessment_questions aq
  where aq.assessment_id = v_attempt.assessment_id;

  select
    count(*) filter (where ar.id is not null),
    count(*) filter (where ar.is_correct is true),
    count(*) filter (where ar.id is not null and coalesce(ar.is_correct, false) is false),
    coalesce(sum(ar.score_awarded), 0)
    into v_answered_count, v_correct_count, v_incorrect_count, v_score_raw
  from public.assessment_questions aq
  left join public.assessment_responses ar
    on ar.question_id = aq.question_id
   and ar.attempt_id = p_attempt_id
  where aq.assessment_id = v_attempt.assessment_id;

  v_unanswered_count := greatest(v_question_count - v_answered_count, 0);
  v_percentage := case
    when v_total_points > 0 then round((v_score_raw / v_total_points) * 100, 2)
    else 0
  end;

  update public.assessment_attempts
     set status = 'graded',
         submitted_at = coalesce(submitted_at, now()),
         graded_at = now(),
         time_spent_seconds = greatest(0, floor(extract(epoch from (now() - started_at)))::integer),
         score_raw = v_score_raw,
         score_percentage = v_percentage,
         question_count = v_question_count,
         answered_count = v_answered_count,
         correct_count = v_correct_count,
         incorrect_count = v_incorrect_count,
         unanswered_count = v_unanswered_count
   where id = p_attempt_id
   returning * into v_attempt;

  insert into public.assessment_results (
    assessment_id,
    assignment_id,
    student_id,
    attempt_id,
    school_id,
    status,
    score_raw,
    score_percentage,
    question_count,
    answered_count,
    correct_count,
    incorrect_count,
    unanswered_count,
    finalized_at
  )
  values (
    v_attempt.assessment_id,
    v_attempt.assignment_id,
    v_attempt.student_id,
    v_attempt.id,
    v_attempt.school_id,
    'graded',
    v_score_raw,
    v_percentage,
    v_question_count,
    v_answered_count,
    v_correct_count,
    v_incorrect_count,
    v_unanswered_count,
    now()
  )
  on conflict (attempt_id)
  do update
     set score_raw = excluded.score_raw,
         score_percentage = excluded.score_percentage,
         question_count = excluded.question_count,
         answered_count = excluded.answered_count,
         correct_count = excluded.correct_count,
         incorrect_count = excluded.incorrect_count,
         unanswered_count = excluded.unanswered_count,
         finalized_at = excluded.finalized_at,
         status = excluded.status
  returning * into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."student_submit_assessment_attempt"("p_attempt_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."student_submit_assessment_attempt_v2"("p_attempt_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_student_id uuid;
  v_attempt public.assessment_attempts%rowtype;
  v_result public.assessment_results%rowtype;
  v_total_points numeric := 0;
  v_score_raw numeric := 0;
  v_question_count integer := 0;
  v_answered_count integer := 0;
  v_correct_count integer := 0;
  v_incorrect_count integer := 0;
  v_unanswered_count integer := 0;
  v_percentage numeric := 0;
  v_reason text := 'submitted';
begin
  if auth.uid() is null then raise exception 'Usuario autenticado obrigatorio.' using errcode = '42501'; end if;
  select public.avalia_current_student_id() into v_student_id;
  select * into v_attempt from public.assessment_attempts where id = p_attempt_id for update;
  if v_student_id is null or v_attempt.id is null or v_attempt.student_id <> v_student_id or v_attempt.status <> 'in_progress' then
    raise exception 'Tentativa nao autorizada para entrega.' using errcode = '42501';
  end if;
  if v_attempt.deadline_at is not null and v_attempt.deadline_at <= now() then v_reason := 'time_expired'; end if;
  update public.assessment_responses ar
     set is_correct = case when ar.selected_alternative_id is null then null else coalesce((select qa.is_correct from public.question_alternatives qa where qa.id = ar.selected_alternative_id and qa.question_id = ar.question_id), false) end,
         score_awarded = case
           when ar.selected_alternative_id is null then null
           when coalesce((select qa.is_correct from public.question_alternatives qa where qa.id = ar.selected_alternative_id and qa.question_id = ar.question_id), false)
             then coalesce((select aq.points from public.assessment_questions aq where aq.assessment_id = v_attempt.assessment_id and aq.question_id = ar.question_id limit 1), 0)
           else 0 end
  where ar.attempt_id = p_attempt_id and exists (select 1 from public.assessment_questions aq where aq.assessment_id = v_attempt.assessment_id and aq.question_id = ar.question_id);
  select coalesce(sum(aq.points), 0), count(*) into v_total_points, v_question_count from public.assessment_questions aq where aq.assessment_id = v_attempt.assessment_id;
  select count(*) filter (where ar.id is not null), count(*) filter (where ar.is_correct is true), count(*) filter (where ar.id is not null and ar.selected_alternative_id is not null and coalesce(ar.is_correct, false) is false), coalesce(sum(coalesce(ar.score_awarded, 0)), 0)
    into v_answered_count, v_correct_count, v_incorrect_count, v_score_raw
  from public.assessment_questions aq
  left join public.assessment_responses ar on ar.question_id = aq.question_id and ar.attempt_id = p_attempt_id
  where aq.assessment_id = v_attempt.assessment_id;
  v_unanswered_count := greatest(v_question_count - v_answered_count, 0);
  v_percentage := case when v_total_points > 0 then round((v_score_raw / v_total_points) * 100, 2) else 0 end;
  update public.assessment_attempts
     set status = case when v_reason = 'time_expired' then 'expired' else 'graded' end,
         application_status = case when v_reason = 'time_expired' and v_unanswered_count > 0 then 'INCOMPLETA' else 'CONCLUIDA' end,
         submitted_at = coalesce(submitted_at, now()),
         graded_at = now(),
         submitted_reason = v_reason,
         time_spent_seconds = greatest(0, floor(extract(epoch from (now() - started_at)))::integer),
         remaining_seconds = case when deadline_at is null then remaining_seconds else greatest(0, floor(extract(epoch from (deadline_at - now())))::integer) end,
         score_raw = v_score_raw,
         score_percentage = v_percentage,
         question_count = v_question_count,
         answered_count = v_answered_count,
         correct_count = v_correct_count,
         incorrect_count = v_incorrect_count,
         unanswered_count = v_unanswered_count,
         progress = public.avalia_plus_build_progress(id),
         last_autosaved_at = coalesce(last_autosaved_at, now())
   where id = p_attempt_id returning * into v_attempt;
  insert into public.assessment_results (assessment_id, assignment_id, student_id, attempt_id, school_id, status, score_raw, score_percentage, question_count, answered_count, correct_count, incorrect_count, unanswered_count, finalized_at)
  values (v_attempt.assessment_id, v_attempt.assignment_id, v_attempt.student_id, v_attempt.id, v_attempt.school_id, case when v_reason = 'time_expired' and v_unanswered_count > 0 then 'submitted' else 'graded' end, v_score_raw, v_percentage, v_question_count, v_answered_count, v_correct_count, v_incorrect_count, v_unanswered_count, now())
  on conflict (attempt_id)
  do update set score_raw = excluded.score_raw, score_percentage = excluded.score_percentage, question_count = excluded.question_count, answered_count = excluded.answered_count, correct_count = excluded.correct_count, incorrect_count = excluded.incorrect_count, unanswered_count = excluded.unanswered_count, finalized_at = excluded.finalized_at, status = excluded.status
  returning * into v_result;
  insert into public.assessment_attempt_events (attempt_id, assignment_id, student_id, actor_user_id, event_type, metadata)
  values (p_attempt_id, v_attempt.assignment_id, v_student_id, auth.uid(), 'SUBMITTED', jsonb_build_object('reason', v_reason));
  return jsonb_build_object('attempt', to_jsonb(v_attempt), 'result', to_jsonb(v_result));
end;
$$;


ALTER FUNCTION "public"."student_submit_assessment_attempt_v2"("p_attempt_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."student_submit_writing"("p_prompt_id" "uuid", "p_text_content" "text" DEFAULT NULL::"text", "p_attachment" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_saved jsonb;
  v_submission_id uuid;
  v_version_id uuid;
  v_submission public.writing_submissions%rowtype;
begin
  v_saved := public.student_save_writing_draft(p_prompt_id, p_text_content, p_attachment);
  v_submission_id := (v_saved #>> '{submission,id}')::uuid;
  v_version_id := (v_saved #>> '{version,id}')::uuid;

  update public.writing_submission_versions
     set is_final = true,
         submitted_at = now()
   where id = v_version_id;

  update public.writing_submissions
     set status = 'submitted',
         submitted_at = now(),
         updated_at = now()
   where id = v_submission_id
   returning * into v_submission;

  perform public.writing_log_event(v_submission.prompt_id, v_submission.id, null, 'FINAL_SUBMISSION', jsonb_build_object('version_id', v_version_id));
  return jsonb_build_object('submission', to_jsonb(v_submission), 'version_id', v_version_id);
end;
$$;


ALTER FUNCTION "public"."student_submit_writing"("p_prompt_id" "uuid", "p_text_content" "text", "p_attachment" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."student_unlock_achievements_for_ledger"("p_ledger_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_ledger public.student_xp_ledger;
  v_total_xp integer;
  v_total_credits integer;
  v_unlocked integer := 0;
  v_achievement public.achievement_catalog;
BEGIN
  SELECT * INTO v_ledger
  FROM public.student_xp_ledger
  WHERE id = p_ledger_id;

  IF v_ledger.id IS NULL THEN
    RETURN 0;
  END IF;

  SELECT
    COALESCE(SUM(xp_amount), 0)::integer,
    COUNT(*)::integer
    INTO v_total_xp, v_total_credits
  FROM public.student_xp_ledger
  WHERE student_id = v_ledger.student_id;

  FOR v_achievement IN
    SELECT *
    FROM public.achievement_catalog
    WHERE active = true
      AND status = 'published'
    ORDER BY sort_order, legacy_id
  LOOP
    IF (
      v_achievement.unlock_rule->>'type' = 'ledger_credit_count'
      AND v_total_credits >= COALESCE(NULLIF(v_achievement.unlock_rule->>'minimum_credits', '')::integer, 1)
    ) OR (
      v_achievement.unlock_rule->>'type' = 'total_xp'
      AND v_total_xp >= COALESCE(NULLIF(v_achievement.unlock_rule->>'minimum_xp', '')::integer, 0)
    ) OR (
      v_achievement.unlock_rule->>'type' = 'event_type'
      AND v_ledger.event_type = v_achievement.unlock_rule->>'event_type'
    ) THEN
      INSERT INTO public.student_achievements (
        student_id,
        achievement_id,
        unlocked_from_ledger_id,
        source_event_key,
        metadata
      )
      VALUES (
        v_ledger.student_id,
        v_achievement.id,
        v_ledger.id,
        v_ledger.event_key,
        jsonb_build_object(
          'unlock_engine', '02F.1',
          'technical_test', v_achievement.is_technical_test
        )
      )
      ON CONFLICT (student_id, achievement_id) DO NOTHING;

      IF FOUND THEN
        v_unlocked := v_unlocked + 1;
      END IF;
    END IF;
  END LOOP;

  RETURN v_unlocked;
END;
$$;


ALTER FUNCTION "public"."student_unlock_achievements_for_ledger"("p_ledger_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."student_update_avatar_config"("p_avatar" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare v_student_id uuid; v_profile public.student_gamification_profiles%rowtype;
begin
  select id into v_student_id from public.students where user_id = auth.uid() and coalesce(status,'active') in ('active','ativo') order by updated_at desc nulls last, created_at desc nulls last limit 1;
  if v_student_id is null or not public.institutional_is_current_student(v_student_id) then raise exception 'Aluno autenticado nao encontrado'; end if;
  v_profile := public.gamification_ensure_profile(v_student_id);
  update public.student_gamification_profiles set avatar_config = coalesce(p_avatar,'{}'::jsonb), updated_at = now() where student_id = v_student_id returning * into v_profile;
  return jsonb_build_object('profile',to_jsonb(v_profile));
end; $$;


ALTER FUNCTION "public"."student_update_avatar_config"("p_avatar" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."student_update_game_attempt"("p_attempt_id" "uuid", "p_status" "text" DEFAULT 'IN_PROGRESS'::"text", "p_client_state" "jsonb" DEFAULT '{}'::"jsonb") RETURNS TABLE("attempt_id" "uuid", "game_id" "uuid", "status" "text", "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_student_id uuid;
  v_status text := upper(btrim(coalesce(p_status, 'IN_PROGRESS')));
  v_attempt public.student_game_attempts;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Usuario autenticado obrigatorio.' USING errcode = '42501';
  END IF;

  IF v_status NOT IN ('IN_PROGRESS', 'PAUSED', 'ABANDONED') THEN
    RAISE EXCEPTION 'Status de tentativa invalido.' USING errcode = '22023';
  END IF;

  IF COALESCE(p_client_state, '{}'::jsonb)::text ~* '(password|senha|token|secret|service_role|access_token|refresh_token)' THEN
    RAISE EXCEPTION 'Estado do jogo contem termo sensivel.' USING errcode = '22023';
  END IF;

  SELECT ctx.student_id INTO v_student_id
  FROM public.current_early_childhood_student_context() ctx
  LIMIT 1;

  SELECT *
    INTO v_attempt
  FROM public.student_game_attempts a
  WHERE a.id = p_attempt_id
    AND a.student_id = v_student_id
  LIMIT 1;

  IF v_attempt.id IS NULL THEN
    RAISE EXCEPTION 'Tentativa nao encontrada para este aluno.' USING errcode = '42501';
  END IF;

  IF v_attempt.status = 'COMPLETED' THEN
    RAISE EXCEPTION 'Tentativa ja concluida.' USING errcode = '22023';
  END IF;

  IF NOT public.student_can_read_game(v_attempt.game_id) THEN
    RAISE EXCEPTION 'Jogo nao autorizado para este aluno.' USING errcode = '42501';
  END IF;

  UPDATE public.student_game_attempts
     SET status = v_status,
         client_state = COALESCE(p_client_state, '{}'::jsonb),
         last_event_at = now(),
         updated_at = now()
   WHERE id = v_attempt.id
   RETURNING * INTO v_attempt;

  RETURN QUERY
  SELECT
    v_attempt.id,
    v_attempt.game_id,
    v_attempt.status,
    v_attempt.updated_at;
END;
$$;


ALTER FUNCTION "public"."student_update_game_attempt"("p_attempt_id" "uuid", "p_status" "text", "p_client_state" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."student_upsert_activity_progress"("p_activity_id" "uuid", "p_status" "text" DEFAULT 'IN_PROGRESS'::"text", "p_percent_complete" integer DEFAULT 0, "p_progress_data" "jsonb" DEFAULT '{}'::"jsonb") RETURNS TABLE("activity_id" "uuid", "status" "text", "percent_complete" integer, "progress_data" "jsonb", "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_student_id uuid;
  v_status text := upper(btrim(coalesce(p_status, 'IN_PROGRESS')));
  v_percent integer := least(greatest(coalesce(p_percent_complete, 0), 0), 100);
  v_progress public.student_activity_progress;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Usuario autenticado obrigatorio.' USING errcode = '42501';
  END IF;

  IF v_status NOT IN ('NOT_STARTED', 'IN_PROGRESS', 'COMPLETED') THEN
    RAISE EXCEPTION 'Status de progresso invalido.' USING errcode = '22023';
  END IF;

  IF p_progress_data::text ~* '(password|senha|token|secret|service_role|access_token|refresh_token)' THEN
    RAISE EXCEPTION 'progress_data contem termo sensivel.' USING errcode = '22023';
  END IF;

  IF NOT public.student_can_read_activity(p_activity_id) THEN
    RAISE EXCEPTION 'Atividade nao autorizada para este aluno.' USING errcode = '42501';
  END IF;

  SELECT ctx.student_id
    INTO v_student_id
  FROM public.current_early_childhood_student_context() ctx
  LIMIT 1;

  IF v_student_id IS NULL THEN
    RAISE EXCEPTION 'Aluno ativo nao encontrado.' USING errcode = '42501';
  END IF;

  UPDATE public.student_activity_progress sap
     SET status = v_status,
         percent_complete = CASE WHEN v_status = 'COMPLETED' THEN 100 ELSE v_percent END,
         progress_data = COALESCE(p_progress_data, '{}'::jsonb),
         started_at = CASE
           WHEN v_status <> 'NOT_STARTED' THEN COALESCE(sap.started_at, now())
           ELSE NULL
         END,
         completed_at = CASE
           WHEN v_status = 'COMPLETED' THEN COALESCE(sap.completed_at, now())
           ELSE NULL
         END,
         updated_at = now()
   WHERE sap.student_id = v_student_id
     AND sap.activity_id = p_activity_id
   RETURNING sap.*
    INTO v_progress;

  IF NOT FOUND THEN
    INSERT INTO public.student_activity_progress (
      student_id,
      activity_id,
      status,
      percent_complete,
      progress_data,
      started_at,
      completed_at,
      updated_at
    )
    VALUES (
      v_student_id,
      p_activity_id,
      v_status,
      CASE WHEN v_status = 'COMPLETED' THEN 100 ELSE v_percent END,
      COALESCE(p_progress_data, '{}'::jsonb),
      CASE WHEN v_status <> 'NOT_STARTED' THEN now() ELSE NULL END,
      CASE WHEN v_status = 'COMPLETED' THEN now() ELSE NULL END,
      now()
    )
    RETURNING public.student_activity_progress.*
      INTO v_progress;
  END IF;

  RETURN QUERY
  SELECT
    v_progress.activity_id,
    v_progress.status,
    v_progress.percent_complete,
    v_progress.progress_data,
    v_progress.updated_at;
END;
$$;


ALTER FUNCTION "public"."student_upsert_activity_progress"("p_activity_id" "uuid", "p_status" "text", "p_percent_complete" integer, "p_progress_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."student_upsert_book_progress"("p_book_id" "uuid", "p_current_page" integer DEFAULT 1, "p_percent_complete" integer DEFAULT 0) RETURNS TABLE("book_id" "uuid", "current_page" integer, "percent_complete" integer, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_student_id uuid;
  v_page integer := greatest(coalesce(p_current_page, 1), 1);
  v_percent integer := least(greatest(coalesce(p_percent_complete, 0), 0), 100);
  v_progress public.book_progress;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Usuario autenticado obrigatorio.' USING errcode = '42501';
  END IF;

  IF NOT public.student_can_read_library_book(p_book_id) THEN
    RAISE EXCEPTION 'Livro nao autorizado para este aluno.' USING errcode = '42501';
  END IF;

  SELECT ce.student_id
    INTO v_student_id
  FROM public.current_student_library_enrollments() ce
  LIMIT 1;

  IF v_student_id IS NULL THEN
    RAISE EXCEPTION 'Aluno ativo nao encontrado.' USING errcode = '42501';
  END IF;

  UPDATE public.book_progress bp
     SET current_page = v_page,
         percent_complete = v_percent,
         updated_at = now()
   WHERE bp.student_id = v_student_id
     AND bp.book_id = p_book_id
   RETURNING bp.*
    INTO v_progress;

  IF NOT FOUND THEN
    INSERT INTO public.book_progress (
      student_id,
      book_id,
      current_page,
      percent_complete,
      updated_at
    )
    VALUES (
      v_student_id,
      p_book_id,
      v_page,
      v_percent,
      now()
    )
    RETURNING public.book_progress.*
      INTO v_progress;
  END IF;

  RETURN QUERY
  SELECT
    v_progress.book_id,
    v_progress.current_page,
    v_progress.percent_complete,
    v_progress.updated_at;
END;
$$;


ALTER FUNCTION "public"."student_upsert_book_progress"("p_book_id" "uuid", "p_current_page" integer, "p_percent_complete" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."student_upsert_discovery_progress"("p_discovery_id" "uuid", "p_status" "text" DEFAULT 'IN_PROGRESS'::"text", "p_discovered_hotspots" "jsonb" DEFAULT '[]'::"jsonb", "p_progress_data" "jsonb" DEFAULT '{}'::"jsonb") RETURNS TABLE("discovery_id" "uuid", "status" "text", "discovered_hotspots" "jsonb", "progress_data" "jsonb", "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_student_id uuid;
  v_status text := upper(btrim(coalesce(p_status, 'IN_PROGRESS')));
  v_progress public.student_discovery_progress;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Usuario autenticado obrigatorio.' USING errcode = '42501';
  END IF;

  IF v_status NOT IN ('NOT_STARTED', 'IN_PROGRESS', 'COMPLETED') THEN
    RAISE EXCEPTION 'Status de progresso invalido.' USING errcode = '22023';
  END IF;

  IF p_discovered_hotspots::text ~* '(password|senha|token|secret|service_role|access_token|refresh_token)'
     OR p_progress_data::text ~* '(password|senha|token|secret|service_role|access_token|refresh_token)' THEN
    RAISE EXCEPTION 'Dados de progresso contem termo sensivel.' USING errcode = '22023';
  END IF;

  IF NOT public.student_can_read_discovery(p_discovery_id) THEN
    RAISE EXCEPTION 'Descoberta nao autorizada para este aluno.' USING errcode = '42501';
