CREATE OR REPLACE FUNCTION "public"."teacher_add_recomposition_tracking_event"("p_plan_id" "uuid", "p_student_id" "uuid" DEFAULT NULL::"uuid", "p_event_type" "text" DEFAULT 'note'::"text", "p_evidence" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_plan public.recomposition_plans%rowtype; v_event_id uuid;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  select * into v_plan from public.recomposition_plans where id = p_plan_id;
  if not found then raise exception 'PLAN_NOT_FOUND'; end if;
  if not public.avalia_plus_teacher_can_manage_class(v_plan.class_id, v_plan.school_id) then raise exception 'PLAN_FORBIDDEN'; end if;
  if p_student_id is not null and not exists (select 1 from public.recomposition_plan_students where plan_id = p_plan_id and student_id = p_student_id and status <> 'removed') then raise exception 'STUDENT_NOT_IN_PLAN'; end if;
  insert into public.recomposition_tracking_events (plan_id, student_id, event_type, evidence) values (p_plan_id, p_student_id, coalesce(p_event_type, 'note'), coalesce(p_evidence, '{}'::jsonb)) returning id into v_event_id;
  return jsonb_build_object('event_id', v_event_id, 'status', 'PASS');
end;
$$;


ALTER FUNCTION "public"."teacher_add_recomposition_tracking_event"("p_plan_id" "uuid", "p_student_id" "uuid", "p_event_type" "text", "p_evidence" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_archive_calendar_entry"("p_entry_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_entry public.class_calendar_entries%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Usuario autenticado obrigatorio.' using errcode = '42501';
  end if;

  select * into v_entry
  from public.class_calendar_entries
  where id = p_entry_id;

  if v_entry.id is null then
    raise exception 'Publicacao de agenda nao encontrada.' using errcode = 'P0002';
  end if;

  if not (
    public.is_platform_admin()
    or public.institutional_teacher_can_manage_class(v_entry.teacher_id, v_entry.class_id, v_entry.school_id)
  ) then
    raise exception 'Professor nao autorizado para arquivar esta agenda.' using errcode = '42501';
  end if;

  update public.class_calendar_entries
  set status = 'archived',
      updated_at = now()
  where id = p_entry_id;

  return jsonb_build_object('entry_id', p_entry_id, 'status', 'archived');
end;
$$;


ALTER FUNCTION "public"."teacher_archive_calendar_entry"("p_entry_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_authorize_assessment_reapplication"("p_assignment_id" "uuid", "p_student_id" "uuid" DEFAULT NULL::"uuid", "p_extra_attempts" integer DEFAULT 1, "p_reason" "text" DEFAULT NULL::"text") RETURNS "public"."assessment_assignments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_assignment public.assessment_assignments%rowtype;
  v_previous integer;
begin
  if auth.uid() is null then raise exception 'Usuario autenticado obrigatorio.' using errcode = '42501'; end if;
  select * into v_assignment from public.assessment_assignments where id = p_assignment_id for update;
  if v_assignment.id is null or not public.avalia_plus_teacher_can_manage_class(v_assignment.class_id, v_assignment.school_id) then
    raise exception 'Usuario nao autorizado para reaplicacao.' using errcode = '42501';
  end if;
  if coalesce(p_extra_attempts, 0) <= 0 then raise exception 'extra_attempts deve ser maior que zero.' using errcode = '22023'; end if;
  v_previous := v_assignment.max_attempts;
  update public.assessment_assignments set max_attempts = max_attempts + p_extra_attempts, application_status = 'EM_ANDAMENTO', updated_at = now() where id = p_assignment_id returning * into v_assignment;
  insert into public.assessment_reapplication_logs (assignment_id, student_id, previous_max_attempts, new_max_attempts, authorized_by, reason)
  values (p_assignment_id, p_student_id, v_previous, v_assignment.max_attempts, auth.uid(), p_reason);
  return v_assignment;
end;
$$;


ALTER FUNCTION "public"."teacher_authorize_assessment_reapplication"("p_assignment_id" "uuid", "p_student_id" "uuid", "p_extra_attempts" integer, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_close_class_diary_entry"("p_entry_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_entry public.class_diary_entries%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Usuario autenticado obrigatorio.' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_entry
  FROM public.class_diary_entries
  WHERE id = p_entry_id
  FOR UPDATE;

  IF v_entry.id IS NULL THEN
    RAISE EXCEPTION 'Diario de Classe nao encontrado.' USING ERRCODE = '22023';
  END IF;

  IF NOT public.class_diary_teacher_can_manage(v_entry.school_id, v_entry.class_id, v_entry.teacher_id) THEN
    RAISE EXCEPTION 'Professor sem permissao para fechar este Diario.' USING ERRCODE = '42501';
  END IF;

  IF v_entry.status = 'closed' THEN
    RETURN jsonb_build_object('diary_entry_id', v_entry.id, 'status', v_entry.status, 'changed', false);
  END IF;

  IF v_entry.status = 'deleted' OR v_entry.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'Diario excluido nao pode ser fechado.' USING ERRCODE = '42501';
  END IF;

  UPDATE public.class_diary_entries
  SET status = 'closed',
    closed_at = now(),
    closed_by = auth.uid(),
    updated_at = now()
  WHERE id = v_entry.id
  RETURNING * INTO v_entry;

  INSERT INTO public.class_diary_events (diary_entry_id, event_type, actor_id, metadata)
  VALUES (
    v_entry.id,
    'closed',
    auth.uid(),
    jsonb_build_object(
      'school_id', v_entry.school_id,
      'class_id', v_entry.class_id,
      'teacher_id', v_entry.teacher_id,
      'entry_date', v_entry.entry_date
    )
  );

  RETURN jsonb_build_object('diary_entry_id', v_entry.id, 'status', v_entry.status, 'changed', true);
END;
$$;


ALTER FUNCTION "public"."teacher_close_class_diary_entry"("p_entry_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_confirm_offline_assessment_import"("p_batch_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_batch public.assessment_offline_import_batches%rowtype;
  v_assignment public.assessment_assignments%rowtype;
  v_student uuid;
  v_attempt public.assessment_attempts%rowtype;
  v_total_points numeric;
  v_question_count integer;
  v_answered integer;
  v_correct integer;
  v_incorrect integer;
  v_raw numeric;
  v_percentage numeric;
  v_created integer := 0;
begin
  if auth.uid() is null then
    raise exception 'AUTH_REQUIRED' using errcode = '42501';
  end if;
  select * into v_batch from public.assessment_offline_import_batches where id = p_batch_id for update;
  if v_batch.id is null then
    raise exception 'IMPORT_BATCH_NOT_FOUND';
  end if;
  v_assignment := public.avalia_plus_assert_teacher_assignment(v_batch.assignment_id);
  if v_batch.status not in ('preview', 'validated') then
    raise exception 'IMPORT_BATCH_NOT_CONFIRMABLE';
  end if;
  if exists (select 1 from public.assessment_offline_import_rows where batch_id = p_batch_id and status <> 'valid') then
    raise exception 'IMPORT_HAS_INVALID_ROWS';
  end if;

  for v_student in
    select distinct student_id
    from public.assessment_offline_import_rows
    where batch_id = p_batch_id and status = 'valid' and student_id is not null
  loop
    if exists (select 1 from public.assessment_results where assignment_id = v_assignment.id and student_id = v_student) then
      raise exception 'RESULT_ALREADY_CONSOLIDATED:%', v_student;
    end if;

    insert into public.assessment_attempts (
      assignment_id, assessment_id, school_id, student_id, attempt_number, status,
      started_at, submitted_at, graded_at, question_count, origin,
      offline_import_batch_id, imported_by, imported_at
    )
    values (
      v_assignment.id, v_assignment.assessment_id, v_assignment.school_id, v_student,
      coalesce((select max(attempt_number) + 1 from public.assessment_attempts where assignment_id = v_assignment.id and student_id = v_student), 1),
      'graded', now(), now(), now(),
      (select count(*) from public.assessment_questions where assessment_id = v_assignment.assessment_id),
      'OFFLINE_IMPORT', p_batch_id, auth.uid(), now()
    )
    returning * into v_attempt;

    insert into public.assessment_responses (
      attempt_id, question_id, selected_alternative_id, response_text, is_correct,
      score_awarded, origin, offline_import_row_id
    )
    select
      v_attempt.id,
      r.question_id,
      r.alternative_id,
      r.response_text,
      case when r.alternative_id is null then null else coalesce(qa.is_correct, false) end,
      case
        when r.alternative_id is null then null
        when coalesce(qa.is_correct, false) then coalesce(aq.points, 0)
        else 0
      end,
      'OFFLINE_IMPORT',
      r.id
    from public.assessment_offline_import_rows r
    left join public.question_alternatives qa on qa.id = r.alternative_id
    left join public.assessment_questions aq on aq.id = r.assessment_question_id
    where r.batch_id = p_batch_id
      and r.student_id = v_student
      and r.status = 'valid';

    select coalesce(sum(points), 0), count(*) into v_total_points, v_question_count
    from public.assessment_questions
    where assessment_id = v_assignment.assessment_id;

    select
      count(*),
      count(*) filter (where is_correct is true),
      count(*) filter (where selected_alternative_id is not null and coalesce(is_correct, false) is false),
      coalesce(sum(coalesce(score_awarded, 0)), 0)
      into v_answered, v_correct, v_incorrect, v_raw
    from public.assessment_responses
    where attempt_id = v_attempt.id;

    v_percentage := case when v_total_points > 0 then round((v_raw / v_total_points) * 100, 2) else 0 end;

    update public.assessment_attempts
       set score_raw = v_raw,
           score_percentage = v_percentage,
           question_count = v_question_count,
           answered_count = v_answered,
           correct_count = v_correct,
           incorrect_count = v_incorrect,
           unanswered_count = greatest(v_question_count - v_answered, 0),
           application_status = 'CONCLUIDA'
     where id = v_attempt.id
     returning * into v_attempt;

    insert into public.assessment_results (
      assessment_id, assignment_id, student_id, attempt_id, school_id, status,
      score_raw, score_percentage, question_count, answered_count, correct_count,
      incorrect_count, unanswered_count, finalized_at, origin,
      offline_import_batch_id, imported_by, imported_at
    )
    values (
      v_attempt.assessment_id, v_attempt.assignment_id, v_attempt.student_id, v_attempt.id, v_attempt.school_id,
      'graded', v_attempt.score_raw, v_attempt.score_percentage, v_attempt.question_count, v_attempt.answered_count,
      v_attempt.correct_count, v_attempt.incorrect_count, v_attempt.unanswered_count, now(),
      'OFFLINE_IMPORT', p_batch_id, auth.uid(), now()
    );

    update public.assessment_offline_import_rows
       set status = 'consolidated', consolidated_at = now()
     where batch_id = p_batch_id and student_id = v_student and status = 'valid';

    v_created := v_created + 1;
  end loop;

  update public.assessment_offline_import_batches
     set status = 'consolidated',
         consolidated_by = auth.uid(),
         consolidated_at = now(),
         summary = summary || jsonb_build_object('consolidated_students', v_created)
   where id = p_batch_id
   returning * into v_batch;

  return jsonb_build_object('batch', to_jsonb(v_batch), 'consolidated_students', v_created);
end;
$$;


ALTER FUNCTION "public"."teacher_confirm_offline_assessment_import"("p_batch_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_confirm_scanned_assessment_file"("p_scan_file_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_file public.assessment_scan_files%rowtype;
  v_batch public.assessment_scan_batches%rowtype;
  v_assignment public.assessment_assignments%rowtype;
  v_attempt public.assessment_attempts%rowtype;
  v_total_points numeric;
  v_question_count integer;
  v_answered integer;
  v_correct integer;
  v_incorrect integer;
  v_raw numeric;
  v_percentage numeric;
begin
  if auth.uid() is null then
    raise exception 'AUTH_REQUIRED' using errcode = '42501';
  end if;
  select * into v_file from public.assessment_scan_files where id = p_scan_file_id for update;
  if v_file.id is null then
    raise exception 'SCAN_FILE_NOT_FOUND';
  end if;
  select * into v_batch from public.assessment_scan_batches where id = v_file.batch_id for update;
  v_assignment := public.avalia_plus_assert_teacher_assignment(v_batch.assignment_id);

  if v_file.student_id is null or v_file.identification_status <> 'IDENTIFIED' then
    raise exception 'SCAN_STUDENT_REVIEW_REQUIRED';
  end if;
  if exists (
    select 1
    from public.assessment_scan_responses
    where scan_file_id = p_scan_file_id
      and detection_status not in ('CONFIRMED', 'ADJUSTED')
  ) then
    raise exception 'SCAN_RESPONSES_REVIEW_REQUIRED';
  end if;
  if not exists (
    select 1 from public.assessment_scan_responses
    where scan_file_id = p_scan_file_id and final_alternative_id is not null
  ) then
    raise exception 'SCAN_WITHOUT_CONFIRMED_RESPONSES';
  end if;
  if exists (
    select 1 from public.assessment_results
    where assignment_id = v_assignment.id and student_id = v_file.student_id
  ) then
    raise exception 'RESULT_ALREADY_CONSOLIDATED';
  end if;

  insert into public.assessment_attempts (
    assignment_id, assessment_id, school_id, student_id, attempt_number, status,
    started_at, submitted_at, graded_at, question_count, origin,
    scan_file_id, imported_by, imported_at
  )
  values (
    v_assignment.id, v_assignment.assessment_id, v_assignment.school_id, v_file.student_id,
    coalesce((select max(attempt_number) + 1 from public.assessment_attempts where assignment_id = v_assignment.id and student_id = v_file.student_id), 1),
    'graded', now(), now(), now(),
    (select count(*) from public.assessment_questions where assessment_id = v_assignment.assessment_id),
    'SCANNED_PHYSICAL', p_scan_file_id, auth.uid(), now()
  )
  returning * into v_attempt;

  insert into public.assessment_responses (
    attempt_id, question_id, selected_alternative_id, response_text, is_correct,
    score_awarded, origin, scan_response_id
  )
  select
    v_attempt.id,
    r.question_id,
    r.final_alternative_id,
    null,
    coalesce(qa.is_correct, false),
    case when coalesce(qa.is_correct, false) then coalesce(aq.points, 0) else 0 end,
    'SCANNED_PHYSICAL',
    r.id
  from public.assessment_scan_responses r
  left join public.question_alternatives qa on qa.id = r.final_alternative_id
  left join public.assessment_questions aq on aq.id = r.assessment_question_id
  where r.scan_file_id = p_scan_file_id
    and r.final_alternative_id is not null
    and r.detection_status in ('CONFIRMED', 'ADJUSTED');

  select coalesce(sum(points), 0), count(*) into v_total_points, v_question_count
  from public.assessment_questions
  where assessment_id = v_assignment.assessment_id;

  select
    count(*),
    count(*) filter (where is_correct is true),
    count(*) filter (where selected_alternative_id is not null and coalesce(is_correct, false) is false),
    coalesce(sum(coalesce(score_awarded, 0)), 0)
    into v_answered, v_correct, v_incorrect, v_raw
  from public.assessment_responses
  where attempt_id = v_attempt.id;

  v_percentage := case when v_total_points > 0 then round((v_raw / v_total_points) * 100, 2) else 0 end;

  update public.assessment_attempts
     set score_raw = v_raw,
         score_percentage = v_percentage,
         question_count = v_question_count,
         answered_count = v_answered,
         correct_count = v_correct,
         incorrect_count = v_incorrect,
         unanswered_count = greatest(v_question_count - v_answered, 0),
         application_status = 'CONCLUIDA'
   where id = v_attempt.id
   returning * into v_attempt;

  insert into public.assessment_results (
    assessment_id, assignment_id, student_id, attempt_id, school_id, status,
    score_raw, score_percentage, question_count, answered_count, correct_count,
    incorrect_count, unanswered_count, finalized_at, origin,
    scan_file_id, imported_by, imported_at
  )
  values (
    v_attempt.assessment_id, v_attempt.assignment_id, v_attempt.student_id, v_attempt.id, v_attempt.school_id,
    'graded', v_attempt.score_raw, v_attempt.score_percentage, v_attempt.question_count, v_attempt.answered_count,
    v_attempt.correct_count, v_attempt.incorrect_count, v_attempt.unanswered_count, now(),
    'SCANNED_PHYSICAL', p_scan_file_id, auth.uid(), now()
  );

  update public.assessment_scan_files
     set processing_status = 'CONSOLIDATED',
         consolidated_at = now(),
         updated_at = now()
   where id = p_scan_file_id
   returning * into v_file;

  update public.assessment_scan_batches
     set pipeline_status = case
           when not exists (
             select 1
             from public.assessment_scan_files f
             where f.batch_id = v_batch.id
               and f.processing_status <> 'CONSOLIDATED'
           ) then 'CONSOLIDATED'
           else 'CONSOLIDATION'
         end,
         updated_at = now(),
         summary = summary || jsonb_build_object('last_consolidated_file_id', p_scan_file_id)
   where id = v_batch.id
   returning * into v_batch;

  perform public.avalia_plus_scan_log_event(v_batch.id, v_file.id, 'SCAN_CONSOLIDATED', jsonb_build_object('attempt_id', v_attempt.id, 'student_id', v_file.student_id, 'score_percentage', v_attempt.score_percentage));
  return jsonb_build_object('file', to_jsonb(v_file), 'attempt_id', v_attempt.id, 'result_origin', 'SCANNED_PHYSICAL', 'score_percentage', v_attempt.score_percentage);
end;
$$;


ALTER FUNCTION "public"."teacher_confirm_scanned_assessment_file"("p_scan_file_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."teacher_confirm_scanned_assessment_file"("p_scan_file_id" "uuid") IS 'Consolida scan revisado no mesmo assessment_attempts/assessment_results com origin=SCANNED_PHYSICAL.';



CREATE OR REPLACE FUNCTION "public"."teacher_correct_writing_submission"("p_submission_id" "uuid", "p_correction" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_submission public.writing_submissions%rowtype;
  v_prompt public.writing_prompts%rowtype;
  v_version public.writing_submission_versions%rowtype;
  v_correction public.writing_corrections%rowtype;
  v_mode text := upper(coalesce(p_correction->>'mode', 'DOCENTE'));
  v_provider jsonb := public.ai_provider_status();
  v_item jsonb;
  v_overall numeric := nullif(p_correction->>'overall_score', '')::numeric;
begin
  if auth.uid() is null then
    raise exception 'AUTH_REQUIRED' using errcode = '42501';
  end if;

  select * into v_submission from public.writing_submissions where id = p_submission_id for update;
  if v_submission.id is null then
    raise exception 'WRITING_SUBMISSION_NOT_FOUND';
  end if;
  if not public.avalia_plus_teacher_can_manage_class(v_submission.class_id, v_submission.school_id) then
    raise exception 'WRITING_CORRECTION_FORBIDDEN' using errcode = '42501';
  end if;
  if v_mode not in ('DOCENTE', 'IA', 'HIBRIDA_IA_DOCENTE') then
    raise exception 'INVALID_WRITING_CORRECTION_MODE';
  end if;
  if v_mode = 'IA' and coalesce(v_provider->>'status', 'EMPTY_REAL') <> 'PASS' then
    raise exception 'AI_CORRECTION_PROVIDER_EMPTY_REAL';
  end if;

  select * into v_prompt from public.writing_prompts where id = v_submission.prompt_id;
  select * into v_version
  from public.writing_submission_versions
  where submission_id = v_submission.id
  order by version_number desc
  limit 1;

  insert into public.writing_corrections (
    submission_id, version_id, mode, provider_status, status, overall_score,
    general_feedback, strengths, improvements, rewrite_guidance,
    created_by, validated_by, validated_at
  )
  values (
    v_submission.id,
    v_version.id,
    v_mode,
    case when v_mode = 'DOCENTE' then 'EMPTY_REAL' else coalesce(v_provider->>'status', 'EMPTY_REAL') end,
    case when v_mode = 'IA' then 'published' else 'validated' end,
    v_overall,
    nullif(p_correction->>'general_feedback', ''),
    coalesce(p_correction->'strengths', '[]'::jsonb),
    coalesce(p_correction->'improvements', '[]'::jsonb),
    nullif(p_correction->>'rewrite_guidance', ''),
    auth.uid(),
    auth.uid(),
    now()
  )
  returning * into v_correction;

  for v_item in select * from jsonb_array_elements(coalesce(p_correction->'rubric_scores', '[]'::jsonb))
  loop
    insert into public.writing_rubric_scores (
      correction_id, criterion_key, criterion_label, dimension, score, max_score, feedback, source
    )
    values (
      v_correction.id,
      coalesce(nullif(v_item->>'criterion_key', ''), nullif(v_item->>'key', ''), gen_random_uuid()::text),
      coalesce(nullif(v_item->>'criterion_label', ''), nullif(v_item->>'label', ''), 'Criterio'),
      coalesce(nullif(v_item->>'dimension', ''), 'criterio_configuravel'),
      nullif(v_item->>'score', '')::numeric,
      nullif(v_item->>'max_score', '')::numeric,
      nullif(v_item->>'feedback', ''),
      case when v_mode = 'HIBRIDA_IA_DOCENTE' then 'hybrid_validated' else 'teacher' end
    );
  end loop;

  for v_item in select * from jsonb_array_elements(coalesce(p_correction->'feedback_items', '[]'::jsonb))
  loop
    insert into public.writing_feedback_items (
      correction_id, version_id, feedback_type, paragraph_index,
      text_excerpt, feedback, suggestion, source
    )
    values (
      v_correction.id,
      v_version.id,
      coalesce(nullif(v_item->>'feedback_type', ''), 'paragraph'),
      nullif(v_item->>'paragraph_index', '')::integer,
      nullif(v_item->>'text_excerpt', ''),
      coalesce(nullif(v_item->>'feedback', ''), 'Feedback registrado.'),
      nullif(v_item->>'suggestion', ''),
      case when v_mode = 'HIBRIDA_IA_DOCENTE' then 'hybrid_validated' else 'teacher' end
    );
  end loop;

  update public.writing_submissions
     set status = case when nullif(v_correction.rewrite_guidance, '') is not null then 'revision_requested' else 'corrected' end,
         correction_mode = v_mode,
         final_score = v_overall,
         final_feedback = v_correction.general_feedback,
         corrected_at = now(),
         corrected_by = auth.uid(),
         updated_at = now()
   where id = v_submission.id
   returning * into v_submission;

  insert into public.writing_analytics_snapshots (
    school_id, class_id, student_id, prompt_id, textual_genre, component,
    submission_count, corrected_count, average_score, evolution
  )
  values (
    v_submission.school_id,
    v_submission.class_id,
    v_submission.student_id,
    v_submission.prompt_id,
    v_prompt.textual_genre,
    v_prompt.component,
    1,
    1,
    v_overall,
    jsonb_build_object('source', 'writing_correction', 'correction_id', v_correction.id)
  );

  perform public.writing_log_event(v_prompt.id, v_submission.id, v_correction.id, 'CORRECTION_PUBLISHED', jsonb_build_object('mode', v_mode, 'score', v_overall));
  return jsonb_build_object('submission', to_jsonb(v_submission), 'correction', to_jsonb(v_correction));
end;
$$;


ALTER FUNCTION "public"."teacher_correct_writing_submission"("p_submission_id" "uuid", "p_correction" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_create_assessment_assignment"("p_assessment_id" "uuid", "p_target_type" "text", "p_class_id" "uuid", "p_student_id" "uuid" DEFAULT NULL::"uuid", "p_available_from" timestamp with time zone DEFAULT "now"(), "p_available_until" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_time_limit_minutes" integer DEFAULT NULL::integer, "p_max_attempts" integer DEFAULT 1, "p_status" "text" DEFAULT 'published'::"text") RETURNS "public"."assessment_assignments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_teacher_id uuid;
  v_school_id uuid;
  v_target_type text := nullif(btrim(coalesce(p_target_type, '')), '');
  v_status text := coalesce(nullif(btrim(coalesce(p_status, '')), ''), 'published');
  v_assignment public.assessment_assignments%rowtype;
  v_assessment_title text;
begin
  if auth.uid() is null then
    raise exception 'Usuario autenticado obrigatorio.' using errcode = '42501';
  end if;

  if v_target_type not in ('class', 'student') then
    raise exception 'target_type deve ser class ou student.' using errcode = '22023';
  end if;

  if v_status not in ('draft', 'published') then
    raise exception 'Criacao permite somente draft ou published.' using errcode = '22023';
  end if;

  if p_max_attempts is null or p_max_attempts <= 0 then
    raise exception 'max_attempts deve ser maior que zero.' using errcode = '22023';
  end if;

  if p_time_limit_minutes is not null and p_time_limit_minutes <= 0 then
    raise exception 'time_limit_minutes deve ser nulo ou maior que zero.' using errcode = '22023';
  end if;

  if p_available_until is not null and p_available_until <= coalesce(p_available_from, now()) then
    raise exception 'available_until deve ser posterior a available_from.' using errcode = '22023';
  end if;

  select c.school_id
    into v_school_id
  from public.classes c
  where c.id = p_class_id
    and coalesce(c.status, 'active') = 'active';

  if v_school_id is null then
    raise exception 'Turma ativa nao encontrada.' using errcode = '42501';
  end if;

  select public.avalia_current_teacher_id() into v_teacher_id;

  if v_teacher_id is null then
    raise exception 'Professor institucional ativo nao encontrado.' using errcode = '42501';
  end if;

  if not public.institutional_teacher_can_manage_class(v_teacher_id, p_class_id, v_school_id) then
    raise exception 'Professor nao gerencia esta turma/escola.' using errcode = '42501';
  end if;

  if not public.avalia_assessment_is_assignable(p_assessment_id) then
    raise exception 'Avaliacao nao esta disponivel para aplicacao.' using errcode = '42501';
  end if;

  select coalesce(nullif(title, ''), 'Avalia+') into v_assessment_title
  from public.assessments
  where id = p_assessment_id;

  if v_target_type = 'student' then
    if p_student_id is null then
      raise exception 'student_id e obrigatorio para alvo student.' using errcode = '22023';
    end if;

    if not exists (
      select 1
      from public.enrollments e
      join public.students s on s.id = e.student_id
      where e.student_id = p_student_id
        and e.class_id = p_class_id
        and e.school_id = v_school_id
        and e.status = 'active'
        and e.enrolled_at <= now()
        and (e.ended_at is null or e.ended_at > now())
        and coalesce(s.status, 'active') = 'active'
    ) then
      raise exception 'Aluno nao pertence a turma/escola alvo.' using errcode = '42501';
    end if;
  elsif p_student_id is not null then
    raise exception 'student_id deve ser nulo para alvo class.' using errcode = '22023';
  end if;

  if v_target_type = 'class' then
    select *
      into v_assignment
    from public.assessment_assignments aa
    where aa.school_id = v_school_id
      and aa.assessment_id = p_assessment_id
      and aa.class_id = p_class_id
      and aa.target_type = 'class'
      and aa.status in ('draft', 'published')
    limit 1;

    update public.assessment_assignments
       set assigned_by = auth.uid(),
           available_from = coalesce(p_available_from, now()),
           available_until = p_available_until,
           time_limit_minutes = p_time_limit_minutes,
           max_attempts = p_max_attempts,
           status = v_status,
           published_at = case
             when v_status = 'published' then coalesce(published_at, now())
             else null
           end
     where id = v_assignment.id
     returning * into v_assignment;
  elsif v_target_type = 'student' then
    select *
      into v_assignment
    from public.assessment_assignments aa
    where aa.school_id = v_school_id
      and aa.assessment_id = p_assessment_id
      and aa.class_id = p_class_id
      and aa.student_id = p_student_id
      and aa.target_type = 'student'
      and aa.status in ('draft', 'published')
    limit 1;

    update public.assessment_assignments
       set assigned_by = auth.uid(),
           available_from = coalesce(p_available_from, now()),
           available_until = p_available_until,
           time_limit_minutes = p_time_limit_minutes,
           max_attempts = p_max_attempts,
           status = v_status,
           published_at = case
             when v_status = 'published' then coalesce(published_at, now())
             else null
           end
     where id = v_assignment.id
     returning * into v_assignment;
  end if;

  if v_assignment.id is null then
    insert into public.assessment_assignments (
      school_id,
      assessment_id,
      assigned_by,
      target_type,
      class_id,
      student_id,
      available_from,
      available_until,
      time_limit_minutes,
      max_attempts,
      status,
      published_at
    )
    values (
      v_school_id,
      p_assessment_id,
      auth.uid(),
      v_target_type,
      p_class_id,
      p_student_id,
      coalesce(p_available_from, now()),
      p_available_until,
      p_time_limit_minutes,
      p_max_attempts,
      v_status,
      case when v_status = 'published' then now() else null end
    )
    returning * into v_assignment;
  end if;

  if v_assignment.status = 'published' then
    perform public.communication_upsert_system_notification(
      'assessment',
      v_assignment.id,
      v_assignment.school_id,
      auth.uid(),
      'professor',
      v_assignment.target_type,
      v_assignment.class_id,
      v_assignment.student_id,
      'Avalia+: ' || coalesce(v_assessment_title, 'avaliação disponível'),
      'Nova avaliação disponível no Avalia+. Acesse para responder dentro do prazo.',
      current_date,
      'Abrir Avalia+',
      'avaliacoes'
    );
  end if;

  return v_assignment;
end;
$$;


ALTER FUNCTION "public"."teacher_create_assessment_assignment"("p_assessment_id" "uuid", "p_target_type" "text", "p_class_id" "uuid", "p_student_id" "uuid", "p_available_from" timestamp with time zone, "p_available_until" timestamp with time zone, "p_time_limit_minutes" integer, "p_max_attempts" integer, "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_create_assessment_scan_batch"("p_assignment_id" "uuid", "p_source_format" "text", "p_ocr_provider" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_assignment public.assessment_assignments%rowtype;
  v_batch public.assessment_scan_batches%rowtype;
  v_format text := upper(coalesce(nullif(p_source_format, ''), 'PDF'));
begin
  if auth.uid() is null then
    raise exception 'AUTH_REQUIRED' using errcode = '42501';
  end if;
  v_assignment := public.avalia_plus_assert_teacher_assignment(p_assignment_id);
  if v_format not in ('PDF', 'JPG', 'JPEG', 'PNG', 'MOBILE_PHOTO') then
    raise exception 'INVALID_SCAN_SOURCE_FORMAT';
  end if;

  insert into public.assessment_scan_batches (
    assessment_id, assignment_id, school_id, class_id, booklet_id,
    source_format, pipeline_status, ocr_provider, ocr_provider_status,
    metadata, created_by
  )
  values (
    v_assignment.assessment_id, v_assignment.id, v_assignment.school_id, v_assignment.class_id, v_assignment.booklet_id,
    v_format, 'UPLOAD', nullif(p_ocr_provider, ''), case when nullif(p_ocr_provider, '') is null then 'EMPTY_REAL' else 'PASS' end,
    coalesce(p_metadata, '{}'::jsonb) || jsonb_build_object('engine', 'OCR_PROVA_FISICA_V1'),
    auth.uid()
  )
  returning * into v_batch;

  perform public.avalia_plus_scan_log_event(v_batch.id, null, 'BATCH_CREATED', to_jsonb(v_batch));
  return jsonb_build_object('batch', to_jsonb(v_batch), 'ocr_provider', coalesce(v_batch.ocr_provider_status, 'EMPTY_REAL'));
end;
$$;


ALTER FUNCTION "public"."teacher_create_assessment_scan_batch"("p_assignment_id" "uuid", "p_source_format" "text", "p_ocr_provider" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_create_gamification_path"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare v_class_id uuid := nullif(p_payload->>'class_id','')::uuid; v_school_id uuid; v_path public.gamification_paths%rowtype; v_step jsonb; v_pos integer := 1;
begin
  select school_id into v_school_id from public.classes where id = v_class_id; if v_school_id is null then raise exception 'Turma nao encontrada'; end if;
  if not public.secretaria_can_manage_school(v_school_id) and not exists(select 1 from public.class_teacher_memberships ctm join public.teachers t on t.id = ctm.teacher_id where ctm.class_id = v_class_id and t.profile_id = auth.uid() and ctm.status = 'active') then raise exception 'Acesso negado para criar trilha'; end if;
  insert into public.gamification_paths(school_id,class_id,group_id,title,description,target_type,status,reward_xp,reward_coins,medal_id,metadata) values(v_school_id,v_class_id,nullif(p_payload->>'group_id','')::uuid,coalesce(nullif(p_payload->>'title',''),'Trilha gamificada'),p_payload->>'description',coalesce(nullif(p_payload->>'target_type',''),'class'),coalesce(nullif(p_payload->>'status',''),'draft'),greatest(coalesce(nullif(p_payload->>'reward_xp','')::integer,0),0),greatest(coalesce(nullif(p_payload->>'reward_coins','')::integer,0),0),nullif(p_payload->>'medal_id','')::uuid,coalesce(p_payload->'metadata','{}'::jsonb)) returning * into v_path;
  for v_step in select value from jsonb_array_elements(coalesce(p_payload->'steps','[]'::jsonb)) loop
    insert into public.gamification_path_steps(path_id,position,source_module,source_id,title,goal,reward_xp,reward_coins,required,metadata) values(v_path.id,coalesce(nullif(v_step->>'position','')::integer,v_pos),v_step->>'source_module',v_step->>'source_id',coalesce(nullif(v_step->>'title',''),'Etapa'),coalesce(v_step->'goal','{}'::jsonb),greatest(coalesce(nullif(v_step->>'reward_xp','')::integer,0),0),greatest(coalesce(nullif(v_step->>'reward_coins','')::integer,0),0),coalesce((v_step->>'required')::boolean,true),coalesce(v_step->'metadata','{}'::jsonb));
    v_pos := v_pos + 1;
  end loop;
  return jsonb_build_object('path',to_jsonb(v_path),'steps_count',v_pos-1);
end; $$;


ALTER FUNCTION "public"."teacher_create_gamification_path"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_create_live_session"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_class_id uuid := nullif(p_payload->>'class_id', '')::uuid;
  v_school_id uuid;
  v_teacher_id uuid;
  v_provider public.live_provider_settings%rowtype;
  v_session public.live_sessions%rowtype;
  v_invited integer := 0;
begin
  select c.school_id into v_school_id from public.classes c where c.id = v_class_id;
  if v_school_id is null then
    v_school_id := nullif(p_payload->>'school_id', '')::uuid;
  end if;
  if v_school_id is null then
    raise exception 'school_id ou class_id obrigatorio';
  end if;

  select t.id into v_teacher_id
  from public.teachers t
  where t.profile_id = auth.uid()
    and t.school_id = v_school_id
    and coalesce(t.status, 'active') = 'active'
  limit 1;

  if not public.secretaria_can_manage_school(v_school_id) and not exists (
    select 1
    from public.class_teacher_memberships ctm
    join public.teachers t on t.id = ctm.teacher_id
    where ctm.class_id = v_class_id
      and t.profile_id = auth.uid()
      and ctm.status = 'active'
      and ctm.started_at <= now()
      and (ctm.ended_at is null or ctm.ended_at > now())
  ) then
    raise exception 'Acesso negado para criar aula ao vivo';
  end if;

  select * into v_provider
  from public.live_provider_settings
  where school_id = v_school_id;

  insert into public.live_sessions (
    school_id, class_id, host_teacher_id, host_profile_id, audience_type,
    title, description, starts_at, ends_at, duration_minutes,
    provider, provider_status, room_url, room_external_id, capabilities, metadata
  )
  values (
    v_school_id,
    v_class_id,
    v_teacher_id,
    auth.uid(),
    coalesce(nullif(p_payload->>'audience_type', ''), 'class'),
    coalesce(nullif(p_payload->>'title', ''), 'Aula ao vivo'),
    p_payload->>'description',
    coalesce(nullif(p_payload->>'starts_at', '')::timestamptz, now()),
    nullif(p_payload->>'ends_at', '')::timestamptz,
    nullif(p_payload->>'duration_minutes', '')::integer,
    v_provider.provider,
    coalesce(v_provider.provider_status, 'EMPTY_REAL'),
    p_payload->>'room_url',
    p_payload->>'room_external_id',
    jsonb_build_object(
      'chat', coalesce((p_payload->>'chat')::boolean, true),
      'attendance', true,
      'mute', coalesce((p_payload->>'mute')::boolean, true),
      'screen_share', coalesce((p_payload->>'screen_share')::boolean, false),
      'media_playback', coalesce((p_payload->>'media_playback')::boolean, false),
      'recording', coalesce((p_payload->>'recording')::boolean, false),
      'external_guest_link', coalesce((p_payload->>'external_guest_link')::boolean, false)
    ),
    coalesce(p_payload->'metadata', '{}'::jsonb)
  )
  returning * into v_session;

  insert into public.live_session_events (session_id, actor_profile_id, event_type, details)
  values (v_session.id, auth.uid(), 'CREATED', to_jsonb(v_session));

  insert into public.live_session_participants (session_id, profile_id, role, join_status)
  values (v_session.id, auth.uid(), 'host', 'INVITED')
  on conflict do nothing;

  if v_class_id is not null then
    insert into public.live_session_participants (session_id, profile_id, student_id, role, join_status)
    select distinct v_session.id, s.user_id, e.student_id, 'student', 'INVITED'
    from public.enrollments e
    join public.students s on s.id = e.student_id
    where e.class_id = v_class_id
      and e.school_id = v_school_id
      and e.status = 'active'
      and e.ended_at is null
      and s.user_id is not null
    on conflict do nothing;
    get diagnostics v_invited = row_count;
  end if;

  return jsonb_build_object(
    'session', to_jsonb(v_session),
    'participants_invited', v_invited,
    'live_provider', coalesce(v_session.provider_status, 'EMPTY_REAL')
  );
end;
$$;


ALTER FUNCTION "public"."teacher_create_live_session"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_create_pedagogical_recommendation"("p_school_id" "uuid", "p_class_id" "uuid", "p_content_type" "text", "p_content_id" "text", "p_content_title" "text", "p_target_type" "text" DEFAULT 'class'::"text", "p_student_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_teacher public.teachers;
  v_existing public.pedagogical_recommendations;
  v_recommendation_id uuid;
  v_previous_status text;
  v_content_type text;
  v_content_id text := btrim(coalesce(p_content_id, ''));
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Usuario autenticado obrigatorio para recomendar atividade.';
  END IF;

  v_content_type := public.normalize_school_content_type(p_content_type);

  IF NULLIF(v_content_id, '') IS NULL OR NULLIF(trim(p_content_title), '') IS NULL THEN
    RAISE EXCEPTION 'Conteudo obrigatorio para recomendacao.';
  END IF;

  IF p_target_type NOT IN ('class', 'student') THEN
    RAISE EXCEPTION 'Destino invalido para recomendacao.';
  END IF;

  IF (p_target_type = 'class' AND p_student_id IS NOT NULL)
    OR (p_target_type = 'student' AND p_student_id IS NULL) THEN
    RAISE EXCEPTION 'Destino da recomendacao incompativel com aluno informado.';
  END IF;

  SELECT * INTO v_teacher
  FROM public.pedagogical_recommendation_current_teacher(p_school_id);

  IF v_teacher.id IS NULL THEN
    RAISE EXCEPTION 'Perfil de professor sem permissao para recomendar nesta escola.';
  END IF;

  IF NOT public.pedagogical_recommendation_teacher_can_target(
    v_teacher.id,
    p_school_id,
    p_class_id,
    p_student_id,
    p_target_type
  ) THEN
    RAISE EXCEPTION 'Professor sem permissao para recomendar para este destino.';
  END IF;

  IF NOT public.is_content_available_for_school(p_school_id, v_content_type, v_content_id) THEN
    RAISE EXCEPTION 'Conteudo indisponivel para esta escola.';
  END IF;

  SELECT * INTO v_existing
  FROM public.pedagogical_recommendations pr
  WHERE pr.school_id = p_school_id
    AND pr.teacher_id = v_teacher.id
    AND public.normalize_school_content_type(pr.content_type) = v_content_type
    AND lower(btrim(pr.content_id)) = lower(v_content_id)
    AND pr.target_type = p_target_type
    AND pr.class_id = p_class_id
    AND COALESCE(pr.student_id, '00000000-0000-0000-0000-000000000000'::uuid)
      = COALESCE(p_student_id, '00000000-0000-0000-0000-000000000000'::uuid)
    AND pr.status <> 'deleted'
  LIMIT 1;

  IF v_existing.id IS NOT NULL THEN
    v_previous_status := v_existing.status;

    UPDATE public.pedagogical_recommendations
    SET
      content_type = v_content_type,
      content_title = trim(p_content_title),
      note = NULLIF(trim(COALESCE(p_note, '')), ''),
      status = 'published',
      published_at = COALESCE(published_at, now()),
      updated_by = auth.uid()
    WHERE id = v_existing.id
    RETURNING id INTO v_recommendation_id;

    INSERT INTO public.pedagogical_recommendation_events (
      recommendation_id,
      event_type,
      from_status,
      to_status,
      performed_by
    )
    VALUES (
      v_recommendation_id,
      CASE WHEN v_previous_status = 'published' THEN 'edited' ELSE 'published' END,
      v_previous_status,
      'published',
      auth.uid()
    );
  ELSE
    INSERT INTO public.pedagogical_recommendations (
      school_id,
      teacher_id,
      content_type,
      content_id,
      content_title,
      target_type,
      class_id,
      student_id,
      note,
      status,
      published_at,
      created_by,
      updated_by
    )
    VALUES (
      p_school_id,
      v_teacher.id,
      v_content_type,
      v_content_id,
      trim(p_content_title),
      p_target_type,
      p_class_id,
      p_student_id,
      NULLIF(trim(COALESCE(p_note, '')), ''),
      'published',
      now(),
      auth.uid(),
      auth.uid()
    )
    RETURNING id INTO v_recommendation_id;

    INSERT INTO public.pedagogical_recommendation_events (
      recommendation_id,
      event_type,
      to_status,
      performed_by
    )
    VALUES (v_recommendation_id, 'created', 'published', auth.uid());
  END IF;

  RETURN jsonb_build_object(
    'recommendation_id', v_recommendation_id,
    'teacher_id', v_teacher.id,
    'school_id', p_school_id,
    'class_id', p_class_id,
    'target_type', p_target_type,
    'student_id', p_student_id,
    'content_type', v_content_type,
    'status', 'published'
  );
END;
$$;


ALTER FUNCTION "public"."teacher_create_pedagogical_recommendation"("p_school_id" "uuid", "p_class_id" "uuid", "p_content_type" "text", "p_content_id" "text", "p_content_title" "text", "p_target_type" "text", "p_student_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_create_recomposition_group"("p_class_id" "uuid", "p_title" "text", "p_target_skill" "text" DEFAULT NULL::"text", "p_descriptor" "text" DEFAULT NULL::"text", "p_student_ids" "uuid"[] DEFAULT '{}'::"uuid"[], "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_class public.classes%rowtype;
  v_teacher_id uuid := public.recomposition_current_teacher_id();
  v_group_id uuid;
  v_student_id uuid;
  v_count integer := 0;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if v_teacher_id is null then raise exception 'TEACHER_CONTEXT_REQUIRED'; end if;
  select * into v_class from public.classes where id = p_class_id;
  if not found then raise exception 'CLASS_NOT_FOUND'; end if;
  if not public.avalia_plus_teacher_can_manage_class(v_class.id, v_class.school_id) then raise exception 'RECOMPOSITION_CLASS_FORBIDDEN'; end if;
  if nullif(btrim(coalesce(p_title, '')), '') is null then raise exception 'TITLE_REQUIRED'; end if;

  insert into public.recomposition_intervention_groups (school_id, class_id, teacher_id, title, target_skill, descriptor, metadata)
  values (v_class.school_id, v_class.id, v_teacher_id, btrim(p_title), nullif(btrim(coalesce(p_target_skill, '')), ''), nullif(btrim(coalesce(p_descriptor, '')), ''), coalesce(p_metadata, '{}'::jsonb))
  returning id into v_group_id;

  foreach v_student_id in array coalesce(p_student_ids, '{}'::uuid[]) loop
    if not public.recomposition_student_in_class(v_class.school_id, v_class.id, v_student_id) then raise exception 'STUDENT_OUT_OF_CLASS'; end if;
    insert into public.recomposition_intervention_group_students (group_id, student_id)
    values (v_group_id, v_student_id)
    on conflict (group_id, student_id) do update set status = 'active';
    v_count := v_count + 1;
  end loop;

  return jsonb_build_object('group_id', v_group_id, 'student_count', v_count, 'status', 'PASS');
end;
$$;


ALTER FUNCTION "public"."teacher_create_recomposition_group"("p_class_id" "uuid", "p_title" "text", "p_target_skill" "text", "p_descriptor" "text", "p_student_ids" "uuid"[], "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_create_recomposition_plan"("p_class_id" "uuid", "p_title" "text", "p_target_type" "text", "p_target_skill" "text" DEFAULT NULL::"text", "p_descriptor" "text" DEFAULT NULL::"text", "p_objective" "text" DEFAULT NULL::"text", "p_period_start" "date" DEFAULT NULL::"date", "p_period_end" "date" DEFAULT NULL::"date", "p_student_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_group_id" "uuid" DEFAULT NULL::"uuid", "p_resources" "jsonb" DEFAULT '[]'::"jsonb", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_class public.classes%rowtype;
  v_teacher_id uuid := public.recomposition_current_teacher_id();
  v_plan_id uuid;
  v_student_ids uuid[] := '{}'::uuid[];
  v_student_id uuid;
  v_resource jsonb;
  v_resource_id uuid;
  v_rec jsonb;
  v_rec_ids jsonb;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if v_teacher_id is null then raise exception 'TEACHER_CONTEXT_REQUIRED'; end if;
  select * into v_class from public.classes where id = p_class_id;
  if not found then raise exception 'CLASS_NOT_FOUND'; end if;
  if not public.avalia_plus_teacher_can_manage_class(v_class.id, v_class.school_id) then raise exception 'RECOMPOSITION_CLASS_FORBIDDEN'; end if;
  if p_target_type not in ('student', 'group', 'class') then raise exception 'INVALID_TARGET_TYPE'; end if;
  if nullif(btrim(coalesce(p_title, '')), '') is null then raise exception 'TITLE_REQUIRED'; end if;

  if p_target_type = 'class' then
    select coalesce(array_agg(e.student_id), '{}'::uuid[]) into v_student_ids
    from public.enrollments e join public.students s on s.id = e.student_id
    where e.school_id = v_class.school_id and e.class_id = v_class.id and e.status in ('active', 'ativo') and coalesce(s.status, 'active') in ('active', 'ativo') and e.enrolled_at <= now() and (e.ended_at is null or e.ended_at > now());
  elsif p_target_type = 'group' then
    if p_group_id is null then raise exception 'GROUP_REQUIRED'; end if;
    if not exists (select 1 from public.recomposition_intervention_groups g where g.id = p_group_id and g.school_id = v_class.school_id and g.class_id = v_class.id and g.teacher_id = v_teacher_id and g.status <> 'archived') then raise exception 'GROUP_FORBIDDEN'; end if;
    select coalesce(array_agg(gs.student_id), '{}'::uuid[]) into v_student_ids from public.recomposition_intervention_group_students gs where gs.group_id = p_group_id and gs.status = 'active';
  else
    v_student_ids := coalesce(p_student_ids, '{}'::uuid[]);
  end if;

  if coalesce(array_length(v_student_ids, 1), 0) = 0 then raise exception 'NO_STUDENTS_SELECTED'; end if;
  foreach v_student_id in array v_student_ids loop
    if not public.recomposition_student_in_class(v_class.school_id, v_class.id, v_student_id) then raise exception 'STUDENT_OUT_OF_CLASS'; end if;
  end loop;

  insert into public.recomposition_plans (school_id, class_id, teacher_id, group_id, target_type, title, target_skill, descriptor, objective, period_start, period_end, responsible_teacher_id, metadata)
  values (v_class.school_id, v_class.id, v_teacher_id, p_group_id, p_target_type, btrim(p_title), nullif(btrim(coalesce(p_target_skill, '')), ''), nullif(btrim(coalesce(p_descriptor, '')), ''), nullif(btrim(coalesce(p_objective, '')), ''), p_period_start, p_period_end, v_teacher_id, coalesce(p_metadata, '{}'::jsonb))
  returning id into v_plan_id;

  foreach v_student_id in array v_student_ids loop
    insert into public.recomposition_plan_students (plan_id, student_id) values (v_plan_id, v_student_id) on conflict (plan_id, student_id) do nothing;
  end loop;
  insert into public.recomposition_tracking_events (plan_id, event_type, to_status, evidence) values (v_plan_id, 'diagnosis', 'active', jsonb_build_object('target_skill', p_target_skill, 'descriptor', p_descriptor, 'student_count', coalesce(array_length(v_student_ids, 1), 0)));

  if jsonb_typeof(coalesce(p_resources, '[]'::jsonb)) = 'array' then
    for v_resource in select * from jsonb_array_elements(coalesce(p_resources, '[]'::jsonb)) loop
      v_rec_ids := '[]'::jsonb;
      insert into public.recomposition_plan_resources (plan_id, content_type, content_id, content_title, source, metadata)
      values (v_plan_id, lower(coalesce(v_resource ->> 'content_type', 'other')), nullif(btrim(coalesce(v_resource ->> 'content_id', '')), ''), btrim(coalesce(v_resource ->> 'content_title', v_resource ->> 'title', 'Conteudo de recomposicao')), coalesce(nullif(btrim(v_resource ->> 'source'), ''), 'manual'), v_resource)
      returning id into v_resource_id;

      if lower(coalesce(v_resource ->> 'content_type', 'other')) in ('printable_activity', 'activity', 'book', 'game', 'experience', 'free_proposal', 'other') then
        if p_target_type = 'class' then
          v_rec := public.teacher_create_pedagogical_recommendation(v_class.school_id, v_class.id, lower(coalesce(v_resource ->> 'content_type', 'other')), coalesce(v_resource ->> 'content_id', v_resource_id::text), btrim(coalesce(v_resource ->> 'content_title', v_resource ->> 'title', 'Conteudo de recomposicao')), 'class', null, coalesce(v_resource ->> 'note', 'Plano de recomposicao: ' || btrim(p_title)));
          v_rec_ids := jsonb_build_array(v_rec ->> 'recommendation_id');
        else
          foreach v_student_id in array v_student_ids loop
            v_rec := public.teacher_create_pedagogical_recommendation(v_class.school_id, v_class.id, lower(coalesce(v_resource ->> 'content_type', 'other')), coalesce(v_resource ->> 'content_id', v_resource_id::text), btrim(coalesce(v_resource ->> 'content_title', v_resource ->> 'title', 'Conteudo de recomposicao')), 'student', v_student_id, coalesce(v_resource ->> 'note', 'Plano de recomposicao: ' || btrim(p_title)));
            v_rec_ids := v_rec_ids || jsonb_build_array(v_rec ->> 'recommendation_id');
          end loop;
        end if;
        update public.recomposition_plan_resources set recommendation_id = nullif(v_rec_ids ->> 0, '')::uuid, metadata = metadata || jsonb_build_object('recommendation_ids', v_rec_ids) where id = v_resource_id;
      end if;
    end loop;
  end if;

  insert into public.recomposition_tracking_events (plan_id, event_type, to_status, evidence) values (v_plan_id, 'intervention', 'active', jsonb_build_object('resources', jsonb_array_length(coalesce(p_resources, '[]'::jsonb))));
  return jsonb_build_object('plan_id', v_plan_id, 'student_count', coalesce(array_length(v_student_ids, 1), 0), 'status', 'PASS');
end;
$$;


ALTER FUNCTION "public"."teacher_create_recomposition_plan"("p_class_id" "uuid", "p_title" "text", "p_target_type" "text", "p_target_skill" "text", "p_descriptor" "text", "p_objective" "text", "p_period_start" "date", "p_period_end" "date", "p_student_ids" "uuid"[], "p_group_id" "uuid", "p_resources" "jsonb", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_create_writing_prompt"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_class public.classes%rowtype;
  v_prompt public.writing_prompts%rowtype;
  v_teacher_id uuid := public.avalia_current_teacher_id();
  v_status text := lower(coalesce(p_payload->>'status', 'draft'));
  v_target_type text := lower(coalesce(p_payload->>'target_type', 'class'));
  v_student jsonb;
  v_group_id uuid := nullif(p_payload->>'group_id', '')::uuid;
  v_student_id uuid;
begin
  if auth.uid() is null then
    raise exception 'AUTH_REQUIRED' using errcode = '42501';
  end if;

  select * into v_class
  from public.classes
  where id = nullif(p_payload->>'class_id', '')::uuid;

  if v_class.id is null then
    raise exception 'CLASS_REQUIRED' using errcode = '22023';
  end if;
  if not public.avalia_plus_teacher_can_manage_class(v_class.id, v_class.school_id) then
    raise exception 'WRITING_CLASS_FORBIDDEN' using errcode = '42501';
  end if;
  if v_status not in ('draft', 'published') then
    raise exception 'INVALID_WRITING_PROMPT_STATUS';
  end if;

  insert into public.writing_prompts (
    school_id, class_id, teacher_id, title, textual_genre, theme, prompt_command,
    school_year, component, bncc_codes, rubric, correction_modes, due_at,
    status, metadata, created_by, published_at
  )
  values (
    v_class.school_id,
    v_class.id,
    v_teacher_id,
    coalesce(nullif(p_payload->>'title', ''), 'Producao textual'),
    coalesce(nullif(p_payload->>'textual_genre', ''), nullif(p_payload->>'genre', ''), 'texto'),
    coalesce(nullif(p_payload->>'theme', ''), 'Tema livre'),
    coalesce(nullif(p_payload->>'prompt_command', ''), nullif(p_payload->>'command', ''), 'Produza seu texto conforme a proposta.'),
    coalesce(nullif(p_payload->>'school_year', ''), v_class.ano_escolar),
    nullif(p_payload->>'component', ''),
    coalesce(array(select jsonb_array_elements_text(coalesce(p_payload->'bncc_codes', '[]'::jsonb))), '{}'::text[]),
    coalesce(p_payload->'rubric', '[]'::jsonb),
    coalesce(array(select jsonb_array_elements_text(coalesce(p_payload->'correction_modes', '[]'::jsonb))), array['DOCENTE']::text[]),
    nullif(p_payload->>'due_at', '')::timestamptz,
    v_status,
    coalesce(p_payload->'metadata', '{}'::jsonb) || jsonb_build_object('engine', 'PRODUCAO_TEXTUAL_IA_V1'),
    auth.uid(),
    case when v_status = 'published' then now() else null end
  )
  returning * into v_prompt;

  if v_target_type = 'group' then
    if v_group_id is null or not exists (
      select 1 from public.recomposition_intervention_groups g
      where g.id = v_group_id
        and g.class_id = v_class.id
        and g.school_id = v_class.school_id
        and g.status <> 'archived'
    ) then
      raise exception 'WRITING_GROUP_TARGET_INVALID';
    end if;
    insert into public.writing_prompt_targets (prompt_id, target_type, group_id, class_id)
    values (v_prompt.id, 'group', v_group_id, v_class.id);
  elsif v_target_type = 'student' then
    for v_student in select * from jsonb_array_elements(coalesce(p_payload->'student_ids', '[]'::jsonb))
    loop
      v_student_id := trim(both '"' from v_student::text)::uuid;
      if not exists (
        select 1 from public.enrollments e
        where e.student_id = v_student_id
          and e.class_id = v_class.id
          and e.school_id = v_class.school_id
          and e.status in ('active', 'ativo')
      ) then
        raise exception 'WRITING_STUDENT_TARGET_INVALID';
      end if;
      insert into public.writing_prompt_targets (prompt_id, target_type, student_id, class_id)
      values (v_prompt.id, 'student', v_student_id, v_class.id);
    end loop;
  else
    insert into public.writing_prompt_targets (prompt_id, target_type, class_id)
    values (v_prompt.id, 'class', v_class.id);
  end if;

  perform public.writing_log_event(v_prompt.id, null, null, 'PROMPT_CREATED', to_jsonb(v_prompt));
  return jsonb_build_object('prompt', to_jsonb(v_prompt), 'target_type', v_target_type);
end;
$$;


ALTER FUNCTION "public"."teacher_create_writing_prompt"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_delete_pedagogical_recommendation"("p_recommendation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_row public.pedagogical_recommendations;
  v_teacher public.teachers;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Usuario autenticado obrigatorio para excluir recomendacao.';
  END IF;

  SELECT * INTO v_row
  FROM public.pedagogical_recommendations
  WHERE id = p_recommendation_id
    AND status <> 'deleted';

  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'Recomendacao nao encontrada.';
  END IF;

  SELECT * INTO v_teacher
  FROM public.pedagogical_recommendation_current_teacher(v_row.school_id);

  IF v_teacher.id IS NULL OR v_teacher.id <> v_row.teacher_id THEN
    RAISE EXCEPTION 'Professor sem permissao para excluir esta recomendacao.';
  END IF;

  IF NOT public.pedagogical_recommendation_teacher_can_target(
    v_teacher.id,
    v_row.school_id,
    v_row.class_id,
    v_row.student_id,
    v_row.target_type
  ) THEN
    RAISE EXCEPTION 'Professor sem permissao para excluir esta recomendacao.';
  END IF;

  UPDATE public.pedagogical_recommendations
  SET
    status = 'deleted',
    deleted_at = now(),
    deleted_by = auth.uid(),
    updated_by = auth.uid()
  WHERE id = p_recommendation_id;

  INSERT INTO public.pedagogical_recommendation_events (
    recommendation_id,
    event_type,
    from_status,
    to_status,
    performed_by
  )
  VALUES (p_recommendation_id, 'deleted', v_row.status, 'deleted', auth.uid());

  RETURN jsonb_build_object(
    'recommendation_id', p_recommendation_id,
    'status', 'deleted'
  );
END;
$$;


ALTER FUNCTION "public"."teacher_delete_pedagogical_recommendation"("p_recommendation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_generate_assessment_print_export"("p_assessment_id" "uuid", "p_export_type" "text", "p_format" "text" DEFAULT 'PDF'::"text", "p_assignment_id" "uuid" DEFAULT NULL::"uuid", "p_class_id" "uuid" DEFAULT NULL::"uuid", "p_booklet_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_assessment public.assessments%rowtype;
  v_assignment public.assessment_assignments%rowtype;
  v_school_id uuid;
  v_class_id uuid;
  v_booklet_id uuid;
  v_export public.assessment_print_exports%rowtype;
  v_payload jsonb;
begin
  if auth.uid() is null then
    raise exception 'AUTH_REQUIRED' using errcode = '42501';
  end if;

  select * into v_assessment from public.assessments where id = p_assessment_id;
  if v_assessment.id is null then
    raise exception 'ASSESSMENT_NOT_FOUND';
  end if;

  if p_assignment_id is not null then
    v_assignment := public.avalia_plus_assert_teacher_assignment(p_assignment_id);
    if v_assignment.assessment_id <> p_assessment_id then
      raise exception 'ASSIGNMENT_ASSESSMENT_MISMATCH';
    end if;
    v_school_id := v_assignment.school_id;
    v_class_id := v_assignment.class_id;
    v_booklet_id := coalesce(p_booklet_id, v_assignment.booklet_id);
  else
    v_school_id := v_assessment.school_id;
    v_class_id := p_class_id;
    v_booklet_id := p_booklet_id;
    if v_class_id is not null and not public.avalia_plus_teacher_can_manage_class(v_class_id, v_school_id) then
      raise exception 'UNAUTHORIZED_CLASS_EXPORT' using errcode = '42501';
    end if;
    if v_class_id is null and not (public.is_platform_admin() or public.secretaria_can_manage_school(v_school_id) or v_assessment.owner_user_id = auth.uid()) then
      raise exception 'UNAUTHORIZED_ASSESSMENT_EXPORT' using errcode = '42501';
    end if;
  end if;

  if upper(coalesce(p_export_type, '')) not in ('STUDENT_TEST', 'TEACHER_KEY', 'ANSWER_SHEET', 'ATTENDANCE_LIST') then
    raise exception 'INVALID_EXPORT_TYPE';
  end if;
  if upper(coalesce(p_format, '')) not in ('PDF', 'DOCX', 'HTML') then
    raise exception 'INVALID_EXPORT_FORMAT';
  end if;

  with selected_questions as (
    select
      aq.id as assessment_question_id,
      aq.question_id,
      coalesce(abq.position, aq.position) as position,
      aq.points,
      qi.code,
      qi.statement,
      qi.command_text,
      qi.base_text,
      qi.component,
      qi.school_year,
      qi.bncc_skill,
      qi.reference_matrix,
      qi.curriculum_matrix,
      qi.thematic_unit,
      qi.knowledge_object,
      qi.difficulty,
      aq.version_snapshot
    from public.assessment_questions aq
    join public.question_items qi on qi.id = aq.question_id
    left join public.assessment_booklet_questions abq on abq.assessment_question_id = aq.id
      and (v_booklet_id is null or abq.booklet_id = v_booklet_id)
    where aq.assessment_id = p_assessment_id
      and (v_booklet_id is null or abq.booklet_id = v_booklet_id)
  ), question_payload as (
    select jsonb_agg(
      jsonb_build_object(
        'assessment_question_id', assessment_question_id,
        'question_id', question_id,
        'position', position,
        'points', points,
        'code', code,
        'statement', statement,
        'command_text', command_text,
        'base_text', base_text,
        'component', component,
        'school_year', school_year,
        'bncc_skill', bncc_skill,
        'reference_matrix', reference_matrix,
        'curriculum_matrix', curriculum_matrix,
        'thematic_unit', thematic_unit,
        'knowledge_object', knowledge_object,
        'difficulty', difficulty,
        'version_snapshot', version_snapshot,
        'alternatives', (
          select jsonb_agg(
            jsonb_build_object(
              'id', qa.id,
              'position', qa.position,
              'label', chr(64 + qa.position),
              'body', qa.body,
              'is_correct', case when upper(p_export_type) = 'TEACHER_KEY' then qa.is_correct else null end
            )
            order by qa.position
          )
          from public.question_alternatives qa
          where qa.question_id = selected_questions.question_id
        )
      )
      order by position
    ) as questions
    from selected_questions
  ), students_payload as (
    select coalesce(jsonb_agg(
      jsonb_build_object(
        'student_id', s.id,
        'student_name', s.nome,
        'class_id', e.class_id,
        'school_id', e.school_id
      )
      order by s.nome
    ), '[]'::jsonb) as students
    from public.enrollments e
    join public.students s on s.id = e.student_id
    where v_class_id is not null
      and e.class_id = v_class_id
      and e.school_id = v_school_id
      and e.status = 'active'
      and coalesce(s.status, 'active') in ('active', 'ativo')
  )
  select jsonb_build_object(
    'assessment', to_jsonb(v_assessment),
    'assignment', case when v_assignment.id is null then null else to_jsonb(v_assignment) end,
    'export_type', upper(p_export_type),
    'format', upper(p_format),
    'booklet_id', v_booklet_id,
    'school_id', v_school_id,
    'class_id', v_class_id,
    'questions', coalesce((select questions from question_payload), '[]'::jsonb),
    'students', case when upper(p_export_type) in ('ANSWER_SHEET', 'ATTENDANCE_LIST') then (select students from students_payload) else '[]'::jsonb end,
    'generated_at', now()
  ) into v_payload;

  insert into public.assessment_print_exports (
    assessment_id, assignment_id, school_id, class_id, booklet_id,
    export_type, format, file_name, content_type, payload, metadata, created_by
  )
  values (
    p_assessment_id,
    p_assignment_id,
    v_school_id,
    v_class_id,
    v_booklet_id,
    upper(p_export_type),
    upper(p_format),
    lower(replace(coalesce(v_assessment.title, 'avalia'), ' ', '-')) || '-' || lower(upper(p_export_type)) || '.' || lower(upper(p_format)),
    case upper(p_format)
      when 'DOCX' then 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
      when 'PDF' then 'application/pdf'
      else 'text/html'
    end,
    v_payload,
    jsonb_build_object('engine', 'AVALIA_PLUS_2_FASE_3', 'duplicate_result_engine', false),
    auth.uid()
  )
  returning * into v_export;

  return jsonb_build_object('export', to_jsonb(v_export), 'payload', v_payload);
end;
$$;


ALTER FUNCTION "public"."teacher_generate_assessment_print_export"("p_assessment_id" "uuid", "p_export_type" "text", "p_format" "text", "p_assignment_id" "uuid", "p_class_id" "uuid", "p_booklet_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_get_assessment_application_monitor"("p_assignment_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_assignment public.assessment_assignments%rowtype;
  v_payload jsonb;
begin
  select * into v_assignment from public.assessment_assignments where id = p_assignment_id;
  if v_assignment.id is null or not public.avalia_plus_teacher_can_manage_class(v_assignment.class_id, v_assignment.school_id) then
    raise exception 'Acesso negado ao monitoramento desta aplicacao.' using errcode = '42501';
  end if;
  with eligible as (
    select e.student_id, s.nome as student_name
    from public.enrollments e join public.students s on s.id = e.student_id
    where e.class_id = v_assignment.class_id and e.school_id = v_assignment.school_id and e.status = 'active' and coalesce(s.status, 'active') in ('active', 'ativo') and (v_assignment.target_type = 'class' or e.student_id = v_assignment.student_id)
  ), latest_attempt as (
    select distinct on (at.student_id) at.* from public.assessment_attempts at where at.assignment_id = p_assignment_id order by at.student_id, at.started_at desc
  ), rows as (
    select e.student_id, e.student_name, at.id as attempt_id, coalesce(at.application_status, 'AGENDADA') as application_status, at.status, at.started_at, at.submitted_at, at.last_autosaved_at, at.answered_count, at.question_count, at.score_percentage
    from eligible e left join latest_attempt at on at.student_id = e.student_id
  )
  select jsonb_build_object('assignment', to_jsonb(v_assignment), 'eligible', (select count(*) from rows), 'started', (select count(*) from rows where attempt_id is not null), 'in_progress', (select count(*) from rows where application_status = 'EM_ANDAMENTO'), 'completed', (select count(*) from rows where application_status = 'CONCLUIDA'), 'incomplete', (select count(*) from rows where application_status = 'INCOMPLETA'), 'students', coalesce((select jsonb_agg(to_jsonb(rows) order by student_name) from rows), '[]'::jsonb)) into v_payload;
  return v_payload;
end;
$$;


ALTER FUNCTION "public"."teacher_get_assessment_application_monitor"("p_assignment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_get_assessment_class_results"("p_assignment_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_payload jsonb;
begin
  if auth.uid() is null then
    raise exception 'Usuario autenticado obrigatorio.' using errcode = '42501';
  end if;

  if p_assignment_id is null then
    raise exception 'assignment_id obrigatorio.' using errcode = '22023';
  end if;

  if not (
    public.is_platform_admin()
    or public.avalia_teacher_can_manage_assignment(p_assignment_id)
    or exists (
      select 1
      from public.assessment_assignments aa
      where aa.id = p_assignment_id
        and public.secretaria_can_manage_school(aa.school_id)
    )
  ) then
    raise exception 'Acesso negado aos resultados desta avaliacao.' using errcode = '42501';
  end if;

  with assignment_scope as (
    select
      aa.*,
      a.title as assessment_title,
      a.component as assessment_component,
      a.school_year as assessment_year,
      c.nome as class_name,
      s.nome as school_name
    from public.assessment_assignments aa
    join public.assessments a on a.id = aa.assessment_id
    join public.classes c on c.id = aa.class_id
    join public.schools s on s.id = aa.school_id
    where aa.id = p_assignment_id
  ),
  assigned_students as (
    select distinct st.id, st.nome
    from assignment_scope aa
    join public.enrollments e
      on e.class_id = aa.class_id
     and e.school_id = aa.school_id
     and e.status = 'active'
     and e.enrolled_at <= now()
     and (e.ended_at is null or e.ended_at > now())
    join public.students st
      on st.id = e.student_id
     and coalesce(st.status, 'active') = 'active'
    where aa.target_type = 'class'
       or (aa.target_type = 'student' and st.id = aa.student_id)
  ),
  assigned_count as (
    select count(*)::integer as total from assigned_students
  ),
  attempts as (
    select at.*
    from public.assessment_attempts at
    where at.assignment_id = p_assignment_id
  ),
  latest_attempt as (
    select distinct on (at.student_id) at.*
    from attempts at
    order by at.student_id, at.started_at desc
  ),
  results as (
    select ar.*
    from public.assessment_results ar
    where ar.assignment_id = p_assignment_id
  ),
  summary as (
    select
      (select total from assigned_count) as assigned_students,
      (select count(distinct student_id)::integer from attempts) as started_students,
      (select count(distinct student_id)::integer from results) as completed_students,
      coalesce(round(avg(score_percentage)::numeric, 2), 0) as average_percentage,
      coalesce(round(avg(correct_count)::numeric, 2), 0) as average_correct,
      coalesce(max(score_percentage), 0) as highest_percentage,
      coalesce(min(score_percentage), 0) as lowest_percentage
    from results
  ),
  students_payload as (
    select coalesce(jsonb_agg(
      jsonb_build_object(
        'student_id', st.id,
        'student_name', st.nome,
        'status', coalesce(r.status, la.status, 'not_started'),
        'attempt_id', la.id,
        'score_percentage', r.score_percentage,
        'answered_count', coalesce(r.answered_count, la.answered_count, 0),
        'correct_count', coalesce(r.correct_count, la.correct_count, 0),
        'incorrect_count', coalesce(r.incorrect_count, la.incorrect_count, 0),
        'unanswered_count', coalesce(r.unanswered_count, la.unanswered_count, 0),
        'finalized_at', r.finalized_at
      )
      order by st.nome
    ), '[]'::jsonb) as data
    from assigned_students st
    left join latest_attempt la on la.student_id = st.id
    left join results r on r.student_id = st.id
  ),
  questions_payload as (
    select coalesce(jsonb_agg(
      jsonb_build_object(
        'question_id', aq.question_id,
        'position', aq.position,
        'title', coalesce(qi.internal_title, left(qi.statement, 140), 'Questao'),
        'bncc_skill', nullif(btrim(coalesce(qi.bncc_skill, '')), ''),
        'responses', coalesce(qs.responses, 0),
        'correct', coalesce(qs.correct, 0),
        'incorrect', coalesce(qs.incorrect, 0),
        'unanswered', greatest((select total from assigned_count) - coalesce(qs.responses, 0), 0),
        'error_rate', case when coalesce(qs.responses, 0) > 0 then round((coalesce(qs.incorrect, 0)::numeric / qs.responses) * 100, 2) else 0 end
      )
      order by coalesce(qs.incorrect, 0) desc, aq.position
    ), '[]'::jsonb) as data
    from public.assessment_questions aq
    join assignment_scope aa on aa.assessment_id = aq.assessment_id
    join public.question_items qi on qi.id = aq.question_id
    left join lateral (
      select
        count(ar.id)::integer as responses,
        count(ar.id) filter (where ar.is_correct is true)::integer as correct,
        count(ar.id) filter (where coalesce(ar.is_correct, false) is false)::integer as incorrect
      from public.assessment_responses ar
      join public.assessment_attempts at on at.id = ar.attempt_id
      where at.assignment_id = aa.id
        and at.status in ('submitted', 'graded')
        and ar.question_id = aq.question_id
    ) qs on true
  ),
  skills_payload as (
    select coalesce(jsonb_agg(
      jsonb_build_object(
        'bncc_skill', bncc_skill,
        'questions', question_count,
        'responses', responses,
        'correct', correct,
        'incorrect', incorrect,
        'performance_percentage', case when responses > 0 then round((correct::numeric / responses) * 100, 2) else 0 end
      )
      order by case when responses > 0 then (correct::numeric / responses) else 0 end asc, bncc_skill
    ), '[]'::jsonb) as data
    from (
      select
        coalesce(nullif(btrim(qi.bncc_skill), ''), 'SEM_HABILIDADE') as bncc_skill,
        count(distinct aq.question_id)::integer as question_count,
        count(ar.id)::integer as responses,
        count(ar.id) filter (where ar.is_correct is true)::integer as correct,
        count(ar.id) filter (where coalesce(ar.is_correct, false) is false)::integer as incorrect
      from assignment_scope aa
      join public.assessment_questions aq on aq.assessment_id = aa.assessment_id
      join public.question_items qi on qi.id = aq.question_id
      left join public.assessment_attempts at
        on at.assignment_id = aa.id
       and at.status in ('submitted', 'graded')
      left join public.assessment_responses ar
        on ar.attempt_id = at.id
       and ar.question_id = aq.question_id
      group by coalesce(nullif(btrim(qi.bncc_skill), ''), 'SEM_HABILIDADE')
    ) skill_rows
  )
  select jsonb_build_object(
    'assignment', jsonb_build_object(
      'id', aa.id,
      'assessment_id', aa.assessment_id,
      'assessment_title', aa.assessment_title,
      'component', aa.assessment_component,
      'school_year', aa.assessment_year,
      'school_id', aa.school_id,
      'school_name', aa.school_name,
      'class_id', aa.class_id,
      'class_name', aa.class_name,
      'target_type', aa.target_type,
      'available_from', aa.available_from,
      'available_until', aa.available_until,
      'status', aa.status
    ),
    'summary', jsonb_build_object(
      'assigned_students', sm.assigned_students,
      'started_students', sm.started_students,
      'completed_students', sm.completed_students,
      'participation_percentage', case when sm.assigned_students > 0 then round((sm.completed_students::numeric / sm.assigned_students) * 100, 2) else 0 end,
      'average_correct', sm.average_correct,
      'average_percentage', sm.average_percentage,
      'highest_percentage', sm.highest_percentage,
      'lowest_percentage', sm.lowest_percentage
    ),
    'students', sp.data,
    'questions', qp.data,
    'skills', sk.data
  )
  into v_payload
  from assignment_scope aa
  cross join summary sm
  cross join students_payload sp
  cross join questions_payload qp
  cross join skills_payload sk;

  if v_payload is null then
    raise exception 'Atribuicao nao encontrada.' using errcode = '42501';
  end if;

  return v_payload;
end;
$$;


ALTER FUNCTION "public"."teacher_get_assessment_class_results"("p_assignment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_get_assessment_pedagogical_intelligence"("p_assignment_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
  select public.avalia_plus_get_pedagogical_intelligence('assignment', p_assignment_id, null, null, null, null, null, null, null, null, null);
$$;


