CREATE OR REPLACE FUNCTION "public"."teacher_get_class_diary_period_summary"("p_class_id" "uuid", "p_from" "date", "p_to" "date") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  WITH ctx AS (
    SELECT
      cl.id AS class_id,
      cl.school_id,
      t.id AS teacher_id,
      cl.nome::text AS class_name,
      sc.nome::text AS school_name
    FROM public.classes cl
    JOIN public.schools sc ON sc.id = cl.school_id
    JOIN public.teachers t ON t.school_id = cl.school_id AND t.profile_id = auth.uid() AND t.status = 'active'
    WHERE cl.id = p_class_id
      AND public.class_diary_teacher_can_manage(cl.school_id, cl.id, t.id)
    LIMIT 1
  ),
  diary AS (
    SELECT cde.*
    FROM public.class_diary_entries cde
    JOIN ctx ON ctx.class_id = cde.class_id AND ctx.teacher_id = cde.teacher_id
    WHERE cde.status <> 'deleted'
      AND cde.entry_date BETWEEN p_from AND p_to
  ),
  attendance AS (
    SELECT
      count(*)::bigint AS total,
      count(*) FILTER (WHERE ar.status = 'present')::bigint AS present,
      count(*) FILTER (WHERE ar.status = 'absent')::bigint AS absent,
      count(*) FILTER (WHERE ar.status = 'justified')::bigint AS justified
    FROM public.attendance_records ar
    JOIN ctx ON ctx.school_id = ar.school_id AND ctx.class_id = ar.class_id
    WHERE ar.attendance_date BETWEEN p_from AND p_to
  ),
  plans AS (
    SELECT tp.*
    FROM public.teacher_plans tp
    JOIN ctx ON ctx.school_id = tp.school_id AND ctx.class_id = tp.class_id AND ctx.teacher_id = tp.teacher_id
    WHERE tp.status <> 'archived'
      AND tp.plan_date BETWEEN p_from AND p_to
  ),
  published AS (
    SELECT cce.*
    FROM public.class_calendar_entries cce
    JOIN ctx ON ctx.school_id = cce.school_id AND ctx.class_id = cce.class_id AND ctx.teacher_id = cce.teacher_id
    WHERE cce.status = 'published'
      AND cce.entry_date BETWEEN p_from AND p_to
  ),
  links AS (
    SELECT count(*)::bigint AS total
    FROM public.class_diary_activity_links cdl
    JOIN diary ON diary.id = cdl.diary_entry_id
  ),
  notes AS (
    SELECT cdn.*, st.nome AS student_name
    FROM public.class_diary_student_notes cdn
    JOIN ctx ON ctx.school_id = cdn.school_id AND ctx.class_id = cdn.class_id AND ctx.teacher_id = cdn.teacher_id
    JOIN public.students st ON st.id = cdn.student_id
    WHERE cdn.status <> 'deleted'
      AND cdn.note_date BETWEEN p_from AND p_to
  )
  SELECT CASE
    WHEN NOT EXISTS (SELECT 1 FROM ctx) THEN
      jsonb_build_object('error', 'Professor sem permissao para consolidar esta turma.')
    ELSE
      jsonb_build_object(
        'class_id', (SELECT class_id FROM ctx),
        'school_id', (SELECT school_id FROM ctx),
        'teacher_id', (SELECT teacher_id FROM ctx),
        'class_name', (SELECT class_name FROM ctx),
        'school_name', (SELECT school_name FROM ctx),
        'from', p_from,
        'to', p_to,
        'registered_classes', (SELECT count(*) FROM diary),
        'attendance_total', coalesce((SELECT total FROM attendance), 0),
        'attendance_present', coalesce((SELECT present FROM attendance), 0),
        'attendance_absent', coalesce((SELECT absent FROM attendance), 0),
        'attendance_justified', coalesce((SELECT justified FROM attendance), 0),
        'planned_count', (SELECT count(*) FROM plans),
        'published_count', (SELECT count(*) FROM published),
        'activity_link_count', coalesce((SELECT total FROM links), 0),
        'individual_note_count', (SELECT count(*) FROM notes),
        'diary_entries', coalesce((SELECT jsonb_agg(jsonb_build_object(
          'id', id,
          'entry_date', entry_date,
          'title', title,
          'status', status,
          'taught_content', taught_content,
          'pedagogical_notes', pedagogical_notes
        ) ORDER BY entry_date DESC, updated_at DESC) FROM diary), '[]'::jsonb),
        'planned_items', coalesce((SELECT jsonb_agg(jsonb_build_object(
          'id', id,
          'plan_date', plan_date,
          'title', title,
          'resource_type', resource_type,
          'status', status
        ) ORDER BY plan_date ASC, created_at ASC) FROM plans), '[]'::jsonb),
        'published_items', coalesce((SELECT jsonb_agg(jsonb_build_object(
          'id', id,
          'entry_date', entry_date,
          'title', title,
          'entry_type', entry_type,
          'status', status
        ) ORDER BY entry_date ASC, created_at ASC) FROM published), '[]'::jsonb),
        'individual_notes', coalesce((SELECT jsonb_agg(jsonb_build_object(
          'id', id,
          'note_date', note_date,
          'student_id', student_id,
          'student_name', student_name,
          'note_text', note_text,
          'diary_entry_id', diary_entry_id
        ) ORDER BY note_date DESC, created_at DESC) FROM notes), '[]'::jsonb)
      )
    END;
$$;


ALTER FUNCTION "public"."teacher_get_class_diary_period_summary"("p_class_id" "uuid", "p_from" "date", "p_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_get_context"() RETURNS TABLE("teacher_id" "uuid", "profile_id" "uuid", "teacher_name" "text", "school_id" "uuid", "school_name" "text", "role" "text", "discipline" "text", "active_class_links" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
  SELECT
    t.id AS teacher_id,
    p.id AS profile_id,
    coalesce(p.display_name, 'Professor')::text AS teacher_name,
    t.school_id,
    s.nome::text AS school_name,
    p.platform_role::text AS role,
    t.disciplina::text AS discipline,
    count(ctm.id) FILTER (
      WHERE ctm.status = 'active'
        AND (ctm.ended_at IS NULL OR ctm.ended_at > now())
        AND coalesce(c.status, 'active') = 'active'
    )::integer AS active_class_links
  FROM public.teachers t
  JOIN public.profiles p ON p.id = t.profile_id
  JOIN public.schools s ON s.id = t.school_id
  LEFT JOIN public.class_teacher_memberships ctm ON ctm.teacher_id = t.id
  LEFT JOIN public.classes c ON c.id = ctm.class_id
  WHERE auth.uid() IS NOT NULL
    AND t.profile_id = auth.uid()
    AND coalesce(t.status, 'active') = 'active'
    AND coalesce(p.status, 'active') = 'active'
    AND lower(coalesce(p.platform_role, '')) = 'professor'
    AND coalesce(s.status, 'active') = 'active'
  GROUP BY t.id, p.id, p.display_name, t.school_id, s.nome, p.platform_role, t.disciplina
  LIMIT 1;
$$;


ALTER FUNCTION "public"."teacher_get_context"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_get_gamification_ranking"("p_scope" "text", "p_class_id" "uuid" DEFAULT NULL::"uuid", "p_school_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare v_school_id uuid;
begin
  if p_scope = 'class' then select school_id into v_school_id from public.classes where id = p_class_id; elsif p_scope = 'school' then v_school_id := p_school_id; else raise exception 'Escopo invalido'; end if;
  if v_school_id is null then raise exception 'Escola nao encontrada'; end if;
  if not public.secretaria_can_manage_school(v_school_id) and not exists(select 1 from public.class_teacher_memberships ctm join public.teachers t on t.id = ctm.teacher_id where ctm.class_id = p_class_id and t.profile_id = auth.uid() and ctm.status = 'active') then raise exception 'Acesso negado ao ranking'; end if;
  if coalesce((select rankings_enabled from public.gamification_settings where school_id = v_school_id), true) = false then return jsonb_build_object('status','DISABLED','rankings','[]'::jsonb); end if;
  return jsonb_build_object('status','PASS','rankings',coalesce((select jsonb_agg(row_to_json(r)) from (select row_number() over(order by gp.xp_total desc, gp.coin_balance desc) rank, gp.student_id, s.nome student_name, gp.class_id, gp.xp_total, gp.coin_balance, gp.level_number from public.student_gamification_profiles gp join public.students s on s.id = gp.student_id where gp.school_id = v_school_id and (p_scope = 'school' or gp.class_id = p_class_id) order by gp.xp_total desc, gp.coin_balance desc limit greatest(1, least(coalesce(p_limit,50),100))) r),'[]'::jsonb));
end; $$;


ALTER FUNCTION "public"."teacher_get_gamification_ranking"("p_scope" "text", "p_class_id" "uuid", "p_school_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_get_home_summary"() RETURNS TABLE("teacher_id" "uuid", "teacher_name" "text", "school_id" "uuid", "school_name" "text", "active_class_links" integer, "total_students" integer, "todays_calendar_count" integer, "unread_notifications" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
  WITH ctx AS (
    SELECT *
    FROM public.teacher_get_context()
    LIMIT 1
  ),
  classes AS (
    SELECT *
    FROM public.teacher_list_classes_for_mobile()
  ),
  class_ids AS (
    SELECT array_agg(class_id) AS ids
    FROM classes
  )
  SELECT
    ctx.teacher_id,
    ctx.teacher_name,
    ctx.school_id,
    ctx.school_name,
    ctx.active_class_links,
    coalesce(sum(classes.student_count), 0)::integer AS total_students,
    (
      SELECT count(*)::integer
      FROM public.class_calendar_entries cce
      CROSS JOIN class_ids
      WHERE cce.school_id = ctx.school_id
        AND cce.class_id = ANY (coalesce(class_ids.ids, ARRAY[]::uuid[]))
        AND cce.entry_date = current_date
        AND coalesce(cce.status, 'published') = 'published'
        AND public.calendar_teacher_can_read_school_event(cce.school_id, cce.class_id)
    ) AS todays_calendar_count,
    (
      SELECT count(*)::integer
      FROM public.notifications n
      WHERE n.user_id = ctx.profile_id
        AND coalesce(n.lida, false) = false
    ) AS unread_notifications
  FROM ctx
  LEFT JOIN classes ON true
  GROUP BY ctx.teacher_id, ctx.teacher_name, ctx.school_id, ctx.school_name, ctx.active_class_links, ctx.profile_id;
$$;


ALTER FUNCTION "public"."teacher_get_home_summary"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_get_notification_center"("p_read_filter" "text" DEFAULT 'all'::"text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS TABLE("notification_id" "uuid", "title" "text", "summary" "text", "delivered_at" timestamp without time zone, "notification_status" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_filter text := lower(coalesce(nullif(trim(p_read_filter), ''), 'all'));
  v_limit integer := greatest(1, least(coalesce(p_limit, 50), 100));
  v_offset integer := greatest(0, coalesce(p_offset, 0));
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Usuario autenticado obrigatorio.' USING errcode = '42501';
  END IF;

  IF v_filter NOT IN ('all', 'read', 'unread') THEN
    RAISE EXCEPTION 'Filtro de leitura invalido.' USING errcode = '22023';
  END IF;

  RETURN QUERY
  SELECT
    n.id AS notification_id,
    coalesce(n.titulo, 'Notificacao')::text AS title,
    coalesce(n.mensagem, '')::text AS summary,
    n.created_at AS delivered_at,
    CASE WHEN coalesce(n.lida, false) THEN 'read' ELSE 'unread' END AS notification_status
  FROM public.teacher_get_context() ctx
  JOIN public.notifications n ON n.user_id = ctx.profile_id
  WHERE v_filter = 'all'
    OR (v_filter = 'read' AND coalesce(n.lida, false) = true)
    OR (v_filter = 'unread' AND coalesce(n.lida, false) = false)
  ORDER BY n.created_at DESC NULLS LAST, n.id DESC
  LIMIT v_limit
  OFFSET v_offset;
END;
$$;


ALTER FUNCTION "public"."teacher_get_notification_center"("p_read_filter" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_get_writing_analytics"("p_class_id" "uuid", "p_date_from" "date" DEFAULT NULL::"date", "p_date_to" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_class public.classes%rowtype;
  v_summary jsonb;
begin
  if auth.uid() is null then
    raise exception 'AUTH_REQUIRED' using errcode = '42501';
  end if;
  select * into v_class from public.classes where id = p_class_id;
  if v_class.id is null then
    raise exception 'CLASS_NOT_FOUND';
  end if;
  if not (
    public.is_platform_admin()
    or public.secretaria_can_manage_school(v_class.school_id)
    or public.avalia_plus_teacher_can_manage_class(v_class.id, v_class.school_id)
  ) then
    raise exception 'WRITING_ANALYTICS_FORBIDDEN' using errcode = '42501';
  end if;

  select jsonb_build_object(
    'status', case when count(*) > 0 then 'PASS' else 'EMPTY_REAL' end,
    'class_id', p_class_id,
    'submission_count', count(*),
    'corrected_count', count(*) filter (where s.status in ('corrected', 'revision_requested')),
    'average_score', round(avg(s.final_score) filter (where s.final_score is not null), 2),
    'by_genre', coalesce(jsonb_agg(distinct jsonb_build_object('genre', p.textual_genre, 'component', p.component)) filter (where p.id is not null), '[]'::jsonb)
  )
  into v_summary
  from public.writing_submissions s
  join public.writing_prompts p on p.id = s.prompt_id
  where s.class_id = p_class_id
    and (p_date_from is null or s.created_at::date >= p_date_from)
    and (p_date_to is null or s.created_at::date <= p_date_to);

  return coalesce(v_summary, jsonb_build_object('status', 'EMPTY_REAL', 'class_id', p_class_id));
end;
$$;


ALTER FUNCTION "public"."teacher_get_writing_analytics"("p_class_id" "uuid", "p_date_from" "date", "p_date_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_list_class_diary_entries"("p_class_id" "uuid" DEFAULT NULL::"uuid", "p_from" "date" DEFAULT NULL::"date", "p_to" "date" DEFAULT NULL::"date") RETURNS TABLE("id" "uuid", "school_id" "uuid", "class_id" "uuid", "teacher_id" "uuid", "entry_date" "date", "title" "text", "taught_content" "text", "pedagogical_notes" "text", "plan_id" "uuid", "plan_title" "text", "calendar_entry_id" "uuid", "calendar_title" "text", "status" "text", "closed_at" timestamp with time zone, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "activity_link_count" bigint, "attendance_total" bigint, "attendance_present" bigint, "attendance_absent" bigint, "attendance_justified" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    cde.id,
    cde.school_id,
    cde.class_id,
    cde.teacher_id,
    cde.entry_date,
    cde.title,
    cde.taught_content,
    cde.pedagogical_notes,
    cde.plan_id,
    tp.title AS plan_title,
    cde.calendar_entry_id,
    cce.title AS calendar_title,
    cde.status,
    cde.closed_at,
    cde.created_at,
    cde.updated_at,
    COALESCE(links.count, 0) AS activity_link_count,
    COALESCE(attendance.total, 0) AS attendance_total,
    COALESCE(attendance.present, 0) AS attendance_present,
    COALESCE(attendance.absent, 0) AS attendance_absent,
    COALESCE(attendance.justified, 0) AS attendance_justified
  FROM public.class_diary_entries cde
  LEFT JOIN public.teacher_plans tp ON tp.id = cde.plan_id
  LEFT JOIN public.class_calendar_entries cce ON cce.id = cde.calendar_entry_id
  LEFT JOIN LATERAL (
    SELECT count(*)::bigint
    FROM public.class_diary_activity_links l
    WHERE l.diary_entry_id = cde.id
  ) links(count) ON true
  LEFT JOIN LATERAL (
    SELECT
      count(*)::bigint AS total,
      count(*) FILTER (WHERE ar.status = 'present')::bigint AS present,
      count(*) FILTER (WHERE ar.status = 'absent')::bigint AS absent,
      count(*) FILTER (WHERE ar.status = 'justified')::bigint AS justified
    FROM public.attendance_records ar
    WHERE ar.school_id = cde.school_id
      AND ar.class_id = cde.class_id
      AND ar.attendance_date = cde.entry_date
  ) attendance ON true
  WHERE cde.status <> 'deleted'
    AND (p_class_id IS NULL OR cde.class_id = p_class_id)
    AND (p_from IS NULL OR cde.entry_date >= p_from)
    AND (p_to IS NULL OR cde.entry_date <= p_to)
    AND public.class_diary_teacher_can_manage(cde.school_id, cde.class_id, cde.teacher_id)
  ORDER BY cde.entry_date DESC, cde.updated_at DESC;
$$;


ALTER FUNCTION "public"."teacher_list_class_diary_entries"("p_class_id" "uuid", "p_from" "date", "p_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_list_class_diary_student_notes"("p_class_id" "uuid" DEFAULT NULL::"uuid", "p_student_id" "uuid" DEFAULT NULL::"uuid", "p_from" "date" DEFAULT NULL::"date", "p_to" "date" DEFAULT NULL::"date") RETURNS TABLE("id" "uuid", "school_id" "uuid", "class_id" "uuid", "teacher_id" "uuid", "student_id" "uuid", "student_name" "text", "diary_entry_id" "uuid", "diary_entry_title" "text", "note_date" "date", "note_text" "text", "status" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    cdn.id,
    cdn.school_id,
    cdn.class_id,
    cdn.teacher_id,
    cdn.student_id,
    coalesce(st.nome, 'Aluno')::text AS student_name,
    cdn.diary_entry_id,
    cde.title AS diary_entry_title,
    cdn.note_date,
    cdn.note_text,
    cdn.status,
    cdn.created_at,
    cdn.updated_at
  FROM public.class_diary_student_notes cdn
  JOIN public.students st ON st.id = cdn.student_id
  LEFT JOIN public.class_diary_entries cde ON cde.id = cdn.diary_entry_id
  WHERE cdn.status <> 'deleted'
    AND (p_class_id IS NULL OR cdn.class_id = p_class_id)
    AND (p_student_id IS NULL OR cdn.student_id = p_student_id)
    AND (p_from IS NULL OR cdn.note_date >= p_from)
    AND (p_to IS NULL OR cdn.note_date <= p_to)
    AND public.class_diary_student_note_can_manage(cdn.school_id, cdn.class_id, cdn.teacher_id, cdn.student_id)
  ORDER BY cdn.note_date DESC, cdn.created_at DESC;
$$;


ALTER FUNCTION "public"."teacher_list_class_diary_student_notes"("p_class_id" "uuid", "p_student_id" "uuid", "p_from" "date", "p_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_list_classes_for_mobile"() RETURNS TABLE("class_id" "uuid", "school_id" "uuid", "class_name" "text", "school_year" "text", "age_group" "text", "shift" "text", "teacher_role" "text", "membership_status" "text", "student_count" integer, "started_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
  WITH ctx AS (
    SELECT *
    FROM public.teacher_get_context()
    LIMIT 1
  )
  SELECT
    c.id AS class_id,
    c.school_id,
    c.nome::text AS class_name,
    coalesce(c.school_year, c.ano_escolar::text) AS school_year,
    c.age_group,
    c.turno::text AS shift,
    ctm.role::text AS teacher_role,
    ctm.status::text AS membership_status,
    count(e.student_id) FILTER (
      WHERE e.status = 'active'
        AND e.enrolled_at <= now()
        AND (e.ended_at IS NULL OR e.ended_at > now())
    )::integer AS student_count,
    ctm.started_at
  FROM ctx
  JOIN public.class_teacher_memberships ctm ON ctm.teacher_id = ctx.teacher_id
  JOIN public.classes c ON c.id = ctm.class_id AND c.school_id = ctx.school_id
  LEFT JOIN public.enrollments e ON e.class_id = c.id AND e.school_id = c.school_id
  WHERE ctm.status = 'active'
    AND (ctm.ended_at IS NULL OR ctm.ended_at > now())
    AND coalesce(c.status, 'active') = 'active'
  GROUP BY c.id, c.school_id, c.nome, c.school_year, c.ano_escolar, c.age_group, c.turno, ctm.role, ctm.status, ctm.started_at
  ORDER BY c.nome ASC;
$$;


ALTER FUNCTION "public"."teacher_list_classes_for_mobile"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_list_pedagogical_recommendations"("p_class_id" "uuid") RETURNS TABLE("id" "uuid", "school_id" "uuid", "teacher_id" "uuid", "content_type" "text", "content_id" "text", "content_title" "text", "target_type" "text", "class_id" "uuid", "class_name" "text", "student_id" "uuid", "student_name" "text", "note" "text", "status" "text", "published_at" timestamp with time zone, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_school_id uuid;
  v_teacher public.teachers;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Usuario autenticado obrigatorio para listar recomendacoes.';
  END IF;

  SELECT c.school_id INTO v_school_id
  FROM public.classes c
  WHERE c.id = p_class_id
    AND c.status = 'active';

  IF v_school_id IS NULL THEN
    RAISE EXCEPTION 'Turma nao encontrada.';
  END IF;

  SELECT * INTO v_teacher
  FROM public.pedagogical_recommendation_current_teacher(v_school_id);

  IF v_teacher.id IS NULL
    OR NOT public.pedagogical_recommendation_teacher_can_target(
      v_teacher.id,
      v_school_id,
      p_class_id,
      NULL,
      'class'
    ) THEN
    RAISE EXCEPTION 'Professor sem permissao para listar recomendacoes desta turma.';
  END IF;

  RETURN QUERY
  SELECT
    pr.id,
    pr.school_id,
    pr.teacher_id,
    pr.content_type,
    pr.content_id,
    pr.content_title,
    pr.target_type,
    pr.class_id,
    c.nome::text AS class_name,
    pr.student_id,
    s.nome::text AS student_name,
    pr.note,
    pr.status,
    pr.published_at,
    pr.created_at,
    pr.updated_at
  FROM public.pedagogical_recommendations pr
  JOIN public.classes c ON c.id = pr.class_id
  LEFT JOIN public.students s ON s.id = pr.student_id
  WHERE pr.class_id = p_class_id
    AND pr.teacher_id = v_teacher.id
    AND pr.status <> 'deleted'
  ORDER BY pr.created_at DESC, pr.content_title ASC;
END;
$$;


ALTER FUNCTION "public"."teacher_list_pedagogical_recommendations"("p_class_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_list_recomposition_context"("p_class_id" "uuid", "p_date_from" "date" DEFAULT NULL::"date", "p_date_to" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_class public.classes%rowtype;
  v_gap_map jsonb;
  v_groups jsonb;
  v_plans jsonb;
  v_recommendations jsonb;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  select * into v_class from public.classes where id = p_class_id;
  if not found then raise exception 'CLASS_NOT_FOUND'; end if;
  if not public.avalia_plus_teacher_can_manage_class(v_class.id, v_class.school_id) then raise exception 'RECOMPOSITION_CLASS_FORBIDDEN'; end if;

  v_gap_map := public.recomposition_get_learning_gap_map(p_class_id, p_date_from, p_date_to);
  v_recommendations := public.recomposition_content_recommendations(p_class_id, null, 12);

  select coalesce(jsonb_agg(jsonb_build_object('id', g.id, 'title', g.title, 'target_skill', g.target_skill, 'descriptor', g.descriptor, 'status', g.status, 'student_count', (select count(*) from public.recomposition_intervention_group_students gs where gs.group_id = g.id and gs.status = 'active'), 'created_at', g.created_at) order by g.created_at desc), '[]'::jsonb)
  into v_groups from public.recomposition_intervention_groups g where g.class_id = v_class.id and g.school_id = v_class.school_id and g.status <> 'archived';

  select coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'title', p.title, 'target_type', p.target_type, 'target_skill', p.target_skill, 'descriptor', p.descriptor, 'objective', p.objective, 'status', p.status, 'student_count', (select count(*) from public.recomposition_plan_students ps where ps.plan_id = p.id and ps.status <> 'removed'), 'resource_count', (select count(*) from public.recomposition_plan_resources pr where pr.plan_id = p.id and pr.status <> 'removed'), 'last_event_at', (select max(te.created_at) from public.recomposition_tracking_events te where te.plan_id = p.id), 'created_at', p.created_at) order by p.created_at desc), '[]'::jsonb)
  into v_plans from public.recomposition_plans p where p.class_id = v_class.id and p.school_id = v_class.school_id and p.status <> 'archived';

  return jsonb_build_object('gap_map', v_gap_map, 'groups', v_groups, 'plans', v_plans, 'recommendations', v_recommendations);
end;
$$;


ALTER FUNCTION "public"."teacher_list_recomposition_context"("p_class_id" "uuid", "p_date_from" "date", "p_date_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_prepare_writing_ai_correction"("p_submission_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_submission public.writing_submissions%rowtype;
  v_prompt public.writing_prompts%rowtype;
  v_version public.writing_submission_versions%rowtype;
  v_ai jsonb;
  v_provider jsonb;
  v_correction public.writing_corrections%rowtype;
begin
  if auth.uid() is null then
    raise exception 'AUTH_REQUIRED' using errcode = '42501';
  end if;

  select * into v_submission from public.writing_submissions where id = p_submission_id for update;
  if v_submission.id is null then
    raise exception 'WRITING_SUBMISSION_NOT_FOUND';
  end if;
  if not public.avalia_plus_teacher_can_manage_class(v_submission.class_id, v_submission.school_id) then
    raise exception 'WRITING_CORRECTION_FORBIDDEN' using errcode = '42501';
  end if;
  select * into v_prompt from public.writing_prompts where id = v_submission.prompt_id;
  select * into v_version
  from public.writing_submission_versions
  where submission_id = v_submission.id
  order by version_number desc
  limit 1;

  v_provider := public.ai_provider_status();
  v_ai := public.ai_pedagogy_prepare_request(
    'teacher',
    'Preparar correcao de producao textual sem substituir o texto do aluno. Genero: ' || v_prompt.textual_genre || '. Criterios: ' || v_prompt.rubric::text,
    v_submission.student_id,
    v_submission.class_id,
    v_prompt.component,
    array_to_string(v_prompt.bncc_codes, ',')
  );

  insert into public.writing_corrections (
    submission_id, version_id, mode, provider_status, ai_interaction_id,
    status, created_by, strengths, improvements
  )
  values (
    v_submission.id,
    v_version.id,
    case when 'HIBRIDA_IA_DOCENTE' = any(v_prompt.correction_modes) then 'HIBRIDA_IA_DOCENTE' else 'IA' end,
    coalesce(v_provider->>'status', 'EMPTY_REAL'),
    nullif(v_ai->>'interaction_id', '')::uuid,
    case when coalesce(v_provider->>'status', 'EMPTY_REAL') = 'PASS' then 'ai_prepared' else 'teacher_review' end,
    auth.uid(),
    '[]'::jsonb,
    '[]'::jsonb
  )
  returning * into v_correction;

  update public.writing_submissions
     set status = 'in_correction',
         correction_mode = v_correction.mode,
         updated_at = now()
   where id = v_submission.id;

  perform public.writing_log_event(v_prompt.id, v_submission.id, v_correction.id, 'AI_CORRECTION_PREPARED', jsonb_build_object('provider', v_provider, 'ai', v_ai));
  return jsonb_build_object(
    'correction', to_jsonb(v_correction),
    'ai_correction_provider', coalesce(v_provider->>'status', 'EMPTY_REAL'),
    'ai_request', v_ai
  );
end;
$$;


ALTER FUNCTION "public"."teacher_prepare_writing_ai_correction"("p_submission_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_preview_offline_assessment_import"("p_assignment_id" "uuid", "p_source_format" "text", "p_file_name" "text", "p_rows" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_assignment public.assessment_assignments%rowtype;
  v_batch public.assessment_offline_import_batches%rowtype;
  v_row jsonb;
  v_idx integer := 0;
  v_student_id uuid;
  v_question_id uuid;
  v_assessment_question_id uuid;
  v_alternative_id uuid;
  v_answer text;
  v_status text;
  v_error text;
  v_valid integer;
  v_invalid integer;
begin
  if auth.uid() is null then
    raise exception 'AUTH_REQUIRED' using errcode = '42501';
  end if;
  v_assignment := public.avalia_plus_assert_teacher_assignment(p_assignment_id);
  if upper(coalesce(p_source_format, '')) not in ('CSV', 'XLSX') then
    raise exception 'INVALID_IMPORT_FORMAT';
  end if;
  if jsonb_typeof(coalesce(p_rows, '[]'::jsonb)) <> 'array' then
    raise exception 'IMPORT_ROWS_MUST_BE_ARRAY';
  end if;

  insert into public.assessment_offline_import_batches (
    assessment_id, assignment_id, school_id, class_id, booklet_id,
    source_format, file_name, status, created_by, validated_at, metadata
  )
  values (
    v_assignment.assessment_id, v_assignment.id, v_assignment.school_id, v_assignment.class_id, v_assignment.booklet_id,
    upper(p_source_format), p_file_name, 'preview', auth.uid(), now(), jsonb_build_object('engine', 'AVALIA_PLUS_2_FASE_3')
  )
  returning * into v_batch;

  for v_row in select * from jsonb_array_elements(coalesce(p_rows, '[]'::jsonb))
  loop
    v_idx := v_idx + 1;
    v_student_id := null;
    v_question_id := null;
    v_assessment_question_id := null;
    v_alternative_id := null;
    v_answer := upper(nullif(btrim(coalesce(v_row->>'answer', v_row->>'resposta', '')), ''));
    v_status := 'valid';
    v_error := null;

    select s.id into v_student_id
    from public.students s
    join public.enrollments e on e.student_id = s.id
    where e.class_id = v_assignment.class_id
      and e.school_id = v_assignment.school_id
      and e.status = 'active'
      and coalesce(s.status, 'active') in ('active', 'ativo')
      and (v_assignment.target_type = 'class' or s.id = v_assignment.student_id)
      and (
        s.id::text = nullif(v_row->>'student_id', '')
        or lower(coalesce(s.email, '')) = lower(nullif(coalesce(v_row->>'student_email', v_row->>'email'), ''))
        or lower(s.nome) = lower(nullif(coalesce(v_row->>'student_name', v_row->>'aluno'), ''))
      )
    limit 1;

    if v_student_id is null then
      v_status := 'invalid';
      v_error := 'STUDENT_NOT_ELIGIBLE';
    end if;

    if nullif(v_row->>'question_id', '') is not null then
      v_question_id := nullif(v_row->>'question_id', '')::uuid;
    elsif nullif(coalesce(v_row->>'question_position', v_row->>'questao'), '') is not null then
      select aq.question_id, aq.id into v_question_id, v_assessment_question_id
      from public.assessment_questions aq
      where aq.assessment_id = v_assignment.assessment_id
        and aq.position = nullif(coalesce(v_row->>'question_position', v_row->>'questao'), '')::integer
      limit 1;
    end if;

    if v_question_id is null then
      v_status := 'invalid';
      v_error := coalesce(v_error, 'QUESTION_NOT_FOUND');
    else
      select aq.id into v_assessment_question_id
      from public.assessment_questions aq
      where aq.assessment_id = v_assignment.assessment_id
        and aq.question_id = v_question_id
      limit 1;
      if v_assessment_question_id is null then
        v_status := 'invalid';
        v_error := coalesce(v_error, 'QUESTION_NOT_IN_ASSESSMENT');
      end if;
    end if;

    if v_question_id is not null and v_answer is not null then
      select qa.id into v_alternative_id
      from public.question_alternatives qa
      where qa.question_id = v_question_id
        and chr(64 + qa.position) = v_answer
      limit 1;
      if v_alternative_id is null and nullif(v_row->>'alternative_id', '') is not null then
        select qa.id into v_alternative_id
        from public.question_alternatives qa
        where qa.id = nullif(v_row->>'alternative_id', '')::uuid
          and qa.question_id = v_question_id
        limit 1;
      end if;
      if v_alternative_id is null and nullif(coalesce(v_row->>'response_text', v_row->>'resposta_texto'), '') is null then
        v_status := 'invalid';
        v_error := coalesce(v_error, 'ANSWER_NOT_FOUND');
      end if;
    end if;

    if v_status = 'valid' and exists (
      select 1 from public.assessment_offline_import_rows r
      where r.batch_id = v_batch.id and r.student_id = v_student_id and r.question_id = v_question_id
    ) then
      v_status := 'duplicate';
      v_error := 'DUPLICATE_ROW';
    end if;

    if v_status = 'valid' and exists (
      select 1 from public.assessment_results ar
      where ar.assignment_id = v_assignment.id and ar.student_id = v_student_id
    ) then
      v_status := 'invalid';
      v_error := 'RESULT_ALREADY_CONSOLIDATED';
    end if;

    insert into public.assessment_offline_import_rows (
      batch_id, row_number, student_id, student_external_ref, question_id, assessment_question_id,
      alternative_id, answer_label, response_text, status, error_code, error_message, raw_payload
    )
    values (
      v_batch.id,
      v_idx,
      v_student_id,
      coalesce(v_row->>'student_id', v_row->>'student_email', v_row->>'student_name', v_row->>'aluno'),
      v_question_id,
      v_assessment_question_id,
      v_alternative_id,
      v_answer,
      nullif(coalesce(v_row->>'response_text', v_row->>'resposta_texto'), ''),
      v_status,
      v_error,
      v_error,
      v_row
    );
  end loop;

  select count(*) filter (where status = 'valid'), count(*) filter (where status <> 'valid')
    into v_valid, v_invalid
  from public.assessment_offline_import_rows
  where batch_id = v_batch.id;

  update public.assessment_offline_import_batches
     set status = case when v_invalid = 0 then 'validated' else 'preview' end,
         summary = jsonb_build_object('total_rows', v_idx, 'valid_rows', v_valid, 'invalid_rows', v_invalid)
   where id = v_batch.id
   returning * into v_batch;

  return jsonb_build_object(
    'batch', to_jsonb(v_batch),
    'rows', coalesce((select jsonb_agg(to_jsonb(r) order by r.row_number) from public.assessment_offline_import_rows r where r.batch_id = v_batch.id), '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."teacher_preview_offline_assessment_import"("p_assignment_id" "uuid", "p_source_format" "text", "p_file_name" "text", "p_rows" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_record_scan_detection"("p_scan_file_id" "uuid", "p_detection" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_file public.assessment_scan_files%rowtype;
  v_batch public.assessment_scan_batches%rowtype;
  v_assignment public.assessment_assignments%rowtype;
  v_item jsonb;
  v_question_id uuid;
  v_assessment_question_id uuid;
  v_alternative_id uuid;
  v_label text;
  v_confidence numeric;
  v_created integer := 0;
begin
  if auth.uid() is null then
    raise exception 'AUTH_REQUIRED' using errcode = '42501';
  end if;
  select * into v_file from public.assessment_scan_files where id = p_scan_file_id for update;
  if v_file.id is null then
    raise exception 'SCAN_FILE_NOT_FOUND';
  end if;
  select * into v_batch from public.assessment_scan_batches where id = v_file.batch_id;
  v_assignment := public.avalia_plus_assert_teacher_assignment(v_batch.assignment_id);

  if jsonb_typeof(coalesce(p_detection->'responses', '[]'::jsonb)) <> 'array' then
    raise exception 'SCAN_RESPONSES_MUST_BE_ARRAY';
  end if;

  for v_item in select * from jsonb_array_elements(coalesce(p_detection->'responses', '[]'::jsonb))
  loop
    v_question_id := null;
    v_assessment_question_id := null;
    v_alternative_id := null;
    v_label := upper(nullif(btrim(coalesce(v_item->>'answer', v_item->>'detected_label', '')), ''));
    v_confidence := nullif(v_item->>'confidence', '')::numeric;

    if nullif(v_item->>'question_id', '') is not null then
      v_question_id := nullif(v_item->>'question_id', '')::uuid;
    elsif nullif(coalesce(v_item->>'question_position', v_item->>'questao'), '') is not null then
      select aq.question_id, aq.id into v_question_id, v_assessment_question_id
      from public.assessment_questions aq
      where aq.assessment_id = v_assignment.assessment_id
        and aq.position = nullif(coalesce(v_item->>'question_position', v_item->>'questao'), '')::integer
      limit 1;
    end if;

    if v_question_id is not null and v_assessment_question_id is null then
      select aq.id into v_assessment_question_id
      from public.assessment_questions aq
      where aq.assessment_id = v_assignment.assessment_id
        and aq.question_id = v_question_id
      limit 1;
    end if;

    if v_question_id is not null and v_label is not null then
      select qa.id into v_alternative_id
      from public.question_alternatives qa
      where qa.question_id = v_question_id
        and chr(64 + qa.position) = v_label
      limit 1;
    end if;

    insert into public.assessment_scan_responses (
      scan_file_id, assessment_question_id, question_id, detected_alternative_id,
      detected_label, confidence, detection_status, source_payload
    )
    values (
      p_scan_file_id,
      v_assessment_question_id,
      v_question_id,
      v_alternative_id,
      v_label,
      v_confidence,
      case when v_question_id is not null and v_alternative_id is not null and coalesce(v_confidence, 0) >= 0.95 then 'DETECTED' else 'REVIEW_REQUIRED' end,
      v_item
    )
    on conflict (scan_file_id, question_id) do update
      set assessment_question_id = excluded.assessment_question_id,
          detected_alternative_id = excluded.detected_alternative_id,
          detected_label = excluded.detected_label,
          confidence = excluded.confidence,
          detection_status = excluded.detection_status,
          source_payload = excluded.source_payload,
          updated_at = now();
    v_created := v_created + 1;
  end loop;

  update public.assessment_scan_files
     set processing_status = 'REVIEW_REQUIRED',
         detected_payload = detected_payload || jsonb_build_object('responses_detected', v_created, 'ocr_provider_status', v_batch.ocr_provider_status),
         updated_at = now()
   where id = p_scan_file_id
   returning * into v_file;

  perform public.avalia_plus_scan_log_event(v_batch.id, v_file.id, 'DETECTION_RECORDED', jsonb_build_object('responses', v_created, 'provider_status', v_batch.ocr_provider_status));
  return jsonb_build_object('file', to_jsonb(v_file), 'responses_recorded', v_created, 'review_required', true);
end;
$$;


ALTER FUNCTION "public"."teacher_record_scan_detection"("p_scan_file_id" "uuid", "p_detection" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_register_assessment_scan_file"("p_batch_id" "uuid", "p_file" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_batch public.assessment_scan_batches%rowtype;
  v_assignment public.assessment_assignments%rowtype;
  v_file public.assessment_scan_files%rowtype;
  v_student_id uuid;
  v_confidence numeric := nullif(p_file->>'identification_confidence', '')::numeric;
  v_mime text := coalesce(nullif(p_file->>'mime_type', ''), 'application/pdf');
begin
  if auth.uid() is null then
    raise exception 'AUTH_REQUIRED' using errcode = '42501';
  end if;
  select * into v_batch from public.assessment_scan_batches where id = p_batch_id;
  if v_batch.id is null then
    raise exception 'SCAN_BATCH_NOT_FOUND';
  end if;
  v_assignment := public.avalia_plus_assert_teacher_assignment(v_batch.assignment_id);
  if v_mime not in ('application/pdf', 'image/jpeg', 'image/png') then
    raise exception 'INVALID_SCAN_MIME_TYPE';
  end if;

  if nullif(p_file->>'student_id', '') is not null then
    select s.id into v_student_id
    from public.students s
    join public.enrollments e on e.student_id = s.id
    where s.id = nullif(p_file->>'student_id', '')::uuid
      and e.class_id = v_assignment.class_id
      and e.school_id = v_assignment.school_id
      and e.status = 'active'
      and (v_assignment.target_type = 'class' or s.id = v_assignment.student_id)
    limit 1;
  end if;

  insert into public.assessment_scan_files (
    batch_id, file_name, mime_type, storage_bucket, storage_path, sha256, file_size,
    student_id, identification_status, identification_confidence, processing_status,
    detected_payload, created_by
  )
  values (
    p_batch_id,
    coalesce(nullif(p_file->>'file_name', ''), 'scan'),
    v_mime,
    nullif(p_file->>'storage_bucket', ''),
    nullif(p_file->>'storage_path', ''),
    nullif(p_file->>'sha256', ''),
    nullif(p_file->>'file_size', '')::integer,
    v_student_id,
    case when v_student_id is not null and coalesce(v_confidence, 0) >= 0.95 then 'IDENTIFIED' else 'REVIEW_REQUIRED' end,
    v_confidence,
    'REVIEW_REQUIRED',
    jsonb_build_object(
      'ocr_provider_status', v_batch.ocr_provider_status,
      'student_payload', p_file - 'storage_path',
      'requires_human_review', true
    ),
    auth.uid()
  )
  returning * into v_file;

  update public.assessment_scan_batches
     set pipeline_status = 'REVIEW',
         updated_at = now(),
         summary = summary || jsonb_build_object('last_file_id', v_file.id)
   where id = p_batch_id;

  perform public.avalia_plus_scan_log_event(p_batch_id, v_file.id, 'FILE_REGISTERED', to_jsonb(v_file));
  return jsonb_build_object('file', to_jsonb(v_file), 'review_required', true);
end;
$$;


ALTER FUNCTION "public"."teacher_register_assessment_scan_file"("p_batch_id" "uuid", "p_file" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_review_scan_response"("p_scan_response_id" "uuid", "p_final_answer" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_response public.assessment_scan_responses%rowtype;
  v_file public.assessment_scan_files%rowtype;
  v_batch public.assessment_scan_batches%rowtype;
  v_assignment public.assessment_assignments%rowtype;
  v_alt uuid;
  v_label text := upper(nullif(btrim(coalesce(p_final_answer->>'answer', p_final_answer->>'final_label', '')), ''));
begin
  if auth.uid() is null then
    raise exception 'AUTH_REQUIRED' using errcode = '42501';
  end if;
  select * into v_response from public.assessment_scan_responses where id = p_scan_response_id for update;
  if v_response.id is null then
    raise exception 'SCAN_RESPONSE_NOT_FOUND';
  end if;
  select * into v_file from public.assessment_scan_files where id = v_response.scan_file_id;
  select * into v_batch from public.assessment_scan_batches where id = v_file.batch_id;
  v_assignment := public.avalia_plus_assert_teacher_assignment(v_batch.assignment_id);

  if nullif(p_final_answer->>'alternative_id', '') is not null then
    v_alt := nullif(p_final_answer->>'alternative_id', '')::uuid;
  elsif v_label is not null then
    select qa.id into v_alt
    from public.question_alternatives qa
    where qa.question_id = v_response.question_id
      and chr(64 + qa.position) = v_label
    limit 1;
  end if;

  update public.assessment_scan_responses
     set final_alternative_id = v_alt,
         final_label = v_label,
         detection_status = case
           when v_alt is not null and (v_alt is distinct from detected_alternative_id or v_label is distinct from detected_label) then 'ADJUSTED'
           when v_alt is not null then 'CONFIRMED'
           else 'REJECTED'
         end,
         reviewed_by = auth.uid(),
         reviewed_at = now(),
         updated_at = now(),
         source_payload = source_payload || jsonb_build_object('manual_review', p_final_answer)
   where id = p_scan_response_id
   returning * into v_response;

  update public.assessment_scan_files
     set processing_status = 'REVIEWED',
         reviewed_by = auth.uid(),
         reviewed_at = now(),
         updated_at = now()
   where id = v_file.id
   returning * into v_file;

  perform public.avalia_plus_scan_log_event(v_batch.id, v_file.id, 'RESPONSE_REVIEWED', to_jsonb(v_response));
  return jsonb_build_object('response', to_jsonb(v_response), 'file', to_jsonb(v_file));
end;
$$;


ALTER FUNCTION "public"."teacher_review_scan_response"("p_scan_response_id" "uuid", "p_final_answer" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_schedule_assessment_application_v2"("p_assessment_id" "uuid", "p_target_type" "text", "p_class_id" "uuid", "p_student_id" "uuid" DEFAULT NULL::"uuid", "p_available_from" timestamp with time zone DEFAULT "now"(), "p_available_until" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_time_limit_minutes" integer DEFAULT NULL::integer, "p_max_attempts" integer DEFAULT 1, "p_cycle_name" "text" DEFAULT NULL::"text", "p_school_year" "text" DEFAULT NULL::"text", "p_booklet_id" "uuid" DEFAULT NULL::"uuid", "p_token_required" boolean DEFAULT false, "p_shuffle_questions" boolean DEFAULT false, "p_shuffle_alternatives" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_assignment public.assessment_assignments%rowtype;
  v_cycle public.assessment_cycles%rowtype;
  v_school_id uuid;
  v_assessment public.assessments%rowtype;
  v_token text;
  v_token_id uuid;
begin
  if auth.uid() is null then raise exception 'Usuario autenticado obrigatorio.' using errcode = '42501'; end if;
  select * into v_assessment from public.assessments where id = p_assessment_id;
  select c.school_id into v_school_id from public.classes c where c.id = p_class_id and coalesce(c.status, 'active') in ('active', 'ativo');
  if v_assessment.id is null or v_school_id is null or not public.avalia_plus_teacher_can_manage_class(p_class_id, v_school_id) then
    raise exception 'Professor/Gestao nao autorizados para esta aplicacao.' using errcode = '42501';
  end if;
  if p_booklet_id is not null and not exists (select 1 from public.assessment_booklets ab where ab.id = p_booklet_id and ab.assessment_id = p_assessment_id and ab.position between 1 and 5) then
    raise exception 'Caderno invalido para esta avaliacao.' using errcode = '22023';
  end if;
  if nullif(btrim(coalesce(p_cycle_name, '')), '') is not null then
    insert into public.assessment_cycles (school_id, school_year, name, component, grade_year, starts_at, ends_at, status, created_by)
    values (v_school_id, coalesce(nullif(p_school_year, ''), v_assessment.school_year, v_assessment.assessment_year, extract(year from now())::text), p_cycle_name, v_assessment.component, v_assessment.school_year, p_available_from, p_available_until, case when coalesce(p_available_from, now()) <= now() then 'EM_ANDAMENTO' else 'AGENDADA' end, auth.uid())
    returning * into v_cycle;
  end if;
  v_assignment := public.teacher_create_assessment_assignment(p_assessment_id, p_target_type, p_class_id, p_student_id, p_available_from, p_available_until, p_time_limit_minutes, p_max_attempts, 'published');
  update public.assessment_assignments
     set cycle_id = v_cycle.id,
         booklet_id = p_booklet_id,
         application_status = case when coalesce(p_available_from, now()) <= now() then 'EM_ANDAMENTO' else 'AGENDADA' end,
         token_required = coalesce(p_token_required, false),
         shuffle_questions = coalesce(p_shuffle_questions, false),
         shuffle_alternatives = coalesce(p_shuffle_alternatives, false),
         application_settings = jsonb_build_object('phase', 'AVALIA_PLUS_2_FASE_2'),
         updated_at = now()
   where id = v_assignment.id returning * into v_assignment;
  insert into public.assessment_cycle_participants (cycle_id, school_id, class_id, student_id, status)
  select v_cycle.id, v_school_id, p_class_id, p_student_id, 'eligible' where v_cycle.id is not null on conflict do nothing;
  if coalesce(p_token_required, false) then
    v_token := public.avalia_plus_generate_token();
    insert into public.assessment_application_tokens (assignment_id, token_hash, token_hint, student_id, valid_from, valid_until, created_by)
    values (v_assignment.id, public.avalia_plus_token_hash(v_token), right(v_token, 4), p_student_id, coalesce(p_available_from, now()), p_available_until, auth.uid()) returning id into v_token_id;
  end if;
  return jsonb_build_object('assignment', to_jsonb(v_assignment), 'cycle', case when v_cycle.id is null then null else to_jsonb(v_cycle) end, 'token', case when v_token is null then null else jsonb_build_object('id', v_token_id, 'value', v_token, 'hint', right(v_token, 4)) end);
end;
$$;


ALTER FUNCTION "public"."teacher_schedule_assessment_application_v2"("p_assessment_id" "uuid", "p_target_type" "text", "p_class_id" "uuid", "p_student_id" "uuid", "p_available_from" timestamp with time zone, "p_available_until" timestamp with time zone, "p_time_limit_minutes" integer, "p_max_attempts" integer, "p_cycle_name" "text", "p_school_year" "text", "p_booklet_id" "uuid", "p_token_required" boolean, "p_shuffle_questions" boolean, "p_shuffle_alternatives" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_set_attendance_records"("p_class_id" "uuid", "p_attendance_date" "date", "p_records" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_class public.classes%rowtype;
  v_item jsonb;
  v_student_id uuid;
  v_status text;
  v_notes text;
  v_enrollment public.enrollments%rowtype;
  v_record public.attendance_records%rowtype;
  v_previous_status text;
  v_saved integer := 0;
begin
  if p_attendance_date is null then
    raise exception 'Data da chamada e obrigatoria.' using errcode = '22023';
  end if;

  if p_attendance_date > current_date then
    raise exception 'Nao e permitido registrar frequencia futura.' using errcode = '22023';
  end if;

  if jsonb_typeof(p_records) <> 'array' then
    raise exception 'Registros de frequencia devem ser enviados como array.' using errcode = '22023';
  end if;

  select * into v_class
  from public.classes
  where id = p_class_id
    and status = 'active'
  limit 1;

  if v_class.id is null then
    raise exception 'Turma ativa nao encontrada.' using errcode = '22023';
  end if;

  if not exists (
    select 1
    from public.class_teacher_memberships ctm
    join public.teachers t on t.id = ctm.teacher_id
    where ctm.class_id = v_class.id
      and ctm.status = 'active'
      and ctm.started_at <= now()
      and (ctm.ended_at is null or ctm.ended_at > now())
      and t.profile_id = auth.uid()
  ) then
    raise exception 'Professor sem vinculo ativo com esta turma.' using errcode = '42501';
  end if;

  for v_item in select * from jsonb_array_elements(p_records)
  loop
    v_student_id := nullif(v_item ->> 'student_id', '')::uuid;
    v_status := lower(nullif(trim(v_item ->> 'status'), ''));
    v_notes := nullif(trim(coalesce(v_item ->> 'notes', '')), '');

    if v_student_id is null then
      raise exception 'student_id ausente em registro de frequencia.' using errcode = '22023';
    end if;

    if v_status not in ('present', 'absent', 'justified') then
      raise exception 'Status de frequencia invalido para aluno %.', v_student_id using errcode = '22023';
    end if;

    select * into v_enrollment
    from public.enrollments e
    where e.student_id = v_student_id
      and e.class_id = v_class.id
      and e.school_id = v_class.school_id
      and e.status = 'active'
      and (e.enrolled_at is null or e.enrolled_at::date <= p_attendance_date)
      and (e.ended_at is null or e.ended_at::date >= p_attendance_date)
    order by e.enrolled_at desc nulls last, e.created_at desc
    limit 1;

    if v_enrollment.id is null then
      raise exception 'Aluno % nao possui matricula ativa nesta turma/data.', v_student_id using errcode = '42501';
    end if;

    select * into v_record
    from public.attendance_records ar
    where ar.student_id = v_student_id
      and ar.class_id = v_class.id
      and ar.attendance_date = p_attendance_date
    for update;

    if v_record.id is null then
      insert into public.attendance_records (
        school_id,
        class_id,
        student_id,
        enrollment_id,
        attendance_date,
        status,
        notes,
        recorded_by,
        updated_by
      )
      values (
        v_class.school_id,
        v_class.id,
        v_student_id,
        v_enrollment.id,
        p_attendance_date,
        v_status,
        v_notes,
        auth.uid(),
        auth.uid()
      )
      returning * into v_record;

      insert into public.attendance_events (
        attendance_record_id,
        school_id,
        class_id,
        student_id,
        enrollment_id,
        attendance_date,
        event_type,
        from_status,
        to_status,
        notes,
        actor_id
      )
      values (
        v_record.id,
        v_record.school_id,
        v_record.class_id,
        v_record.student_id,
        v_record.enrollment_id,
        v_record.attendance_date,
        'created',
        null,
        v_record.status,
        v_record.notes,
        auth.uid()
      );
    else
      v_previous_status := v_record.status;
      if v_record.status is distinct from v_status or coalesce(v_record.notes, '') is distinct from coalesce(v_notes, '') then
        update public.attendance_records
        set enrollment_id = v_enrollment.id,
          status = v_status,
          notes = v_notes,
          updated_by = auth.uid(),
          updated_at = now()
        where id = v_record.id
        returning * into v_record;

        insert into public.attendance_events (
          attendance_record_id,
          school_id,
          class_id,
          student_id,
          enrollment_id,
          attendance_date,
          event_type,
          from_status,
          to_status,
          notes,
          actor_id
        )
        values (
          v_record.id,
          v_record.school_id,
          v_record.class_id,
          v_record.student_id,
          v_record.enrollment_id,
          v_record.attendance_date,
          'updated',
          v_previous_status,
          v_record.status,
          v_record.notes,
          auth.uid()
        );
      end if;
    end if;

    v_saved := v_saved + 1;
  end loop;

  return jsonb_build_object(
    'class_id', p_class_id,
    'attendance_date', p_attendance_date,
    'saved', v_saved,
    'updated_by', auth.uid(),
    'updated_at', now()
  );
end;
$$;


ALTER FUNCTION "public"."teacher_set_attendance_records"("p_class_id" "uuid", "p_attendance_date" "date", "p_records" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_set_pedagogical_recommendation_status"("p_recommendation_id" "uuid", "p_to_status" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_row public.pedagogical_recommendations;
  v_teacher public.teachers;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Usuario autenticado obrigatorio para alterar recomendacao.';
  END IF;

  IF p_to_status NOT IN ('published', 'archived') THEN
    RAISE EXCEPTION 'Status invalido para recomendacao.';
  END IF;

  SELECT * INTO v_row
  FROM public.pedagogical_recommendations
  WHERE id = p_recommendation_id
    AND status <> 'deleted';

  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'Recomendacao nao encontrada.';
  END IF;

  SELECT * INTO v_teacher
  FROM public.pedagogical_recommendation_current_teacher(v_row.school_id);

  IF v_teacher.id IS NULL OR v_teacher.id <> v_row.teacher_id THEN
    RAISE EXCEPTION 'Professor sem permissao para alterar esta recomendacao.';
  END IF;

  IF NOT public.pedagogical_recommendation_teacher_can_target(
    v_teacher.id,
    v_row.school_id,
    v_row.class_id,
    v_row.student_id,
    v_row.target_type
  ) THEN
    RAISE EXCEPTION 'Professor sem permissao para alterar esta recomendacao.';
  END IF;

  IF p_to_status = 'published'
    AND NOT public.is_content_available_for_school(v_row.school_id, v_row.content_type, v_row.content_id) THEN
    RAISE EXCEPTION 'Conteudo indisponivel para esta escola.';
  END IF;

  UPDATE public.pedagogical_recommendations
  SET
    status = p_to_status,
    published_at = CASE WHEN p_to_status = 'published' THEN now() ELSE published_at END,
    updated_by = auth.uid()
  WHERE id = p_recommendation_id;

  INSERT INTO public.pedagogical_recommendation_events (
    recommendation_id,
    event_type,
    from_status,
    to_status,
    performed_by
  )
  VALUES (
    p_recommendation_id,
    CASE WHEN p_to_status = 'published' THEN 'published' ELSE 'archived' END,
    v_row.status,
    p_to_status,
    auth.uid()
  );

  RETURN jsonb_build_object(
    'recommendation_id', p_recommendation_id,
    'status', p_to_status
  );
END;
$$;


ALTER FUNCTION "public"."teacher_set_pedagogical_recommendation_status"("p_recommendation_id" "uuid", "p_to_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_set_scan_file_student"("p_scan_file_id" "uuid", "p_student_id" "uuid", "p_confidence" numeric DEFAULT 1) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_file public.assessment_scan_files%rowtype;
  v_batch public.assessment_scan_batches%rowtype;
  v_assignment public.assessment_assignments%rowtype;
begin
  if auth.uid() is null then
    raise exception 'AUTH_REQUIRED' using errcode = '42501';
  end if;
  select * into v_file from public.assessment_scan_files where id = p_scan_file_id for update;
  if v_file.id is null then
    raise exception 'SCAN_FILE_NOT_FOUND';
  end if;
  select * into v_batch from public.assessment_scan_batches where id = v_file.batch_id;
  v_assignment := public.avalia_plus_assert_teacher_assignment(v_batch.assignment_id);

  if not exists (
    select 1
    from public.students s
    join public.enrollments e on e.student_id = s.id
    where s.id = p_student_id
      and e.class_id = v_assignment.class_id
      and e.school_id = v_assignment.school_id
      and e.status = 'active'
      and (v_assignment.target_type = 'class' or s.id = v_assignment.student_id)
  ) then
    raise exception 'STUDENT_NOT_ELIGIBLE';
  end if;

  update public.assessment_scan_files
     set student_id = p_student_id,
         identification_status = 'IDENTIFIED',
         identification_confidence = greatest(least(coalesce(p_confidence, 1), 1), 0),
         reviewed_by = auth.uid(),
         reviewed_at = now(),
         updated_at = now()
   where id = p_scan_file_id
   returning * into v_file;

  perform public.avalia_plus_scan_log_event(v_batch.id, v_file.id, 'STUDENT_IDENTIFIED', jsonb_build_object('student_id', p_student_id));
  return jsonb_build_object('file', to_jsonb(v_file));
end;
$$;


ALTER FUNCTION "public"."teacher_set_scan_file_student"("p_scan_file_id" "uuid", "p_student_id" "uuid", "p_confidence" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_update_recomposition_plan_status"("p_plan_id" "uuid", "p_to_status" "text", "p_evidence" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_plan public.recomposition_plans%rowtype;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if p_to_status not in ('draft', 'active', 'in_progress', 'completed', 'archived') then raise exception 'INVALID_STATUS'; end if;
  select * into v_plan from public.recomposition_plans where id = p_plan_id for update;
  if not found then raise exception 'PLAN_NOT_FOUND'; end if;
  if not public.avalia_plus_teacher_can_manage_class(v_plan.class_id, v_plan.school_id) then raise exception 'PLAN_FORBIDDEN'; end if;
  update public.recomposition_plans set status = p_to_status, updated_by = auth.uid() where id = p_plan_id;
  insert into public.recomposition_tracking_events (plan_id, event_type, from_status, to_status, evidence) values (p_plan_id, 'status_change', v_plan.status, p_to_status, coalesce(p_evidence, '{}'::jsonb));
  return jsonb_build_object('plan_id', p_plan_id, 'status', p_to_status);
end;
$$;


ALTER FUNCTION "public"."teacher_update_recomposition_plan_status"("p_plan_id" "uuid", "p_to_status" "text", "p_evidence" "jsonb") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."class_calendar_entries" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "class_id" "uuid" NOT NULL,
    "school_id" "uuid" NOT NULL,
    "teacher_id" "uuid" NOT NULL,
    "plan_id" "uuid",
    "entry_date" "date" NOT NULL,
    "start_time" time without time zone,
    "end_time" time without time zone,
    "title" "text" NOT NULL,
    "description" "text",
    "entry_type" "text" DEFAULT 'outro'::"text" NOT NULL,
    "status" "text" DEFAULT 'published'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "class_calendar_entries_status_check" CHECK (("status" = ANY (ARRAY['published'::"text", 'cancelled'::"text", 'archived'::"text"]))),
    CONSTRAINT "class_calendar_entries_time_check" CHECK ((("end_time" IS NULL) OR ("start_time" IS NULL) OR ("end_time" > "start_time"))),
    CONSTRAINT "class_calendar_entries_title_not_blank" CHECK (("length"("btrim"("title")) > 0)),
    CONSTRAINT "class_calendar_entries_type_check" CHECK (("entry_type" = ANY (ARRAY['atividade'::"text", 'aula'::"text", 'lembrete'::"text", 'livro'::"text", 'experiencia'::"text", 'atividade_online'::"text", 'outro'::"text"])))
);


ALTER TABLE "public"."class_calendar_entries" OWNER TO "postgres";


COMMENT ON TABLE "public"."class_calendar_entries" IS 'Entradas publicadas na agenda da turma. Visiveis a alunos/familias somente quando houver policy institucional apropriada.';



COMMENT ON COLUMN "public"."class_calendar_entries"."description" IS 'Descricao publica da publicacao. Nao copiar teacher_plans.teacher_notes automaticamente.';



CREATE OR REPLACE FUNCTION "public"."teacher_upsert_calendar_entry"("p_entry_id" "uuid" DEFAULT NULL::"uuid", "p_plan_id" "uuid" DEFAULT NULL::"uuid", "p_class_id" "uuid" DEFAULT NULL::"uuid", "p_entry_date" "date" DEFAULT CURRENT_DATE, "p_start_time" time without time zone DEFAULT NULL::time without time zone, "p_end_time" time without time zone DEFAULT NULL::time without time zone, "p_title" "text" DEFAULT ''::"text", "p_description" "text" DEFAULT NULL::"text", "p_entry_type" "text" DEFAULT 'outro'::"text") RETURNS "public"."class_calendar_entries"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_class public.classes%rowtype;
  v_teacher public.teachers%rowtype;
  v_entry public.class_calendar_entries%rowtype;
  v_type text := lower(coalesce(nullif(btrim(p_entry_type), ''), 'outro'));
  v_time text;
begin
  if auth.uid() is null then
    raise exception 'Usuario autenticado obrigatorio.' using errcode = '42501';
  end if;

  if p_class_id is null then
    raise exception 'Turma obrigatoria.' using errcode = '22023';
  end if;

  select * into v_class
  from public.classes
  where id = p_class_id
    and coalesce(status, 'active') = 'active';

  if v_class.id is null or v_class.school_id is null then
    raise exception 'Turma institucional nao encontrada.' using errcode = '22023';
  end if;

  select t.* into v_teacher
  from public.teachers t
  join public.class_teacher_memberships ctm on ctm.teacher_id = t.id
  where t.profile_id = auth.uid()
    and t.school_id = v_class.school_id
    and coalesce(t.status, 'active') = 'active'
    and ctm.class_id = v_class.id
    and ctm.status = 'active'
    and ctm.started_at <= now()
    and (ctm.ended_at is null or ctm.ended_at > now())
  order by ctm.started_at desc
  limit 1;

  if v_teacher.id is null and public.is_platform_admin() then
    select t.* into v_teacher
    from public.teachers t
    where t.school_id = v_class.school_id
      and coalesce(t.status, 'active') = 'active'
    order by t.created_at asc
    limit 1;
  end if;

  if v_teacher.id is null then
    raise exception 'Professor nao autorizado para esta turma.' using errcode = '42501';
  end if;

  if length(btrim(coalesce(p_title, ''))) = 0 then
    raise exception 'Titulo obrigatorio.' using errcode = '22023';
  end if;

  if v_type not in ('atividade', 'aula', 'lembrete', 'livro', 'experiencia', 'atividade_online', 'outro') then
    v_type := 'outro';
  end if;

  if p_end_time is not null and p_start_time is not null and p_end_time <= p_start_time then
    raise exception 'Horario final deve ser posterior ao inicial.' using errcode = '22023';
  end if;

  if p_plan_id is not null and not public.institutional_plan_matches_publication(p_plan_id, v_teacher.id, v_class.id, v_class.school_id) then
    raise exception 'Planejamento nao pertence a esta turma/professor.' using errcode = '42501';
  end if;

  if p_entry_id is not null then
    update public.class_calendar_entries
    set
      plan_id = p_plan_id,
      entry_date = p_entry_date,
      start_time = p_start_time,
      end_time = p_end_time,
      title = btrim(p_title),
      description = nullif(btrim(coalesce(p_description, '')), ''),
      entry_type = v_type,
      status = 'published',
      updated_at = now()
    where id = p_entry_id
      and class_id = v_class.id
      and school_id = v_class.school_id
      and teacher_id = v_teacher.id
    returning * into v_entry;

    if v_entry.id is null then
      raise exception 'Publicacao de agenda nao encontrada para este professor/turma.' using errcode = '42501';
    end if;
  else
    insert into public.class_calendar_entries (
      class_id, school_id, teacher_id, plan_id, entry_date, start_time, end_time,
      title, description, entry_type, status
    ) values (
      v_class.id, v_class.school_id, v_teacher.id, p_plan_id, p_entry_date, p_start_time, p_end_time,
      btrim(p_title), nullif(btrim(coalesce(p_description, '')), ''), v_type, 'published'
    )
    returning * into v_entry;
  end if;

  v_time := case
    when v_entry.start_time is not null then ' às ' || to_char(v_entry.start_time, 'HH24:MI')
    else ''
  end;

  perform public.communication_upsert_system_notification(
    'calendar',
    v_entry.id,
    v_entry.school_id,
    auth.uid(),
    'professor',
    'class',
    v_entry.class_id,
    null,
    'Agenda: ' || v_entry.title,
    coalesce(nullif(v_entry.description, ''), 'Novo compromisso publicado para a turma.') || ' Data: ' || to_char(v_entry.entry_date, 'DD/MM/YYYY') || v_time || '.',
    v_entry.entry_date,
    'Abrir agenda',
    'agenda'
  );

  return v_entry;
end;
$$;


ALTER FUNCTION "public"."teacher_upsert_calendar_entry"("p_entry_id" "uuid", "p_plan_id" "uuid", "p_class_id" "uuid", "p_entry_date" "date", "p_start_time" time without time zone, "p_end_time" time without time zone, "p_title" "text", "p_description" "text", "p_entry_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."teacher_upsert_class_diary_entry"("p_entry_id" "uuid" DEFAULT NULL::"uuid", "p_school_id" "uuid" DEFAULT NULL::"uuid", "p_class_id" "uuid" DEFAULT NULL::"uuid", "p_entry_date" "date" DEFAULT CURRENT_DATE, "p_title" "text" DEFAULT 'Diario de Classe'::"text", "p_taught_content" "text" DEFAULT ''::"text", "p_pedagogical_notes" "text" DEFAULT ''::"text", "p_plan_id" "uuid" DEFAULT NULL::"uuid", "p_calendar_entry_id" "uuid" DEFAULT NULL::"uuid", "p_activity_links" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_class public.classes%ROWTYPE;
  v_teacher public.teachers%ROWTYPE;
  v_entry public.class_diary_entries%ROWTYPE;
  v_existing public.class_diary_entries%ROWTYPE;
  v_event_type text := 'created';
  v_link_count integer := 0;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Usuario autenticado obrigatorio.' USING ERRCODE = '42501';
  END IF;

  IF p_class_id IS NULL OR p_entry_date IS NULL THEN
    RAISE EXCEPTION 'Turma e data sao obrigatorias.' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_class
  FROM public.classes c
  WHERE c.id = p_class_id
    AND coalesce(c.status, 'active') = 'active'
    AND (p_school_id IS NULL OR c.school_id = p_school_id)
  LIMIT 1;

  IF v_class.id IS NULL OR v_class.school_id IS NULL THEN
    RAISE EXCEPTION 'Turma ativa nao encontrada para esta escola.' USING ERRCODE = '22023';
  END IF;

  SELECT t.* INTO v_teacher
  FROM public.teachers t
  JOIN public.class_teacher_memberships ctm ON ctm.teacher_id = t.id
  WHERE t.profile_id = auth.uid()
    AND t.school_id = v_class.school_id
    AND coalesce(t.status, 'active') = 'active'
    AND ctm.class_id = v_class.id
    AND ctm.status = 'active'
    AND ctm.started_at <= now()
    AND (ctm.ended_at IS NULL OR ctm.ended_at > now())
  ORDER BY ctm.started_at DESC, t.created_at DESC
  LIMIT 1;

  IF v_teacher.id IS NULL THEN
    RAISE EXCEPTION 'Professor sem vinculo ativo com esta turma.' USING ERRCODE = '42501';
  END IF;

  IF NOT public.class_diary_teacher_can_manage(v_class.school_id, v_class.id, v_teacher.id) THEN
    RAISE EXCEPTION 'Professor sem permissao para registrar Diario desta turma.' USING ERRCODE = '42501';
  END IF;

  IF NOT public.class_diary_validate_links(v_class.school_id, v_class.id, v_teacher.id, p_plan_id, p_calendar_entry_id) THEN
    RAISE EXCEPTION 'Planejamento ou agenda nao pertencem a esta turma/professor.' USING ERRCODE = '42501';
  END IF;

  IF p_entry_id IS NOT NULL THEN
    SELECT * INTO v_existing
    FROM public.class_diary_entries cde
    WHERE cde.id = p_entry_id
      AND cde.school_id = v_class.school_id
      AND cde.class_id = v_class.id
      AND cde.teacher_id = v_teacher.id
    FOR UPDATE;
  ELSE
    SELECT * INTO v_existing
    FROM public.class_diary_entries cde
    WHERE cde.school_id = v_class.school_id
      AND cde.class_id = v_class.id
      AND cde.teacher_id = v_teacher.id
      AND cde.entry_date = p_entry_date
      AND cde.status <> 'deleted'
      AND cde.deleted_at IS NULL
    FOR UPDATE;
  END IF;

  IF p_entry_id IS NOT NULL AND v_existing.id IS NULL THEN
    RAISE EXCEPTION 'Diario de Classe nao encontrado para este professor/turma.' USING ERRCODE = '42501';
  END IF;

  IF v_existing.id IS NOT NULL THEN
    IF v_existing.status = 'closed' THEN
      RAISE EXCEPTION 'Diario fechado nao pode ser editado nesta versao.' USING ERRCODE = '42501';
    END IF;

    IF v_existing.status = 'deleted' OR v_existing.deleted_at IS NOT NULL THEN
      RAISE EXCEPTION 'Diario excluido nao pode ser editado.' USING ERRCODE = '42501';
    END IF;

    UPDATE public.class_diary_entries
    SET title = COALESCE(NULLIF(trim(p_title), ''), 'Diario de Classe'),
      taught_content = COALESCE(p_taught_content, ''),
      pedagogical_notes = COALESCE(p_pedagogical_notes, ''),
      plan_id = p_plan_id,
      calendar_entry_id = p_calendar_entry_id,
      updated_at = now()
    WHERE id = v_existing.id
    RETURNING * INTO v_entry;

    v_event_type := 'updated';
  ELSE
    INSERT INTO public.class_diary_entries (
      school_id,
      class_id,
      teacher_id,
      entry_date,
      title,
      taught_content,
      pedagogical_notes,
      plan_id,
      calendar_entry_id,
      status,
      created_by
    )
    VALUES (
      v_class.school_id,
      v_class.id,
      v_teacher.id,
      p_entry_date,
      COALESCE(NULLIF(trim(p_title), ''), 'Diario de Classe'),
      COALESCE(p_taught_content, ''),
      COALESCE(p_pedagogical_notes, ''),
      p_plan_id,
      p_calendar_entry_id,
      'draft',
      auth.uid()
    )
    RETURNING * INTO v_entry;
  END IF;

  v_link_count := public.class_diary_apply_activity_links(v_entry.id, COALESCE(p_activity_links, '[]'::jsonb));

  INSERT INTO public.class_diary_events (diary_entry_id, event_type, actor_id, metadata)
  VALUES (
    v_entry.id,
    v_event_type,
    auth.uid(),
    jsonb_build_object(
      'status', v_entry.status,
      'school_id', v_entry.school_id,
      'class_id', v_entry.class_id,
      'teacher_id', v_entry.teacher_id,
      'entry_date', v_entry.entry_date,
      'activity_links', v_link_count
    )
  );

  RETURN jsonb_build_object(
    'diary_entry_id', v_entry.id,
    'status', v_entry.status,
    'event_type', v_event_type,
    'activity_links', v_link_count
  );
END;
$$;


