CREATE TABLE IF NOT EXISTS "public"."student_credential_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "credential_id" "uuid",
    "student_id" "uuid",
    "school_id" "uuid",
    "actor_profile_id" "uuid" DEFAULT "auth"."uid"(),
    "action" "text" NOT NULL,
    "result" "text" DEFAULT 'success'::"text" NOT NULL,
    "reason" "text",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "student_credential_events_action_check" CHECK (("action" = ANY (ARRAY['CREDENTIAL_CREATED'::"text", 'PASSWORD_RESET'::"text", 'ACCESS_BLOCKED'::"text", 'ACCESS_UNBLOCKED'::"text", 'IDEMPOTENT_REPLAY'::"text", 'PROVISIONING_BLOCKED'::"text", 'PROVISIONING_FAILED'::"text"]))),
    CONSTRAINT "student_credential_events_no_secret_check" CHECK (((COALESCE("reason", ''::"text") !~* '(password|senha|token|secret|service_role|access_token|refresh_token)'::"text") AND (COALESCE(("metadata")::"text", ''::"text") !~* '(password|senha|token|secret|service_role|access_token|refresh_token)'::"text"))),
    CONSTRAINT "student_credential_events_result_check" CHECK (("result" = ANY (ARRAY['success'::"text", 'blocked'::"text", 'failed'::"text"])))
);


ALTER TABLE "public"."student_credential_events" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."student_discoveries" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "legacy_id" "text" NOT NULL,
    "title" "text" NOT NULL,
    "description" "text",
    "student_instruction" "text",
    "segment" "text" DEFAULT 'educacao_infantil'::"text" NOT NULL,
    "age_group" "text",
    "school_year" "text",
    "discovery_type" "text" DEFAULT 'experience'::"text" NOT NULL,
    "book_legacy_id" "text",
    "page_start" integer,
    "page_end" integer,
    "unit_code" "text",
    "unit_title" "text",
    "sequence_code" "text",
    "sequence_title" "text",
    "bncc_codes" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "bncc_skills" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "experience_fields" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "resources" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "completion_rule" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "reward" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "sort_order" integer DEFAULT 0 NOT NULL,
    "duration_seconds" integer,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "active" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "student_discoveries_legacy_id_not_blank" CHECK (("length"("btrim"("legacy_id")) > 0)),
    CONSTRAINT "student_discoveries_no_secret_check" CHECK ((("legacy_id" !~* '(password|senha|token|secret|service_role|access_token|refresh_token)'::"text") AND (("resources")::"text" !~* '(password|senha|token|secret|service_role|access_token|refresh_token)'::"text") AND (("metadata")::"text" !~* '(password|senha|token|secret|service_role|access_token|refresh_token)'::"text"))),
    CONSTRAINT "student_discoveries_page_range_check" CHECK ((("page_start" IS NULL) OR ("page_end" IS NULL) OR ("page_end" >= "page_start"))),
    CONSTRAINT "student_discoveries_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'published'::"text", 'archived'::"text"])))
);


ALTER TABLE "public"."student_discoveries" OWNER TO "postgres";


COMMENT ON TABLE "public"."student_discoveries" IS 'Catalogo canonico de descobertas/experiencias do aluno, separado de atividades e jogos.';



CREATE TABLE IF NOT EXISTS "public"."student_discovery_progress" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "student_id" "uuid" NOT NULL,
    "discovery_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'NOT_STARTED'::"text" NOT NULL,
    "discovered_hotspots" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "progress_data" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "started_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "student_discovery_progress_no_secret_check" CHECK (((("discovered_hotspots")::"text" !~* '(password|senha|token|secret|service_role|access_token|refresh_token)'::"text") AND (("progress_data")::"text" !~* '(password|senha|token|secret|service_role|access_token|refresh_token)'::"text"))),
    CONSTRAINT "student_discovery_progress_status_check" CHECK (("status" = ANY (ARRAY['NOT_STARTED'::"text", 'IN_PROGRESS'::"text", 'COMPLETED'::"text"])))
);


ALTER TABLE "public"."student_discovery_progress" OWNER TO "postgres";


COMMENT ON TABLE "public"."student_discovery_progress" IS 'Progresso proprio do aluno em descobertas/experiencias. Escrita via RPC segura.';



CREATE TABLE IF NOT EXISTS "public"."student_game_assets" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "game_id" "uuid" NOT NULL,
    "legacy_id" "text" NOT NULL,
    "role" "text" NOT NULL,
    "asset_type" "text" NOT NULL,
    "title" "text",
    "bucket" "text",
    "storage_path" "text",
    "local_path" "text",
    "mime_type" "text",
    "storage_access" "text" DEFAULT 'local_pending'::"text" NOT NULL,
    "status" "text" DEFAULT 'awaiting_upload'::"text" NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "sort_order" integer DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "student_game_assets_access_check" CHECK (("storage_access" = ANY (ARRAY['private'::"text", 'public'::"text", 'local_pending'::"text", 'generated'::"text"]))),
    CONSTRAINT "student_game_assets_legacy_id_not_blank" CHECK (("length"("btrim"("legacy_id")) > 0)),
    CONSTRAINT "student_game_assets_no_secret_check" CHECK ((("legacy_id" !~* '(password|senha|token|secret|service_role|access_token|refresh_token)'::"text") AND ("role" !~* '(password|senha|token|secret|service_role|access_token|refresh_token)'::"text") AND (COALESCE("bucket", ''::"text") !~* '(password|senha|token|secret|service_role|access_token|refresh_token)'::"text") AND (COALESCE("storage_path", ''::"text") !~* '(password|senha|token|secret|service_role|access_token|refresh_token)'::"text") AND (COALESCE("local_path", ''::"text") !~* '(password|senha|token|secret|service_role|access_token|refresh_token)'::"text") AND (("metadata")::"text" !~* '(password|senha|token|secret|service_role|access_token|refresh_token)'::"text"))),
    CONSTRAINT "student_game_assets_private_path_check" CHECK ((("storage_access" <> 'private'::"text") OR (("bucket" IS NOT NULL) AND ("storage_path" IS NOT NULL)))),
    CONSTRAINT "student_game_assets_status_check" CHECK (("status" = ANY (ARRAY['awaiting_upload'::"text", 'ready'::"text", 'published'::"text", 'missing'::"text", 'archived'::"text"]))),
    CONSTRAINT "student_game_assets_type_check" CHECK (("asset_type" = ANY (ARRAY['image'::"text", 'video'::"text", 'audio'::"text", 'sprite'::"text", 'atlas'::"text", 'html'::"text", 'css'::"text", 'js'::"text", 'json'::"text", 'other'::"text"])))
);


ALTER TABLE "public"."student_game_assets" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."student_game_attempts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "student_id" "uuid" NOT NULL,
    "game_id" "uuid" NOT NULL,
    "attempt_number" integer NOT NULL,
    "status" "text" DEFAULT 'STARTED'::"text" NOT NULL,
    "started_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "last_event_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "completed_at" timestamp with time zone,
    "client_state" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "raw_result" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "canonical_result" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "score_percent" integer,
    "duration_seconds" integer,
    "result_event_key" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "student_game_attempts_attempt_number_check" CHECK (("attempt_number" > 0)),
    CONSTRAINT "student_game_attempts_completed_at_check" CHECK (((("status" = 'COMPLETED'::"text") AND ("completed_at" IS NOT NULL)) OR ("status" <> 'COMPLETED'::"text"))),
    CONSTRAINT "student_game_attempts_duration_check" CHECK ((("duration_seconds" IS NULL) OR ("duration_seconds" >= 0))),
    CONSTRAINT "student_game_attempts_no_secret_check" CHECK (((("client_state")::"text" !~* '(password|senha|token|secret|service_role|access_token|refresh_token)'::"text") AND (("raw_result")::"text" !~* '(password|senha|token|secret|service_role|access_token|refresh_token)'::"text") AND (("canonical_result")::"text" !~* '(password|senha|token|secret|service_role|access_token|refresh_token)'::"text") AND (COALESCE("result_event_key", ''::"text") !~* '(password|senha|token|secret|service_role|access_token|refresh_token)'::"text"))),
    CONSTRAINT "student_game_attempts_score_check" CHECK ((("score_percent" IS NULL) OR (("score_percent" >= 0) AND ("score_percent" <= 100)))),
    CONSTRAINT "student_game_attempts_status_check" CHECK (("status" = ANY (ARRAY['STARTED'::"text", 'IN_PROGRESS'::"text", 'PAUSED'::"text", 'COMPLETED'::"text", 'ABANDONED'::"text"])))
);


ALTER TABLE "public"."student_game_attempts" OWNER TO "postgres";


