CREATE TABLE IF NOT EXISTS "public"."student_institutional_credentials" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "student_id" "uuid" NOT NULL,
    "school_id" "uuid" NOT NULL,
    "namespace_id" "uuid" NOT NULL,
    "login" "text" NOT NULL,
    "sequence_no" bigint NOT NULL,
    "auth_user_id" "uuid",
    "technical_email" "text",
    "password_hash" "text",
    "password_hash_algorithm" "text" DEFAULT 'pgcrypto_bf'::"text" NOT NULL,
    "password_version" integer DEFAULT 0 NOT NULL,
    "status" "text" DEFAULT 'pending_auth'::"text" NOT NULL,
    "created_by" "uuid" DEFAULT "auth"."uid"(),
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "technical_auth_created_at" timestamp with time zone,
    "password_changed_at" timestamp with time zone,
    "last_reset_at" timestamp with time zone,
    "last_sign_in_at" timestamp with time zone,
    "blocked_at" timestamp with time zone,
    "unblocked_at" timestamp with time zone,
    CONSTRAINT "student_institutional_credentials_hash_check" CHECK (((("status" = 'pending_auth'::"text") AND ("password_hash" IS NULL)) OR (("status" <> 'pending_auth'::"text") AND ("password_hash" IS NOT NULL)))),
    CONSTRAINT "student_institutional_credentials_login_format" CHECK (("login" ~ '^[A-Z0-9]{2,12}-[0-9]{6}$'::"text")),
    CONSTRAINT "student_institutional_credentials_status_check" CHECK (("status" = ANY (ARRAY['pending_auth'::"text", 'active'::"text", 'blocked'::"text", 'archived'::"text"])))
);


ALTER TABLE "public"."student_institutional_credentials" OWNER TO "postgres";


COMMENT ON TABLE "public"."student_institutional_credentials" IS 'Canonical student institutional login identity. Stores password hashes only, never plaintext passwords.';



